window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["生态环境法"] = {"yuanzinengfa":[{"i":1,"n":"第一条","txt":"为了保障原子能研究、开发与和平利用，推进科技进步和产业提升，促进经济社会高质量发展，维护国家安全，增进人民福祉，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于中华人民共和国领域及中华人民共和国管辖的其他海域内的原子能研究、开发和利用活动。"},{"i":3,"n":"第三条","txt":"从事原子能研究、开发和利用活动，应当坚持中国共产党的领导，贯彻总体国家安全观，坚持理性、协调、并进的核安全观，坚持底线思维与系统观念，统筹发展和安全，保护生态环境，保障人身健康和生命财产安全。"},{"i":4,"n":"第四条","txt":"原子能科技与产业发展应当坚持创新驱动发展战略和绿色发展、可持续发展战略。"},{"i":5,"n":"第五条","txt":"国务院核工业主管部门、能源主管部门、核安全监督管理部门按照职责分工负责原子能研究、开发和利用活动的管理和监督。"},{"i":6,"n":"第六条","txt":"国务院有关部门和有关地方人民政府对原子能研究、开发和利用活动，在科学技术奖励、产业发展、财政、税费等方面，按照国家规定给予政策支持。"},{"i":7,"n":"第七条","txt":"有关行政机关、企业事业单位应当依法做好原子能研究、开发和利用活动中安全监督管理、环境影响评价等方面的信息公开工作。"},{"i":8,"n":"第八条","txt":"国家加强原子能科学知识和法律知识的宣传教育，鼓励有条件的地方人民政府、核设施营运单位以及其他有关单位建设和利用科普场馆、设施，开展原子能科学知识普及活动。"},{"i":9,"n":"第九条","txt":"国家支持和平利用原子能，鼓励和平利用原子能的国际交流与合作，促进共享和平利用原子能事业成果。"},{"i":10,"n":"第十条","txt":"国家加强原子能领域标准体系建设，推动、参与原子能领域国际标准化活动。"},{"i":11,"n":"第十一条","txt":"对在原子能研究、开发和利用活动中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":12,"n":"第十二条","txt":"国家加强原子能科学研究与技术开发，强化基础研究，探索前沿技术，推进学科交叉融合，鼓励自主研发，加强知识产权保护，强化国家战略科技力量建设，促进原子能领域高素质专业人才队伍建设。"},{"i":13,"n":"第十三条","txt":"国家建立原子能领域相关科技创新基地和平台，加强原子能科研设施和科研条件保障能力建设，推动科研设施、资源开放共享，促进科技成果转化。"},{"i":14,"n":"第十四条","txt":"国家鼓励和支持受控热核聚变的科学研究与技术开发。"},{"i":15,"n":"第十五条","txt":"国家制定并实施原子能科学研究与技术开发专项规划，促进核燃料循环、核反应堆、核技术应用等领域先进技术的研究与开发，提升原子能科学技术水平。"},{"i":16,"n":"第十六条","txt":"国家公开征集原子能科学研究与技术开发需求建议，发布项目申报指南，鼓励科研院所、高等学校、企业等单位开展原子能科学研究与技术开发。"},{"i":17,"n":"第十七条","txt":"国家加强原子能领域科学技术规划计划的衔接，完善科学技术资源、技术开发需求的交流机制，发挥市场配置资源的作用。"},{"i":18,"n":"第十八条","txt":"国家推动建立和完善与原子能发展相适应的设备研制生产体系，鼓励和支持企业形成自主研发、设计、制造能力。"},{"i":19,"n":"第十九条","txt":"国家建立完整的核燃料循环体系，对乏燃料实行循环利用，妥善处理处置放射性废物。"},{"i":20,"n":"第二十条","txt":"国务院核工业主管部门负责组织编制核燃料循环中长期发展专项规划，统筹核燃料生产能力和布局。"},{"i":21,"n":"第二十一条","txt":"核燃料循环设施建设项目由国务院核工业主管部门依法审批或者核准，重大项目报国务院审批或者核准。申请条件、审批程序和时限等按照国家规定执行。"},{"i":22,"n":"第二十二条","txt":"国家依法加强铀（钍）矿勘查，合理确定铀（钍）矿与共生和伴生矿产资源的勘查和开发秩序，实行保护性开发。"},{"i":23,"n":"第二十三条","txt":"经国家批准的单位方可从事核燃料生产经营活动。"},{"i":24,"n":"第二十四条","txt":"国家建立健全乏燃料贮存、运输和后处理等管理制度，统筹规划乏燃料处理处置能力和布局，确保乏燃料的安全、高效和环保处理。"},{"i":25,"n":"第二十五条","txt":"从事原子能研究、开发和利用活动的单位，应当尽可能减少放射性废物的产生量，严格按照有关法律、行政法规和标准的要求，对放射性废物实行分类管理和安全处理处置。"},{"i":26,"n":"第二十六条","txt":"在确保国家安全的前提下，国家允许核燃料循环产业相关企业有效利用资本市场，逐步形成核燃料循环产业多元化投入机制。"},{"i":27,"n":"第二十七条","txt":"国家积极安全有序发展核电，规范和促进核反应堆综合利用。"},{"i":28,"n":"第二十八条","txt":"国务院能源主管部门负责核电管理，组织编制国家核电发展规划。核电发展规划按照规定的程序报国务院批准。核电站建设项目由国务院核准。"},{"i":29,"n":"第二十九条","txt":"国家支持核反应堆在动力、供热、海水淡化、制氢、同位素生产以及科研等方面的应用。"},{"i":30,"n":"第三十条","txt":"核反应堆的选址、设计、建造、调试、运行和管理等应当遵守有关法律、行政法规的规定。"},{"i":31,"n":"第三十一条","txt":"核设施营运单位应当按照国家规定预提核设施退役费用、放射性废物处置费用，列入投资概算、生产成本，专门用于核设施退役、放射性废物处置。"},{"i":32,"n":"第三十二条","txt":"国家支持放射性同位素、射线装置等在工业、农业、生物、医疗卫生、生态环境保护等领域的应用。"},{"i":33,"n":"第三十三条","txt":"国务院核工业、生态环境、公安、卫生健康、疾病预防控制等主管部门按照职责分工加强对核技术应用活动的管理和监督。"},{"i":34,"n":"第三十四条","txt":"国务院核工业主管部门会同有关部门制定核技术应用产业发展指导意见。"},{"i":35,"n":"第三十五条","txt":"国家对放射源、射线装置实行分类管理，具体分类办法由国务院有关部门制定。"},{"i":36,"n":"第三十六条","txt":"从事核技术应用生产经营活动的单位，应当依法取得相应的资质，严格执行放射性同位素和射线装置在生产、运输、销售、使用、贮存、处置各环节的管理规定。"},{"i":37,"n":"第三十七条","txt":"国家建立核技术应用废旧放射源回收制度。放射源使用单位应当按照国家规定将废旧放射源交回生产单位、返回原出口方或者送交取得相应资质的单位贮存、处置。"},{"i":38,"n":"第三十八条","txt":"从事原子能研究、开发和利用活动，必须遵循确保安全的方针，按照法律、行政法规的要求，严格落实核安全责任。"},{"i":39,"n":"第三十九条","txt":"国家建立符合受控热核聚变特点、促进核聚变应用的监督管理制度，对聚变燃料、聚变装置（设施）实行分级分类管理。"},{"i":40,"n":"第四十条","txt":"从事原子能研究、开发和利用活动的单位，应当遵守国家有关辐射防护的规定，保护公众和从业人员的安全与健康，保护生态环境。"},{"i":41,"n":"第四十一条","txt":"国家建立健全核安保制度，加强原子能研究、开发和利用活动的安全保卫工作。"},{"i":42,"n":"第四十二条","txt":"从事涉及国家秘密的原子能研究、开发和利用活动的单位，应当依法建立健全保密管理制度，完善保密防护措施，开展保密宣传教育，加强保密监督检查。"},{"i":43,"n":"第四十三条","txt":"国家对核材料实行严格管制，建立和运行国家核材料衡算与控制系统。"},{"i":44,"n":"第四十四条","txt":"国家加强运输通道及装备体系建设，保障放射性物品的公路、铁路、水路、航空等运输。"},{"i":45,"n":"第四十五条","txt":"国家设立核事故应急协调委员会，组织、协调全国的核事故应急管理工作，统筹制定国家核事故应急预案，对核事故应急实行分级管理。"},{"i":46,"n":"第四十六条","txt":"发生核事故时，有关单位和个人必须立即采取应急措施，并按照有关法律、行政法规的规定报告，禁止缓报、瞒报、谎报核事故。"},{"i":47,"n":"第四十七条","txt":"国家加强原子能领域进出口管理工作，履行进出口国际义务和承诺，保证进出口物项的和平用途。"},{"i":48,"n":"第四十八条","txt":"国家依法对核以及核两用物项出口进行严格管制，实行许可制度。"},{"i":49,"n":"第四十九条","txt":"国家严格限制铀浓缩设施、设备，乏燃料后处理设施、设备，重水生产设施、设备等物项及其相关技术等核扩散敏感物项，以及可以用于核爆炸装置的材料的出口。"},{"i":50,"n":"第五十条","txt":"核进口单位应当严格执行国家关于核进口的法律、行政法规和其他有关规定，履行核进口承诺义务。"},{"i":51,"n":"第五十一条","txt":"进出口放射性同位素应当遵守法律、行政法规和其他有关规定确定的目录、条件和程序等要求。"},{"i":52,"n":"第五十二条","txt":"禁止将放射性废物和被放射性污染的物品输入中华人民共和国境内或者经中华人民共和国境内转移，法律、行政法规另有规定的除外。"},{"i":53,"n":"第五十三条","txt":"国务院有关部门、县级以上地方人民政府及其有关部门，违反本法规定，有下列情形之一，对负有责任的领导人员和直接责任人员依法给予处分："},{"i":54,"n":"第五十四条","txt":"违反本法规定，未经批准，擅自从事核燃料生产经营活动的，由国务院核工业主管部门责令停止生产经营活动，没收核燃料及违法所得，处违法生产经营的核燃料市场价值二倍以上十倍以下的罚款；对负有责任的领导人员和直接责任人员处十万元以上五十万元以下的罚款，并依法给予处分。"},{"i":55,"n":"第五十五条","txt":"核材料、核设施、其他放射性物质及相关设施的持有或者营运单位未按照有关法律、行政法规要求开展安全保卫工作的，由国务院核工业主管部门会同有关部门责令限期整改；拒不整改或者经限期整改仍不符合要求的，处一百万元以上五百万元以下的罚款，暂扣或者吊销相关许可证，对负有责任的领导人员和直接责任人员处十万元以上五十万元以下的罚款，并依法给予处分。"},{"i":56,"n":"第五十六条","txt":"核进口单位未按照有关规定履行核进口承诺义务的，由国务院核工业主管部门责令改正，处二百万元以上一千万元以下的罚款；对负有责任的领导人员和直接责任人员处十万元以上五十万元以下的罚款，并依法给予处分。"},{"i":57,"n":"第五十七条","txt":"国家建立核损害赔偿责任制度，按照法律和国家有关规定处理核事故造成的损害。"},{"i":58,"n":"第五十八条","txt":"违反本法规定的行为，本法未作行政处罚规定，其他有关法律、行政法规有规定的，依照其规定；造成财产损失或者其他损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":59,"n":"第五十九条","txt":"涉及军工、军事等国防领域的原子能研究、开发和利用活动的管理办法，由国务院、中央军事委员会依据本法规定的原则另行制定。"},{"i":60,"n":"第六十条","txt":"任何国家或者地区在原子能领域对中华人民共和国采取歧视性的禁止、限制或者其他类似措施的，中华人民共和国可以根据实际情况对该国家或者该地区采取相应的措施。"},{"i":61,"n":"第六十一条","txt":"本法下列用语的含义："},{"i":62,"n":"第六十二条","txt":"本法自2026年1月15日起施行。"}],"kezaishengnengyuanfa":[{"i":1,"n":"第一条","txt":"为了促进可再生能源的开发利用，增加能源供应，改善能源结构，保障能源安全，保护环境，实现经济社会的可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称可再生能源，是指风能、太阳能、水能、生物质能、地热能、海洋能等非化石能源。"},{"i":3,"n":"第三条","txt":"本法适用于中华人民共和国领域和管辖的其他海域。"},{"i":4,"n":"第四条","txt":"国家将可再生能源的开发利用列为能源发展的优先领域，通过制定可再生能源开发利用总量目标和采取相应措施，推动可再生能源市场的建立和发展。"},{"i":5,"n":"第五条","txt":"国务院能源主管部门对全国可再生能源的开发利用实施统一管理。国务院有关部门在各自的职责范围内负责有关的可再生能源开发利用管理工作。"},{"i":6,"n":"第六条","txt":"国务院能源主管部门负责组织和协调全国可再生能源资源的调查，并会同国务院有关部门组织制定资源调查的技术规范。"},{"i":7,"n":"第七条","txt":"国务院能源主管部门根据全国能源需求与可再生能源资源实际状况，制定全国可再生能源开发利用中长期总量目标，报国务院批准后执行，并予公布。"},{"i":8,"n":"第八条","txt":"国务院能源主管部门会同国务院有关部门，根据全国可再生能源开发利用中长期总量目标和可再生能源技术发展状况，编制全国可再生能源开发利用规划，报国务院批准后实施。"},{"i":9,"n":"第九条","txt":"编制可再生能源开发利用规划，应当遵循因地制宜、统筹兼顾、合理布局、有序发展的原则，对风能、太阳能、水能、生物质能、地热能、海洋能等可再生能源的开发利用作出统筹安排。规划内容应当包括发展目标、主要任务、区域布局、重点项目、实施进度、配套电网建设、服务体系和保障措施等。"},{"i":10,"n":"第十条","txt":"国务院能源主管部门根据全国可再生能源开发利用规划，制定、公布可再生能源产业发展指导目录。"},{"i":11,"n":"第十一条","txt":"国务院标准化行政主管部门应当制定、公布国家可再生能源电力的并网技术标准和其他需要在全国范围内统一技术要求的有关可再生能源技术和产品的国家标准。"},{"i":12,"n":"第十二条","txt":"国家将可再生能源开发利用的科学技术研究和产业化发展列为科技发展与高技术产业发展的优先领域，纳入国家科技发展规划和高技术产业发展规划，并安排资金支持可再生能源开发利用的科学技术研究、应用示范和产业化发展，促进可再生能源开发利用的技术进步，降低可再生能源产品的生产成本，提高产品质量。"},{"i":13,"n":"第十三条","txt":"国家鼓励和支持可再生能源并网发电。"},{"i":14,"n":"第十四条","txt":"国家实行可再生能源发电全额保障性收购制度。"},{"i":15,"n":"第十五条","txt":"国家扶持在电网未覆盖的地区建设可再生能源独立电力系统，为当地生产和生活提供电力服务。"},{"i":16,"n":"第十六条","txt":"国家鼓励清洁、高效地开发利用生物质燃料，鼓励发展能源作物。"},{"i":17,"n":"第十七条","txt":"国家鼓励单位和个人安装和使用太阳能热水系统、太阳能供热采暖和制冷系统、太阳能光伏发电系统等太阳能利用系统。"},{"i":18,"n":"第十八条","txt":"国家鼓励和支持农村地区的可再生能源开发利用。"},{"i":19,"n":"第十九条","txt":"可再生能源发电项目的上网电价，由国务院价格主管部门根据不同类型可再生能源发电的特点和不同地区的情况，按照有利于促进可再生能源开发利用和经济合理的原则确定，并根据可再生能源开发利用技术的发展适时调整。上网电价应当公布。"},{"i":20,"n":"第二十条","txt":"电网企业依照本法第十九条规定确定的上网电价收购可再生能源电量所发生的费用，高于按照常规能源发电平均上网电价计算所发生费用之间的差额，由在全国范围对销售电量征收可再生能源电价附加补偿。"},{"i":21,"n":"第二十一条","txt":"电网企业为收购可再生能源电量而支付的合理的接网费用以及其他合理的相关费用，可以计入电网企业输电成本，并从销售电价中回收。"},{"i":22,"n":"第二十二条","txt":"国家投资或者补贴建设的公共可再生能源独立电力系统的销售电价，执行同一地区分类销售电价，其合理的运行和管理费用超出销售电价的部分，依照本法第二十条的规定补偿。"},{"i":23,"n":"第二十三条","txt":"进入城市管网的可再生能源热力和燃气的价格，按照有利于促进可再生能源开发利用和经济合理的原则，根据价格管理权限确定。"},{"i":24,"n":"第二十四条","txt":"国家财政设立可再生能源发展基金，资金来源包括国家财政年度安排的专项资金和依法征收的可再生能源电价附加收入等。"},{"i":25,"n":"第二十五条","txt":"对列入国家可再生能源产业发展指导目录、符合信贷条件的可再生能源开发利用项目，金融机构可以提供有财政贴息的优惠贷款。"},{"i":26,"n":"第二十六条","txt":"国家对列入可再生能源产业发展指导目录的项目给予税收优惠。具体办法由国务院规定。"},{"i":27,"n":"第二十七条","txt":"电力企业应当真实、完整地记载和保存可再生能源发电的有关资料，并接受电力监管机构的检查和监督。"},{"i":28,"n":"第二十八条","txt":"国务院能源主管部门和县级以上地方人民政府管理能源工作的部门和其他有关部门在可再生能源开发利用监督管理工作中，违反本法规定，有下列行为之一的，由本级人民政府或者上级人民政府有关部门责令改正，对负有责任的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":29,"n":"第二十九条","txt":"违反本法第十四条规定，电网企业未按照规定完成收购可再生能源电量，造成可再生能源发电企业经济损失的，应当承担赔偿责任，并由国家电力监管机构责令限期改正；拒不改正的，处以可再生能源发电企业经济损失额一倍以下的罚款。"},{"i":30,"n":"第三十条","txt":"违反本法第十六条第二款规定，经营燃气管网、热力管网的企业不准许符合入网技术标准的燃气、热力入网，造成燃气、热力生产企业经济损失的，应当承担赔偿责任，并由省级人民政府管理能源工作的部门责令限期改正；拒不改正的，处以燃气、热力生产企业经济损失额一倍以下的罚款。"},{"i":31,"n":"第三十一条","txt":"违反本法第十六条第三款规定，石油销售企业未按照规定将符合国家标准的生物液体燃料纳入其燃料销售体系，造成生物液体燃料生产企业经济损失的，应当承担赔偿责任，并由国务院能源主管部门或者省级人民政府管理能源工作的部门责令限期改正；拒不改正的，处以生物液体燃料生产企业经济损失额一倍以下的罚款。"},{"i":32,"n":"第三十二条","txt":"本法中下列用语的含义："},{"i":33,"n":"第三十三条","txt":"本法自2006年1月1日起施行。"}],"guojiagongyuanfa":[{"i":1,"n":"第一条","txt":"为了高质量推进国家公园建设，加强对国家公园的保护和管理，保持重要自然生态系统原真性和完整性，建设生态文明，全面推进美丽中国建设，加快推进人与自然和谐共生的现代化，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称国家公园，是指由国务院批准设立，以保护具有国家代表性的自然生态系统为主要目的，实现自然资源科学保护和合理利用的特定陆地和海洋区域。"},{"i":3,"n":"第三条","txt":"国家建立以国家公园为主体的自然保护地体系，逐步将自然生态系统最重要、自然景观最独特、自然遗产最精华、生物多样性最富集的自然生态空间纳入国家公园，实行严格保护。"},{"i":4,"n":"第四条","txt":"国家公园建设应当坚持中国共产党的领导，践行绿水青山就是金山银山理念，坚持以人民为中心的发展思想，坚持生态保护第一、统筹保护和发展，坚持国家代表性和全民公益性，坚持因地制宜、突出特色，构建政府主导、多方参与、社会共享的机制，实现生态保护、绿色发展、民生改善相统一。"},{"i":5,"n":"第五条","txt":"国务院和国家公园所在地省、自治区、直辖市人民政府应当加强对国家公园建设的统筹协调，完善支持国家公园建设的政策措施。"},{"i":6,"n":"第六条","txt":"国家建立统一规范高效的国家公园管理体制。"},{"i":7,"n":"第七条","txt":"国务院国家公园主管部门和有关部门按照职责建立健全国家公园标准体系，依法组织制定并适时修订国家公园相关标准。"},{"i":8,"n":"第八条","txt":"国家鼓励和支持国家公园相关科学技术研究开发和应用推广，加强国家公园专业人才培养，强化科技创新对国家公园建设的支撑作用。"},{"i":9,"n":"第九条","txt":"国务院国家公园主管部门、国务院有关部门、国家公园管理机构、国家公园所在地县级以上地方人民政府及其有关部门应当组织开展多种形式的国家公园保护宣传教育活动，培育国家公园文化，传播国家公园理念。"},{"i":10,"n":"第十条","txt":"对在国家公园建设中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":11,"n":"第十一条","txt":"国家通过多种方式，支持和促进国家公园领域的国际交流合作。"},{"i":12,"n":"第十二条","txt":"国家科学规划国家公园总体发展布局，严格国家公园设立条件，合理确定国家公园数量和规模。"},{"i":13,"n":"第十三条","txt":"拟设立国家公园的，国家公园候选区所在地省、自治区、直辖市人民政府应当按照国家公园空间布局方案有关要求做好前期工作，组织开展基础调查，在广泛听取有关方面意见、深入论证的基础上提出国家公园名称、区域范围、管控分区方案以及原有居民、企业生产生活影响评估和解决方案等，并向社会公示。对拟设国家公园区域内不符合管控要求的开发建设项目，依法依规做好分类处置、有序退出、合理补偿等工作。"},{"i":14,"n":"第十四条","txt":"国家公园名称应当符合国家公园命名规范和地名管理的有关规定。国家公园名称一般不使用行政区划名称。"},{"i":15,"n":"第十五条","txt":"国家公园区域范围的划定应当统筹考虑自然生态系统的原真性、完整性和周边经济社会发展的需要，坚持实事求是、科学合理，经过充分调查和科学论证。"},{"i":16,"n":"第十六条","txt":"根据自然生态系统特性、功能定位和管理目标，国家公园划分为核心保护区和一般控制区。国家公园区域内自然生态系统保存完整、代表性强，核心资源集中分布，或者生态脆弱需要休养生息的区域划为核心保护区，核心保护区以外的区域划为一般控制区。"},{"i":17,"n":"第十七条","txt":"设立国家公园后，国家公园所在地省、自治区、直辖市人民政府应当及时组织完成国家公园勘界，国家公园管理机构应当根据保护和管理需要及时设置国家公园界碑界桩、电子标识或者电子围栏等界线标志。"},{"i":18,"n":"第十八条","txt":"国家公园区域范围、管控分区等由国务院国家公园主管部门向社会公布。"},{"i":19,"n":"第十九条","txt":"国务院国家公园主管部门发布全国国家公园统一标志。国家公园管理机构可以确定其管理的国家公园的专属标志，报国务院国家公园主管部门同意后发布。"},{"i":20,"n":"第二十条","txt":"国家坚持山水林田湖草沙一体化保护，按照自然生态系统特性和内在规律，对国家公园实行整体保护、系统修复、综合治理。"},{"i":21,"n":"第二十一条","txt":"国家公园管理机构组织编制所管理国家公园的总体规划，明确保护和管理的目标任务、保护对象、保护措施等事项，并对拟开展的生态修复活动和原有居民生产生活活动等作出安排。组织编制国家公园总体规划，应当广泛听取有关方面意见、深入论证。"},{"i":22,"n":"第二十二条","txt":"国家公园管理机构应当依据法律、法规、国家有关规定和国家公园总体规划，健全完善国家公园保护和管理的规章制度，加强国家公园日常保护和管理工作。"},{"i":23,"n":"第二十三条","txt":"对国家公园区域内的自然资源，按照国家自然资源确权登记有关规定统一进行确权登记，确权登记时应当将国家公园作为独立登记单元。"},{"i":24,"n":"第二十四条","txt":"国家加强国家公园监测网络体系建设，充分发挥各类监测站点的作用，运用信息化手段加强监测数据集成分析、共享和综合应用，全面掌握自然生态系统构成、分布、动态变化和生物多样性状况，及时评估和预警生态风险。"},{"i":25,"n":"第二十五条","txt":"国家公园管理机构应当会同国家公园所在地地方人民政府有关部门对国家公园区域内各类自然生态系统和野生生物及其遗传资源、自然遗迹、自然景观等特定保护对象分类制定保护和管理目标，开展专项保护。"},{"i":26,"n":"第二十六条","txt":"国家公园区域内受损自然生态系统修复、生态廊道连通、重要栖息地恢复等应当坚持自然恢复为主；确有必要开展种群调控、树种更新等人工修复活动的，应当充分听取有关方面意见，按照有关规定制定科学合理的修复方案。"},{"i":27,"n":"第二十七条","txt":"除下列活动外，国家公园核心保护区内禁止人为活动："},{"i":28,"n":"第二十八条","txt":"国家公园一般控制区内仅允许开展下列人为活动："},{"i":29,"n":"第二十九条","txt":"国家公园区域内原有居民的生产生活活动，应当以不超出现有规模和利用强度、合理改善生产生活条件为前提。"},{"i":30,"n":"第三十条","txt":"在国家公园区域内开展本法第二十七条、第二十八条规定的活动，依法需要办理相关手续的，有关单位和个人应当依法办理；涉及建设活动的，有关主管部门还应当征求国务院国家公园主管部门或者国家公园管理机构的意见。"},{"i":31,"n":"第三十一条","txt":"对国家公园内自然生态过程、保护对象生息繁衍具有明显季节性变化规律的区域，经科学论证，在不损害生态功能的前提下，可以实行季节性差别管控措施。"},{"i":32,"n":"第三十二条","txt":"国务院有关部门定期对国家公园内自然资源和生态环境状况等进行科学评估，并依法公布。"},{"i":33,"n":"第三十三条","txt":"国家公园管理机构应当建立日常巡护制度，合理配备巡护人员和巡护装备，加强巡护站点建设。巡护人员应当观察和记录主要保护对象生境状况及其变化情况，对违反国家公园保护和管理规定的行为予以劝阻、制止并及时报告。"},{"i":34,"n":"第三十四条","txt":"国家公园管理机构应当制定国家公园突发事件应急预案，加强与国家公园所在地地方人民政府的协作配合，做好国家公园防灾减灾、安全管理和应急保障相关工作，提升应急保障能力。"},{"i":35,"n":"第三十五条","txt":"国家鼓励和支持公众参与国家公园保护，开展多种形式的自然和生态环境保护教育，培育全社会热爱自然、保护生态环境的意识。"},{"i":36,"n":"第三十六条","txt":"国家公园管理机构应当与国家公园所在地地方人民政府加强协作配合，与国家公园区域内原有居民、农村集体经济组织以及国家公园周边居民、企业等加强沟通协商，指导、支持其积极参与国家公园的保护，提供与国家公园保护目标相一致的生态产品和服务。"},{"i":37,"n":"第三十七条","txt":"国家公园所在地地方人民政府可以与国家公园管理机构协作，按照与国家公园保护目标相协调的要求，共同保护国家公园周边自然资源，依据国土空间规划合理建设周边社区。"},{"i":38,"n":"第三十八条","txt":"国家公园管理机构根据生态保护需要设立的生态管护岗位应当优先聘用当地居民。"},{"i":39,"n":"第三十九条","txt":"对划入国家公园区域内的集体所有土地及其附属资源，应当依法维护权利人的权益，引导相关利益主体通过多元化方式参与国家公园建设和保护。"},{"i":40,"n":"第四十条","txt":"国家公园管理机构应当在确保生态得到保护的前提下，完善国家公园公共服务体系，提升公共服务功能。"},{"i":41,"n":"第四十一条","txt":"在国家公园区域内开展经营性服务的，可以由国家公园管理机构以竞争性方式选择服务提供者。具体办法由国务院国家公园主管部门会同有关部门制定。"},{"i":42,"n":"第四十二条","txt":"国家公园区域内利用公共资源建设的景区的门票以及景区内的游览场所、交通工具等另行收费项目，实行政府定价或者政府指导价。"},{"i":43,"n":"第四十三条","txt":"国家鼓励和支持志愿者、志愿服务组织和其他组织依法开展与国家公园有关的志愿服务活动。"},{"i":44,"n":"第四十四条","txt":"国家建立以财政投入为主的多元化国家公园资金保障制度。国务院和有关地方人民政府应当按照财政事权与支出责任划分原则将所需经费列入本级预算。"},{"i":45,"n":"第四十五条","txt":"国家鼓励企业事业单位、社会组织和个人等社会力量通过设立基金、捐赠、资助等方式，为国家公园建设提供支持。"},{"i":46,"n":"第四十六条","txt":"国家鼓励国家公园特色生态产品区域公用品牌创建，支持国家公园生态保护形成的生态资源权益依法参与市场交易，拓展国家公园生态产品价值实现机制。"},{"i":47,"n":"第四十七条","txt":"国家健全国家公园生态保护补偿机制，根据国家公园规模和管护成效等合理确定财政转移支付规模，并推进国家公园市场化生态保护补偿工作。"},{"i":48,"n":"第四十八条","txt":"因保护国家公园区域内受法律保护的野生动物和其他致害严重的陆生野生动物，造成人员伤亡、农作物或者其他财产损失的，依法由有关地方人民政府给予补偿，相关经费按照规定由中央财政予以补助。"},{"i":49,"n":"第四十九条","txt":"国家公园管理机构、其他有关部门应当依据职责加强对国家公园保护情况的监督检查，依法查处违法行为；对不属于本部门执法权限的案件线索，应当及时移交有关部门处理。"},{"i":50,"n":"第五十条","txt":"对违反国家公园保护和管理规定的行为，任何单位和个人有权向国家公园管理机构或者其他有关部门举报，接到举报的部门应当依法及时处理。"},{"i":51,"n":"第五十一条","txt":"国家建立国家公园保护和管理成效考核评价制度，考核评价结果纳入相关考核评价体系。"},{"i":52,"n":"第五十二条","txt":"国家公园管理机构应当依法及时公开国家公园保护和管理等工作情况，自觉接受社会监督和舆论监督。"},{"i":53,"n":"第五十三条","txt":"国家公园管理机构、其他有关部门工作人员在国家公园保护和管理等工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":54,"n":"第五十四条","txt":"损毁、涂改、遮挡或者擅自拆除、移动国家公园界线标志的，由国家公园管理机构责令停止违法行为、采取补救措施，可以处二万元以下的罚款；造成损失的，依法承担赔偿责任。"},{"i":55,"n":"第五十五条","txt":"在国家公园核心保护区内开展本法第二十七条规定以外的活动的，责令停止违法行为，没收违法所得，可以处十万元以下的罚款；属于违法修筑设施或者进行工程建设的，责令限期拆除、恢复原状，处十万元以上一百万元以下的罚款；造成生态破坏的，责令限期修复或者采取其他补救措施，处一百万元以上五百万元以下的罚款。"},{"i":56,"n":"第五十六条","txt":"在国家公园一般控制区内开展本法第二十八条规定以外的活动的，责令停止违法行为，没收违法所得，可以处五万元以下的罚款；属于违法修筑设施或者进行工程建设的，责令限期拆除、恢复原状，处五万元以上五十万元以下的罚款；造成生态破坏的，责令限期修复或者采取其他补救措施，处五十万元以上二百万元以下的罚款。"},{"i":57,"n":"第五十七条","txt":"国家公园区域内原有居民违反本法第二十九条第一款规定开展生产生活活动的，责令改正，根据情节轻重可以处二千元以下的罚款。"},{"i":58,"n":"第五十八条","txt":"在国家公园区域内开展本法第二十七条、第二十八条规定的活动，未采取必要措施避免或者减少对自然生态系统、生态廊道、重要栖息地以及自然和人文景观的不利影响的，责令改正，可以处十万元以下的罚款；造成生态破坏的，责令限期修复或者采取其他补救措施，相关活动在核心保护区开展的，处十万元以上五十万元以下的罚款，在一般控制区开展的，处五万元以上二十万元以下的罚款。"},{"i":59,"n":"第五十九条","txt":"国家公园区域内的单位、个人以及进入国家公园的人员不服从国家公园管理机构管理的，国家公园管理机构有权予以劝阻、制止；构成扰乱公共秩序等违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":60,"n":"第六十条","txt":"本法第五十五条、第五十六条、第五十七条、第五十八条规定的违法行为，按照有关规定由国家公园管理机构处罚，并与国家公园所在地地方人民政府有关部门建立执法协作机制。"},{"i":61,"n":"第六十一条","txt":"违反本法规定，破坏自然资源或者污染环境、破坏生态的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":62,"n":"第六十二条","txt":"国家公园所在地省、自治区、直辖市人民代表大会及其常务委员会可以依据本法，结合本地实际，对国家公园生态环境保护和修复及相关活动管理等事项制定具体办法。"},{"i":63,"n":"第六十三条","txt":"本法自2026年1月1日起施行。"}],"tudiguanlifa":[{"i":1,"n":"第一条","txt":"为了加强土地管理，维护土地的社会主义公有制，保护、开发土地资源，合理利用土地，切实保护耕地，促进社会经济的可持续发展，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国实行土地的社会主义公有制，即全民所有制和劳动群众集体所有制。"},{"i":3,"n":"第三条","txt":"十分珍惜、合理利用土地和切实保护耕地是我国的基本国策。各级人民政府应当采取措施，全面规划，严格管理，保护、开发土地资源，制止非法占用土地的行为。"},{"i":4,"n":"第四条","txt":"国家实行土地用途管制制度。"},{"i":5,"n":"第五条","txt":"国务院自然资源主管部门统一负责全国土地的管理和监督工作。"},{"i":6,"n":"第六条","txt":"国务院授权的机构对省、自治区、直辖市人民政府以及国务院确定的城市人民政府土地利用和土地管理情况进行督察。"},{"i":7,"n":"第七条","txt":"任何单位和个人都有遵守土地管理法律、法规的义务，并有权对违反土地管理法律、法规的行为提出检举和控告。"},{"i":8,"n":"第八条","txt":"在保护和开发土地资源、合理利用土地以及进行有关的科学研究等方面成绩显著的单位和个人，由人民政府给予奖励。"},{"i":9,"n":"第九条","txt":"城市市区的土地属于国家所有。"},{"i":10,"n":"第十条","txt":"国有土地和农民集体所有的土地，可以依法确定给单位或者个人使用。使用土地的单位和个人，有保护、管理和合理利用土地的义务。"},{"i":11,"n":"第十一条","txt":"农民集体所有的土地依法属于村农民集体所有的，由村集体经济组织或者村民委员会经营、管理；已经分别属于村内两个以上农村集体经济组织的农民集体所有的，由村内各该农村集体经济组织或者村民小组经营、管理；已经属于乡（镇）农民集体所有的，由乡（镇）农村集体经济组织经营、管理。"},{"i":12,"n":"第十二条","txt":"土地的所有权和使用权的登记，依照有关不动产登记的法律、行政法规执行。"},{"i":13,"n":"第十三条","txt":"农民集体所有和国家所有依法由农民集体使用的耕地、林地、草地，以及其他依法用于农业的土地，采取农村集体经济组织内部的家庭承包方式承包，不宜采取家庭承包方式的荒山、荒沟、荒丘、荒滩等，可以采取招标、拍卖、公开协商等方式承包，从事种植业、林业、畜牧业、渔业生产。家庭承包的耕地的承包期为三十年，草地的承包期为三十年至五十年，林地的承包期为三十年至七十年；耕地承包期届满后再延长三十年，草地、林地承包期届满后依法相应延长。"},{"i":14,"n":"第十四条","txt":"土地所有权和使用权争议，由当事人协商解决；协商不成的，由人民政府处理。"},{"i":15,"n":"第十五条","txt":"各级人民政府应当依据国民经济和社会发展规划、国土整治和资源环境保护的要求、土地供给能力以及各项建设对土地的需求，组织编制土地利用总体规划。"},{"i":16,"n":"第十六条","txt":"下级土地利用总体规划应当依据上一级土地利用总体规划编制。"},{"i":17,"n":"第十七条","txt":"土地利用总体规划按照下列原则编制："},{"i":18,"n":"第十八条","txt":"国家建立国土空间规划体系。编制国土空间规划应当坚持生态优先，绿色、可持续发展，科学有序统筹安排生态、农业、城镇等功能空间，优化国土空间结构和布局，提升国土空间开发、保护的质量和效率。"},{"i":19,"n":"第十九条","txt":"县级土地利用总体规划应当划分土地利用区，明确土地用途。"},{"i":20,"n":"第二十条","txt":"土地利用总体规划实行分级审批。"},{"i":21,"n":"第二十一条","txt":"城市建设用地规模应当符合国家规定的标准，充分利用现有建设用地，不占或者尽量少占农用地。"},{"i":22,"n":"第二十二条","txt":"江河、湖泊综合治理和开发利用规划，应当与土地利用总体规划相衔接。在江河、湖泊、水库的管理和保护范围以及蓄洪滞洪区内，土地利用应当符合江河、湖泊综合治理和开发利用规划，符合河道、湖泊行洪、蓄洪和输水的要求。"},{"i":23,"n":"第二十三条","txt":"各级人民政府应当加强土地利用计划管理，实行建设用地总量控制。"},{"i":24,"n":"第二十四条","txt":"省、自治区、直辖市人民政府应当将土地利用年度计划的执行情况列为国民经济和社会发展计划执行情况的内容，向同级人民代表大会报告。"},{"i":25,"n":"第二十五条","txt":"经批准的土地利用总体规划的修改，须经原批准机关批准；未经批准，不得改变土地利用总体规划确定的土地用途。"},{"i":26,"n":"第二十六条","txt":"国家建立土地调查制度。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府自然资源主管部门会同同级有关部门根据土地调查成果、规划土地用途和国家制定的统一标准，评定土地等级。"},{"i":28,"n":"第二十八条","txt":"国家建立土地统计制度。"},{"i":29,"n":"第二十九条","txt":"国家建立全国土地管理信息系统，对土地利用状况进行动态监测。"},{"i":30,"n":"第三十条","txt":"国家保护耕地，严格控制耕地转为非耕地。"},{"i":31,"n":"第三十一条","txt":"县级以上地方人民政府可以要求占用耕地的单位将所占用耕地耕作层的土壤用于新开垦耕地、劣质地或者其他耕地的土壤改良。"},{"i":32,"n":"第三十二条","txt":"省、自治区、直辖市人民政府应当严格执行土地利用总体规划和土地利用年度计划，采取措施，确保本行政区域内耕地总量不减少、质量不降低。耕地总量减少的，由国务院责令在规定期限内组织开垦与所减少耕地的数量与质量相当的耕地；耕地质量降低的，由国务院责令在规定期限内组织整治。新开垦和整治的耕地由国务院自然资源主管部门会同农业农村主管部门验收。"},{"i":33,"n":"第三十三条","txt":"国家实行永久基本农田保护制度。下列耕地应当根据土地利用总体规划划为永久基本农田，实行严格保护："},{"i":34,"n":"第三十四条","txt":"永久基本农田划定以乡（镇）为单位进行，由县级人民政府自然资源主管部门会同同级农业农村主管部门组织实施。永久基本农田应当落实到地块，纳入国家永久基本农田数据库严格管理。"},{"i":35,"n":"第三十五条","txt":"永久基本农田经依法划定后，任何单位和个人不得擅自占用或者改变其用途。国家能源、交通、水利、军事设施等重点建设项目选址确实难以避让永久基本农田，涉及农用地转用或者土地征收的，必须经国务院批准。"},{"i":36,"n":"第三十六条","txt":"各级人民政府应当采取措施，引导因地制宜轮作休耕，改良土壤，提高地力，维护排灌工程设施，防止土地荒漠化、盐渍化、水土流失和土壤污染。"},{"i":37,"n":"第三十七条","txt":"非农业建设必须节约使用土地，可以利用荒地的，不得占用耕地；可以利用劣地的，不得占用好地。"},{"i":38,"n":"第三十八条","txt":"禁止任何单位和个人闲置、荒芜耕地。已经办理审批手续的非农业建设占用耕地，一年内不用而又可以耕种并收获的，应当由原耕种该幅耕地的集体或者个人恢复耕种，也可以由用地单位组织耕种；一年以上未动工建设的，应当按照省、自治区、直辖市的规定缴纳闲置费；连续二年未使用的，经原批准机关批准，由县级以上人民政府无偿收回用地单位的土地使用权；该幅土地原为农民集体所有的，应当交由原农村集体经济组织恢复耕种。"},{"i":39,"n":"第三十九条","txt":"国家鼓励单位和个人按照土地利用总体规划，在保护和改善生态环境、防止水土流失和土地荒漠化的前提下，开发未利用的土地；适宜开发为农用地的，应当优先开发成农用地。"},{"i":40,"n":"第四十条","txt":"开垦未利用的土地，必须经过科学论证和评估，在土地利用总体规划划定的可开垦的区域内，经依法批准后进行。禁止毁坏森林、草原开垦耕地，禁止围湖造田和侵占江河滩地。"},{"i":41,"n":"第四十一条","txt":"开发未确定使用权的国有荒山、荒地、荒滩从事种植业、林业、畜牧业、渔业生产的，经县级以上人民政府依法批准，可以确定给开发单位或者个人长期使用。"},{"i":42,"n":"第四十二条","txt":"国家鼓励土地整理。县、乡（镇）人民政府应当组织农村集体经济组织，按照土地利用总体规划，对田、水、路、林、村综合整治，提高耕地质量，增加有效耕地面积，改善农业生产条件和生态环境。"},{"i":43,"n":"第四十三条","txt":"因挖损、塌陷、压占等造成土地破坏，用地单位和个人应当按照国家有关规定负责复垦；没有条件复垦或者复垦不符合要求的，应当缴纳土地复垦费，专项用于土地复垦。复垦的土地应当优先用于农业。"},{"i":44,"n":"第四十四条","txt":"建设占用土地，涉及农用地转为建设用地的，应当办理农用地转用审批手续。"},{"i":45,"n":"第四十五条","txt":"为了公共利益的需要，有下列情形之一，确需征收农民集体所有的土地的，可以依法实施征收："},{"i":46,"n":"第四十六条","txt":"征收下列土地的，由国务院批准："},{"i":47,"n":"第四十七条","txt":"国家征收土地的，依照法定程序批准后，由县级以上地方人民政府予以公告并组织实施。"},{"i":48,"n":"第四十八条","txt":"征收土地应当给予公平、合理的补偿，保障被征地农民原有生活水平不降低、长远生计有保障。"},{"i":49,"n":"第四十九条","txt":"被征地的农村集体经济组织应当将征收土地的补偿费用的收支状况向本集体经济组织的成员公布，接受监督。"},{"i":50,"n":"第五十条","txt":"地方各级人民政府应当支持被征地的农村集体经济组织和农民从事开发经营，兴办企业。"},{"i":51,"n":"第五十一条","txt":"大中型水利、水电工程建设征收土地的补偿费标准和移民安置办法，由国务院另行规定。"},{"i":52,"n":"第五十二条","txt":"建设项目可行性研究论证时，自然资源主管部门可以根据土地利用总体规划、土地利用年度计划和建设用地标准，对建设用地有关事项进行审查，并提出意见。"},{"i":53,"n":"第五十三条","txt":"经批准的建设项目需要使用国有建设用地的，建设单位应当持法律、行政法规规定的有关文件，向有批准权的县级以上人民政府自然资源主管部门提出建设用地申请，经自然资源主管部门审查，报本级人民政府批准。"},{"i":54,"n":"第五十四条","txt":"建设单位使用国有土地，应当以出让等有偿使用方式取得；但是，下列建设用地，经县级以上人民政府依法批准，可以以划拨方式取得："},{"i":55,"n":"第五十五条","txt":"以出让等有偿使用方式取得国有土地使用权的建设单位，按照国务院规定的标准和办法，缴纳土地使用权出让金等土地有偿使用费和其他费用后，方可使用土地。"},{"i":56,"n":"第五十六条","txt":"建设单位使用国有土地的，应当按照土地使用权出让等有偿使用合同的约定或者土地使用权划拨批准文件的规定使用土地；确需改变该幅土地建设用途的，应当经有关人民政府自然资源主管部门同意，报原批准用地的人民政府批准。其中，在城市规划区内改变土地用途的，在报批前，应当先经有关城市规划行政主管部门同意。"},{"i":57,"n":"第五十七条","txt":"建设项目施工和地质勘查需要临时使用国有土地或者农民集体所有的土地的，由县级以上人民政府自然资源主管部门批准。其中，在城市规划区内的临时用地，在报批前，应当先经有关城市规划行政主管部门同意。土地使用者应当根据土地权属，与有关自然资源主管部门或者农村集体经济组织、村民委员会签订临时使用土地合同，并按照合同的约定支付临时使用土地补偿费。"},{"i":58,"n":"第五十八条","txt":"有下列情形之一的，由有关人民政府自然资源主管部门报经原批准用地的人民政府或者有批准权的人民政府批准，可以收回国有土地使用权："},{"i":59,"n":"第五十九条","txt":"乡镇企业、乡（镇）村公共设施、公益事业、农村村民住宅等乡（镇）村建设，应当按照村庄和集镇规划，合理布局，综合开发，配套建设；建设用地，应当符合乡（镇）土地利用总体规划和土地利用年度计划，并依照本法第四十四条、第六十条、第六十一条、第六十二条的规定办理审批手续。"},{"i":60,"n":"第六十条","txt":"农村集体经济组织使用乡（镇）土地利用总体规划确定的建设用地兴办企业或者与其他单位、个人以土地使用权入股、联营等形式共同举办企业的，应当持有关批准文件，向县级以上地方人民政府自然资源主管部门提出申请，按照省、自治区、直辖市规定的批准权限，由县级以上地方人民政府批准；其中，涉及占用农用地的，依照本法第四十四条的规定办理审批手续。"},{"i":61,"n":"第六十一条","txt":"乡（镇）村公共设施、公益事业建设，需要使用土地的，经乡（镇）人民政府审核，向县级以上地方人民政府自然资源主管部门提出申请，按照省、自治区、直辖市规定的批准权限，由县级以上地方人民政府批准；其中，涉及占用农用地的，依照本法第四十四条的规定办理审批手续。"},{"i":62,"n":"第六十二条","txt":"农村村民一户只能拥有一处宅基地，其宅基地的面积不得超过省、自治区、直辖市规定的标准。"},{"i":63,"n":"第六十三条","txt":"土地利用总体规划、城乡规划确定为工业、商业等经营性用途，并经依法登记的集体经营性建设用地，土地所有权人可以通过出让、出租等方式交由单位或者个人使用，并应当签订书面合同，载明土地界址、面积、动工期限、使用期限、土地用途、规划条件和双方其他权利义务。"},{"i":64,"n":"第六十四条","txt":"集体建设用地的使用者应当严格按照土地利用总体规划、城乡规划确定的用途使用土地。"},{"i":65,"n":"第六十五条","txt":"在土地利用总体规划制定前已建的不符合土地利用总体规划确定的用途的建筑物、构筑物，不得重建、扩建。"},{"i":66,"n":"第六十六条","txt":"有下列情形之一的，农村集体经济组织报经原批准用地的人民政府批准，可以收回土地使用权："},{"i":67,"n":"第六十七条","txt":"县级以上人民政府自然资源主管部门对违反土地管理法律、法规的行为进行监督检查。"},{"i":68,"n":"第六十八条","txt":"县级以上人民政府自然资源主管部门履行监督检查职责时，有权采取下列措施："},{"i":69,"n":"第六十九条","txt":"土地管理监督检查人员履行职责，需要进入现场进行勘测、要求有关单位或者个人提供文件、资料和作出说明的，应当出示土地管理监督检查证件。"},{"i":70,"n":"第七十条","txt":"有关单位和个人对县级以上人民政府自然资源主管部门就土地违法行为进行的监督检查应当支持与配合，并提供工作方便，不得拒绝与阻碍土地管理监督检查人员依法执行职务。"},{"i":71,"n":"第七十一条","txt":"县级以上人民政府自然资源主管部门在监督检查工作中发现国家工作人员的违法行为，依法应当给予处分的，应当依法予以处理；自己无权处理的，应当依法移送监察机关或者有关机关处理。"},{"i":72,"n":"第七十二条","txt":"县级以上人民政府自然资源主管部门在监督检查工作中发现土地违法行为构成犯罪的，应当将案件移送有关机关，依法追究刑事责任；尚不构成犯罪的，应当依法给予行政处罚。"},{"i":73,"n":"第七十三条","txt":"依照本法规定应当给予行政处罚，而有关自然资源主管部门不给予行政处罚的，上级人民政府自然资源主管部门有权责令有关自然资源主管部门作出行政处罚决定或者直接给予行政处罚，并给予有关自然资源主管部门的负责人处分。"},{"i":74,"n":"第七十四条","txt":"买卖或者以其他形式非法转让土地的，由县级以上人民政府自然资源主管部门没收违法所得；对违反土地利用总体规划擅自将农用地改为建设用地的，限期拆除在非法转让的土地上新建的建筑物和其他设施，恢复土地原状，对符合土地利用总体规划的，没收在非法转让的土地上新建的建筑物和其他设施；可以并处罚款；对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":75,"n":"第七十五条","txt":"违反本法规定，占用耕地建窑、建坟或者擅自在耕地上建房、挖砂、采石、采矿、取土等，破坏种植条件的，或者因开发土地造成土地荒漠化、盐渍化的，由县级以上人民政府自然资源主管部门、农业农村主管部门等按照职责责令限期改正或者治理，可以并处罚款；构成犯罪的，依法追究刑事责任。"},{"i":76,"n":"第七十六条","txt":"违反本法规定，拒不履行土地复垦义务的，由县级以上人民政府自然资源主管部门责令限期改正；逾期不改正的，责令缴纳复垦费，专项用于土地复垦，可以处以罚款。"},{"i":77,"n":"第七十七条","txt":"未经批准或者采取欺骗手段骗取批准，非法占用土地的，由县级以上人民政府自然资源主管部门责令退还非法占用的土地，对违反土地利用总体规划擅自将农用地改为建设用地的，限期拆除在非法占用的土地上新建的建筑物和其他设施，恢复土地原状，对符合土地利用总体规划的，没收在非法占用的土地上新建的建筑物和其他设施，可以并处罚款；对非法占用土地单位的直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":78,"n":"第七十八条","txt":"农村村民未经批准或者采取欺骗手段骗取批准，非法占用土地建住宅的，由县级以上人民政府农业农村主管部门责令退还非法占用的土地，限期拆除在非法占用的土地上新建的房屋。"},{"i":79,"n":"第七十九条","txt":"无权批准征收、使用土地的单位或者个人非法批准占用土地的，超越批准权限非法批准占用土地的，不按照土地利用总体规划确定的用途批准用地的，或者违反法律规定的程序批准占用、征收土地的，其批准文件无效，对非法批准征收、使用土地的直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。非法批准、使用的土地应当收回，有关当事人拒不归还的，以非法占用土地论处。"},{"i":80,"n":"第八十条","txt":"侵占、挪用被征收土地单位的征地补偿费用和其他有关费用，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":81,"n":"第八十一条","txt":"依法收回国有土地使用权当事人拒不交出土地的，临时使用土地期满拒不归还的，或者不按照批准的用途使用国有土地的，由县级以上人民政府自然资源主管部门责令交还土地，处以罚款。"},{"i":82,"n":"第八十二条","txt":"擅自将农民集体所有的土地通过出让、转让使用权或者出租等方式用于非农业建设，或者违反本法规定，将集体经营性建设用地通过出让、出租等方式交由单位或者个人使用的，由县级以上人民政府自然资源主管部门责令限期改正，没收违法所得，并处罚款。"},{"i":83,"n":"第八十三条","txt":"依照本法规定，责令限期拆除在非法占用的土地上新建的建筑物和其他设施的，建设单位或者个人必须立即停止施工，自行拆除；对继续施工的，作出处罚决定的机关有权制止。建设单位或者个人对责令限期拆除的行政处罚决定不服的，可以在接到责令限期拆除决定之日起十五日内，向人民法院起诉；期满不起诉又不自行拆除的，由作出处罚决定的机关依法申请人民法院强制执行，费用由违法者承担。"},{"i":84,"n":"第八十四条","txt":"自然资源主管部门、农业农村主管部门的工作人员玩忽职守、滥用职权、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":85,"n":"第八十五条","txt":"外商投资企业使用土地的，适用本法；法律另有规定的，从其规定。"},{"i":86,"n":"第八十六条","txt":"在根据本法第十八条的规定编制国土空间规划前，经依法批准的土地利用总体规划和城乡规划继续执行。"},{"i":87,"n":"第八十七条","txt":"本法自1999年1月1日起施行。"}],"xunhuanjingjicujinfa":[{"i":1,"n":"第一条","txt":"为了促进循环经济发展，提高资源利用效率，保护和改善环境，实现可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称循环经济，是指在生产、流通和消费等过程中进行的减量化、再利用、资源化活动的总称。"},{"i":3,"n":"第三条","txt":"发展循环经济是国家经济社会发展的一项重大战略，应当遵循统筹规划、合理布局，因地制宜、注重实效，政府推动、市场引导，企业实施、公众参与的方针。"},{"i":4,"n":"第四条","txt":"发展循环经济应当在技术可行、经济合理和有利于节约资源、保护环境的前提下，按照减量化优先的原则实施。"},{"i":5,"n":"第五条","txt":"国务院循环经济发展综合管理部门负责组织协调、监督管理全国循环经济发展工作；国务院生态环境等有关主管部门按照各自的职责负责有关循环经济的监督管理工作。"},{"i":6,"n":"第六条","txt":"国家制定产业政策，应当符合发展循环经济的要求。"},{"i":7,"n":"第七条","txt":"国家鼓励和支持开展循环经济科学技术的研究、开发和推广，鼓励开展循环经济宣传、教育、科学知识普及和国际合作。"},{"i":8,"n":"第八条","txt":"县级以上人民政府应当建立发展循环经济的目标责任制，采取规划、财政、投资、政府采购等措施，促进循环经济发展。"},{"i":9,"n":"第九条","txt":"企业事业单位应当建立健全管理制度，采取措施，降低资源消耗，减少废物的产生量和排放量，提高废物的再利用和资源化水平。"},{"i":10,"n":"第十条","txt":"公民应当增强节约资源和保护环境意识，合理消费，节约资源。"},{"i":11,"n":"第十一条","txt":"国家鼓励和支持行业协会在循环经济发展中发挥技术指导和服务作用。县级以上人民政府可以委托有条件的行业协会等社会组织开展促进循环经济发展的公共服务。"},{"i":12,"n":"第十二条","txt":"国务院循环经济发展综合管理部门会同国务院生态环境等有关主管部门编制全国循环经济发展规划，报国务院批准后公布施行。设区的市级以上地方人民政府循环经济发展综合管理部门会同本级人民政府生态环境等有关主管部门编制本行政区域循环经济发展规划，报本级人民政府批准后公布施行。"},{"i":13,"n":"第十三条","txt":"县级以上地方人民政府应当依据上级人民政府下达的本行政区域主要污染物排放、建设用地和用水总量控制指标，规划和调整本行政区域的产业结构，促进循环经济发展。"},{"i":14,"n":"第十四条","txt":"国务院循环经济发展综合管理部门会同国务院统计、生态环境等有关主管部门建立和完善循环经济评价指标体系。"},{"i":15,"n":"第十五条","txt":"生产列入强制回收名录的产品或者包装物的企业，必须对废弃的产品或者包装物负责回收；对其中可以利用的，由各该生产企业负责利用；对因不具备技术经济条件而不适合利用的，由各该生产企业负责无害化处置。"},{"i":16,"n":"第十六条","txt":"国家对钢铁、有色金属、煤炭、电力、石油加工、化工、建材、建筑、造纸、印染等行业年综合能源消费量、用水量超过国家规定总量的重点企业，实行能耗、水耗的重点监督管理制度。"},{"i":17,"n":"第十七条","txt":"国家建立健全循环经济统计制度，加强资源消耗、综合利用和废物产生的统计管理，并将主要统计指标定期向社会公布。"},{"i":18,"n":"第十八条","txt":"国务院循环经济发展综合管理部门会同国务院生态环境等有关主管部门，定期发布鼓励、限制和淘汰的技术、工艺、设备、材料和产品名录。"},{"i":19,"n":"第十九条","txt":"从事工艺、设备、产品及包装物设计，应当按照减少资源消耗和废物产生的要求，优先选择采用易回收、易拆解、易降解、无毒无害或者低毒低害的材料和设计方案，并应当符合有关国家标准的强制性要求。"},{"i":20,"n":"第二十条","txt":"工业企业应当采用先进或者适用的节水技术、工艺和设备，制定并实施节水计划，加强节水管理，对生产用水进行全过程控制。"},{"i":21,"n":"第二十一条","txt":"国家鼓励和支持企业使用高效节油产品。"},{"i":22,"n":"第二十二条","txt":"开采矿产资源，应当统筹规划，制定合理的开发利用方案，采用合理的开采顺序、方法和选矿工艺。采矿许可证颁发机关应当对申请人提交的开发利用方案中的开采回采率、采矿贫化率、选矿回收率、矿山水循环利用率和土地复垦率等指标依法进行审查；审查不合格的，不予颁发采矿许可证。采矿许可证颁发机关应当依法加强对开采矿产资源的监督管理。"},{"i":23,"n":"第二十三条","txt":"建筑设计、建设、施工等单位应当按照国家有关规定和标准，对其设计、建设、施工的建筑物及构筑物采用节能、节水、节地、节材的技术工艺和小型、轻型、再生产品。有条件的地区，应当充分利用太阳能、地热能、风能等可再生能源。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府及其农业等主管部门应当推进土地集约利用，鼓励和支持农业生产者采用节水、节肥、节药的先进种植、养殖和灌溉技术，推动农业机械节能，优先发展生态农业。"},{"i":25,"n":"第二十五条","txt":"国家机关及使用财政性资金的其他组织应当厉行节约、杜绝浪费，带头使用节能、节水、节地、节材和有利于保护环境的产品、设备和设施，节约使用办公用品。国务院和县级以上地方人民政府管理机关事务工作的机构会同本级人民政府有关部门制定本级国家机关等机构的用能、用水定额指标，财政部门根据该定额指标制定支出标准。"},{"i":26,"n":"第二十六条","txt":"餐饮、娱乐、宾馆等服务性企业，应当采用节能、节水、节材和有利于保护环境的产品，减少使用或者不使用浪费资源、污染环境的产品。"},{"i":27,"n":"第二十七条","txt":"国家鼓励和支持使用再生水。在有条件使用再生水的地区，限制或者禁止将自来水作为城市道路清扫、城市绿化和景观用水使用。"},{"i":28,"n":"第二十八条","txt":"国家在保障产品安全和卫生的前提下，限制一次性消费品的生产和销售。具体名录由国务院循环经济发展综合管理部门会同国务院财政、生态环境等有关主管部门制定。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府应当统筹规划区域经济布局，合理调整产业结构，促进企业在资源综合利用等领域进行合作，实现资源的高效利用和循环使用。"},{"i":30,"n":"第三十条","txt":"企业应当按照国家规定，对生产过程中产生的粉煤灰、煤矸石、尾矿、废石、废料、废气等工业废物进行综合利用。"},{"i":31,"n":"第三十一条","txt":"企业应当发展串联用水系统和循环用水系统，提高水的重复利用率。"},{"i":32,"n":"第三十二条","txt":"企业应当采用先进或者适用的回收技术、工艺和设备，对生产过程中产生的余热、余压等进行综合利用。"},{"i":33,"n":"第三十三条","txt":"建设单位应当对工程施工中产生的建筑废物进行综合利用；不具备综合利用条件的，应当委托具备条件的生产经营者进行综合利用或者无害化处置。"},{"i":34,"n":"第三十四条","txt":"国家鼓励和支持农业生产者和相关企业采用先进或者适用技术，对农作物秸秆、畜禽粪便、农产品加工业副产品、废农用薄膜等进行综合利用，开发利用沼气等生物质能源。"},{"i":35,"n":"第三十五条","txt":"县级以上人民政府及其林业草原主管部门应当积极发展生态林业，鼓励和支持林业生产者和相关企业采用木材节约和代用技术，开展林业废弃物和次小薪材、沙生灌木等综合利用，提高木材综合利用率。"},{"i":36,"n":"第三十六条","txt":"国家支持生产经营者建立产业废物交换信息系统，促进企业交流产业废物信息。"},{"i":37,"n":"第三十七条","txt":"国家鼓励和推进废物回收体系建设。"},{"i":38,"n":"第三十八条","txt":"对废电器电子产品、报废机动车船、废轮胎、废铅酸电池等特定产品进行拆解或者再利用，应当符合有关法律、行政法规的规定。"},{"i":39,"n":"第三十九条","txt":"回收的电器电子产品，经过修复后销售的，必须符合再利用产品标准，并在显著位置标识为再利用产品。"},{"i":40,"n":"第四十条","txt":"国家支持企业开展机动车零部件、工程机械、机床等产品的再制造和轮胎翻新。"},{"i":41,"n":"第四十一条","txt":"县级以上人民政府应当统筹规划建设城乡生活垃圾分类收集和资源化利用设施，建立和完善分类收集和资源化利用体系，提高生活垃圾资源化率。"},{"i":42,"n":"第四十二条","txt":"国务院和省、自治区、直辖市人民政府设立发展循环经济的有关专项资金，支持循环经济的科技研究开发、循环经济技术和产品的示范与推广、重大循环经济项目的实施、发展循环经济的信息服务等。具体办法由国务院财政部门会同国务院循环经济发展综合管理等有关主管部门制定。"},{"i":43,"n":"第四十三条","txt":"国务院和省、自治区、直辖市人民政府及其有关部门应当将循环经济重大科技攻关项目的自主创新研究、应用示范和产业化发展列入国家或者省级科技发展规划和高技术产业发展规划，并安排财政性资金予以支持。"},{"i":44,"n":"第四十四条","txt":"国家对促进循环经济发展的产业活动给予税收优惠，并运用税收等措施鼓励进口先进的节能、节水、节材等技术、设备和产品，限制在生产过程中耗能高、污染重的产品的出口。具体办法由国务院财政、税务主管部门制定。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府循环经济发展综合管理部门在制定和实施投资计划时，应当将节能、节水、节地、节材、资源综合利用等项目列为重点投资领域。"},{"i":46,"n":"第四十六条","txt":"国家实行有利于资源节约和合理利用的价格政策，引导单位和个人节约和合理使用水、电、气等资源性产品。"},{"i":47,"n":"第四十七条","txt":"国家实行有利于循环经济发展的政府采购政策。使用财政性资金进行采购的，应当优先采购节能、节水、节材和有利于保护环境的产品及再生产品。"},{"i":48,"n":"第四十八条","txt":"县级以上人民政府及其有关部门应当对在循环经济管理、科学技术研究、产品开发、示范和推广工作中做出显著成绩的单位和个人给予表彰和奖励。"},{"i":49,"n":"第四十九条","txt":"县级以上人民政府循环经济发展综合管理部门或者其他有关主管部门发现违反本法的行为或者接到对违法行为的举报后不予查处，或者有其他不依法履行监督管理职责行为的，由本级人民政府或者上一级人民政府有关主管部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":50,"n":"第五十条","txt":"生产、销售列入淘汰名录的产品、设备的，依照《中华人民共和国产品质量法》的规定处罚。"},{"i":51,"n":"第五十一条","txt":"违反本法规定，对在拆解或者处置过程中可能造成环境污染的电器电子等产品，设计使用列入国家禁止使用名录的有毒有害物质的，由县级以上地方人民政府市场监督管理部门责令限期改正；逾期不改正的，处二万元以上二十万元以下的罚款；情节严重的，依法吊销营业执照。"},{"i":52,"n":"第五十二条","txt":"违反本法规定，电力、石油加工、化工、钢铁、有色金属和建材等企业未在规定的范围或者期限内停止使用不符合国家规定的燃油发电机组或者燃油锅炉的，由县级以上地方人民政府循环经济发展综合管理部门责令限期改正；逾期不改正的，责令拆除该燃油发电机组或者燃油锅炉，并处五万元以上五十万元以下的罚款。"},{"i":53,"n":"第五十三条","txt":"违反本法规定，矿山企业未达到经依法审查确定的开采回采率、采矿贫化率、选矿回收率、矿山水循环利用率和土地复垦率等指标的，由县级以上人民政府地质矿产主管部门责令限期改正，处五万元以上五十万元以下的罚款；逾期不改正的，由采矿许可证颁发机关依法吊销采矿许可证。"},{"i":54,"n":"第五十四条","txt":"违反本法规定，在国务院或者省、自治区、直辖市人民政府规定禁止生产、销售、使用粘土砖的期限或者区域内生产、销售或者使用粘土砖的，由县级以上地方人民政府指定的部门责令限期改正；有违法所得的，没收违法所得；逾期继续生产、销售的，由地方人民政府市场监督管理部门依法吊销营业执照。"},{"i":55,"n":"第五十五条","txt":"违反本法规定，电网企业拒不收购企业利用余热、余压、煤层气以及煤矸石、煤泥、垃圾等低热值燃料生产的电力的，由国家电力监管机构责令限期改正；造成企业损失的，依法承担赔偿责任。"},{"i":56,"n":"第五十六条","txt":"违反本法规定，有下列行为之一的，由地方人民政府市场监督管理部门责令限期改正，可以处五千元以上五万元以下的罚款；逾期不改正的，依法吊销营业执照；造成损失的，依法承担赔偿责任："},{"i":57,"n":"第五十七条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"本法自2009年1月1日起施行。"}],"senlinfa":[{"i":1,"n":"第一条","txt":"为了践行绿水青山就是金山银山理念，保护、培育和合理利用森林资源，加快国土绿化，保障森林生态安全，建设生态文明，实现人与自然和谐共生，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域内从事森林、林木的保护、培育、利用和森林、林木、林地的经营管理活动，适用本法。"},{"i":3,"n":"第三条","txt":"保护、培育、利用森林资源应当尊重自然、顺应自然，坚持生态优先、保护优先、保育结合、可持续发展的原则。"},{"i":4,"n":"第四条","txt":"国家实行森林资源保护发展目标责任制和考核评价制度。上级人民政府对下级人民政府完成森林资源保护发展目标和森林防火、重大林业有害生物防治工作的情况进行考核，并公开考核结果。"},{"i":5,"n":"第五条","txt":"国家采取财政、税收、金融等方面的措施，支持森林资源保护发展。各级人民政府应当保障森林生态保护修复的投入，促进林业发展。"},{"i":6,"n":"第六条","txt":"国家以培育稳定、健康、优质、高效的森林生态系统为目标，对公益林和商品林实行分类经营管理，突出主导功能，发挥多种功能，实现森林资源永续利用。"},{"i":7,"n":"第七条","txt":"国家建立森林生态效益补偿制度，加大公益林保护支持力度，完善重点生态功能区转移支付政策，指导受益地区和森林生态保护地区人民政府通过协商等方式进行生态效益补偿。"},{"i":8,"n":"第八条","txt":"国务院和省、自治区、直辖市人民政府可以依照国家对民族自治地方自治权的规定，对民族自治地方的森林保护和林业发展实行更加优惠的政策。"},{"i":9,"n":"第九条","txt":"国务院林业主管部门主管全国林业工作。县级以上地方人民政府林业主管部门，主管本行政区域的林业工作。"},{"i":10,"n":"第十条","txt":"植树造林、保护森林，是公民应尽的义务。各级人民政府应当组织开展全民义务植树活动。"},{"i":11,"n":"第十一条","txt":"国家采取措施，鼓励和支持林业科学研究，推广先进适用的林业技术，提高林业科学技术水平。"},{"i":12,"n":"第十二条","txt":"各级人民政府应当加强森林资源保护的宣传教育和知识普及工作，鼓励和支持基层群众性自治组织、新闻媒体、林业企业事业单位、志愿者等开展森林资源保护宣传活动。"},{"i":13,"n":"第十三条","txt":"对在造林绿化、森林保护、森林经营管理以及林业科学研究等方面成绩显著的组织或者个人，按照国家有关规定给予表彰、奖励。"},{"i":14,"n":"第十四条","txt":"森林资源属于国家所有，由法律规定属于集体所有的除外。"},{"i":15,"n":"第十五条","txt":"林地和林地上的森林、林木的所有权、使用权，由不动产登记机构统一登记造册，核发证书。国务院确定的国家重点林区（以下简称重点林区）的森林、林木和林地，由国务院自然资源主管部门负责登记。"},{"i":16,"n":"第十六条","txt":"国家所有的林地和林地上的森林、林木可以依法确定给林业经营者使用。林业经营者依法取得的国有林地和林地上的森林、林木的使用权，经批准可以转让、出租、作价出资等。具体办法由国务院制定。"},{"i":17,"n":"第十七条","txt":"集体所有和国家所有依法由农民集体使用的林地（以下简称集体林地）实行承包经营的，承包方享有林地承包经营权和承包林地上的林木所有权，合同另有约定的从其约定。承包方可以依法采取出租（转包）、入股、转让等方式流转林地经营权、林木所有权和使用权。"},{"i":18,"n":"第十八条","txt":"未实行承包经营的集体林地以及林地上的林木，由农村集体经济组织统一经营。经本集体经济组织成员的村民会议三分之二以上成员或者三分之二以上村民代表同意并公示，可以通过招标、拍卖、公开协商等方式依法流转林地经营权、林木所有权和使用权。"},{"i":19,"n":"第十九条","txt":"集体林地经营权流转应当签订书面合同。林地经营权流转合同一般包括流转双方的权利义务、流转期限、流转价款及支付方式、流转期限届满林地上的林木和固定生产设施的处置、违约责任等内容。"},{"i":20,"n":"第二十条","txt":"国有企业事业单位、机关、团体、部队营造的林木，由营造单位管护并按照国家规定支配林木收益。"},{"i":21,"n":"第二十一条","txt":"为了生态保护、基础设施建设等公共利益的需要，确需征收、征用林地、林木的，应当依照《中华人民共和国土地管理法》等法律、行政法规的规定办理审批手续，并给予公平、合理的补偿。"},{"i":22,"n":"第二十二条","txt":"单位之间发生的林木、林地所有权和使用权争议，由县级以上人民政府依法处理。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府应当将森林资源保护和林业发展纳入国民经济和社会发展规划。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府应当落实国土空间开发保护要求，合理规划森林资源保护利用结构和布局，制定森林资源保护发展目标，提高森林覆盖率、森林蓄积量，提升森林生态系统质量和稳定性。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府林业主管部门应当根据森林资源保护发展目标，编制林业发展规划。下级林业发展规划依据上级林业发展规划编制。"},{"i":26,"n":"第二十六条","txt":"县级以上人民政府林业主管部门可以结合本地实际，编制林地保护利用、造林绿化、森林经营、天然林保护等相关专项规划。"},{"i":27,"n":"第二十七条","txt":"国家建立森林资源调查监测制度，对全国森林资源现状及变化情况进行调查、监测和评价，并定期公布。"},{"i":28,"n":"第二十八条","txt":"国家加强森林资源保护，发挥森林蓄水保土、调节气候、改善环境、维护生物多样性和提供林产品等多种功能。"},{"i":29,"n":"第二十九条","txt":"中央和地方财政分别安排资金，用于公益林的营造、抚育、保护、管理和非国有公益林权利人的经济补偿等，实行专款专用。具体办法由国务院财政部门会同林业主管部门制定。"},{"i":30,"n":"第三十条","txt":"国家支持重点林区的转型发展和森林资源保护修复，改善生产生活条件，促进所在地区经济社会发展。重点林区按照规定享受国家重点生态功能区转移支付等政策。"},{"i":31,"n":"第三十一条","txt":"国家在不同自然地带的典型森林生态地区、珍贵动物和植物生长繁殖的林区、天然热带雨林区和具有特殊保护价值的其他天然林区，建立以国家公园为主体的自然保护地体系，加强保护管理。"},{"i":32,"n":"第三十二条","txt":"国家实行天然林全面保护制度，严格限制天然林采伐，加强天然林管护能力建设，保护和修复天然林资源，逐步提高天然林生态功能。具体办法由国务院规定。"},{"i":33,"n":"第三十三条","txt":"地方各级人民政府应当组织有关部门建立护林组织，负责护林工作；根据实际需要建设护林设施，加强森林资源保护；督促相关组织订立护林公约、组织群众护林、划定护林责任区、配备专职或者兼职护林员。"},{"i":34,"n":"第三十四条","txt":"地方各级人民政府负责本行政区域的森林防火工作，发挥群防作用；县级以上人民政府组织领导应急管理、林业、公安等部门按照职责分工密切配合做好森林火灾的科学预防、扑救和处置工作："},{"i":35,"n":"第三十五条","txt":"县级以上人民政府林业主管部门负责本行政区域的林业有害生物的监测、检疫和防治。"},{"i":36,"n":"第三十六条","txt":"国家保护林地，严格控制林地转为非林地，实行占用林地总量控制，确保林地保有量不减少。各类建设项目占用林地不得超过本行政区域的占用林地总量控制指标。"},{"i":37,"n":"第三十七条","txt":"矿藏勘查、开采以及其他各类工程建设，应当不占或者少占林地；确需占用林地的，应当经县级以上人民政府林业主管部门审核同意，依法办理建设用地审批手续。"},{"i":38,"n":"第三十八条","txt":"需要临时使用林地的，应当经县级以上人民政府林业主管部门批准；临时使用林地的期限一般不超过二年，并不得在临时使用的林地上修建永久性建筑物。"},{"i":39,"n":"第三十九条","txt":"禁止毁林开垦、采石、采砂、采土以及其他毁坏林木和林地的行为。"},{"i":40,"n":"第四十条","txt":"国家保护古树名木和珍贵树木。禁止破坏古树名木和珍贵树木及其生存的自然环境。"},{"i":41,"n":"第四十一条","txt":"各级人民政府应当加强林业基础设施建设，应用先进适用的科技手段，提高森林防火、林业有害生物防治等森林管护能力。"},{"i":42,"n":"第四十二条","txt":"国家统筹城乡造林绿化，开展大规模国土绿化行动，绿化美化城乡，推动森林城市建设，促进乡村振兴，建设美丽家园。"},{"i":43,"n":"第四十三条","txt":"各级人民政府应当组织各行各业和城乡居民造林绿化。"},{"i":44,"n":"第四十四条","txt":"国家鼓励公民通过植树造林、抚育管护、认建认养等方式参与造林绿化。"},{"i":45,"n":"第四十五条","txt":"各级人民政府组织造林绿化，应当科学规划、因地制宜，优化林种、树种结构，鼓励使用乡土树种和林木良种、营造混交林，提高造林绿化质量。"},{"i":46,"n":"第四十六条","txt":"各级人民政府应当采取以自然恢复为主、自然恢复和人工修复相结合的措施，科学保护修复森林生态系统。新造幼林地和其他应当封山育林的地方，由当地人民政府组织封山育林。"},{"i":47,"n":"第四十七条","txt":"国家根据生态保护的需要，将森林生态区位重要或者生态状况脆弱，以发挥生态效益为主要目的的林地和林地上的森林划定为公益林。未划定为公益林的林地和林地上的森林属于商品林。"},{"i":48,"n":"第四十八条","txt":"公益林由国务院和省、自治区、直辖市人民政府划定并公布。"},{"i":49,"n":"第四十九条","txt":"国家对公益林实施严格保护。"},{"i":50,"n":"第五十条","txt":"国家鼓励发展下列商品林："},{"i":51,"n":"第五十一条","txt":"商品林由林业经营者依法自主经营。在不破坏生态的前提下，可以采取集约化经营措施，合理利用森林、林木、林地，提高商品林经济效益。"},{"i":52,"n":"第五十二条","txt":"在林地上修筑下列直接为林业生产经营服务的工程设施，符合国家有关部门规定的标准的，由县级以上人民政府林业主管部门批准，不需要办理建设用地审批手续；超出标准需要占用林地的，应当依法办理建设用地审批手续："},{"i":53,"n":"第五十三条","txt":"国有林业企业事业单位应当编制森林经营方案，明确森林培育和管护的经营措施，报县级以上人民政府林业主管部门批准后实施。重点林区的森林经营方案由国务院林业主管部门批准后实施。"},{"i":54,"n":"第五十四条","txt":"国家严格控制森林年采伐量。省、自治区、直辖市人民政府林业主管部门根据消耗量低于生长量和森林分类经营管理的原则，编制本行政区域的年采伐限额，经征求国务院林业主管部门意见，报本级人民政府批准后公布实施，并报国务院备案。重点林区的年采伐限额，由国务院林业主管部门编制，报国务院批准后公布实施。"},{"i":55,"n":"第五十五条","txt":"采伐森林、林木应当遵守下列规定："},{"i":56,"n":"第五十六条","txt":"采伐林地上的林木应当申请采伐许可证，并按照采伐许可证的规定进行采伐；采伐自然保护区以外的竹林，不需要申请采伐许可证，但应当符合林木采伐技术规程。"},{"i":57,"n":"第五十七条","txt":"采伐许可证由县级以上人民政府林业主管部门核发。"},{"i":58,"n":"第五十八条","txt":"申请采伐许可证，应当提交有关采伐的地点、林种、树种、面积、蓄积、方式、更新措施和林木权属等内容的材料。超过省级以上人民政府林业主管部门规定面积或者蓄积量的，还应当提交伐区调查设计材料。"},{"i":59,"n":"第五十九条","txt":"符合林木采伐技术规程的，审核发放采伐许可证的部门应当及时核发采伐许可证。但是，审核发放采伐许可证的部门不得超过年采伐限额发放采伐许可证。"},{"i":60,"n":"第六十条","txt":"有下列情形之一的，不得核发采伐许可证："},{"i":61,"n":"第六十一条","txt":"采伐林木的组织和个人应当按照有关规定完成更新造林。更新造林的面积不得少于采伐的面积，更新造林应当达到相关技术规程规定的标准。"},{"i":62,"n":"第六十二条","txt":"国家通过贴息、林权收储担保补助等措施，鼓励和引导金融机构开展涉林抵押贷款、林农信用贷款等符合林业特点的信贷业务，扶持林权收储机构进行市场化收储担保。"},{"i":63,"n":"第六十三条","txt":"国家支持发展森林保险。县级以上人民政府依法对森林保险提供保险费补贴。"},{"i":64,"n":"第六十四条","txt":"林业经营者可以自愿申请森林认证，促进森林经营水平提高和可持续经营。"},{"i":65,"n":"第六十五条","txt":"木材经营加工企业应当建立原料和产品出入库台账。任何单位和个人不得收购、加工、运输明知是盗伐、滥伐等非法来源的林木。"},{"i":66,"n":"第六十六条","txt":"县级以上人民政府林业主管部门依照本法规定，对森林资源的保护、修复、利用、更新等进行监督检查，依法查处破坏森林资源等违法行为。"},{"i":67,"n":"第六十七条","txt":"县级以上人民政府林业主管部门履行森林资源保护监督检查职责，有权采取下列措施："},{"i":68,"n":"第六十八条","txt":"破坏森林资源造成生态环境损害的，县级以上人民政府自然资源主管部门、林业主管部门可以依法向人民法院提起诉讼，对侵权人提出损害赔偿要求。"},{"i":69,"n":"第六十九条","txt":"审计机关按照国家有关规定对国有森林资源资产进行审计监督。"},{"i":70,"n":"第七十条","txt":"县级以上人民政府林业主管部门或者其他有关国家机关未依照本法规定履行职责的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":71,"n":"第七十一条","txt":"违反本法规定，侵害森林、林木、林地的所有者或者使用者的合法权益的，依法承担侵权责任。"},{"i":72,"n":"第七十二条","txt":"违反本法规定，国有林业企业事业单位未履行保护培育森林资源义务、未编制森林经营方案或者未按照批准的森林经营方案开展森林经营活动的，由县级以上人民政府林业主管部门责令限期改正，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":73,"n":"第七十三条","txt":"违反本法规定，未经县级以上人民政府林业主管部门审核同意，擅自改变林地用途的，由县级以上人民政府林业主管部门责令限期恢复植被和林业生产条件，可以处恢复植被和林业生产条件所需费用三倍以下的罚款。"},{"i":74,"n":"第七十四条","txt":"违反本法规定，进行开垦、采石、采砂、采土或者其他活动，造成林木毁坏的，由县级以上人民政府林业主管部门责令停止违法行为，限期在原地或者异地补种毁坏株数一倍以上三倍以下的树木，可以处毁坏林木价值五倍以下的罚款；造成林地毁坏的，由县级以上人民政府林业主管部门责令停止违法行为，限期恢复植被和林业生产条件，可以处恢复植被和林业生产条件所需费用三倍以下的罚款。"},{"i":75,"n":"第七十五条","txt":"违反本法规定，擅自移动或者毁坏森林保护标志的，由县级以上人民政府林业主管部门恢复森林保护标志，所需费用由违法者承担。"},{"i":76,"n":"第七十六条","txt":"盗伐林木的，由县级以上人民政府林业主管部门责令限期在原地或者异地补种盗伐株数一倍以上五倍以下的树木，并处盗伐林木价值五倍以上十倍以下的罚款。"},{"i":77,"n":"第七十七条","txt":"违反本法规定，伪造、变造、买卖、租借采伐许可证的，由县级以上人民政府林业主管部门没收证件和违法所得，并处违法所得一倍以上三倍以下的罚款；没有违法所得的，可以处二万元以下的罚款。"},{"i":78,"n":"第七十八条","txt":"违反本法规定，收购、加工、运输明知是盗伐、滥伐等非法来源的林木的，由县级以上人民政府林业主管部门责令停止违法行为，没收违法收购、加工、运输的林木或者变卖所得，可以处违法收购、加工、运输林木价款三倍以下的罚款。"},{"i":79,"n":"第七十九条","txt":"违反本法规定，未完成更新造林任务的，由县级以上人民政府林业主管部门责令限期完成；逾期未完成的，可以处未完成造林任务所需费用二倍以下的罚款；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":80,"n":"第八十条","txt":"违反本法规定，拒绝、阻碍县级以上人民政府林业主管部门依法实施监督检查的，可以处五万元以下的罚款，情节严重的，可以责令停产停业整顿。"},{"i":81,"n":"第八十一条","txt":"违反本法规定，有下列情形之一的，由县级以上人民政府林业主管部门依法组织代为履行，代为履行所需费用由违法者承担："},{"i":82,"n":"第八十二条","txt":"公安机关按照国家有关规定，可以依法行使本法第七十四条第一款、第七十六条、第七十七条、第七十八条规定的行政处罚权。"},{"i":83,"n":"第八十三条","txt":"本法下列用语的含义是："},{"i":84,"n":"第八十四条","txt":"本法自2020年7月1日起施行。"}],"shuitubaochifa":[{"i":1,"n":"第一条","txt":"为了预防和治理水土流失，保护和合理利用水土资源，减轻水、旱、风沙灾害，改善生态环境，保障经济社会可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事水土保持活动，应当遵守本法。"},{"i":3,"n":"第三条","txt":"水土保持工作实行预防为主、保护优先、全面规划、综合治理、因地制宜、突出重点、科学管理、注重效益的方针。"},{"i":4,"n":"第四条","txt":"县级以上人民政府应当加强对水土保持工作的统一领导，将水土保持工作纳入本级国民经济和社会发展规划，对水土保持规划确定的任务，安排专项资金，并组织实施。"},{"i":5,"n":"第五条","txt":"国务院水行政主管部门主管全国的水土保持工作。"},{"i":6,"n":"第六条","txt":"各级人民政府及其有关部门应当加强水土保持宣传和教育工作，普及水土保持科学知识，增强公众的水土保持意识。"},{"i":7,"n":"第七条","txt":"国家鼓励和支持水土保持科学技术研究，提高水土保持科学技术水平，推广先进的水土保持技术，培养水土保持科学技术人才。"},{"i":8,"n":"第八条","txt":"任何单位和个人都有保护水土资源、预防和治理水土流失的义务，并有权对破坏水土资源、造成水土流失的行为进行举报。"},{"i":9,"n":"第九条","txt":"国家鼓励和支持社会力量参与水土保持工作。"},{"i":10,"n":"第十条","txt":"水土保持规划应当在水土流失调查结果及水土流失重点预防区和重点治理区划定的基础上，遵循统筹协调、分类指导的原则编制。"},{"i":11,"n":"第十一条","txt":"国务院水行政主管部门应当定期组织全国水土流失调查并公告调查结果。"},{"i":12,"n":"第十二条","txt":"县级以上人民政府应当依据水土流失调查结果划定并公告水土流失重点预防区和重点治理区。"},{"i":13,"n":"第十三条","txt":"水土保持规划的内容应当包括水土流失状况、水土流失类型区划分、水土流失防治目标、任务和措施等。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府水行政主管部门会同同级人民政府有关部门编制水土保持规划，报本级人民政府或者其授权的部门批准后，由水行政主管部门组织实施。"},{"i":15,"n":"第十五条","txt":"有关基础设施建设、矿产资源开发、城镇建设、公共服务设施建设等方面的规划，在实施过程中可能造成水土流失的，规划的组织编制机关应当在规划中提出水土流失预防和治理的对策和措施，并在规划报请审批前征求本级人民政府水行政主管部门的意见。"},{"i":16,"n":"第十六条","txt":"地方各级人民政府应当按照水土保持规划，采取封育保护、自然修复等措施，组织单位和个人植树种草，扩大林草覆盖面积，涵养水源，预防和减轻水土流失。"},{"i":17,"n":"第十七条","txt":"地方各级人民政府应当加强对取土、挖砂、采石等活动的管理，预防和减轻水土流失。"},{"i":18,"n":"第十八条","txt":"水土流失严重、生态脆弱的地区，应当限制或者禁止可能造成水土流失的生产建设活动，严格保护植物、沙壳、结皮、地衣等。"},{"i":19,"n":"第十九条","txt":"水土保持设施的所有权人或者使用权人应当加强对水土保持设施的管理与维护，落实管护责任，保障其功能正常发挥。"},{"i":20,"n":"第二十条","txt":"禁止在二十五度以上陡坡地开垦种植农作物。在二十五度以上陡坡地种植经济林的，应当科学选择树种，合理确定规模，采取水土保持措施，防止造成水土流失。"},{"i":21,"n":"第二十一条","txt":"禁止毁林、毁草开垦和采集发菜。禁止在水土流失重点预防区和重点治理区铲草皮、挖树兜或者滥挖虫草、甘草、麻黄等。"},{"i":22,"n":"第二十二条","txt":"林木采伐应当采用合理方式，严格控制皆伐；对水源涵养林、水土保持林、防风固沙林等防护林只能进行抚育和更新性质的采伐；对采伐区和集材道应当采取防止水土流失的措施，并在采伐后及时更新造林。"},{"i":23,"n":"第二十三条","txt":"在五度以上坡地植树造林、抚育幼林、种植中药材等，应当采取水土保持措施。"},{"i":24,"n":"第二十四条","txt":"生产建设项目选址、选线应当避让水土流失重点预防区和重点治理区；无法避让的，应当提高防治标准，优化施工工艺，减少地表扰动和植被损坏范围，有效控制可能造成的水土流失。"},{"i":25,"n":"第二十五条","txt":"在山区、丘陵区、风沙区以及水土保持规划确定的容易发生水土流失的其他区域开办可能造成水土流失的生产建设项目，生产建设单位应当编制水土保持方案，报县级以上人民政府水行政主管部门审批，并按照经批准的水土保持方案，采取水土流失预防和治理措施。没有能力编制水土保持方案的，应当委托具备相应技术条件的机构编制。"},{"i":26,"n":"第二十六条","txt":"依法应当编制水土保持方案的生产建设项目，生产建设单位未编制水土保持方案或者水土保持方案未经水行政主管部门批准的，生产建设项目不得开工建设。"},{"i":27,"n":"第二十七条","txt":"依法应当编制水土保持方案的生产建设项目中的水土保持设施，应当与主体工程同时设计、同时施工、同时投产使用；生产建设项目竣工验收，应当验收水土保持设施；水土保持设施未经验收或者验收不合格的，生产建设项目不得投产使用。"},{"i":28,"n":"第二十八条","txt":"依法应当编制水土保持方案的生产建设项目，其生产建设活动中排弃的砂、石、土、矸石、尾矿、废渣等应当综合利用；不能综合利用，确需废弃的，应当堆放在水土保持方案确定的专门存放地，并采取措施保证不产生新的危害。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府水行政主管部门、流域管理机构，应当对生产建设项目水土保持方案的实施情况进行跟踪检查，发现问题及时处理。"},{"i":30,"n":"第三十条","txt":"国家加强水土流失重点预防区和重点治理区的坡耕地改梯田、淤地坝等水土保持重点工程建设，加大生态修复力度。"},{"i":31,"n":"第三十一条","txt":"国家加强江河源头区、饮用水水源保护区和水源涵养区水土流失的预防和治理工作，多渠道筹集资金，将水土保持生态效益补偿纳入国家建立的生态效益补偿制度。"},{"i":32,"n":"第三十二条","txt":"开办生产建设项目或者从事其他生产建设活动造成水土流失的，应当进行治理。"},{"i":33,"n":"第三十三条","txt":"国家鼓励单位和个人按照水土保持规划参与水土流失治理，并在资金、技术、税收等方面予以扶持。"},{"i":34,"n":"第三十四条","txt":"国家鼓励和支持承包治理荒山、荒沟、荒丘、荒滩，防治水土流失，保护和改善生态环境，促进土地资源的合理开发和可持续利用，并依法保护土地承包合同当事人的合法权益。"},{"i":35,"n":"第三十五条","txt":"在水力侵蚀地区，地方各级人民政府及其有关部门应当组织单位和个人，以天然沟壑及其两侧山坡地形成的小流域为单元，因地制宜地采取工程措施、植物措施和保护性耕作等措施，进行坡耕地和沟道水土流失综合治理。"},{"i":36,"n":"第三十六条","txt":"在饮用水水源保护区，地方各级人民政府及其有关部门应当组织单位和个人，采取预防保护、自然修复和综合治理措施，配套建设植物过滤带，积极推广沼气，开展清洁小流域建设，严格控制化肥和农药的使用，减少水土流失引起的面源污染，保护饮用水水源。"},{"i":37,"n":"第三十七条","txt":"已在禁止开垦的陡坡地上开垦种植农作物的，应当按照国家有关规定退耕，植树种草；耕地短缺、退耕确有困难的，应当修建梯田或者采取其他水土保持措施。"},{"i":38,"n":"第三十八条","txt":"对生产建设活动所占用土地的地表土应当进行分层剥离、保存和利用，做到土石方挖填平衡，减少地表扰动范围；对废弃的砂、石、土、矸石、尾矿、废渣等存放地，应当采取拦挡、坡面防护、防洪排导等措施。生产建设活动结束后，应当及时在取土场、开挖面和存放地的裸露土地上植树种草、恢复植被，对闭库的尾矿库进行复垦。"},{"i":39,"n":"第三十九条","txt":"国家鼓励和支持在山区、丘陵区、风沙区以及容易发生水土流失的其他区域，采取下列有利于水土保持的措施："},{"i":40,"n":"第四十条","txt":"县级以上人民政府水行政主管部门应当加强水土保持监测工作，发挥水土保持监测工作在政府决策、经济社会发展和社会公众服务中的作用。县级以上人民政府应当保障水土保持监测工作经费。"},{"i":41,"n":"第四十一条","txt":"对可能造成严重水土流失的大中型生产建设项目，生产建设单位应当自行或者委托具备水土保持监测资质的机构，对生产建设活动造成的水土流失进行监测，并将监测情况定期上报当地水行政主管部门。"},{"i":42,"n":"第四十二条","txt":"国务院水行政主管部门和省、自治区、直辖市人民政府水行政主管部门应当根据水土保持监测情况，定期对下列事项进行公告："},{"i":43,"n":"第四十三条","txt":"县级以上人民政府水行政主管部门负责对水土保持情况进行监督检查。流域管理机构在其管辖范围内可以行使国务院水行政主管部门的监督检查职权。"},{"i":44,"n":"第四十四条","txt":"水政监督检查人员依法履行监督检查职责时，有权采取下列措施："},{"i":45,"n":"第四十五条","txt":"水政监督检查人员依法履行监督检查职责时，应当出示执法证件。被检查单位或者个人对水土保持监督检查工作应当给予配合，如实报告情况，提供有关文件、证照、资料；不得拒绝或者阻碍水政监督检查人员依法执行公务。"},{"i":46,"n":"第四十六条","txt":"不同行政区域之间发生水土流失纠纷应当协商解决；协商不成的，由共同的上一级人民政府裁决。"},{"i":47,"n":"第四十七条","txt":"水行政主管部门或者其他依照本法规定行使监督管理权的部门，不依法作出行政许可决定或者办理批准文件的，发现违法行为或者接到对违法行为的举报不予查处的，或者有其他未依照本法规定履行职责的行为的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":48,"n":"第四十八条","txt":"违反本法规定，在崩塌、滑坡危险区或者泥石流易发区从事取土、挖砂、采石等可能造成水土流失的活动的，由县级以上地方人民政府水行政主管部门责令停止违法行为，没收违法所得，对个人处一千元以上一万元以下的罚款，对单位处二万元以上二十万元以下的罚款。"},{"i":49,"n":"第四十九条","txt":"违反本法规定，在禁止开垦坡度以上陡坡地开垦种植农作物，或者在禁止开垦、开发的植物保护带内开垦、开发的，由县级以上地方人民政府水行政主管部门责令停止违法行为，采取退耕、恢复植被等补救措施；按照开垦或者开发面积，可以对个人处每平方米二元以下的罚款、对单位处每平方米十元以下的罚款。"},{"i":50,"n":"第五十条","txt":"违反本法规定，毁林、毁草开垦的，依照《中华人民共和国森林法》、《中华人民共和国草原法》的有关规定处罚。"},{"i":51,"n":"第五十一条","txt":"违反本法规定，采集发菜，或者在水土流失重点预防区和重点治理区铲草皮、挖树兜、滥挖虫草、甘草、麻黄等的，由县级以上地方人民政府水行政主管部门责令停止违法行为，采取补救措施，没收违法所得，并处违法所得一倍以上五倍以下的罚款；没有违法所得的，可以处五万元以下的罚款。"},{"i":52,"n":"第五十二条","txt":"在林区采伐林木不依法采取防止水土流失措施的，由县级以上地方人民政府林业主管部门、水行政主管部门责令限期改正，采取补救措施；造成水土流失的，由水行政主管部门按照造成水土流失的面积处每平方米二元以上十元以下的罚款。"},{"i":53,"n":"第五十三条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府水行政主管部门责令停止违法行为，限期补办手续；逾期不补办手续的，处五万元以上五十万元以下的罚款；对生产建设单位直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":54,"n":"第五十四条","txt":"违反本法规定，水土保持设施未经验收或者验收不合格将生产建设项目投产使用的，由县级以上人民政府水行政主管部门责令停止生产或者使用，直至验收合格，并处五万元以上五十万元以下的罚款。"},{"i":55,"n":"第五十五条","txt":"违反本法规定，在水土保持方案确定的专门存放地以外的区域倾倒砂、石、土、矸石、尾矿、废渣等的，由县级以上地方人民政府水行政主管部门责令停止违法行为，限期清理，按照倾倒数量处每立方米十元以上二十元以下的罚款；逾期仍不清理的，县级以上地方人民政府水行政主管部门可以指定有清理能力的单位代为清理，所需费用由违法行为人承担。"},{"i":56,"n":"第五十六条","txt":"违反本法规定，开办生产建设项目或者从事其他生产建设活动造成水土流失，不进行治理的，由县级以上人民政府水行政主管部门责令限期治理；逾期仍不治理的，县级以上人民政府水行政主管部门可以指定有治理能力的单位代为治理，所需费用由违法行为人承担。"},{"i":57,"n":"第五十七条","txt":"违反本法规定，拒不缴纳水土保持补偿费的，由县级以上人民政府水行政主管部门责令限期缴纳；逾期不缴纳的，自滞纳之日起按日加收滞纳部分万分之五的滞纳金，可以处应缴水土保持补偿费三倍以下的罚款。"},{"i":58,"n":"第五十八条","txt":"违反本法规定，造成水土流失危害的，依法承担民事责任；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":59,"n":"第五十九条","txt":"县级以上地方人民政府根据当地实际情况确定的负责水土保持工作的机构，行使本法规定的水行政主管部门水土保持工作的职责。"},{"i":60,"n":"第六十条","txt":"本法自2011年3月1日起施行。"}],"shuifa":[{"i":1,"n":"第一条","txt":"为了合理开发、利用、节约和保护水资源，防治水害，实现水资源的可持续利用，适应国民经济和社会发展的需要，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域内开发、利用、节约、保护、管理水资源，防治水害，适用本法。"},{"i":3,"n":"第三条","txt":"水资源属于国家所有。水资源的所有权由国务院代表国家行使。农村集体经济组织的水塘和由农村集体经济组织修建管理的水库中的水，归各该农村集体经济组织使用。"},{"i":4,"n":"第四条","txt":"开发、利用、节约、保护水资源和防治水害，应当全面规划、统筹兼顾、标本兼治、综合利用、讲求效益，发挥水资源的多种功能，协调好生活、生产经营和生态环境用水。"},{"i":5,"n":"第五条","txt":"县级以上人民政府应当加强水利基础设施建设，并将其纳入本级国民经济和社会发展计划。"},{"i":6,"n":"第六条","txt":"国家鼓励单位和个人依法开发、利用水资源，并保护其合法权益。开发、利用水资源的单位和个人有依法保护水资源的义务。"},{"i":7,"n":"第七条","txt":"国家对水资源依法实行取水许可制度和有偿使用制度。但是，农村集体经济组织及其成员使用本集体经济组织的水塘、水库中的水的除外。国务院水行政主管部门负责全国取水许可制度和水资源有偿使用制度的组织实施。"},{"i":8,"n":"第八条","txt":"国家厉行节约用水，大力推行节约用水措施，推广节约用水新技术、新工艺，发展节水型工业、农业和服务业，建立节水型社会。"},{"i":9,"n":"第九条","txt":"国家保护水资源，采取有效措施，保护植被，植树种草，涵养水源，防治水土流失和水体污染，改善生态环境。"},{"i":10,"n":"第十条","txt":"国家鼓励和支持开发、利用、节约、保护、管理水资源和防治水害的先进科学技术的研究、推广和应用。"},{"i":11,"n":"第十一条","txt":"在开发、利用、节约、保护、管理水资源和防治水害等方面成绩显著的单位和个人，由人民政府给予奖励。"},{"i":12,"n":"第十二条","txt":"国家对水资源实行流域管理与行政区域管理相结合的管理体制。"},{"i":13,"n":"第十三条","txt":"国务院有关部门按照职责分工，负责水资源开发、利用、节约和保护的有关工作。"},{"i":14,"n":"第十四条","txt":"国家制定全国水资源战略规划。"},{"i":15,"n":"第十五条","txt":"流域范围内的区域规划应当服从流域规划，专业规划应当服从综合规划。"},{"i":16,"n":"第十六条","txt":"制定规划，必须进行水资源综合科学考察和调查评价。水资源综合科学考察和调查评价，由县级以上人民政府水行政主管部门会同同级有关部门组织进行。"},{"i":17,"n":"第十七条","txt":"国家确定的重要江河、湖泊的流域综合规划，由国务院水行政主管部门会同国务院有关部门和有关省、自治区、直辖市人民政府编制，报国务院批准。跨省、自治区、直辖市的其他江河、湖泊的流域综合规划和区域综合规划，由有关流域管理机构会同江河、湖泊所在地的省、自治区、直辖市人民政府水行政主管部门和有关部门编制，分别经有关省、自治区、直辖市人民政府审查提出意见后，报国务院水行政主管部门审核；国务院水行政主管部门征求国务院有关部门意见后，报国务院或者其授权的部门批准。"},{"i":18,"n":"第十八条","txt":"规划一经批准，必须严格执行。"},{"i":19,"n":"第十九条","txt":"建设水工程，必须符合流域综合规划。在国家确定的重要江河、湖泊和跨省、自治区、直辖市的江河、湖泊上建设水工程，未取得有关流域管理机构签署的符合流域综合规划要求的规划同意书的，建设单位不得开工建设；在其他江河、湖泊上建设水工程，未取得县级以上地方人民政府水行政主管部门按照管理权限签署的符合流域综合规划要求的规划同意书的，建设单位不得开工建设。水工程建设涉及防洪的，依照防洪法的有关规定执行；涉及其他地区和行业的，建设单位应当事先征求有关地区和部门的意见。"},{"i":20,"n":"第二十条","txt":"开发、利用水资源，应当坚持兴利与除害相结合，兼顾上下游、左右岸和有关地区之间的利益，充分发挥水资源的综合效益，并服从防洪的总体安排。"},{"i":21,"n":"第二十一条","txt":"开发、利用水资源，应当首先满足城乡居民生活用水，并兼顾农业、工业、生态环境用水以及航运等需要。"},{"i":22,"n":"第二十二条","txt":"跨流域调水，应当进行全面规划和科学论证，统筹兼顾调出和调入流域的用水需要，防止对生态环境造成破坏。"},{"i":23,"n":"第二十三条","txt":"地方各级人民政府应当结合本地区水资源的实际情况，按照地表水与地下水统一调度开发、开源与节流相结合、节流优先和污水处理再利用的原则，合理组织开发、综合利用水资源。"},{"i":24,"n":"第二十四条","txt":"在水资源短缺的地区，国家鼓励对雨水和微咸水的收集、开发、利用和对海水的利用、淡化。"},{"i":25,"n":"第二十五条","txt":"地方各级人民政府应当加强对灌溉、排涝、水土保持工作的领导，促进农业生产发展；在容易发生盐碱化和渍害的地区，应当采取措施，控制和降低地下水的水位。"},{"i":26,"n":"第二十六条","txt":"国家鼓励开发、利用水能资源。在水能丰富的河流，应当有计划地进行多目标梯级开发。"},{"i":27,"n":"第二十七条","txt":"国家鼓励开发、利用水运资源。在水生生物洄游通道、通航或者竹木流放的河流上修建永久性拦河闸坝，建设单位应当同时修建过鱼、过船、过木设施，或者经国务院授权的部门批准采取其他补救措施，并妥善安排施工和蓄水期间的水生生物保护、航运和竹木流放，所需费用由建设单位承担。"},{"i":28,"n":"第二十八条","txt":"任何单位和个人引水、截（蓄）水、排水，不得损害公共利益和他人的合法权益。"},{"i":29,"n":"第二十九条","txt":"国家对水工程建设移民实行开发性移民的方针，按照前期补偿、补助与后期扶持相结合的原则，妥善安排移民的生产和生活，保护移民的合法权益。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府水行政主管部门、流域管理机构以及其他有关部门在制定水资源开发、利用规划和调度水资源时，应当注意维持江河的合理流量和湖泊、水库以及地下水的合理水位，维护水体的自然净化能力。"},{"i":31,"n":"第三十一条","txt":"从事水资源开发、利用、节约、保护和防治水害等水事活动，应当遵守经批准的规划；因违反规划造成江河和湖泊水域使用功能降低、地下水超采、地面沉降、水体污染的，应当承担治理责任。"},{"i":32,"n":"第三十二条","txt":"国务院水行政主管部门会同国务院环境保护行政主管部门、有关部门和有关省、自治区、直辖市人民政府，按照流域综合规划、水资源保护规划和经济社会发展要求，拟定国家确定的重要江河、湖泊的水功能区划，报国务院批准。跨省、自治区、直辖市的其他江河、湖泊的水功能区划，由有关流域管理机构会同江河、湖泊所在地的省、自治区、直辖市人民政府水行政主管部门、环境保护行政主管部门和其他有关部门拟定，分别经有关省、自治区、直辖市人民政府审查提出意见后，由国务院水行政主管部门会同国务院环境保护行政主管部门审核，报国务院或者其授权的部门批准。"},{"i":33,"n":"第三十三条","txt":"国家建立饮用水水源保护区制度。省、自治区、直辖市人民政府应当划定饮用水水源保护区，并采取措施，防止水源枯竭和水体污染，保证城乡居民饮用水安全。"},{"i":34,"n":"第三十四条","txt":"禁止在饮用水水源保护区内设置排污口。"},{"i":35,"n":"第三十五条","txt":"从事工程建设，占用农业灌溉水源、灌排工程设施，或者对原有灌溉用水、供水水源有不利影响的，建设单位应当采取相应的补救措施；造成损失的，依法给予补偿。"},{"i":36,"n":"第三十六条","txt":"在地下水超采地区，县级以上地方人民政府应当采取措施，严格控制开采地下水。在地下水严重超采地区，经省、自治区、直辖市人民政府批准，可以划定地下水禁止开采或者限制开采区。在沿海地区开采地下水，应当经过科学论证，并采取措施，防止地面沉降和海水入侵。"},{"i":37,"n":"第三十七条","txt":"禁止在江河、湖泊、水库、运河、渠道内弃置、堆放阻碍行洪的物体和种植阻碍行洪的林木及高秆作物。"},{"i":38,"n":"第三十八条","txt":"在河道管理范围内建设桥梁、码头和其他拦河、跨河、临河建筑物、构筑物，铺设跨河管道、电缆，应当符合国家规定的防洪标准和其他有关的技术要求，工程建设方案应当依照防洪法的有关规定报经有关水行政主管部门审查同意。"},{"i":39,"n":"第三十九条","txt":"国家实行河道采砂许可制度。河道采砂许可制度实施办法，由国务院规定。"},{"i":40,"n":"第四十条","txt":"禁止围湖造地。已经围垦的，应当按照国家规定的防洪标准有计划地退地还湖。"},{"i":41,"n":"第四十一条","txt":"单位和个人有保护水工程的义务，不得侵占、毁坏堤防、护岸、防汛、水文监测、水文地质监测等工程设施。"},{"i":42,"n":"第四十二条","txt":"县级以上地方人民政府应当采取措施，保障本行政区域内水工程，特别是水坝和堤防的安全，限期消除险情。水行政主管部门应当加强对水工程安全的监督管理。"},{"i":43,"n":"第四十三条","txt":"国家对水工程实施保护。国家所有的水工程应当按照国务院的规定划定工程管理和保护范围。"},{"i":44,"n":"第四十四条","txt":"国务院发展计划主管部门和国务院水行政主管部门负责全国水资源的宏观调配。全国的和跨省、自治区、直辖市的水中长期供求规划，由国务院水行政主管部门会同有关部门制订，经国务院发展计划主管部门审查批准后执行。地方的水中长期供求规划，由县级以上地方人民政府水行政主管部门会同同级有关部门依据上一级水中长期供求规划和本地区的实际情况制订，经本级人民政府发展计划主管部门审查批准后执行。"},{"i":45,"n":"第四十五条","txt":"调蓄径流和分配水量，应当依据流域规划和水中长期供求规划，以流域为单元制定水量分配方案。"},{"i":46,"n":"第四十六条","txt":"县级以上地方人民政府水行政主管部门或者流域管理机构应当根据批准的水量分配方案和年度预测来水量，制定年度水量分配方案和调度计划，实施水量统一调度；有关地方人民政府必须服从。"},{"i":47,"n":"第四十七条","txt":"国家对用水实行总量控制和定额管理相结合的制度。"},{"i":48,"n":"第四十八条","txt":"直接从江河、湖泊或者地下取用水资源的单位和个人，应当按照国家取水许可制度和水资源有偿使用制度的规定，向水行政主管部门或者流域管理机构申请领取取水许可证，并缴纳水资源费，取得取水权。但是，家庭生活和零星散养、圈养畜禽饮用等少量取水的除外。"},{"i":49,"n":"第四十九条","txt":"用水应当计量，并按照批准的用水计划用水。"},{"i":50,"n":"第五十条","txt":"各级人民政府应当推行节水灌溉方式和节水技术，对农业蓄水、输水工程采取必要的防渗漏措施，提高农业用水效率。"},{"i":51,"n":"第五十一条","txt":"工业用水应当采用先进技术、工艺和设备，增加循环用水次数，提高水的重复利用率。"},{"i":52,"n":"第五十二条","txt":"城市人民政府应当因地制宜采取有效措施，推广节水型生活用水器具，降低城市供水管网漏失率，提高生活用水效率；加强城市污水集中处理，鼓励使用再生水，提高污水再生利用率。"},{"i":53,"n":"第五十三条","txt":"新建、扩建、改建建设项目，应当制订节水措施方案，配套建设节水设施。节水设施应当与主体工程同时设计、同时施工、同时投产。"},{"i":54,"n":"第五十四条","txt":"各级人民政府应当积极采取措施，改善城乡居民的饮用水条件。"},{"i":55,"n":"第五十五条","txt":"使用水工程供应的水，应当按照国家规定向供水单位缴纳水费。供水价格应当按照补偿成本、合理收益、优质优价、公平负担的原则确定。具体办法由省级以上人民政府价格主管部门会同同级水行政主管部门或者其他供水行政主管部门依据职权制定。"},{"i":56,"n":"第五十六条","txt":"不同行政区域之间发生水事纠纷的，应当协商处理；协商不成的，由上一级人民政府裁决，有关各方必须遵照执行。在水事纠纷解决前，未经各方达成协议或者共同的上一级人民政府批准，在行政区域交界线两侧一定范围内，任何一方不得修建排水、阻水、取水和截（蓄）水工程，不得单方面改变水的现状。"},{"i":57,"n":"第五十七条","txt":"单位之间、个人之间、单位与个人之间发生的水事纠纷，应当协商解决；当事人不愿协商或者协商不成的，可以申请县级以上地方人民政府或者其授权的部门调解，也可以直接向人民法院提起民事诉讼。县级以上地方人民政府或者其授权的部门调解不成的，当事人可以向人民法院提起民事诉讼。"},{"i":58,"n":"第五十八条","txt":"县级以上人民政府或者其授权的部门在处理水事纠纷时，有权采取临时处置措施，有关各方或者当事人必须服从。"},{"i":59,"n":"第五十九条","txt":"县级以上人民政府水行政主管部门和流域管理机构应当对违反本法的行为加强监督检查并依法进行查处。"},{"i":60,"n":"第六十条","txt":"县级以上人民政府水行政主管部门、流域管理机构及其水政监督检查人员履行本法规定的监督检查职责时，有权采取下列措施："},{"i":61,"n":"第六十一条","txt":"有关单位或者个人对水政监督检查人员的监督检查工作应当给予配合，不得拒绝或者阻碍水政监督检查人员依法执行职务。"},{"i":62,"n":"第六十二条","txt":"水政监督检查人员在履行监督检查职责时，应当向被检查单位或者个人出示执法证件。"},{"i":63,"n":"第六十三条","txt":"县级以上人民政府或者上级水行政主管部门发现本级或者下级水行政主管部门在监督检查工作中有违法或者失职行为的，应当责令其限期改正。"},{"i":64,"n":"第六十四条","txt":"水行政主管部门或者其他有关部门以及水工程管理单位及其工作人员，利用职务上的便利收取他人财物、其他好处或者玩忽职守，对不符合法定条件的单位或者个人核发许可证、签署审查同意意见，不按照水量分配方案分配水量，不按照国家有关规定收取水资源费，不履行监督职责，或者发现违法行为不予查处，造成严重后果，构成犯罪的，对负有责任的主管人员和其他直接责任人员依照刑法的有关规定追究刑事责任；尚不够刑事处罚的，依法给予行政处分。"},{"i":65,"n":"第六十五条","txt":"在河道管理范围内建设妨碍行洪的建筑物、构筑物，或者从事影响河势稳定、危害河岸堤防安全和其他妨碍河道行洪的活动的，由县级以上人民政府水行政主管部门或者流域管理机构依据职权，责令停止违法行为，限期拆除违法建筑物、构筑物，恢复原状；逾期不拆除、不恢复原状的，强行拆除，所需费用由违法单位或者个人负担，并处一万元以上十万元以下的罚款。"},{"i":66,"n":"第六十六条","txt":"有下列行为之一，且防洪法未作规定的，由县级以上人民政府水行政主管部门或者流域管理机构依据职权，责令停止违法行为，限期清除障碍或者采取其他补救措施，处一万元以上五万元以下的罚款："},{"i":67,"n":"第六十七条","txt":"在饮用水水源保护区内设置排污口的，由县级以上地方人民政府责令限期拆除、恢复原状；逾期不拆除、不恢复原状的，强行拆除、恢复原状，并处五万元以上十万元以下的罚款。"},{"i":68,"n":"第六十八条","txt":"生产、销售或者在生产经营中使用国家明令淘汰的落后的、耗水量高的工艺、设备和产品的，由县级以上地方人民政府经济综合主管部门责令停止生产、销售或者使用，处二万元以上十万元以下的罚款。"},{"i":69,"n":"第六十九条","txt":"有下列行为之一的，由县级以上人民政府水行政主管部门或者流域管理机构依据职权，责令停止违法行为，限期采取补救措施，处二万元以上十万元以下的罚款；情节严重的，吊销其取水许可证："},{"i":70,"n":"第七十条","txt":"拒不缴纳、拖延缴纳或者拖欠水资源费的，由县级以上人民政府水行政主管部门或者流域管理机构依据职权，责令限期缴纳；逾期不缴纳的，从滞纳之日起按日加收滞纳部分千分之二的滞纳金，并处应缴或者补缴水资源费一倍以上五倍以下的罚款。"},{"i":71,"n":"第七十一条","txt":"建设项目的节水设施没有建成或者没有达到国家规定的要求，擅自投入使用的，由县级以上人民政府有关部门或者流域管理机构依据职权，责令停止使用，限期改正，处五万元以上十万元以下的罚款。"},{"i":72,"n":"第七十二条","txt":"有下列行为之一，构成犯罪的，依照刑法的有关规定追究刑事责任；尚不够刑事处罚，且防洪法未作规定的，由县级以上地方人民政府水行政主管部门或者流域管理机构依据职权，责令停止违法行为，采取补救措施，处一万元以上五万元以下的罚款；违反治安管理处罚法的，由公安机关依法给予治安管理处罚；给他人造成损失的，依法承担赔偿责任："},{"i":73,"n":"第七十三条","txt":"侵占、盗窃或者抢夺防汛物资，防洪排涝、农田水利、水文监测和测量以及其他水工程设备和器材，贪污或者挪用国家救灾、抢险、防汛、移民安置和补偿及其他水利建设款物，构成犯罪的，依照刑法的有关规定追究刑事责任。"},{"i":74,"n":"第七十四条","txt":"在水事纠纷发生及其处理过程中煽动闹事、结伙斗殴、抢夺或者损坏公私财物、非法限制他人人身自由，构成犯罪的，依照刑法的有关规定追究刑事责任；尚不够刑事处罚的，由公安机关依法给予治安管理处罚。"},{"i":75,"n":"第七十五条","txt":"不同行政区域之间发生水事纠纷，有下列行为之一的，对负有责任的主管人员和其他直接责任人员依法给予行政处分："},{"i":76,"n":"第七十六条","txt":"引水、截（蓄）水、排水，损害公共利益或者他人合法权益的，依法承担民事责任。"},{"i":77,"n":"第七十七条","txt":"对违反本法第三十九条有关河道采砂许可制度规定的行政处罚，由国务院规定。"},{"i":78,"n":"第七十八条","txt":"中华人民共和国缔结或者参加的与国际或者国境边界河流、湖泊有关的国际条约、协定与中华人民共和国法律有不同规定的，适用国际条约、协定的规定。但是，中华人民共和国声明保留的条款除外。"},{"i":79,"n":"第七十九条","txt":"本法所称水工程，是指在江河、湖泊和地下水源上开发、利用、控制、调配和保护水资源的各类工程。"},{"i":80,"n":"第八十条","txt":"海水的开发、利用、保护和管理，依照有关法律的规定执行。"},{"i":81,"n":"第八十一条","txt":"从事防洪活动，依照防洪法的规定执行。"},{"i":82,"n":"第八十二条","txt":"本法自2002年10月1日起施行。"}],"haiyushiyongguanlifa":[{"i":1,"n":"第一条","txt":"为了加强海域使用管理，维护国家海域所有权和海域使用权人的合法权益，促进海域的合理开发和可持续利用，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称海域，是指中华人民共和国内水、领海的水面、水体、海床和底土。"},{"i":3,"n":"第三条","txt":"海域属于国家所有，国务院代表国家行使海域所有权。任何单位或者个人不得侵占、买卖或者以其他形式非法转让海域。"},{"i":4,"n":"第四条","txt":"国家实行海洋功能区划制度。海域使用必须符合海洋功能区划。"},{"i":5,"n":"第五条","txt":"国家建立海域使用管理信息系统，对海域使用状况实施监视、监测。"},{"i":6,"n":"第六条","txt":"国家建立海域使用权登记制度，依法登记的海域使用权受法律保护。"},{"i":7,"n":"第七条","txt":"国务院海洋行政主管部门负责全国海域使用的监督管理。沿海县级以上地方人民政府海洋行政主管部门根据授权，负责本行政区毗邻海域使用的监督管理。"},{"i":8,"n":"第八条","txt":"任何单位和个人都有遵守海域使用管理法律、法规的义务，并有权对违反海域使用管理法律、法规的行为提出检举和控告。"},{"i":9,"n":"第九条","txt":"在保护和合理利用海域以及进行有关的科学研究等方面成绩显著的单位和个人，由人民政府给予奖励。"},{"i":10,"n":"第十条","txt":"国务院海洋行政主管部门会同国务院有关部门和沿海省、自治区、直辖市人民政府，编制全国海洋功能区划。"},{"i":11,"n":"第十一条","txt":"海洋功能区划按照下列原则编制："},{"i":12,"n":"第十二条","txt":"海洋功能区划实行分级审批。"},{"i":13,"n":"第十三条","txt":"海洋功能区划的修改，由原编制机关会同同级有关部门提出修改方案，报原批准机关批准；未经批准，不得改变海洋功能区划确定的海域功能。"},{"i":14,"n":"第十四条","txt":"海洋功能区划经批准后，应当向社会公布；但是，涉及国家秘密的部分除外。"},{"i":15,"n":"第十五条","txt":"养殖、盐业、交通、旅游等行业规划涉及海域使用的，应当符合海洋功能区划。"},{"i":16,"n":"第十六条","txt":"单位和个人可以向县级以上人民政府海洋行政主管部门申请使用海域。"},{"i":17,"n":"第十七条","txt":"县级以上人民政府海洋行政主管部门依据海洋功能区划，对海域使用申请进行审核，并依照本法和省、自治区、直辖市人民政府的规定，报有批准权的人民政府批准。"},{"i":18,"n":"第十八条","txt":"下列项目用海，应当报国务院审批："},{"i":19,"n":"第十九条","txt":"海域使用申请经依法批准后，国务院批准用海的，由国务院海洋行政主管部门登记造册，向海域使用申请人颁发海域使用权证书；地方人民政府批准用海的，由地方人民政府登记造册，向海域使用申请人颁发海域使用权证书。海域使用申请人自领取海域使用权证书之日起，取得海域使用权。"},{"i":20,"n":"第二十条","txt":"海域使用权除依照本法第十九条规定的方式取得外，也可以通过招标或者拍卖的方式取得。招标或者拍卖方案由海洋行政主管部门制订，报有审批权的人民政府批准后组织实施。海洋行政主管部门制订招标或者拍卖方案，应当征求同级有关部门的意见。"},{"i":21,"n":"第二十一条","txt":"颁发海域使用权证书，应当向社会公告。"},{"i":22,"n":"第二十二条","txt":"本法施行前，已经由农村集体经济组织或者村民委员会经营、管理的养殖用海，符合海洋功能区划的，经当地县级人民政府核准，可以将海域使用权确定给该农村集体经济组织或者村民委员会，由本集体经济组织的成员承包，用于养殖生产。"},{"i":23,"n":"第二十三条","txt":"海域使用权人依法使用海域并获得收益的权利受法律保护，任何单位和个人不得侵犯。"},{"i":24,"n":"第二十四条","txt":"海域使用权人在使用海域期间，未经依法批准，不得从事海洋基础测绘。"},{"i":25,"n":"第二十五条","txt":"海域使用权最高期限，按照下列用途确定："},{"i":26,"n":"第二十六条","txt":"海域使用权期限届满，海域使用权人需要继续使用海域的，应当至迟于期限届满前二个月向原批准用海的人民政府申请续期。除根据公共利益或者国家安全需要收回海域使用权的外，原批准用海的人民政府应当批准续期。准予续期的，海域使用权人应当依法缴纳续期的海域使用金。"},{"i":27,"n":"第二十七条","txt":"因企业合并、分立或者与他人合资、合作经营，变更海域使用权人的，需经原批准用海的人民政府批准。"},{"i":28,"n":"第二十八条","txt":"海域使用权人不得擅自改变经批准的海域用途；确需改变的，应当在符合海洋功能区划的前提下，报原批准用海的人民政府批准。"},{"i":29,"n":"第二十九条","txt":"海域使用权期满，未申请续期或者申请续期未获批准的，海域使用权终止。"},{"i":30,"n":"第三十条","txt":"因公共利益或者国家安全的需要，原批准用海的人民政府可以依法收回海域使用权。"},{"i":31,"n":"第三十一条","txt":"因海域使用权发生争议，当事人协商解决不成的，由县级以上人民政府海洋行政主管部门调解；当事人也可以直接向人民法院提起诉讼。"},{"i":32,"n":"第三十二条","txt":"填海项目竣工后形成的土地，属于国家所有。"},{"i":33,"n":"第三十三条","txt":"国家实行海域有偿使用制度。"},{"i":34,"n":"第三十四条","txt":"根据不同的用海性质或者情形，海域使用金可以按照规定一次缴纳或者按年度逐年缴纳。"},{"i":35,"n":"第三十五条","txt":"下列用海，免缴海域使用金："},{"i":36,"n":"第三十六条","txt":"下列用海，按照国务院财政部门和国务院海洋行政主管部门的规定，经有批准权的人民政府财政部门和海洋行政主管部门审查批准，可以减缴或者免缴海域使用金："},{"i":37,"n":"第三十七条","txt":"县级以上人民政府海洋行政主管部门应当加强对海域使用的监督检查。"},{"i":38,"n":"第三十八条","txt":"海洋行政主管部门应当加强队伍建设，提高海域使用管理监督检查人员的政治、业务素质。海域使用管理监督检查人员必须秉公执法，忠于职守，清正廉洁，文明服务，并依法接受监督。"},{"i":39,"n":"第三十九条","txt":"县级以上人民政府海洋行政主管部门履行监督检查职责时，有权采取下列措施："},{"i":40,"n":"第四十条","txt":"海域使用管理监督检查人员履行监督检查职责时，应当出示有效执法证件。"},{"i":41,"n":"第四十一条","txt":"依照法律规定行使海洋监督管理权的有关部门在海上执法时应当密切配合，互相支持，共同维护国家海域所有权和海域使用权人的合法权益。"},{"i":42,"n":"第四十二条","txt":"未经批准或者骗取批准，非法占用海域的，责令退还非法占用的海域，恢复海域原状，没收违法所得，并处非法占用海域期间内该海域面积应缴纳的海域使用金五倍以上十五倍以下的罚款；对未经批准或者骗取批准，进行围海、填海活动的，并处非法占用海域期间内该海域面积应缴纳的海域使用金十倍以上二十倍以下的罚款。"},{"i":43,"n":"第四十三条","txt":"无权批准使用海域的单位非法批准使用海域的，超越批准权限非法批准使用海域的，或者不按海洋功能区划批准使用海域的，批准文件无效，收回非法使用的海域；对非法批准使用海域的直接负责的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":44,"n":"第四十四条","txt":"违反本法第二十三条规定，阻挠、妨害海域使用权人依法使用海域的，海域使用权人可以请求海洋行政主管部门排除妨害，也可以依法向人民法院提起诉讼；造成损失的，可以依法请求损害赔偿。"},{"i":45,"n":"第四十五条","txt":"违反本法第二十六条规定，海域使用权期满，未办理有关手续仍继续使用海域的，责令限期办理，可以并处一万元以下的罚款；拒不办理的，以非法占用海域论处。"},{"i":46,"n":"第四十六条","txt":"违反本法第二十八条规定，擅自改变海域用途的，责令限期改正，没收违法所得，并处非法改变海域用途的期间内该海域面积应缴纳的海域使用金五倍以上十五倍以下的罚款；对拒不改正的，由颁发海域使用权证书的人民政府注销海域使用权证书，收回海域使用权。"},{"i":47,"n":"第四十七条","txt":"违反本法第二十九条第二款规定，海域使用权终止，原海域使用权人不按规定拆除用海设施和构筑物的，责令限期拆除；逾期拒不拆除的，处五万元以下的罚款，并由县级以上人民政府海洋行政主管部门委托有关单位代为拆除，所需费用由原海域使用权人承担。"},{"i":48,"n":"第四十八条","txt":"违反本法规定，按年度逐年缴纳海域使用金的海域使用权人不按期缴纳海域使用金的，限期缴纳；在限期内仍拒不缴纳的，由颁发海域使用权证书的人民政府注销海域使用权证书，收回海域使用权。"},{"i":49,"n":"第四十九条","txt":"违反本法规定，拒不接受海洋行政主管部门监督检查、不如实反映情况或者不提供有关资料的，责令限期改正，给予警告，可以并处二万元以下的罚款。"},{"i":50,"n":"第五十条","txt":"本法规定的行政处罚，由县级以上人民政府海洋行政主管部门依据职权决定。但是，本法已对处罚机关作出规定的除外。"},{"i":51,"n":"第五十一条","txt":"国务院海洋行政主管部门和县级以上地方人民政府违反本法规定颁发海域使用权证书，或者颁发海域使用权证书后不进行监督管理，或者发现违法行为不予查处的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分；徇私舞弊、滥用职权或者玩忽职守构成犯罪的，依法追究刑事责任。"},{"i":52,"n":"第五十二条","txt":"在中华人民共和国内水、领海使用特定海域不足三个月，可能对国防安全、海上交通安全和其他用海活动造成重大影响的排他性用海活动，参照本法有关规定办理临时海域使用证。"},{"i":53,"n":"第五十三条","txt":"军事用海的管理办法，由国务院、中央军事委员会依据本法制定。"},{"i":54,"n":"第五十四条","txt":"本法自2002年1月1日起施行。"}],"haidaobaohufa":[{"i":1,"n":"第一条","txt":"为了保护海岛及其周边海域生态系统，合理开发利用海岛自然资源，维护国家海洋权益，促进经济社会可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"从事中华人民共和国所属海岛的保护、开发利用及相关管理活动，适用本法。"},{"i":3,"n":"第三条","txt":"国家对海岛实行科学规划、保护优先、合理开发、永续利用的原则。"},{"i":4,"n":"第四条","txt":"无居民海岛属于国家所有，国务院代表国家行使无居民海岛所有权。"},{"i":5,"n":"第五条","txt":"国务院海洋主管部门和国务院其他有关部门依照法律和国务院规定的职责分工，负责全国有居民海岛及其周边海域生态保护工作。沿海县级以上地方人民政府海洋主管部门和其他有关部门按照各自的职责，负责本行政区域内有居民海岛及其周边海域生态保护工作。"},{"i":6,"n":"第六条","txt":"海岛的名称，由国家地名管理机构和国务院海洋主管部门按照国务院有关规定确定和发布。"},{"i":7,"n":"第七条","txt":"国务院和沿海地方各级人民政府应当加强对海岛保护的宣传教育工作，增强公民的海岛保护意识，并对在海岛保护以及有关科学研究工作中做出显著成绩的单位和个人予以奖励。"},{"i":8,"n":"第八条","txt":"国家实行海岛保护规划制度。海岛保护规划是从事海岛保护、利用活动的依据。"},{"i":9,"n":"第九条","txt":"国务院海洋主管部门会同本级人民政府有关部门、军事机关，依据国民经济和社会发展规划、全国海洋功能区划，组织编制全国海岛保护规划，报国务院审批。"},{"i":10,"n":"第十条","txt":"沿海省、自治区人民政府海洋主管部门会同本级人民政府有关部门、军事机关，依据全国海岛保护规划、省域城镇体系规划和省、自治区土地利用总体规划，组织编制省域海岛保护规划，报省、自治区人民政府审批，并报国务院备案。"},{"i":11,"n":"第十一条","txt":"省、自治区人民政府根据实际情况，可以要求本行政区域内的沿海城市、县、镇人民政府组织编制海岛保护专项规划，并纳入城市总体规划、镇总体规划；可以要求沿海县人民政府组织编制县域海岛保护规划。"},{"i":12,"n":"第十二条","txt":"沿海县级人民政府可以组织编制全国海岛保护规划确定的可利用无居民海岛的保护和利用规划。"},{"i":13,"n":"第十三条","txt":"修改海岛保护规划，应当依照本法第九条、第十条、第十一条规定的审批程序报经批准。"},{"i":14,"n":"第十四条","txt":"国家建立完善海岛统计调查制度。国务院海洋主管部门会同有关部门拟定海岛综合统计调查计划，依法经批准后组织实施，并发布海岛统计调查公报。"},{"i":15,"n":"第十五条","txt":"国家建立海岛管理信息系统，开展海岛自然资源的调查评估，对海岛的保护与利用等状况实施监视、监测。"},{"i":16,"n":"第十六条","txt":"国务院和沿海地方各级人民政府应当采取措施，保护海岛的自然资源、自然景观以及历史、人文遗迹。"},{"i":17,"n":"第十七条","txt":"国家保护海岛植被，促进海岛淡水资源的涵养；支持有居民海岛淡水储存、海水淡化和岛外淡水引入工程设施的建设。"},{"i":18,"n":"第十八条","txt":"国家支持利用海岛开展科学研究活动。在海岛从事科学研究活动不得造成海岛及其周边海域生态系统破坏。"},{"i":19,"n":"第十九条","txt":"国家开展海岛物种登记，依法保护和管理海岛生物物种。"},{"i":20,"n":"第二十条","txt":"国家支持在海岛建立可再生能源开发利用、生态建设等实验基地。"},{"i":21,"n":"第二十一条","txt":"国家安排海岛保护专项资金，用于海岛的保护、生态修复和科学研究活动。"},{"i":22,"n":"第二十二条","txt":"国家保护设置在海岛的军事设施，禁止破坏、危害军事设施的行为。"},{"i":23,"n":"第二十三条","txt":"有居民海岛的开发、建设应当遵守有关城乡规划、环境保护、土地管理、海域使用管理、水资源和森林保护等法律、法规的规定，保护海岛及其周边海域生态系统。"},{"i":24,"n":"第二十四条","txt":"有居民海岛的开发、建设应当对海岛土地资源、水资源及能源状况进行调查评估，依法进行环境影响评价。海岛的开发、建设不得超出海岛的环境容量。新建、改建、扩建建设项目，必须符合海岛主要污染物排放、建设用地和用水总量控制指标的要求。"},{"i":25,"n":"第二十五条","txt":"在有居民海岛进行工程建设，应当坚持先规划后建设、生态保护设施优先建设或者与工程项目同步建设的原则。"},{"i":26,"n":"第二十六条","txt":"严格限制在有居民海岛沙滩建造建筑物或者设施；确需建造的，应当依照有关城乡规划、土地管理、环境保护等法律、法规的规定执行。未经依法批准在有居民海岛沙滩建造的建筑物或者设施，对海岛及其周边海域生态系统造成严重破坏的，应当依法拆除。"},{"i":27,"n":"第二十七条","txt":"严格限制填海、围海等改变有居民海岛海岸线的行为，严格限制填海连岛工程建设；确需填海、围海改变海岛海岸线，或者填海连岛的，项目申请人应当提交项目论证报告、经批准的环境影响评价报告等申请文件，依照《中华人民共和国海域使用管理法》的规定报经批准。"},{"i":28,"n":"第二十八条","txt":"未经批准利用的无居民海岛，应当维持现状；禁止采石、挖海砂、采伐林木以及进行生产、建设、旅游等活动。"},{"i":29,"n":"第二十九条","txt":"严格限制在无居民海岛采集生物和非生物样本；因教学、科学研究确需采集的，应当报经海岛所在县级以上地方人民政府海洋主管部门批准。"},{"i":30,"n":"第三十条","txt":"从事全国海岛保护规划确定的可利用无居民海岛的开发利用活动，应当遵守可利用无居民海岛保护和利用规划，采取严格的生态保护措施，避免造成海岛及其周边海域生态系统破坏。"},{"i":31,"n":"第三十一条","txt":"经批准开发利用无居民海岛的，应当依法缴纳使用金。但是，因国防、公务、教学、防灾减灾、非经营性公用基础设施建设和基础测绘、气象观测等公益事业使用无居民海岛的除外。"},{"i":32,"n":"第三十二条","txt":"经批准在可利用无居民海岛建造建筑物或者设施，应当按照可利用无居民海岛保护和利用规划限制建筑物、设施的建设总量、高度以及与海岸线的距离，使其与周围植被和景观相协调。"},{"i":33,"n":"第三十三条","txt":"无居民海岛利用过程中产生的废水，应当按照规定进行处理和排放。"},{"i":34,"n":"第三十四条","txt":"临时性利用无居民海岛的，不得在所利用的海岛建造永久性建筑物或者设施。"},{"i":35,"n":"第三十五条","txt":"在依法确定为开展旅游活动的可利用无居民海岛及其周边海域，不得建造居民定居场所，不得从事生产性养殖活动；已经存在生产性养殖活动的，应当在编制可利用无居民海岛保护和利用规划中确定相应的污染防治措施。"},{"i":36,"n":"第三十六条","txt":"国家对领海基点所在海岛、国防用途海岛、海洋自然保护区内的海岛等具有特殊用途或者特殊保护价值的海岛，实行特别保护。"},{"i":37,"n":"第三十七条","txt":"领海基点所在的海岛，应当由海岛所在省、自治区、直辖市人民政府划定保护范围，报国务院海洋主管部门备案。领海基点及其保护范围周边应当设置明显标志。"},{"i":38,"n":"第三十八条","txt":"禁止破坏国防用途无居民海岛的自然地形、地貌和有居民海岛国防用途区域及其周边的地形、地貌。"},{"i":39,"n":"第三十九条","txt":"国务院、国务院有关部门和沿海省、自治区、直辖市人民政府，根据海岛自然资源、自然景观以及历史、人文遗迹保护的需要，对具有特殊保护价值的海岛及其周边海域，依法批准设立海洋自然保护区或者海洋特别保护区。"},{"i":40,"n":"第四十条","txt":"县级以上人民政府有关部门应当依法对有居民海岛保护和开发、建设进行监督检查。"},{"i":41,"n":"第四十一条","txt":"海洋主管部门应当依法对无居民海岛保护和合理利用情况进行监督检查。"},{"i":42,"n":"第四十二条","txt":"海洋主管部门依法履行监督检查职责，有权要求被检查单位和个人就海岛利用的有关问题作出说明，提供海岛利用的有关文件和资料；有权进入被检查单位和个人所利用的海岛实施现场检查。"},{"i":43,"n":"第四十三条","txt":"检查人员必须忠于职守、秉公执法、清正廉洁、文明服务，并依法接受监督。在依法查处违反本法规定的行为时，发现国家机关工作人员有违法行为应当给予处分的，应当向其任免机关或者监察机关提出处分建议。"},{"i":44,"n":"第四十四条","txt":"海洋主管部门或者其他对海岛保护负有监督管理职责的部门，发现违法行为或者接到对违法行为的举报后不依法予以查处，或者有其他未依照本法规定履行职责的行为的，由本级人民政府或者上一级人民政府有关主管部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":45,"n":"第四十五条","txt":"违反本法规定，改变自然保护区内海岛的海岸线，填海、围海改变海岛海岸线，或者进行填海连岛的，依照《中华人民共和国海域使用管理法》的规定处罚。"},{"i":46,"n":"第四十六条","txt":"违反本法规定，采挖、破坏珊瑚、珊瑚礁，或者砍伐海岛周边海域红树林的，依照《中华人民共和国海洋环境保护法》的规定处罚。"},{"i":47,"n":"第四十七条","txt":"违反本法规定，在无居民海岛采石、挖海砂、采伐林木或者采集生物、非生物样本的，由县级以上人民政府海洋主管部门责令停止违法行为，没收违法所得，可以并处二万元以下的罚款。"},{"i":48,"n":"第四十八条","txt":"违反本法规定，进行严重改变无居民海岛自然地形、地貌的活动的，由县级以上人民政府海洋主管部门责令停止违法行为，处以五万元以上五十万元以下的罚款。"},{"i":49,"n":"第四十九条","txt":"在海岛及其周边海域违法排放污染物的，依照有关环境保护法律的规定处罚。"},{"i":50,"n":"第五十条","txt":"违反本法规定，在领海基点保护范围内进行工程建设或者其他可能改变该区域地形、地貌活动，在临时性利用的无居民海岛建造永久性建筑物或者设施，或者在依法确定为开展旅游活动的可利用无居民海岛建造居民定居场所的，由县级以上人民政府海洋主管部门责令停止违法行为，处以二万元以上二十万元以下的罚款。"},{"i":51,"n":"第五十一条","txt":"损毁或者擅自移动领海基点标志的，依法给予治安管理处罚。"},{"i":52,"n":"第五十二条","txt":"破坏、危害设置在海岛的军事设施，或者损毁、擅自移动设置在海岛的助航导航、测量、气象观测、海洋监测和地震监测等公益设施的，依照有关法律、行政法规的规定处罚。"},{"i":53,"n":"第五十三条","txt":"无权批准开发利用无居民海岛而批准，超越批准权限批准开发利用无居民海岛，或者违反海岛保护规划批准开发利用无居民海岛的，批准文件无效；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":54,"n":"第五十四条","txt":"违反本法规定，拒绝海洋主管部门监督检查，在接受监督检查时弄虚作假，或者不提供有关文件和资料的，由县级以上人民政府海洋主管部门责令改正，可以处二万元以下的罚款。"},{"i":55,"n":"第五十五条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":56,"n":"第五十六条","txt":"低潮高地的保护及相关管理活动，比照本法有关规定执行。"},{"i":57,"n":"第五十七条","txt":"本法中下列用语的含义："},{"i":58,"n":"第五十八条","txt":"本法自2010年3月1日起施行。"}],"shenhaihaidiquyuziyuankantankaifafa":[{"i":1,"n":"第一条","txt":"为了规范深海海底区域资源勘探、开发活动，推进深海科学技术研究、资源调查，保护海洋环境，促进深海海底区域资源可持续利用，维护人类共同利益，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国的公民、法人或者其他组织从事深海海底区域资源勘探、开发和相关环境保护、科学技术研究、资源调查活动，适用本法。"},{"i":3,"n":"第三条","txt":"深海海底区域资源勘探、开发活动应当坚持和平利用、合作共享、保护环境、维护人类共同利益的原则。"},{"i":4,"n":"第四条","txt":"国家制定有关深海海底区域资源勘探、开发规划，并采取经济、技术政策和措施，鼓励深海科学技术研究和资源调查，提升资源勘探、开发和海洋环境保护的能力。"},{"i":5,"n":"第五条","txt":"国务院海洋主管部门负责对深海海底区域资源勘探、开发和资源调查活动的监督管理。国务院其他有关部门按照国务院规定的职责负责相关管理工作。"},{"i":6,"n":"第六条","txt":"国家鼓励和支持在深海海底区域资源勘探、开发和相关环境保护、资源调查、科学技术研究和教育培训等方面，开展国际合作。"},{"i":7,"n":"第七条","txt":"中华人民共和国的公民、法人或者其他组织在向国际海底管理局申请从事深海海底区域资源勘探、开发活动前，应当向国务院海洋主管部门提出申请，并提交下列材料："},{"i":8,"n":"第八条","txt":"国务院海洋主管部门应当对申请者提交的材料进行审查，对于符合国家利益并具备资金、技术、装备等能力条件的，应当在六十个工作日内予以许可，并出具相关文件。"},{"i":9,"n":"第九条","txt":"承包者对勘探、开发合同区域内特定资源享有相应的专属勘探、开发权。"},{"i":10,"n":"第十条","txt":"承包者在转让勘探、开发合同的权利、义务前，或者在对勘探、开发合同作出重大变更前，应当报经国务院海洋主管部门同意。"},{"i":11,"n":"第十一条","txt":"发生或者可能发生严重损害海洋环境等事故，承包者应当立即启动应急预案，并采取下列措施："},{"i":12,"n":"第十二条","txt":"承包者应当在合理、可行的范围内，利用可获得的先进技术，采取必要措施，防止、减少、控制勘探、开发区域内的活动对海洋环境造成的污染和其他危害。"},{"i":13,"n":"第十三条","txt":"承包者应当按照勘探、开发合同的约定和要求、国务院海洋主管部门规定，调查研究勘探、开发区域的海洋状况，确定环境基线，评估勘探、开发活动可能对海洋环境的影响；制定和执行环境监测方案，监测勘探、开发活动对勘探、开发区域海洋环境的影响，并保证监测设备正常运行，保存原始监测记录。"},{"i":14,"n":"第十四条","txt":"承包者从事勘探、开发活动应当采取必要措施，保护和保全稀有或者脆弱的生态系统，以及衰竭、受威胁或者有灭绝危险的物种和其他海洋生物的生存环境，保护海洋生物多样性，维护海洋资源的可持续利用。"},{"i":15,"n":"第十五条","txt":"国家支持深海科学技术研究和专业人才培养，将深海科学技术列入科学技术发展的优先领域，鼓励与相关产业的合作研究。"},{"i":16,"n":"第十六条","txt":"国家支持深海公共平台的建设和运行，建立深海公共平台共享合作机制，为深海科学技术研究、资源调查活动提供专业服务，促进深海科学技术交流、合作及成果共享。"},{"i":17,"n":"第十七条","txt":"国家鼓励单位和个人通过开放科学考察船舶、实验室、陈列室和其他场地、设施，举办讲座或者提供咨询等多种方式，开展深海科学普及活动。"},{"i":18,"n":"第十八条","txt":"从事深海海底区域资源调查活动的公民、法人或者其他组织，应当按照有关规定将有关资料副本、实物样本或者目录汇交国务院海洋主管部门和其他相关部门。负责接受汇交的部门应当对汇交的资料和实物样本进行登记、保管，并按照有关规定向社会提供利用。"},{"i":19,"n":"第十九条","txt":"国务院海洋主管部门应当对承包者勘探、开发活动进行监督检查。"},{"i":20,"n":"第二十条","txt":"承包者应当定期向国务院海洋主管部门报告下列履行勘探、开发合同的事项："},{"i":21,"n":"第二十一条","txt":"国务院海洋主管部门可以检查承包者用于勘探、开发活动的船舶、设施、设备以及航海日志、记录、数据等。"},{"i":22,"n":"第二十二条","txt":"承包者应当对国务院海洋主管部门的监督检查予以协助、配合。"},{"i":23,"n":"第二十三条","txt":"违反本法第七条、第九条第二款、第十条第一款规定，有下列行为之一的，国务院海洋主管部门可以撤销许可并撤回相关文件："},{"i":24,"n":"第二十四条","txt":"违反本法第八条第三款、第十条第二款、第十八条、第二十条、第二十二条规定，有下列行为之一的，由国务院海洋主管部门责令改正，处二万元以上十万元以下的罚款："},{"i":25,"n":"第二十五条","txt":"违反本法第八条第二款规定，未经许可或者未签订勘探、开发合同从事深海海底区域资源勘探、开发活动的，由国务院海洋主管部门责令停止违法行为，处十万元以上五十万元以下的罚款；有违法所得的，并处没收违法所得。"},{"i":26,"n":"第二十六条","txt":"违反本法第九条第三款、第十一条、第十二条规定，造成海洋环境污染损害或者作业区域内文物、铺设物等损害的，由国务院海洋主管部门责令停止违法行为，处五十万元以上一百万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"本法下列用语的含义："},{"i":28,"n":"第二十八条","txt":"深海海底区域资源开发活动涉税事项，依照中华人民共和国税收法律、行政法规的规定执行。"},{"i":29,"n":"第二十九条","txt":"本法自2016年5月1日起施行。"}],"yuyefa":[{"i":1,"n":"第一条","txt":"为了加强渔业资源的保护、开发和可持续利用，保障渔业生产者的合法权益，促进渔业高质量发展，适应社会主义现代化建设和人民生活需要，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国内水、滩涂、领海、专属经济区以及中华人民共和国管辖的其他海域从事养殖和捕捞水生动物、水生植物等渔业生产活动，以及渔业资源保护等活动，适用本法。"},{"i":3,"n":"第三条","txt":"渔业工作坚持中国共产党的领导，统筹发展和安全，统筹渔业资源保护与可持续利用，坚持量质并重、创新驱动、绿色发展。"},{"i":4,"n":"第四条","txt":"国家对渔业生产实行以养殖为主，养殖、捕捞、加工并举，因地制宜、各有侧重的方针，提高水产品供应保障能力。"},{"i":5,"n":"第五条","txt":"县级以上人民政府应当把渔业发展纳入国民经济和社会发展规划。"},{"i":6,"n":"第六条","txt":"国务院渔业渔政主管部门主管全国的渔业工作。"},{"i":7,"n":"第七条","txt":"国家对渔业的监督管理，实行统一领导、分级管理。"},{"i":8,"n":"第八条","txt":"国家鼓励、支持渔业科学技术研究开发和成果转化，加强渔业资源与环境监测评估，推广优良水产品种、先进技术和新型设施装备等，提高渔业科学技术水平。"},{"i":9,"n":"第九条","txt":"县级以上人民政府应当按照有关规定做好转产转业渔民的就业创业扶持、社会救助等工作，加强职业技能培训，依法维护其社会保障权益。"},{"i":10,"n":"第十条","txt":"从事渔业生产的单位应当遵守法律、法规和国家有关规定，建立健全安全生产规章制度，加强安全生产教育、培训和管理，提高安全生产水平。"},{"i":11,"n":"第十一条","txt":"渔业生产者依法自愿成立行业协会，为其成员提供生产、营销、信息、技术、培训、咨询等方面的服务，发挥协调和自律作用，维护成员和行业的合法权益。"},{"i":12,"n":"第十二条","txt":"国家鼓励渔业对外交流与合作，积极参与国际渔业治理，促进全球渔业资源科学养护和可持续利用。"},{"i":13,"n":"第十三条","txt":"外国人、外国籍渔业船舶进入中华人民共和国管辖水域，从事渔业生产或者渔业资源调查活动，应当经国务院有关主管部门批准，并遵守本法和中华人民共和国其他有关法律、法规的规定；中华人民共和国缔结或者参加的条约、协定有规定的，按照条约、协定办理。"},{"i":14,"n":"第十四条","txt":"对在保护渔业资源、发展渔业生产、进行渔业科学技术研究开发和成果转化，以及传承渔业文化等方面成绩显著的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":15,"n":"第十五条","txt":"国家鼓励单位和个人科学合理利用适于养殖的水域、滩涂发展养殖业，支持资源节约、环境友好、质量安全的养殖模式。"},{"i":16,"n":"第十六条","txt":"国家对水域、滩涂利用进行统一规划，确定可以用于养殖业的水域、滩涂，建立养殖水域、滩涂保护制度。"},{"i":17,"n":"第十七条","txt":"单位和个人使用国家所有的水域、滩涂从事养殖生产的，应当向县级以上地方人民政府渔业渔政主管部门提出申请，由本级人民政府核发养殖证，合理确定养殖期限，许可其使用该水域、滩涂从事养殖生产。核发养殖证的具体办法由国务院规定。"},{"i":18,"n":"第十八条","txt":"单位和个人因使用水域、滩涂从事养殖生产发生争议的，依照有关法律规定处理；争议解决前，任何一方不得破坏养殖生产。"},{"i":19,"n":"第十九条","txt":"县级以上地方人民政府因公共利益需要依法变更或者撤回养殖证，给单位或者个人造成财产损失的，应当给予公平、合理的补偿。"},{"i":20,"n":"第二十条","txt":"县级以上地方人民政府应当采取措施，加强对水产品生产基地和重要养殖水域、滩涂的保护。"},{"i":21,"n":"第二十一条","txt":"省级以上人民政府渔业渔政主管部门应当根据水产种质资源保护的需要，确定水产种质资源保种场，加强水产原种和优良品种的保护。"},{"i":22,"n":"第二十二条","txt":"国家鼓励和支持水产优良品种的选育、培育和推广。"},{"i":23,"n":"第二十三条","txt":"销售或者运输水产苗种，应当依照有关动植物检疫的法律、行政法规的规定实施检疫。"},{"i":24,"n":"第二十四条","txt":"水产苗种的进口、出口，应当依照有关进出境动植物检疫的法律、行政法规的规定实施检疫，防止病害传入境内和传出境外，加强生态安全风险防控。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府渔业渔政主管部门应当加强对养殖生产的技术指导和病害防治工作。"},{"i":26,"n":"第二十六条","txt":"从事养殖生产、运输、销售等活动，应当遵守本法和有关农产品质量安全、食品安全的法律、法规的规定，不得使用国家禁止使用的饵料、饲料、饲料添加剂、药物或者其他有毒有害物质，保障水产品质量安全。"},{"i":27,"n":"第二十七条","txt":"从事养殖生产应当保护水域、滩涂生态环境，科学确定养殖密度、规模等，合理投饵、投饲、使用药物，养殖排放尾水应当符合有关污染物排放标准，不得造成水域、滩涂的环境污染、生态破坏。"},{"i":28,"n":"第二十八条","txt":"水产苗种生产者、从事水产养殖的单位应当按照国务院渔业渔政主管部门的规定，如实记录水产苗种亲本引种和培育、苗种繁育生产、疫病防控、用药、投入品使用、产品销售等信息，并至少保存二年。"},{"i":29,"n":"第二十九条","txt":"养殖水生外来种、杂交种，应当向县级以上地方人民政府渔业渔政主管部门备案，制定应急处置预案，采取必要的防护措施，防止物种逃逸造成生态安全风险。"},{"i":30,"n":"第三十条","txt":"国家根据捕捞量低于渔业资源增长量的原则，确定渔业资源的总可捕捞量，实行捕捞限额制度。国务院渔业渔政主管部门依法组织渔业资源的调查和评估，为实行捕捞限额制度提供科学依据。"},{"i":31,"n":"第三十一条","txt":"国家根据捕捞能力与渔业资源可捕捞量相适应的原则，确定渔业船网工具控制指标。"},{"i":32,"n":"第三十二条","txt":"国家对捕捞业实行捕捞许可证制度。捕捞许可证由县级以上人民政府渔业渔政主管部门批准发放。"},{"i":33,"n":"第三十三条","txt":"取得捕捞许可证，应当具备下列条件："},{"i":34,"n":"第三十四条","txt":"从事捕捞作业的单位和个人，应当按照捕捞许可证规定的作业类型、场所、时限、渔具数量和捕捞限额等进行作业。"},{"i":35,"n":"第三十五条","txt":"渔业船舶应当符合适航要求，按照有关规定安装安全通信导航、船位监测、消防、救生、污染防治等设施设备并确保处于良好运行状态，足额配备符合条件的渔业船员，依法办理安全生产责任保险。"},{"i":36,"n":"第三十六条","txt":"制造、改造、购置、进口的渔业船舶应当经船舶检验机构检验合格后，方可下水、作业。具体管理办法由国务院制定。"},{"i":37,"n":"第三十七条","txt":"禁止无船名船号、无渔业船舶证书、无船籍港的船舶从事捕捞作业。"},{"i":38,"n":"第三十八条","txt":"渔港建设应当符合国家统一规划，实行谁投资谁受益的原则。"},{"i":39,"n":"第三十九条","txt":"国家采取措施鼓励、扶持远洋渔业的可持续发展，加强与周边邻国渔业协作，共同养护渔业资源。"},{"i":40,"n":"第四十条","txt":"国家加强重要渔业水域保护。海洋重要渔业水域由国务院渔业渔政主管部门征求国务院交通运输、自然资源、生态环境等部门意见后划定并公布；其他重要渔业水域由省、自治区、直辖市人民政府渔业渔政主管部门征求同级水行政、交通运输、自然资源、生态环境等部门意见后划定并公布。"},{"i":41,"n":"第四十一条","txt":"国家保护水产种质资源及其生存环境，并在具有较高经济价值和遗传育种价值的水产种质资源的主要生长繁育区域建立水产种质资源保护区。"},{"i":42,"n":"第四十二条","txt":"国家加强对水产种质资源的调查、收集、整理、鉴定、登记、保存，建立水产种质资源库。"},{"i":43,"n":"第四十三条","txt":"县级以上人民政府渔业渔政主管部门应当因地制宜采取增殖放流、建设海洋牧场、投放人工鱼礁、种植海藻场或者海草床等措施，增殖渔业资源，修复渔业水域生态环境。"},{"i":44,"n":"第四十四条","txt":"省级以上人民政府渔业渔政主管部门根据渔业资源状况、水生生物繁殖生长规律以及重点水生生物物种、水产种质资源保护等方面的需要，科学论证、设立并公布禁渔区、禁渔期，明确禁渔的区域范围、起止时间和禁止作业类型等，并加强宣传教育。"},{"i":45,"n":"第四十五条","txt":"禁止使用炸鱼、毒鱼、电鱼等破坏渔业资源和渔业水域生态环境的方法进行捕捞。禁止携带炸鱼、毒鱼、电鱼等破坏渔业资源和渔业水域生态环境的装置、器具等进入渔业水域。"},{"i":46,"n":"第四十六条","txt":"禁止捕捞有重要经济价值的水生动物苗种或者禁捕的怀卵亲本；捕捞作业时误捕的，应当及时放生；因科学研究、养殖、捕捞过坝、增殖放流或者其他特殊需要确需捕捞的，应当经省级以上人民政府渔业渔政主管部门批准，在指定的区域和时间内，按照限额捕捞。"},{"i":47,"n":"第四十七条","txt":"在重要渔业水域开展建闸、筑坝、航道建设、港口建设等工程建设，其生态环境影响评价文件应当包括对渔业资源和渔业水域生态环境影响的内容；涉及水产种质资源保护区的，应当就其对渔业资源和渔业水域生态环境的影响编制专题论证报告。生态环境主管部门审查相关生态环境影响评价文件时，应当征求同级渔业渔政主管部门意见。"},{"i":48,"n":"第四十八条","txt":"对用于渔业并兼有调蓄、灌溉等功能的水体，水行政、渔业渔政等部门应当确定渔业资源保护和渔业生产所需的最低水位线。"},{"i":49,"n":"第四十九条","txt":"禁止围湖造田。重要的水产苗种基地和养殖场所不得围垦。"},{"i":50,"n":"第五十条","txt":"进行水下爆破、勘探、采砂、施工等作业，对渔业资源有严重影响的，作业单位应当事先同县级以上地方人民政府渔业渔政主管部门协商，采取措施，防止或者减少对渔业资源的损害；造成渔业资源损失的，依法给予赔偿。"},{"i":51,"n":"第五十一条","txt":"各级人民政府应当采取措施，保护和改善渔业水域生态环境，防治污染。"},{"i":52,"n":"第五十二条","txt":"国家对珍贵、濒危水生野生动物实行重点保护，防止其灭绝。禁止捕杀、伤害国家重点保护的水生野生动物；因科学研究、种群调控、疫源疫病监测或者其他特殊需要确需捕捞的，依照有关野生动物保护等法律、行政法规的规定执行。"},{"i":53,"n":"第五十三条","txt":"渔业执法机构应当加强对渔业工作的监督检查，及时查处违法行为。"},{"i":54,"n":"第五十四条","txt":"机动渔船底拖网禁渔区线外侧海域和特定渔业资源渔场的渔业生产作业等活动，由海警机构依照《中华人民共和国海警法》的规定实施监督检查。海警机构依法实施监督检查，可以采取本法第五十三条规定的措施。"},{"i":55,"n":"第五十五条","txt":"渔业执法人员实施监督检查，应当遵守执法规范，不得少于二人，并按照规定着制式服装，出示执法证件。"},{"i":56,"n":"第五十六条","txt":"船舶进出渔港，应当按照有关规定报告并服从调度。"},{"i":57,"n":"第五十七条","txt":"远洋渔业船舶应当从国家对外开放口岸、国务院或者国务院授权的部门批准的口岸出境入境，并按照有关规定接受口岸检疫、检查。"},{"i":58,"n":"第五十八条","txt":"渔业执法机构依照有关法律、行政法规以及中华人民共和国缔结或者参加的条约、协定的规定，对外国籍渔业船舶实施港口国、沿岸国监督检查。"},{"i":59,"n":"第五十九条","txt":"外国籍渔业船舶以及装载渔获物的相关船舶到中华人民共和国港口装卸渔获物，应当经有关港口主管部门批准，并到国家对外开放口岸、国务院或者国务院授权的部门批准的港口停泊，按照有关规定接受口岸检疫、检查。"},{"i":60,"n":"第六十条","txt":"国务院渔业渔政主管部门应当会同有关部门加强渔业信用体系建设，按照国家有关规定建立信用记录制度。"},{"i":61,"n":"第六十一条","txt":"渔业执法机构及其工作人员不得参与渔业生产经营活动。"},{"i":62,"n":"第六十二条","txt":"县级以上人民政府渔业渔政主管部门与交通运输主管部门应当按照职责分工，加强协作，共同防范渔业船舶和商船碰撞事故发生，保障相关人员生命财产安全。"},{"i":63,"n":"第六十三条","txt":"渔业执法机构、海警机构与有关部门、机构根据实际需要建立协同执法机制，加强信息共享和执法配合。"},{"i":64,"n":"第六十四条","txt":"任何单位和个人对违反本法的行为，有权向渔业执法机构或者海警机构举报。接到举报的机构应当及时依法处理。"},{"i":65,"n":"第六十五条","txt":"未依法取得养殖证擅自在国家所有的水域、滩涂从事养殖生产的，责令限期改正，补办养殖证或者拆除养殖设施并恢复原状；逾期不改正的，依法强制拆除、代为恢复原状，所需费用由违法者承担。"},{"i":66,"n":"第六十六条","txt":"未依法取得水产苗种生产许可证从事水产苗种生产活动或者生产、经营未经审定的水产新品种苗种的，责令停止违法行为，没收水产苗种和违法所得，并处水产苗种价值一倍以上十倍以下的罚款。"},{"i":67,"n":"第六十七条","txt":"养殖水生外来种、杂交种，未向县级以上地方人民政府渔业渔政主管部门备案或者未制定应急处置预案的，责令限期改正；逾期不改正的，处五万元以下的罚款。"},{"i":68,"n":"第六十八条","txt":"制造、改造应当取得而未取得渔业船网工具指标的渔业船舶的，责令停止违法行为，没收违法所得，没收制造、改造的渔业船舶及其设备、部件和材料；情节严重的，并处船舶价值二倍以下的罚款。对委托制造、改造者，处船舶价值一倍以下的罚款。"},{"i":69,"n":"第六十九条","txt":"未依法取得捕捞许可证擅自进行捕捞的，没收渔获物和违法所得，并处二十万元以下的罚款；情节严重的，并处二十万元以上二百万元以下的罚款，可以没收渔具、船舶。"},{"i":70,"n":"第七十条","txt":"涂改、伪造、变造、买卖、出租、出借或者以其他形式转让捕捞许可证的，没收违法所得，吊销捕捞许可证，并处一万元以上十万元以下的罚款。"},{"i":71,"n":"第七十一条","txt":"违反本法第三十二条第四款规定，未经国务院渔业渔政主管部门批准从事捕捞作业的，予以批评教育，没收渔获物和违法所得；情节严重的，并处二百万元以下的罚款，可以没收渔具。在他国已经受过处罚的，可以减轻或者免除处罚。"},{"i":72,"n":"第七十二条","txt":"无渔业船舶证书、无船籍港且无船名船号的船舶从事捕捞作业的，没收渔获物、违法所得、渔具和船舶，可以并处船舶价值二倍以下的罚款。"},{"i":73,"n":"第七十三条","txt":"违反本法规定，有下列情形之一的，没收渔获物、违法所得和渔具，并处一万元以上十万元以下的罚款："},{"i":74,"n":"第七十四条","txt":"违反本法规定，有下列情形之一的，责令改正，处一万元以上十万元以下的罚款："},{"i":75,"n":"第七十五条","txt":"违反本法规定，有下列情形之一的，责令改正，处五万元以下的罚款；情节严重的，处五万元以上二十万元以下的罚款："},{"i":76,"n":"第七十六条","txt":"未经批准，捕捞有重要经济价值的水生动物苗种或者禁捕的怀卵亲本，或者在水产种质资源保护区内从事捕捞活动的，没收渔获物和违法所得，并处一万元以上二十万元以下的罚款；情节严重的，并处二十万元以上二百万元以下的罚款，可以没收渔具、船舶。"},{"i":77,"n":"第七十七条","txt":"使用炸鱼、毒鱼、电鱼等破坏渔业资源和渔业水域生态环境的方法进行捕捞的，没收装置、器具、有毒物质、渔获物和违法所得，并处二十万元以下的罚款；情节严重的，并处二十万元以上二百万元以下的罚款，吊销捕捞许可证，可以没收船舶。"},{"i":78,"n":"第七十八条","txt":"违反本法规定，有下列情形之一的，没收渔获物、违法所得和渔具，并处二十万元以下的罚款；情节严重的，并处二十万元以上二百万元以下的罚款，吊销捕捞许可证，可以没收船舶："},{"i":79,"n":"第七十九条","txt":"在重要渔业水域开展建闸、筑坝、航道建设、港口建设等工程建设，未按照要求开展生态环境影响评价，擅自开工建设的，依照有关生态环境保护的法律、法规的规定处理、处罚。"},{"i":80,"n":"第八十条","txt":"从事养殖生产、运输、销售等活动中使用国家禁止使用的饵料、饲料、饲料添加剂、药物或者其他有毒有害物质，在水产种质资源保护区内新建、扩建排污口或者造成渔业水域生态环境破坏、渔业污染事故的，依照有关农产品质量安全、食品安全、生态环境保护等法律、行政法规的规定处理、处罚。"},{"i":81,"n":"第八十一条","txt":"向开放水域投放水生外来种、杂交种等不符合生态要求的水生生物的，责令停止投放、限期采取补救措施，没收用于投放的水生生物，对投放者可以并处五万元以下的罚款；逾期未采取补救措施的，由渔业执法机构代为采取补救措施，所需费用由违法者承担。"},{"i":82,"n":"第八十二条","txt":"外国人、外国籍渔业船舶违反本法规定，擅自进入中华人民共和国管辖水域从事渔业生产或者渔业资源调查活动的，没收渔获物、违法所得、渔具、渔业资源调查资料和设施设备，责令其离开或者将其驱逐；情节严重的，并处二十万元以上二百万元以下的罚款；情节特别严重的，并没收船舶。"},{"i":83,"n":"第八十三条","txt":"除本法另有规定外，本法规定的行政处罚由渔业执法机构作出决定；海警机构依法进行渔业执法的行政处罚，由海警机构作出决定，需要吊销捕捞许可证的，提请发证机关吊销。"},{"i":84,"n":"第八十四条","txt":"违反本法规定，具有《中华人民共和国行政处罚法》规定的从轻、减轻或者不予处罚情形的，依照其规定从轻、减轻或者不予处罚。"},{"i":85,"n":"第八十五条","txt":"县级以上人民政府渔业渔政主管部门等有关部门及其工作人员违反本法规定，有下列情形之一的，对负有责任的领导人员和直接责任人员，依法给予处分："},{"i":86,"n":"第八十六条","txt":"违反本法规定，造成他人损害的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":87,"n":"第八十七条","txt":"本法下列用语的含义："},{"i":88,"n":"第八十八条","txt":"省、自治区、直辖市根据需要制定休闲渔业管理办法。"},{"i":89,"n":"第八十九条","txt":"在水域、滩涂以外通过设施养殖等方式进行渔业养殖的，适用本法有关规定。"},{"i":90,"n":"第九十条","txt":"本法自2026年5月1日起施行。"}],"shidibaohufa":[{"i":1,"n":"第一条","txt":"为了加强湿地保护，维护湿地生态功能及生物多样性，保障生态安全，促进生态文明建设，实现人与自然和谐共生，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域及管辖的其他海域内从事湿地保护、利用、修复及相关管理活动，适用本法。"},{"i":3,"n":"第三条","txt":"湿地保护应当坚持保护优先、严格管理、系统治理、科学修复、合理利用的原则，发挥湿地涵养水源、调节气候、改善环境、维护生物多样性等多种生态功能。"},{"i":4,"n":"第四条","txt":"县级以上人民政府应当将湿地保护纳入国民经济和社会发展规划，并将开展湿地保护工作所需经费按照事权划分原则列入预算。"},{"i":5,"n":"第五条","txt":"国务院林业草原主管部门负责湿地资源的监督管理，负责湿地保护规划和相关国家标准拟定、湿地开发利用的监督管理、湿地生态保护修复工作。国务院自然资源、水行政、住房城乡建设、生态环境、农业农村等其他有关部门，按照职责分工承担湿地保护、修复、管理有关工作。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府应当加强湿地保护协调工作。县级以上地方人民政府有关部门按照职责分工负责湿地保护、修复、管理有关工作。"},{"i":7,"n":"第七条","txt":"各级人民政府应当加强湿地保护宣传教育和科学知识普及工作，通过湿地保护日、湿地保护宣传周等开展宣传教育活动，增强全社会湿地保护意识；鼓励基层群众性自治组织、社会组织、志愿者开展湿地保护法律法规和湿地保护知识宣传活动，营造保护湿地的良好氛围。"},{"i":8,"n":"第八条","txt":"国家鼓励单位和个人依法通过捐赠、资助、志愿服务等方式参与湿地保护活动。"},{"i":9,"n":"第九条","txt":"国家支持开展湿地保护科学技术研究开发和应用推广，加强湿地保护专业技术人才培养，提高湿地保护科学技术水平。"},{"i":10,"n":"第十条","txt":"国家支持开展湿地保护科学技术、生物多样性、候鸟迁徙等方面的国际合作与交流。"},{"i":11,"n":"第十一条","txt":"任何单位和个人都有保护湿地的义务，对破坏湿地的行为有权举报或者控告，接到举报或者控告的机关应当及时处理，并依法保护举报人、控告人的合法权益。"},{"i":12,"n":"第十二条","txt":"国家建立湿地资源调查评价制度。"},{"i":13,"n":"第十三条","txt":"国家实行湿地面积总量管控制度，将湿地面积总量管控目标纳入湿地保护目标责任制。"},{"i":14,"n":"第十四条","txt":"国家对湿地实行分级管理，按照生态区位、面积以及维护生态功能、生物多样性的重要程度，将湿地分为重要湿地和一般湿地。重要湿地包括国家重要湿地和省级重要湿地，重要湿地以外的湿地为一般湿地。重要湿地依法划入生态保护红线。"},{"i":15,"n":"第十五条","txt":"国务院林业草原主管部门应当会同国务院有关部门，依据国民经济和社会发展规划、国土空间规划和生态环境保护规划编制全国湿地保护规划，报国务院或者其授权的部门批准后组织实施。"},{"i":16,"n":"第十六条","txt":"国务院林业草原、标准化主管部门会同国务院自然资源、水行政、住房城乡建设、生态环境、农业农村主管部门组织制定湿地分级分类、监测预警、生态修复等国家标准；国家标准未作规定的，可以依法制定地方标准并备案。"},{"i":17,"n":"第十七条","txt":"县级以上人民政府林业草原主管部门建立湿地保护专家咨询机制，为编制湿地保护规划、制定湿地名录、制定相关标准等提供评估论证等服务。"},{"i":18,"n":"第十八条","txt":"办理自然资源权属登记涉及湿地的，应当按照规定记载湿地的地理坐标、空间范围、类型、面积等信息。"},{"i":19,"n":"第十九条","txt":"国家严格控制占用湿地。"},{"i":20,"n":"第二十条","txt":"建设项目确需临时占用湿地的，应当依照《中华人民共和国土地管理法》、《中华人民共和国水法》、《中华人民共和国森林法》、《中华人民共和国草原法》、《中华人民共和国海域使用管理法》等有关法律法规的规定办理。临时占用湿地的期限一般不得超过二年，并不得在临时占用的湿地上修建永久性建筑物。"},{"i":21,"n":"第二十一条","txt":"除因防洪、航道、港口或者其他水工程占用河道管理范围及蓄滞洪区内的湿地外，经依法批准占用重要湿地的单位应当根据当地自然条件恢复或者重建与所占用湿地面积和质量相当的湿地；没有条件恢复、重建的，应当缴纳湿地恢复费。缴纳湿地恢复费的，不再缴纳其他相同性质的恢复费用。"},{"i":22,"n":"第二十二条","txt":"国务院林业草原主管部门应当按照监测技术规范开展国家重要湿地动态监测，及时掌握湿地分布、面积、水量、生物多样性、受威胁状况等变化信息。"},{"i":23,"n":"第二十三条","txt":"国家坚持生态优先、绿色发展，完善湿地保护制度，健全湿地保护政策支持和科技支撑机制，保障湿地生态功能和永续利用，实现生态效益、社会效益、经济效益相统一。"},{"i":24,"n":"第二十四条","txt":"省级以上人民政府及其有关部门根据湿地保护规划和湿地保护需要，依法将湿地纳入国家公园、自然保护区或者自然公园。"},{"i":25,"n":"第二十五条","txt":"地方各级人民政府及其有关部门应当采取措施，预防和控制人为活动对湿地及其生物多样性的不利影响，加强湿地污染防治，减缓人为因素和自然因素导致的湿地退化，维护湿地生态功能稳定。"},{"i":26,"n":"第二十六条","txt":"地方各级人民政府对省级重要湿地和一般湿地利用活动进行分类指导，鼓励单位和个人开展符合湿地保护要求的生态旅游、生态农业、生态教育、自然体验等活动，适度控制种植养殖等湿地利用规模。"},{"i":27,"n":"第二十七条","txt":"县级以上地方人民政府应当充分考虑保障重要湿地生态功能的需要，优化重要湿地周边产业布局。"},{"i":28,"n":"第二十八条","txt":"禁止下列破坏湿地及其生态功能的行为："},{"i":29,"n":"第二十九条","txt":"县级以上人民政府有关部门应当按照职责分工，开展湿地有害生物监测工作，及时采取有效措施预防、控制、消除有害生物对湿地生态系统的危害。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府应当加强对国家重点保护野生动植物集中分布湿地的保护。任何单位和个人不得破坏鸟类和水生生物的生存环境。"},{"i":31,"n":"第三十一条","txt":"国务院水行政主管部门和地方各级人民政府应当加强对河流、湖泊范围内湿地的管理和保护，因地制宜采取水系连通、清淤疏浚、水源涵养与水土保持等治理修复措施，严格控制河流源头和蓄滞洪区、水土流失严重区等区域的湿地开发利用活动，减轻对湿地及其生物多样性的不利影响。"},{"i":32,"n":"第三十二条","txt":"国务院自然资源主管部门和沿海地方各级人民政府应当加强对滨海湿地的管理和保护，严格管控围填滨海湿地。经依法批准的项目，应当同步实施生态保护修复，减轻对滨海湿地生态功能的不利影响。"},{"i":33,"n":"第三十三条","txt":"国务院住房城乡建设主管部门和地方各级人民政府应当加强对城市湿地的管理和保护，采取城市水系治理和生态修复等措施，提升城市湿地生态质量，发挥城市湿地雨洪调蓄、净化水质、休闲游憩、科普教育等功能。"},{"i":34,"n":"第三十四条","txt":"红树林湿地所在地县级以上地方人民政府应当组织编制红树林湿地保护专项规划，采取有效措施保护红树林湿地。"},{"i":35,"n":"第三十五条","txt":"泥炭沼泽湿地所在地县级以上地方人民政府应当制定泥炭沼泽湿地保护专项规划，采取有效措施保护泥炭沼泽湿地。"},{"i":36,"n":"第三十六条","txt":"国家建立湿地生态保护补偿制度。"},{"i":37,"n":"第三十七条","txt":"县级以上人民政府应当坚持自然恢复为主、自然恢复和人工修复相结合的原则，加强湿地修复工作，恢复湿地面积，提高湿地生态系统质量。"},{"i":38,"n":"第三十八条","txt":"县级以上人民政府组织开展湿地保护与修复，应当充分考虑水资源禀赋条件和承载能力，合理配置水资源，保障湿地基本生态用水需求，维护湿地生态功能。"},{"i":39,"n":"第三十九条","txt":"县级以上地方人民政府应当科学论证，对具备恢复条件的原有湿地、退化湿地、盐碱化湿地等，因地制宜采取措施，恢复湿地生态功能。"},{"i":40,"n":"第四十条","txt":"红树林湿地所在地县级以上地方人民政府应当对生态功能重要区域、海洋灾害风险等级较高地区、濒危物种保护区域或者造林条件较好地区的红树林湿地优先实施修复，对严重退化的红树林湿地进行抢救性修复，修复应当尽量采用本地树种。"},{"i":41,"n":"第四十一条","txt":"泥炭沼泽湿地所在地县级以上地方人民政府应当因地制宜，组织对退化泥炭沼泽湿地进行修复，并根据泥炭沼泽湿地的类型、发育状况和退化程度等，采取相应的修复措施。"},{"i":42,"n":"第四十二条","txt":"修复重要湿地应当编制湿地修复方案。"},{"i":43,"n":"第四十三条","txt":"修复重要湿地应当按照经批准的湿地修复方案进行修复。"},{"i":44,"n":"第四十四条","txt":"因违法占用、开采、开垦、填埋、排污等活动，导致湿地破坏的，违法行为人应当负责修复。违法行为人变更的，由承继其债权、债务的主体负责修复。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府林业草原、自然资源、水行政、住房城乡建设、生态环境、农业农村主管部门应当依照本法规定，按照职责分工对湿地的保护、修复、利用等活动进行监督检查，依法查处破坏湿地的违法行为。"},{"i":46,"n":"第四十六条","txt":"县级以上人民政府林业草原、自然资源、水行政、住房城乡建设、生态环境、农业农村主管部门进行监督检查，有权采取下列措施："},{"i":47,"n":"第四十七条","txt":"县级以上人民政府林业草原、自然资源、水行政、住房城乡建设、生态环境、农业农村主管部门依法履行监督检查职责，有关单位和个人应当予以配合，不得拒绝、阻碍。"},{"i":48,"n":"第四十八条","txt":"国务院林业草原主管部门应当加强对国家重要湿地保护情况的监督检查。省、自治区、直辖市人民政府林业草原主管部门应当加强对省级重要湿地保护情况的监督检查。"},{"i":49,"n":"第四十九条","txt":"国家实行湿地保护目标责任制，将湿地保护纳入地方人民政府综合绩效评价内容。"},{"i":50,"n":"第五十条","txt":"湿地的保护、修复和管理情况，应当纳入领导干部自然资源资产离任审计。"},{"i":51,"n":"第五十一条","txt":"县级以上人民政府有关部门发现破坏湿地的违法行为或者接到对违法行为的举报，不予查处或者不依法查处，或者有其他玩忽职守、滥用职权、徇私舞弊行为的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":52,"n":"第五十二条","txt":"违反本法规定，建设项目擅自占用国家重要湿地的，由县级以上人民政府林业草原等有关主管部门按照职责分工责令停止违法行为，限期拆除在非法占用的湿地上新建的建筑物、构筑物和其他设施，修复湿地或者采取其他补救措施，按照违法占用湿地的面积，处每平方米一千元以上一万元以下罚款；违法行为人不停止建设或者逾期不拆除的，由作出行政处罚决定的部门依法申请人民法院强制执行。"},{"i":53,"n":"第五十三条","txt":"建设项目占用重要湿地，未依照本法规定恢复、重建湿地的，由县级以上人民政府林业草原主管部门责令限期恢复、重建湿地；逾期未改正的，由县级以上人民政府林业草原主管部门委托他人代为履行，所需费用由违法行为人承担，按照占用湿地的面积，处每平方米五百元以上二千元以下罚款。"},{"i":54,"n":"第五十四条","txt":"违反本法规定，开（围）垦、填埋自然湿地的，由县级以上人民政府林业草原等有关主管部门按照职责分工责令停止违法行为，限期修复湿地或者采取其他补救措施，没收违法所得，并按照破坏湿地面积，处每平方米五百元以上五千元以下罚款；破坏国家重要湿地的，并按照破坏湿地面积，处每平方米一千元以上一万元以下罚款。"},{"i":55,"n":"第五十五条","txt":"违反本法规定，向湿地引进或者放生外来物种的，依照《中华人民共和国生物安全法》等有关法律法规的规定处理、处罚。"},{"i":56,"n":"第五十六条","txt":"违反本法规定，在红树林湿地内挖塘的，由县级以上人民政府林业草原等有关主管部门按照职责分工责令停止违法行为，限期修复湿地或者采取其他补救措施，按照破坏湿地面积，处每平方米一千元以上一万元以下罚款；对树木造成毁坏的，责令限期补种成活毁坏株数一倍以上三倍以下的树木，无法确定毁坏株数的，按照相同区域同类树种生长密度计算株数。"},{"i":57,"n":"第五十七条","txt":"违反本法规定开采泥炭的，由县级以上人民政府林业草原等有关主管部门按照职责分工责令停止违法行为，限期修复湿地或者采取其他补救措施，没收违法所得，并按照采挖泥炭体积，处每立方米二千元以上一万元以下罚款。"},{"i":58,"n":"第五十八条","txt":"违反本法规定，未编制修复方案修复湿地或者未按照修复方案修复湿地，造成湿地破坏的，由省级以上人民政府林业草原主管部门责令改正，处十万元以上一百万元以下罚款。"},{"i":59,"n":"第五十九条","txt":"破坏湿地的违法行为人未按照规定期限或者未按照修复方案修复湿地的，由县级以上人民政府林业草原主管部门委托他人代为履行，所需费用由违法行为人承担；违法行为人因被宣告破产等原因丧失修复能力的，由县级以上人民政府组织实施修复。"},{"i":60,"n":"第六十条","txt":"违反本法规定，拒绝、阻碍县级以上人民政府有关部门依法进行的监督检查的，处二万元以上二十万元以下罚款；情节严重的，可以责令停产停业整顿。"},{"i":61,"n":"第六十一条","txt":"违反本法规定，造成生态环境损害的，国家规定的机关或者法律规定的组织有权依法请求违法行为人承担修复责任、赔偿损失和有关费用。"},{"i":62,"n":"第六十二条","txt":"违反本法规定，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"本法下列用语的含义："},{"i":64,"n":"第六十四条","txt":"省、自治区、直辖市和设区的市、自治州可以根据本地实际，制定湿地保护具体办法。"},{"i":65,"n":"第六十五条","txt":"本法自2022年6月1日起施行。"}],"meitanfa":[{"i":1,"n":"第一条","txt":"为了合理开发利用和保护煤炭资源，规范煤炭生产、经营活动，促进和保障煤炭行业的发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域从事煤炭生产、经营活动，适用本法。"},{"i":3,"n":"第三条","txt":"煤炭资源属于国家所有。地表或者地下的煤炭资源的国家所有权，不因其依附的土地的所有权或者使用权的不同而改变。"},{"i":4,"n":"第四条","txt":"国家对煤炭开发实行统一规划、合理布局、综合利用的方针。"},{"i":5,"n":"第五条","txt":"国家依法保护煤炭资源，禁止任何乱采、滥挖破坏煤炭资源的行为。"},{"i":6,"n":"第六条","txt":"国家保护依法投资开发煤炭资源的投资者的合法权益。"},{"i":7,"n":"第七条","txt":"煤矿企业必须坚持安全第一、预防为主的安全生产方针，建立健全安全生产的责任制度和群防群治制度。"},{"i":8,"n":"第八条","txt":"各级人民政府及其有关部门和煤矿企业必须采取措施加强劳动保护，保障煤矿职工的安全和健康。"},{"i":9,"n":"第九条","txt":"国家鼓励和支持在开发利用煤炭资源过程中采用先进的科学技术和管理方法。"},{"i":10,"n":"第十条","txt":"国家维护煤矿矿区的生产秩序、工作秩序，保护煤矿企业设施。"},{"i":11,"n":"第十一条","txt":"开发利用煤炭资源，应当遵守有关环境保护的法律、法规，防治污染和其他公害，保护生态环境。"},{"i":12,"n":"第十二条","txt":"国务院煤炭管理部门依法负责全国煤炭行业的监督管理。国务院有关部门在各自的职责范围内负责煤炭行业的监督管理。"},{"i":13,"n":"第十三条","txt":"煤炭矿务局是国有煤矿企业，具有独立法人资格。"},{"i":14,"n":"第十四条","txt":"国务院煤炭管理部门根据全国矿产资源勘查规划编制全国煤炭资源勘查规划。"},{"i":15,"n":"第十五条","txt":"国务院煤炭管理部门根据全国矿产资源规划规定的煤炭资源，组织编制和实施煤炭生产开发规划。"},{"i":16,"n":"第十六条","txt":"煤炭生产开发规划应当根据国民经济和社会发展的需要制定，并纳入国民经济和社会发展计划。"},{"i":17,"n":"第十七条","txt":"国家制定优惠政策，支持煤炭工业发展，促进煤矿建设。"},{"i":18,"n":"第十八条","txt":"煤矿建设使用土地，应当依照有关法律、行政法规的规定办理。征收土地的，应当依法支付土地补偿费和安置补偿费，做好迁移居民的安置工作。"},{"i":19,"n":"第十九条","txt":"煤矿建设应当坚持煤炭开发与环境治理同步进行。煤矿建设项目的环境保护设施必须与主体工程同时设计、同时施工、同时验收、同时投入使用。"},{"i":20,"n":"第二十条","txt":"煤矿投入生产前，煤矿企业应当依照有关安全生产的法律、行政法规的规定取得安全生产许可证。未取得安全生产许可证的，不得从事煤炭生产。"},{"i":21,"n":"第二十一条","txt":"对国民经济具有重要价值的特殊煤种或者稀缺煤种，国家实行保护性开采。"},{"i":22,"n":"第二十二条","txt":"开采煤炭资源必须符合煤矿开采规程，遵守合理的开采顺序，达到规定的煤炭资源回采率。"},{"i":23,"n":"第二十三条","txt":"煤矿企业应当加强煤炭产品质量的监督检查和管理。煤炭产品质量应当按照国家标准或者行业标准分等论级。"},{"i":24,"n":"第二十四条","txt":"煤炭生产应当依法在批准的开采范围内进行，不得超越批准的开采范围越界、越层开采。"},{"i":25,"n":"第二十五条","txt":"因开采煤炭压占土地或者造成地表土地塌陷、挖损，由采矿者负责进行复垦，恢复到可供利用的状态；造成他人损失的，应当依法给予补偿。"},{"i":26,"n":"第二十六条","txt":"关闭煤矿和报废矿井，应当依照有关法律、法规和国务院煤炭管理部门的规定办理。"},{"i":27,"n":"第二十七条","txt":"国家建立煤矿企业积累煤矿衰老期转产资金的制度。"},{"i":28,"n":"第二十八条","txt":"国家提倡和支持煤矿企业和其他企业发展煤电联产、炼焦、煤化工、煤建材等，进行煤炭的深加工和精加工。"},{"i":29,"n":"第二十九条","txt":"国家发展和推广洁净煤技术。"},{"i":30,"n":"第三十条","txt":"县级以上各级人民政府及其煤炭管理部门和其他有关部门，应当加强对煤矿安全生产工作的监督管理。"},{"i":31,"n":"第三十一条","txt":"煤矿企业的安全生产管理，实行矿务局长、矿长负责制。"},{"i":32,"n":"第三十二条","txt":"矿务局长、矿长及煤矿企业的其他主要负责人必须遵守有关矿山安全的法律、法规和煤炭行业安全规章、规程，加强对煤矿安全生产工作的管理，执行安全生产责任制度，采取有效措施，防止伤亡和其他安全生产事故的发生。"},{"i":33,"n":"第三十三条","txt":"煤矿企业应当对职工进行安全生产教育、培训；未经安全生产教育、培训的，不得上岗作业。"},{"i":34,"n":"第三十四条","txt":"在煤矿井下作业中，出现危及职工生命安全并无法排除的紧急情况时，作业现场负责人或者安全管理人员应当立即组织职工撤离危险现场，并及时报告有关方面负责人。"},{"i":35,"n":"第三十五条","txt":"煤矿企业工会发现企业行政方面违章指挥、强令职工冒险作业或者生产过程中发现明显重大事故隐患，可能危及职工生命安全的情况，有权提出解决问题的建议，煤矿企业行政方面必须及时作出处理决定。企业行政方面拒不处理的，工会有权提出批评、检举和控告。"},{"i":36,"n":"第三十六条","txt":"煤矿企业必须为职工提供保障安全生产所需的劳动保护用品。"},{"i":37,"n":"第三十七条","txt":"煤矿企业应当依法为职工参加工伤保险缴纳工伤保险费。鼓励企业为井下作业职工办理意外伤害保险，支付保险费。"},{"i":38,"n":"第三十八条","txt":"煤矿企业使用的设备、器材、火工产品和安全仪器，必须符合国家标准或者行业标准。"},{"i":39,"n":"第三十九条","txt":"煤炭经营企业从事煤炭经营，应当遵守有关法律、法规的规定，改善服务，保障供应。禁止一切非法经营活动。"},{"i":40,"n":"第四十条","txt":"煤炭经营应当减少中间环节和取消不合理的中间环节，提倡有条件的煤矿企业直销。"},{"i":41,"n":"第四十一条","txt":"从事煤炭运输的车站、港口及其他运输企业不得利用其掌握的运力作为参与煤炭经营、谋取不正当利益的手段。"},{"i":42,"n":"第四十二条","txt":"国务院物价行政主管部门会同国务院煤炭管理部门和有关部门对煤炭的销售价格进行监督管理。"},{"i":43,"n":"第四十三条","txt":"煤矿企业和煤炭经营企业供应用户的煤炭质量应当符合国家标准或者行业标准，质级相符，质价相符。用户对煤炭质量有特殊要求的，由供需双方在煤炭购销合同中约定。"},{"i":44,"n":"第四十四条","txt":"煤矿企业和煤炭经营企业供应用户的煤炭质量不符合国家标准或者行业标准，或者不符合合同约定，或者质级不符、质价不符，给用户造成损失的，应当依法给予赔偿。"},{"i":45,"n":"第四十五条","txt":"煤矿企业、煤炭经营企业、运输企业和煤炭用户应当依照法律、国务院有关规定或者合同约定供应、运输和接卸煤炭。"},{"i":46,"n":"第四十六条","txt":"煤炭的进出口依照国务院的规定，实行统一管理。"},{"i":47,"n":"第四十七条","txt":"煤炭经营管理办法，由国务院依照本法制定。"},{"i":48,"n":"第四十八条","txt":"任何单位或者个人不得危害煤矿矿区的电力、通讯、水源、交通及其他生产设施。"},{"i":49,"n":"第四十九条","txt":"对盗窃或者破坏煤矿矿区设施、器材及其他危及煤矿矿区安全的行为，一切单位和个人都有权检举、控告。"},{"i":50,"n":"第五十条","txt":"未经煤矿企业同意，任何单位或者个人不得在煤矿企业依法取得土地使用权的有效期间内在该土地上种植、养殖、取土或者修建建筑物、构筑物。"},{"i":51,"n":"第五十一条","txt":"未经煤矿企业同意，任何单位或者个人不得占用煤矿企业的铁路专用线、专用道路、专用航道、专用码头、电力专用线、专用供水管路。"},{"i":52,"n":"第五十二条","txt":"任何单位或者个人需要在煤矿采区范围内进行可能危及煤矿安全的作业时，应当经煤矿企业同意，报煤炭管理部门批准，并采取安全措施后，方可进行作业。"},{"i":53,"n":"第五十三条","txt":"煤炭管理部门和有关部门依法对煤矿企业和煤炭经营企业执行煤炭法律、法规的情况进行监督检查。"},{"i":54,"n":"第五十四条","txt":"煤炭管理部门和有关部门的监督检查人员应当熟悉煤炭法律、法规，掌握有关煤炭专业技术，公正廉洁，秉公执法。"},{"i":55,"n":"第五十五条","txt":"煤炭管理部门和有关部门的监督检查人员进行监督检查时，有权向煤矿企业、煤炭经营企业或者用户了解有关执行煤炭法律、法规的情况，查阅有关资料，并有权进入现场进行检查。"},{"i":56,"n":"第五十六条","txt":"煤炭管理部门和有关部门的监督检查人员对煤矿企业和煤炭经营企业违反煤炭法律、法规的行为，有权要求其依法改正。"},{"i":57,"n":"第五十七条","txt":"违反本法第二十二条的规定，开采煤炭资源未达到国务院煤炭管理部门规定的煤炭资源回采率的，由煤炭管理部门责令限期改正；逾期仍达不到规定的回采率的，责令停止生产。"},{"i":58,"n":"第五十八条","txt":"违反本法第二十四条的规定，擅自开采保安煤柱或者采用危及相邻煤矿生产安全的危险方法进行采矿作业的，由劳动行政主管部门会同煤炭管理部门责令停止作业；由煤炭管理部门没收违法所得，并处违法所得一倍以上五倍以下的罚款；构成犯罪的，由司法机关依法追究刑事责任；造成损失的，依法承担赔偿责任。"},{"i":59,"n":"第五十九条","txt":"违反本法第四十三条的规定，在煤炭产品中掺杂、掺假，以次充好的，责令停止销售，没收违法所得，并处违法所得一倍以上五倍以下的罚款；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":60,"n":"第六十条","txt":"违反本法第五十条的规定，未经煤矿企业同意，在煤矿企业依法取得土地使用权的有效期间内在该土地上修建建筑物、构筑物的，由当地人民政府动员拆除；拒不拆除的，责令拆除。"},{"i":61,"n":"第六十一条","txt":"违反本法第五十一条的规定，未经煤矿企业同意，占用煤矿企业的铁路专用线、专用道路、专用航道、专用码头、电力专用线、专用供水管路的，由县级以上地方人民政府责令限期改正；逾期不改正的，强制清除，可以并处五万元以下的罚款；造成损失的，依法承担赔偿责任。"},{"i":62,"n":"第六十二条","txt":"违反本法第五十二条的规定，未经批准或者未采取安全措施，在煤矿采区范围内进行危及煤矿安全作业的，由煤炭管理部门责令停止作业，可以并处五万元以下的罚款；造成损失的，依法承担赔偿责任。"},{"i":63,"n":"第六十三条","txt":"有下列行为之一的，由公安机关依照治安管理处罚法的有关规定处罚；构成犯罪的，由司法机关依法追究刑事责任："},{"i":64,"n":"第六十四条","txt":"煤矿企业的管理人员违章指挥、强令职工冒险作业，发生重大伤亡事故的，依照刑法有关规定追究刑事责任。"},{"i":65,"n":"第六十五条","txt":"煤矿企业的管理人员对煤矿事故隐患不采取措施予以消除，发生重大伤亡事故的，依照刑法有关规定追究刑事责任。"},{"i":66,"n":"第六十六条","txt":"煤炭管理部门和有关部门的工作人员玩忽职守、徇私舞弊、滥用职权的，依法给予行政处分；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":67,"n":"第六十七条","txt":"本法自1996年12月1日起施行。"}],"shengtaihuanjingfadian":[{"i":1,"n":"第一条","txt":"为了保护生态环境，防治污染和其他公害，保障公众健康和生态环境权益，维护生态安全，推动绿色低碳发展，建设生态文明，全面推进美丽中国建设，加快推进人与自然和谐共生的现代化，实现中华民族永续发展，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称生态环境，是指影响人类生存和发展以及生态系统功能的各种天然的和经过人工改造的自然空间、自然因素及其相互联系与作用的总体，包括大气、水、海洋、土地、矿藏、森林、山岭、草原、湿地、冰川、高原、荒漠、野生生物、自然遗迹、人文遗迹、自然保护地、城市和乡村等。"},{"i":3,"n":"第三条","txt":"中华人民共和国领域和中华人民共和国管辖的其他海域内的污染防治、生态保护、绿色低碳发展等生态环境保护相关活动，适用本法。"},{"i":4,"n":"第四条","txt":"生态环境保护坚持中国共产党的领导，贯彻习近平生态文明思想，树立尊重自然、顺应自然、保护自然的生态文明理念，坚持良好生态环境是最普惠的民生福祉，完善落实绿水青山就是金山银山理念的体制机制，坚持用最严格制度最严密法治保护生态环境。"},{"i":5,"n":"第五条","txt":"节约资源和保护生态环境是国家的基本国策。"},{"i":6,"n":"第六条","txt":"生态环境保护坚持预防为主、系统治理、生态优先、绿色发展、公众参与、损害担责的原则。"},{"i":7,"n":"第七条","txt":"任何单位和个人都有保护生态环境的义务。"},{"i":8,"n":"第八条","txt":"各级人民政府应当加强生态环境保护工作，正确处理高质量发展和高水平保护的关系，根据生态环境保护目标和治理任务，采取有效措施，改善生态环境质量。"},{"i":9,"n":"第九条","txt":"企业事业单位和其他生产经营者应当采取有效措施，防止、减少环境污染和生态破坏，节约集约利用资源，控制温室气体排放，履行绿色低碳发展义务，并对所造成的损害依法承担责任。"},{"i":10,"n":"第十条","txt":"公民应当增强生态环境保护意识，采取简约适度、绿色低碳的生活方式，自觉履行生态环境保护义务，遵守生态环境法律法规，配合实施生态环境保护措施。"},{"i":11,"n":"第十一条","txt":"国家支持生态环境科学技术研究、开发和应用，加强生态环境保护工作的科技支撑和人才培养，在确保安全前提下促进信息技术、数字技术、人工智能技术等的应用，提高生态环境保护的科学技术水平。"},{"i":12,"n":"第十二条","txt":"各级人民政府及其有关部门应当加强生态环境保护宣传和普及工作，开展生态环境法治宣传教育，弘扬生态文化，增强公众的生态环境保护意识和法治素养。"},{"i":13,"n":"第十三条","txt":"对在生态环境保护工作中做出显著成绩的单位和个人，按照国家规定给予表彰和奖励。"},{"i":14,"n":"第十四条","txt":"国家加强生态环境领域的国际合作，履行中华人民共和国缔结或者参加的国际条约规定的义务，支持生态环境保护国际交流与合作，积极参与生态环境国际规则的研究与制定，积极阐释中国特色生态环境法治理念、主张和成功实践，推动构建公平合理、合作共赢的全球环境治理体系。"},{"i":15,"n":"第十五条","txt":"每年8月15日为全国生态日。国家通过多种形式开展生态文明宣传教育活动。"},{"i":16,"n":"第十六条","txt":"县级以上人民政府应当组织、协调、督促有关部门依法履行生态环境保护监督管理职责。"},{"i":17,"n":"第十七条","txt":"国务院生态环境主管部门在其职责范围内对全国生态环境保护工作实施统一监督管理，统一政策规划标准制定，统一监测评估，统一监督执法，统一督察问责。地方人民政府生态环境主管部门在其职责范围内对本行政区域生态环境保护工作实施统一监督管理。"},{"i":18,"n":"第十八条","txt":"国家建立健全生态环境保护责任清单制度，明确国务院有关部门和地方人民政府有关部门的生态环境保护监督管理职责。"},{"i":19,"n":"第十九条","txt":"省、市、县、乡依法建立健全河湖长制、林长制。各级河湖长负责本行政区域江河湖泊管理和保护相关工作；各级林长负责本行政区域森林草原资源保护发展相关工作。"},{"i":20,"n":"第二十条","txt":"县级以上地方人民政府根据实际需要建立生态环境保护工作协调联动机制，加强部门协同配合，推进本行政区域生态环境保护工作。"},{"i":21,"n":"第二十一条","txt":"国家建立健全跨行政区域的重点区域、流域、海域生态环境联合保护协调机制，实行统一规划、统一标准、统一监测、统一保护措施。"},{"i":22,"n":"第二十二条","txt":"国家完善生态安全工作协调机制，采取有效措施提升生态安全风险研判评估、监测预警、应急应对和处置能力，形成全域联动、立体高效的生态安全防护体系，统筹推进生态安全工作。"},{"i":23,"n":"第二十三条","txt":"国家建立健全生态环境信息共享机制，提升信息共享能力，加强生态环境信息共享。"},{"i":24,"n":"第二十四条","txt":"国家坚持分区域、差异化、精准管控，实施地上地下、陆海统筹、区域联动的生态环境监督管理制度，加强规划、标准、监测等监督管理制度的衔接协调。"},{"i":25,"n":"第二十五条","txt":"各级人民政府及其有关部门应当加强生态环境保护监督管理能力建设，提高生态环境保护监督管理信息化、数字化、智能化水平。"},{"i":26,"n":"第二十六条","txt":"国务院有关部门和县级以上地方人民政府组织制定经济、技术政策和措施，应当充分考虑对生态环境的影响，听取有关方面和专家的意见。"},{"i":27,"n":"第二十七条","txt":"国家实行生态环境保护目标责任制和考核评价制度，将生态环境保护目标完成情况纳入考核评价内容。考核评价工作应当增强针对性、实效性，力戒形式主义。考核结果应当向社会公开。"},{"i":28,"n":"第二十八条","txt":"国家建立健全生态环境保护督察制度，对有关方面履行生态文明建设和生态环境保护责任组织开展全面督察。生态环境保护督察实行中央和省、自治区、直辖市两级督察体制。"},{"i":29,"n":"第二十九条","txt":"被督察对象应当自觉接受生态环境保护督察，积极配合督察工作。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府应当每年向本级人民代表大会或者人民代表大会常务委员会报告生态环境状况和生态环境保护目标完成情况，对发生的重大生态环境事件应当及时向本级人民代表大会常务委员会报告，依法接受监督。"},{"i":31,"n":"第三十一条","txt":"国家加强生态环境司法保障建设。"},{"i":32,"n":"第三十二条","txt":"国家完善生态环境损害赔偿和生态环境公益诉讼制度，维护国家利益、社会公共利益。"},{"i":33,"n":"第三十三条","txt":"行政机关、监察机关、审判机关和检察机关应当加强协同配合，建立健全案件移送、信息共享等机制，对污染环境、破坏生态等违法行为依法追究法律责任。"},{"i":34,"n":"第三十四条","txt":"国家实行自然资源资产离任审计，对领导干部履行自然资源资产管理和生态环境保护责任情况进行审计。"},{"i":35,"n":"第三十五条","txt":"国家加强生态的保护与修复，坚持山水林田湖草沙一体化保护与修复，实行自然恢复为主、自然恢复与人工修复相结合的系统治理。"},{"i":36,"n":"第三十六条","txt":"国家健全主体功能区制度体系，根据城市化地区、农产品主产区、重点生态功能区等的不同定位，优化国土空间发展格局。"},{"i":37,"n":"第三十七条","txt":"国家完善资源总量管理和全面节约制度，避免资源浪费，提高资源利用效率。"},{"i":38,"n":"第三十八条","txt":"国家健全自然资源资产产权制度和管理制度体系，完善全民所有自然资源资产所有权委托代理机制，推进自然资源有偿使用。"},{"i":39,"n":"第三十九条","txt":"国家健全生态产品价值实现机制，形成多元化的生态产品价值实现路径，推进生态产业化和产业生态化。"},{"i":40,"n":"第四十条","txt":"开发利用自然资源，应当合理开发，节约集约，高效利用，防止污染环境、破坏生态，减少温室气体排放，依法制定有关生态环境保护的方案并予以实施。"},{"i":41,"n":"第四十一条","txt":"国家统筹水资源、水环境、水生态治理，加强水生态环境保护。"},{"i":42,"n":"第四十二条","txt":"国家加强生物多样性保护，建立健全生物多样性保护工作协调机制和生物多样性调查、监测、评估和保护制度，合理布局建设生物多样性保护空间体系。"},{"i":43,"n":"第四十三条","txt":"国家建设以国家公园为主体、以自然保护区为基础、以各类自然公园为补充的自然保护地体系，确保重要生态系统、自然遗迹、自然景观和生物多样性得到系统性保护。"},{"i":44,"n":"第四十四条","txt":"国家推进青藏高原生态屏障区、长江重点生态区、黄河重点生态区和东北森林带、北方防沙带、南方丘陵山地带、海岸带等区域生态屏障建设，加强长江、黄河、淮河、海河、珠江、松花江、辽河、洞庭湖、鄱阳湖、太湖、洪泽湖、巢湖等重要江河湖泊生态环境保护。"},{"i":45,"n":"第四十五条","txt":"国务院生态环境主管部门根据海洋生态环境状况和质量改善要求，会同国务院发展改革、自然资源、住房城乡建设、交通运输、水行政、渔业渔政、林业草原等有关部门和海警机构，划定国家生态环境治理重点海域及其控制区域，拟订综合治理行动方案，报国务院批准后实施。"},{"i":46,"n":"第四十六条","txt":"各级人民政府应当加强对农业生态环境的保护，促进农业生态环境保护新技术的应用，加强对农业污染源的监测预警，统筹有关部门采取有效措施，防治土壤污染和土地沙化、酸化、盐渍化、贫瘠化、石漠化、地面沉降以及防治植被破坏、水土流失、水体富营养化、水源枯竭、种源灭绝、外来物种入侵等生态失调现象，推广植物病虫害的综合防治。"},{"i":47,"n":"第四十七条","txt":"城乡建设应当结合当地自然的生态环境特点，保护植被、水域和自然景观、人文遗迹、古树名木等，加强城市园林、绿地的建设与管理。"},{"i":48,"n":"第四十八条","txt":"国家建立健全生态环境与健康监测、调查和风险评估制度；鼓励和组织开展生态环境质量对公众健康影响的研究，采取有效措施预防和控制与环境污染、生态破坏等有关的疾病。"},{"i":49,"n":"第四十九条","txt":"国家对严重污染环境、破坏生态等的技术、工艺、设备、材料、产品实行淘汰制度。"},{"i":50,"n":"第五十条","txt":"国务院负有生态环境保护监督管理职责的部门以及重点区域、流域、海域有关省、自治区、直辖市人民政府可以组织有关部门开展联合执法，跨行政区域、流域、海域执法，交叉执法。"},{"i":51,"n":"第五十一条","txt":"负有生态环境保护监督管理职责的部门有权依法对污染环境、破坏生态等的企业事业单位和其他生产经营者以及生态环境技术服务机构等进行现场检查。被检查者应当如实反映情况，提供必要的资料。实施现场检查的部门及其工作人员应当为被检查者保守商业秘密、个人隐私和个人信息。"},{"i":52,"n":"第五十二条","txt":"企业事业单位和其他生产经营者违反法律法规规定，造成或者可能造成严重污染环境、破坏生态等后果，或者有关证据可能灭失、被隐匿的，负有生态环境保护监督管理职责的部门可以依法查封、扣押有关场所、船舶、设施、设备、工具、物品。"},{"i":53,"n":"第五十三条","txt":"设区的市级人民政府生态环境主管部门设立的派出机构，可以以自己的名义依法实施现场检查、查封、扣押、代履行和行政处罚。"},{"i":54,"n":"第五十四条","txt":"国家构建生态环境信用监管体系。"},{"i":55,"n":"第五十五条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域以外，造成或者可能造成中华人民共和国领域和中华人民共和国管辖的其他海域环境污染、生态破坏的，有关部门和机构有权采取必要的措施。"},{"i":56,"n":"第五十六条","txt":"国家建立健全以国家发展规划为统领，以国土空间规划为基础，以专项规划、区域规划为支撑，由国家和地方规划共同组成的国家规划体系，加强规划之间的衔接协调，发挥规划对生态环境保护的引领、指导和约束作用。"},{"i":57,"n":"第五十七条","txt":"县级以上人民政府应当将生态环境保护工作纳入国民经济和社会发展规划。"},{"i":58,"n":"第五十八条","txt":"国家建立健全覆盖全域全类型、统一衔接的国土空间用途管制和规划许可制度，依据国土空间规划对国土空间实行分区、分类用途管制，国土空间开发利用活动应当符合国土空间用途管制要求，并依法取得规划许可。"},{"i":59,"n":"第五十九条","txt":"国土空间规划应当科学有序统筹安排农业、生态、城镇等功能空间，划定耕地和永久基本农田、生态保护红线、城镇开发边界，优化国土空间结构和布局。"},{"i":60,"n":"第六十条","txt":"国家建立健全生态保护红线管理制度，优先将生态功能极重要区域、生态极敏感脆弱区域等区域划入生态保护红线，实行严格保护。"},{"i":61,"n":"第六十一条","txt":"国务院生态环境主管部门会同有关部门，根据国家发展规划编制国家生态环境保护规划，报国务院批准并公布实施。"},{"i":62,"n":"第六十二条","txt":"未达到国家生态环境质量标准的重点区域、流域、海域的有关地方人民政府，应当依法编制限期达标规划、改善规划及其实施方案，并采取有效措施按期达标、改善生态环境质量。限期达标规划、改善规划及其实施方案应当及时公布。"},{"i":63,"n":"第六十三条","txt":"生态环境、发展改革、自然资源、住房城乡建设、水行政、农业农村、林业草原等有关部门，可以在各自职责范围内根据实际需要编制有关生态环境领域的规划。"},{"i":64,"n":"第六十四条","txt":"国家可以根据实际需要，对国家发展规划确定的重点地区、跨行政区域且经济社会活动联系紧密的连片区域和承担重大战略任务的特定区域编制区域规划，指导区域生态环境保护和协调协同发展。"},{"i":65,"n":"第六十五条","txt":"编制生态环境领域的规划，应当征求有关部门、专家等方面的意见；规划实施后，规划编制机关应当按照国家规定组织开展监测分析和评估。"},{"i":66,"n":"第六十六条","txt":"国家建立健全生态环境分区管控制度。"},{"i":67,"n":"第六十七条","txt":"生态环境分区管控方案应当落实生态保护红线、环境质量底线、资源利用上线目标，划定优先保护、重点管控、一般管控单元，明确相应的生态环境准入清单。禁止违反生态环境准入清单规定进行生产建设活动。"},{"i":68,"n":"第六十八条","txt":"国家推进生态环境领域标准体系建设，加强标准之间的衔接协调，发挥标准对生态环境保护的支撑作用。"},{"i":69,"n":"第六十九条","txt":"国务院生态环境主管部门制定国家生态环境质量标准。"},{"i":70,"n":"第七十条","txt":"国务院生态环境、发展改革、工业和信息化、自然资源、住房城乡建设、交通运输、水行政、农业农村、林业草原、标准化等有关部门，在各自职责范围内依法制定有关污染防治、生态保护、绿色低碳发展等方面的标准。"},{"i":71,"n":"第七十一条","txt":"制定生态环境领域的标准，应当以保障公众健康、保护生态环境为宗旨，与经济社会发展相适应，做到科学合理。"},{"i":72,"n":"第七十二条","txt":"制定生态环境领域的标准，应当组织专家进行审查和论证，并征求有关部门、行业协会、企业事业单位和公众等方面的意见，提高标准的科学性。"},{"i":73,"n":"第七十三条","txt":"生态环境领域标准的制定机关，应当在其网站上及时公布标准全文，供公众免费查阅、下载。"},{"i":74,"n":"第七十四条","txt":"生态环境领域标准的执行情况应当定期进行评估，根据评估结果对标准适时进行修订、废止。"},{"i":75,"n":"第七十五条","txt":"国家鼓励、支持开展生态环境基准研究。"},{"i":76,"n":"第七十六条","txt":"国家建立健全生态环境监测制度。"},{"i":77,"n":"第七十七条","txt":"各类生态环境监测站点的设置应当符合法律法规规定和有关监测规范的要求。"},{"i":78,"n":"第七十八条","txt":"生态环境监测机构、实行排污许可管理和其他负有法定监测义务的企业事业单位应当依法建立健全监测数据质量管理制度。"},{"i":79,"n":"第七十九条","txt":"生态环境监测机构应当具备相应的设施、设备、技术人员、技术能力和管理能力，并依法报有关部门备案。"},{"i":80,"n":"第八十条","txt":"禁止通过干扰采样、调换样品、改变监测条件、虚假监测、篡改或者伪造记录等方式对生态环境监测数据弄虚作假或者指使对生态环境监测数据弄虚作假。"},{"i":81,"n":"第八十一条","txt":"省级以上人民政府应当组织有关部门或者委托专业机构，对生态环境状况进行调查、评价，建立健全生态环境的承载能力监测预警机制。"},{"i":82,"n":"第八十二条","txt":"本法所称生态环境影响评价，是指对规划和建设项目实施后可能造成的生态环境影响进行分析、预测和评估，提出预防或者减轻不良生态环境影响的对策和措施，进行跟踪监测的方法与制度。"},{"i":83,"n":"第八十三条","txt":"编制有关开发利用规划，建设对生态环境有影响的项目，应当依法进行生态环境影响评价。"},{"i":84,"n":"第八十四条","txt":"生态环境影响评价应当客观、公开、公正，综合考虑规划或者建设项目实施后对各种生态环境因素及其所构成的生态系统可能造成的影响，为决策提供科学依据。"},{"i":85,"n":"第八十五条","txt":"国家加强生态环境影响评价的基础数据库和评价指标体系建设，鼓励、支持对生态环境影响评价的方法、技术规范进行科学研究，建立必要的生态环境影响评价信息共享制度，提高生态环境影响评价的科学性。"},{"i":86,"n":"第八十六条","txt":"国务院有关部门、设区的市级以上地方人民政府及其有关部门，对其组织编制的国土空间规划，区域、流域、海域的建设、开发利用规划，应当在规划编制过程中组织进行生态环境影响评价，编写该规划有关生态环境影响的篇章或者说明。"},{"i":87,"n":"第八十七条","txt":"国务院有关部门、设区的市级以上地方人民政府及其有关部门，对其组织编制的工业、农业、林业、能源、水利、交通、城市和产业园区建设、旅游、自然资源开发的有关专项规划，应当在规划编制过程中组织进行生态环境影响评价，并向审批该专项规划的机关提出生态环境影响报告书。"},{"i":88,"n":"第八十八条","txt":"依照本法第八十六条、第八十七条规定进行生态环境影响评价的规划的具体范围，由国务院生态环境主管部门会同有关部门规定，报国务院批准。"},{"i":89,"n":"第八十九条","txt":"专项规划的生态环境影响报告书应当包括下列内容："},{"i":90,"n":"第九十条","txt":"专项规划的编制机关对可能造成不良生态环境影响并直接涉及公众生态环境权益的规划，应当在该规划草案报送审批前，举行论证会、听证会，或者采取其他形式，征求有关单位、专家和公众对生态环境影响报告书草案的意见。但是，国家规定不予公开的情形除外。"},{"i":91,"n":"第九十一条","txt":"专项规划的编制机关在报批规划草案时，应当将生态环境影响报告书一并附送审批机关审查；未附送生态环境影响报告书的，审批机关不予审批。"},{"i":92,"n":"第九十二条","txt":"设区的市级以上人民政府在审批专项规划草案、作出决策前，应当先由其生态环境主管部门召集有关部门代表和专家组成审查小组，对生态环境影响报告书进行审查，并提出书面审查意见。"},{"i":93,"n":"第九十三条","txt":"审查小组提出修改意见的，专项规划的编制机关应当根据生态环境影响报告书结论和审查意见对规划草案进行修改完善，并对生态环境影响报告书结论和审查意见的采纳情况作出说明；不采纳的，应当说明理由。"},{"i":94,"n":"第九十四条","txt":"对生态环境有重大影响的规划实施后，编制机关应当及时组织生态环境影响的跟踪评价，将评价结果报告审批机关，并通报生态环境等有关部门；发现有明显不良生态环境影响的，应当及时提出改进措施。"},{"i":95,"n":"第九十五条","txt":"国家根据建设项目对生态环境的影响程度，对建设项目的生态环境影响评价实行分类管理。"},{"i":96,"n":"第九十六条","txt":"建设项目的生态环境影响报告书应当包括下列内容："},{"i":97,"n":"第九十七条","txt":"建设项目的生态环境影响评价，应当避免与规划的生态环境影响评价相重复。"},{"i":98,"n":"第九十八条","txt":"建设单位可以委托技术单位对其建设项目开展生态环境影响评价，编制建设项目生态环境影响报告书、生态环境影响报告表；建设单位具备生态环境影响评价技术能力的，可以自行对其建设项目开展生态环境影响评价，编制建设项目生态环境影响报告书、生态环境影响报告表。"},{"i":99,"n":"第九十九条","txt":"接受委托为建设单位编制建设项目生态环境影响报告书、生态环境影响报告表的技术单位应当依法独立客观公正开展业务，建立健全质量控制制度，确保所出具的生态环境影响报告书、生态环境影响报告表客观、真实、准确。"},{"i":100,"n":"第一百条","txt":"建设单位应当对建设项目生态环境影响报告书、生态环境影响报告表的内容和结论负责，接受委托编制建设项目生态环境影响报告书、生态环境影响报告表的技术单位对其编制的建设项目生态环境影响报告书、生态环境影响报告表承担相应责任。"},{"i":101,"n":"第一百零一条","txt":"除国家规定不予公开的情形外，对生态环境可能造成重大影响、应当编制生态环境影响报告书的建设项目，建设单位应当在报批建设项目生态环境影响报告书前，举行论证会、听证会，或者采取其他形式，向可能受影响的公众说明情况，充分征求有关单位、专家和公众的意见。"},{"i":102,"n":"第一百零二条","txt":"建设项目的生态环境影响报告书、生态环境影响报告表，由建设单位按照规定报有审批权的生态环境主管部门审批。"},{"i":103,"n":"第一百零三条","txt":"生态环境主管部门在收到建设项目生态环境影响报告书后，除国家规定不予公开的情形外，应当全文公开；发现建设项目未充分征求公众意见的，应当责成建设单位征求公众意见。"},{"i":104,"n":"第一百零四条","txt":"国务院生态环境主管部门负责审批下列建设项目的生态环境影响报告书、生态环境影响报告表："},{"i":105,"n":"第一百零五条","txt":"建设项目有下列情形之一的，生态环境主管部门应当对生态环境影响报告书、生态环境影响报告表作出不予批准的决定："},{"i":106,"n":"第一百零六条","txt":"建设项目的生态环境影响报告书、生态环境影响报告表经批准后，建设项目的性质、规模、地点、采用的生产工艺或者防治污染、防止生态破坏的措施发生重大变动的，建设单位应当重新报批建设项目的生态环境影响报告书、生态环境影响报告表。"},{"i":107,"n":"第一百零七条","txt":"建设项目的生态环境影响报告书、生态环境影响报告表未依法经审批部门审查或者审查后未予批准的，或者未经原审批部门重新审核同意的，建设单位不得开工建设。"},{"i":108,"n":"第一百零八条","txt":"建设项目建设、运行过程中，建设单位应当实施生态环境影响报告书、生态环境影响报告表及其审批部门审批意见中提出的生态环境保护对策措施。"},{"i":109,"n":"第一百零九条","txt":"建设项目建设、运行过程中产生不符合经审批的生态环境影响报告书、生态环境影响报告表的情形的，建设单位应当组织生态环境影响的后评价，采取改进措施，并报原生态环境影响报告书、生态环境影响报告表审批部门和建设项目审批部门备案；原生态环境影响报告书、生态环境影响报告表审批部门也可以责成建设单位进行生态环境影响的后评价，采取改进措施。"},{"i":110,"n":"第一百一十条","txt":"生态环境主管部门应当对建设项目投入生产或者使用后所产生的生态环境影响进行跟踪检查，对造成严重环境污染或者生态破坏的，应当查清原因、查明责任。"},{"i":111,"n":"第一百一十一条","txt":"国家建立健全生态保护补偿制度，通过财政纵向补偿、地区间横向补偿、市场机制补偿等机制，对按照规定或者约定开展生态环境保护的地区、单位和个人予以补偿，按照生态系统的整体性、系统性及其内在规律，建立健全政府主导、企业和社会参与、市场化运作、可持续的生态保护补偿机制，促进对生态环境的整体保护。"},{"i":112,"n":"第一百一十二条","txt":"县级以上人民政府应当构建稳定的生态保护补偿资金投入机制，依法通过多种方式拓宽生态保护补偿资金渠道。"},{"i":113,"n":"第一百一十三条","txt":"国家通过财政转移支付等方式，对开展重要生态环境要素保护的地区、单位和个人，以及在依法划定的重点生态功能区、生态保护红线、自然保护地等生态功能重要区域开展生态环境保护的地区、单位和个人，予以补偿。"},{"i":114,"n":"第一百一十四条","txt":"国家鼓励、指导、推动受益地区与保护地区人民政府通过协商等方式建立生态保护补偿机制，开展地区间横向生态保护补偿。根据生态环境保护的需要，上级人民政府可以组织、协调下级人民政府之间开展地区间横向生态保护补偿。"},{"i":115,"n":"第一百一十五条","txt":"国家充分发挥市场机制在生态保护补偿中的作用，推进生态保护补偿市场化发展。"},{"i":116,"n":"第一百一十六条","txt":"国家完善生态保护补偿监测支撑体系，建立健全生态保护补偿统计体系，完善生态保护补偿标准体系，为生态保护补偿工作提供技术支撑。"},{"i":117,"n":"第一百一十七条","txt":"各级人民政府及其有关部门、企业事业单位和其他生产经营者，应当依法做好突发生态环境事件的预防准备、监测预警、应急处置、调查评估、事后恢复等工作。"},{"i":118,"n":"第一百一十八条","txt":"按照社会危害程度、影响范围等因素，突发生态环境事件分为特别重大、重大、较大和一般四级。突发生态环境事件的分级标准由国务院生态环境主管部门会同有关部门制定，报国务院批准后公布实施。"},{"i":119,"n":"第一百一十九条","txt":"国家建立健全分级负责、属地为主、部门协同的突发生态环境事件应对责任体系，严密防控生态环境风险、保护生态环境敏感目标，及时妥善科学处置各类突发生态环境事件。"},{"i":120,"n":"第一百二十条","txt":"生态环境、应急管理等有关部门应当密切配合，加强信息共享、协调联动，共同做好突发生态环境事件应对工作。"},{"i":121,"n":"第一百二十一条","txt":"企业事业单位和其他生产经营者应当依法完善突发生态环境事件风险防控措施，开展隐患排查，及时消除隐患。"},{"i":122,"n":"第一百二十二条","txt":"各级人民政府及其有关部门、企业事业单位和其他生产经营者，在自然灾害、事故灾难、公共卫生事件应急处置过程中，应当采取必要措施，避免或者减少对生态环境造成的危害。"},{"i":123,"n":"第一百二十三条","txt":"国务院组织制定国家突发生态环境事件应急预案并组织实施。县级以上地方人民政府应当制定本行政区域的突发生态环境事件应急预案并按照规定备案。"},{"i":124,"n":"第一百二十四条","txt":"县级以上人民政府应当建立健全突发生态环境事件监测预警机制，组织制定预警方案；生态环境受到损害，可能影响公众健康和生态安全时，依法及时发布预警信息，启动应急措施。"},{"i":125,"n":"第一百二十五条","txt":"突发生态环境事件涉及或者可能涉及相邻行政区域的，事发地人民政府及其生态环境主管部门应当及时通报相邻行政区域同级人民政府及其生态环境主管部门。"},{"i":126,"n":"第一百二十六条","txt":"突发生态环境事件应急处置工作结束后，有关人民政府应当立即组织评估事件造成的生态环境影响和损失，并及时公布评估结果。"},{"i":127,"n":"第一百二十七条","txt":"国家采取有利于保护生态环境的财政、税收、价格、采购、金融、产业等政策和措施。"},{"i":128,"n":"第一百二十八条","txt":"国务院和县级以上地方人民政府应当按照事权和支出责任划分原则，将生态环境保护工作所需经费纳入本级政府预算，加大生态环境保护的财政投入，优化生态文明建设领域财政资源配置，确保投入规模同建设任务相匹配，提高财政资金的使用效益。"},{"i":129,"n":"第一百二十九条","txt":"国家对参与生态环境保护的单位和个人，依法给予税收优惠。"},{"i":130,"n":"第一百三十条","txt":"国家完善自然资源、污水垃圾处理、用水用能等领域价格形成机制，对资源高消耗、高污染行业依法实行差别化的价格政策。"},{"i":131,"n":"第一百三十一条","txt":"国家机关和其他使用财政性资金的公共机构应当优先采购和使用节能、节水、节地、节材、节矿等有利于保护生态环境的产品、设备、设施和服务。"},{"i":132,"n":"第一百三十二条","txt":"国家强化对生态环境保护的金融支持，持续推动绿色信贷、绿色债券、绿色保险、绿色信托等绿色金融产品和服务规范健康发展。"},{"i":133,"n":"第一百三十三条","txt":"国家鼓励、支持生态环境保护技术装备、资源节约集约利用和生态环境服务等生态环境保护产业的发展。"},{"i":134,"n":"第一百三十四条","txt":"国家推动建立资源环境要素市场交易制度，推进资源环境要素市场化配置，充分发挥市场机制作用。"},{"i":135,"n":"第一百三十五条","txt":"国家推广先进适用技术、工艺、设备，减少资源消耗和污染物、温室气体的产生、排放，促进废弃物综合利用和污染物无害化处理。"},{"i":136,"n":"第一百三十六条","txt":"企业事业单位和其他生产经营者，为保护生态环境，依照有关规定转产、搬迁、关闭的，人民政府应当予以支持。"},{"i":137,"n":"第一百三十七条","txt":"公民、法人和其他组织依法享有获取生态环境信息、参与和监督生态环境保护的权利。"},{"i":138,"n":"第一百三十八条","txt":"国务院生态环境主管部门统一发布国家生态环境质量、重点污染源监测信息及其他重大生态环境信息。省级以上人民政府生态环境主管部门定期发布生态环境状况公报。"},{"i":139,"n":"第一百三十九条","txt":"负有生态环境保护监督管理职责的部门应当加强协调沟通，保证公开的生态环境信息准确一致。"},{"i":140,"n":"第一百四十条","txt":"国家鼓励企业事业单位和其他生产经营者自愿公开相关生态环境信息。"},{"i":141,"n":"第一百四十一条","txt":"国家鼓励、引导公民、法人和其他组织按照依法、有序、自愿、便利的原则，参与生态环境保护。"},{"i":142,"n":"第一百四十二条","txt":"国家鼓励、引导公民、法人和其他组织使用有利于保护生态环境的产品、技术和工艺，减少废弃物的产生，促进废弃物循环利用。"},{"i":143,"n":"第一百四十三条","txt":"编制生态环境领域的规划、制定生态环境领域的标准、开展生态环境影响评价等工作，应当依法采取举行听证会、公开征求意见等方式，保障公众参与生态环境保护的权利。"},{"i":144,"n":"第一百四十四条","txt":"国家鼓励公民、法人和其他组织对生态环境保护公共事务进行监督。"},{"i":145,"n":"第一百四十五条","txt":"负有生态环境保护监督管理职责的部门应当公布举报电话、电子邮箱等高效便捷的举报渠道，方便公众举报。"},{"i":146,"n":"第一百四十六条","txt":"接受举报的机关应当及时处理并对举报人的相关信息予以保密；对实名举报的，应当反馈处理结果等情况。"},{"i":147,"n":"第一百四十七条","txt":"国家鼓励社会组织、志愿者依法从事生态环境保护公益活动。"},{"i":148,"n":"第一百四十八条","txt":"本编适用于环境污染的防治。"},{"i":149,"n":"第一百四十九条","txt":"污染防治坚持精准治污、科学治污、依法治污的方针，坚持统筹规划、源头防控、分类管理、社会共治，强化多污染物控制协同、区域治理协同，加强全过程监督管理，实现减污降碳协同增效，改善生态环境质量，保障公众健康。"},{"i":150,"n":"第一百五十条","txt":"排放污染物的单位和个人，应当采取有效措施，防治在生产、生活和其他活动中产生的大气污染、水污染、海洋污染、土壤污染、固体废物污染、噪声污染、放射性污染，以及化学物质污染、电磁辐射污染、光污染等环境污染。"},{"i":151,"n":"第一百五十一条","txt":"排放污染物，应当符合污染物排放标准、重点污染物排放总量控制指标、排污许可管理和有关法律、法规、规章的要求。"},{"i":152,"n":"第一百五十二条","txt":"排放污染物的企业事业单位，应当建立污染防治责任制度，明确单位负责人和相关人员的责任。"},{"i":153,"n":"第一百五十三条","txt":"国务院生态环境主管部门制定国家污染物排放标准。"},{"i":154,"n":"第一百五十四条","txt":"制定污染物排放标准，应当以生态环境质量标准和经济、技术条件为根据，反映污染物排放特征、可接受生态环境风险，科学合理确定污染物排放控制要求。"},{"i":155,"n":"第一百五十五条","txt":"国家实行重点污染物排放总量控制制度。"},{"i":156,"n":"第一百五十六条","txt":"省、自治区、直辖市人民政府可以根据本行政区域的生态环境质量状况和污染防治工作的需要，对国家确定的重点污染物之外的其他重点污染物排放实行总量控制。"},{"i":157,"n":"第一百五十七条","txt":"企业事业单位应当遵守分解落实到本单位的重点污染物排放总量控制指标。"},{"i":158,"n":"第一百五十八条","txt":"对超过重点污染物排放总量控制指标或者未完成生态环境质量目标的地区，省级以上人民政府生态环境主管部门应当暂停审批该地区新增重点污染物排放总量的建设项目的生态环境影响报告书、生态环境影响报告表。"},{"i":159,"n":"第一百五十九条","txt":"省级以上人民政府生态环境主管部门会同有关部门对环境污染问题突出、防治工作不力、群众反映强烈的地区，约谈县级以上地方人民政府及其有关部门主要负责人，要求其采取有效措施及时整改。约谈整改情况应当向社会公开。"},{"i":160,"n":"第一百六十条","txt":"国务院生态环境主管部门依法组织实施排放源统计调查，建立健全排放源统计核算方法体系、数据质量控制制度。国家定期组织实施全国污染源普查。"},{"i":161,"n":"第一百六十一条","txt":"国务院生态环境主管部门会同有关部门，建立健全污染损害评估制度。"},{"i":162,"n":"第一百六十二条","txt":"建设项目中的污染防治设施，应当与主体工程同时设计、同时施工、同时投产使用。污染防治设施应当符合经批准的生态环境影响报告书、生态环境影响报告表的要求，不得擅自拆除或者闲置。"},{"i":163,"n":"第一百六十三条","txt":"企业事业单位和其他生产经营者排放污染物的，应当依照法律法规和国务院生态环境主管部门的规定设置、使用污染物排放口（以下简称排污口）。"},{"i":164,"n":"第一百六十四条","txt":"禁止通过暗管、渗井、渗坑、灌注、裂隙、溶洞、篡改或者伪造监测数据、以逃避现场检查为目的的临时停产、非紧急情况下开启应急排放通道、不正常运行污染防治设施等逃避监管的方式排放污染物。"},{"i":165,"n":"第一百六十五条","txt":"各级人民政府应当统筹规划、建设城乡污水处理设施及配套管网，固体废物的收集、运输和处置设施、场所，以及其他污染防治设施，并保障其正常运行，提高城乡污染防治设施建设水平。"},{"i":166,"n":"第一百六十六条","txt":"国务院生态环境主管部门定期公布污染防治技术、工艺和设备导向目录。"},{"i":167,"n":"第一百六十七条","txt":"国家逐步推行重点大气污染物、水污染物等排污权交易，建立健全针对重点污染物排放总量控制指标的排污权交易制度，加强对排污权交易全过程监督管理。"},{"i":168,"n":"第一百六十八条","txt":"直接向环境排放应税污染物的企业事业单位和其他生产经营者，应当依照法律规定缴纳环境保护税。"},{"i":169,"n":"第一百六十九条","txt":"国家鼓励投保环境污染责任保险。"},{"i":170,"n":"第一百七十条","txt":"各级人民政府应当在财政预算中安排资金，支持农村饮用水水源地保护、生活污水治理和生活垃圾等废弃物处理、农业面源污染防治、畜禽养殖和屠宰污染防治、水产养殖污染防治、土壤污染防治和农村工矿污染治理等工作。"},{"i":171,"n":"第一百七十一条","txt":"各级人民政府及其农业农村等有关部门和机构应当指导农业生产经营者科学种植和养殖，科学合理安全使用农药、兽药、饲料和饲料添加剂、肥料等农业投入品，科学处置农用薄膜、农作物秸秆、农业投入品包装废弃物等农业废弃物，加强对农业生产经营活动排放污染物的控制，防止农业面源污染。"},{"i":172,"n":"第一百七十二条","txt":"国家对农业面源污染突出区域强化系统治理，提升农业面源污染防治成效。"},{"i":173,"n":"第一百七十三条","txt":"国务院生态环境主管部门会同有关部门确定重金属污染防治重点地区和重点行业，报国务院批准。重点地区所在设区的市级以上地方人民政府，应当按照国家规定组织编制并实施重金属污染防治方案。重点行业企业应当定期开展隐患排查整治，采取有效措施防治重金属污染。"},{"i":174,"n":"第一百七十四条","txt":"国家建立健全以排污许可制为核心的固定污染源监督管理制度，具体办法由国务院制定。"},{"i":175,"n":"第一百七十五条","txt":"根据污染物产生量、排放量、对生态环境的影响程度等因素，对实行排污许可管理的企业事业单位和其他生产经营者实行排污许可分类管理："},{"i":176,"n":"第一百七十六条","txt":"下列企业事业单位和其他生产经营者应当取得排污许可证："},{"i":177,"n":"第一百七十七条","txt":"设区的市级以上人民政府生态环境主管部门应当加强排污许可的监督管理。"},{"i":178,"n":"第一百七十八条","txt":"企业事业单位和其他生产经营者应当向其生产经营场所所在地设区的市级以上地方人民政府生态环境主管部门申请取得排污许可证。"},{"i":179,"n":"第一百七十九条","txt":"排污许可证是对实行排污许可管理的企业事业单位和其他生产经营者进行生态环境监督管理的主要依据。"},{"i":180,"n":"第一百八十条","txt":"对具备下列条件的实行排污许可管理的企业事业单位和其他生产经营者，颁发排污许可证："},{"i":181,"n":"第一百八十一条","txt":"排污许可证应当记载下列信息："},{"i":182,"n":"第一百八十二条","txt":"排污许可证有效期为五年。在排污许可证有效期内，实行排污许可管理的企业事业单位和其他生产经营者有下列情形之一的，应当重新取得排污许可证："},{"i":183,"n":"第一百八十三条","txt":"实行排污许可管理的企业事业单位和其他生产经营者应当按照排污许可证的要求和有关标准规范，依法开展自行监测，建立管理台账，并保存原始监测记录和管理台账。原始监测记录和管理台账保存期限不得少于五年。"},{"i":184,"n":"第一百八十四条","txt":"实行排污许可重点管理的企业事业单位和其他生产经营者，应当按照国家规定安装、使用、维护污染物排放自动监测设备，开展监控、自动监测，并与生态环境主管部门的监控设备联网，保证自动监测设备正常运行，保存原始监测记录。监测的具体办法由国务院生态环境主管部门制定。"},{"i":185,"n":"第一百八十五条","txt":"实行排污许可管理的企业事业单位和其他生产经营者应当按照规定向社会公开污染物排放种类、排放浓度和排放量，以及污染防治设施的建设运行情况、自行监测数据等污染物排放信息，接受社会监督。"},{"i":186,"n":"第一百八十六条","txt":"污染物产生量、排放量和对生态环境的影响程度都很小的企业事业单位和其他生产经营者，应当填报排污登记表，不实行排污许可管理。排污登记表有效期为五年。"},{"i":187,"n":"第一百八十七条","txt":"本分编适用于大气污染的防治。"},{"i":188,"n":"第一百八十八条","txt":"本法所称大气污染，是指大气因某种物质的介入，而导致其化学、物理等方面特性的改变，危害公众健康或者破坏生态环境，造成大气环境质量恶化的现象。"},{"i":189,"n":"第一百八十九条","txt":"防治大气污染，应当以改善大气环境质量为目标，转变经济发展方式，优化产业结构和布局，调整能源结构、交通运输结构。"},{"i":190,"n":"第一百九十条","txt":"设区的市级以上地方人民政府编制规划，采取有效措施，控制或者逐步削减大气污染物的排放量，使大气环境质量达到规定标准并逐步改善。"},{"i":191,"n":"第一百九十一条","txt":"国务院生态环境主管部门对全国大气污染防治工作实施统一监督管理。地方人民政府生态环境主管部门对本行政区域大气污染防治工作实施统一监督管理。"},{"i":192,"n":"第一百九十二条","txt":"未达到国家大气环境质量标准的地区所在直辖市和设区的市、县级人民政府，应当及时编制大气环境质量限期达标规划，采取有效措施，按照省级以上人民政府规定的期限达到大气环境质量标准。"},{"i":193,"n":"第一百九十三条","txt":"直辖市和设区的市级人民政府编制的大气环境质量限期达标规划应当报国务院生态环境主管部门备案。"},{"i":194,"n":"第一百九十四条","txt":"大气环境质量限期达标规划应当根据大气污染防治的要求和经济、技术条件适时进行评估、修订。"},{"i":195,"n":"第一百九十五条","txt":"制定燃煤、石油焦、生物质燃料、涂料等含挥发性有机物的产品、烟花爆竹以及锅炉等产品的质量标准，应当明确大气污染防治要求。"},{"i":196,"n":"第一百九十六条","txt":"国务院生态环境主管部门组织开展大气环境质量和大气污染源监测，组织建设与管理全国大气环境质量和大气污染源监测网络。"},{"i":197,"n":"第一百九十七条","txt":"企业事业单位和其他生产经营者应当按照国家规定对其排放的工业废气和有毒有害大气污染物进行监测，并保存原始监测记录。监测的具体办法由国务院生态环境主管部门制定。"},{"i":198,"n":"第一百九十八条","txt":"生态环境主管部门应当及时对突发环境污染事件产生的大气污染物进行监测，并向社会公开监测信息。"},{"i":199,"n":"第一百九十九条","txt":"国家鼓励、支持开展对大气污染来源及其变化趋势的分析，发挥科学技术在大气污染防治中的支撑作用。"},{"i":200,"n":"第二百条","txt":"海洋工程大气污染的防治不适用本分编。"},{"i":201,"n":"第二百零一条","txt":"国务院有关部门和地方各级人民政府应当优化煤炭使用方式，减少煤炭生产、贮存、运输、使用、转化过程中的大气污染物排放。"},{"i":202,"n":"第二百零二条","txt":"国家推行煤炭洗选加工，降低煤炭的硫分和灰分，限制高硫分、高灰分煤炭的开采。新建煤矿应当同步建设配套的煤炭洗选设施，使煤炭的硫分、灰分含量达到规定标准；已建成的煤矿除所采煤炭属于低硫分、低灰分或者根据已达标排放的燃煤电厂要求不需要洗选的外，应当限期建成配套的煤炭洗选设施。"},{"i":203,"n":"第二百零三条","txt":"从事煤层气开采利用的，煤层气排放应当符合相关标准规范。"},{"i":204,"n":"第二百零四条","txt":"禁止进口、销售或者燃用不符合质量标准的煤炭，鼓励燃用优质煤炭。"},{"i":205,"n":"第二百零五条","txt":"地方各级人民政府应当采取有效措施，加强散煤的管理，禁止销售不符合散煤质量标准的煤炭，鼓励、支持采取清洁低碳能源、集中供热替代等措施防治燃用散煤造成大气污染。"},{"i":206,"n":"第二百零六条","txt":"石油炼制企业应当按照燃油质量标准生产燃油。"},{"i":207,"n":"第二百零七条","txt":"设区的市级以上地方人民政府可以划定并公布高污染燃料禁燃区，并根据大气环境质量改善要求，逐步扩大高污染燃料禁燃区范围。高污染燃料的目录由国务院生态环境主管部门确定。"},{"i":208,"n":"第二百零八条","txt":"城市建设应当统筹规划，在燃煤供热地区，推进热电联产和集中供热。在集中供热管网覆盖地区，禁止新建、扩建分散燃煤供热锅炉；已建成的不能达标排放的燃煤供热锅炉，应当在设区的市级以上地方人民政府规定的期限内拆除。"},{"i":209,"n":"第二百零九条","txt":"县级以上人民政府市场监督管理部门会同生态环境主管部门对锅炉生产、进口、销售、使用环节执行大气污染防治标准或者要求的情况进行监督检查；不符合大气污染防治标准或者要求的，不得生产、进口、销售或者使用。"},{"i":210,"n":"第二百一十条","txt":"燃煤电厂和其他燃煤单位应当采用清洁生产工艺，配套建设除尘、脱硫、脱硝等装置，或者采取技术改造等其他控制大气污染物排放的措施。"},{"i":211,"n":"第二百一十一条","txt":"钢铁、建材、有色金属、石油、化工等企业生产过程中排放粉尘、硫化物和氮氧化物的，应当采用清洁生产工艺，配套建设除尘、脱硫、脱硝等装置，或者采取技术改造等其他控制大气污染物排放的措施。"},{"i":212,"n":"第二百一十二条","txt":"国家鼓励、支持钢铁、水泥、焦化等重点行业和燃煤锅炉采用超低排放等技术，减少大气污染物的排放。"},{"i":213,"n":"第二百一十三条","txt":"国务院有关部门在各自职责范围内制定含挥发性有机物的原辅材料和产品的挥发性有机物含量限值标准、低挥发性有机物含量的原辅材料和产品标准。"},{"i":214,"n":"第二百一十四条","txt":"生产、使用含挥发性有机物的原辅材料和产品，应当按照国家规定，在密闭空间、设备中进行并安装、使用污染防治设施，或者采取有效措施减少废气排放。"},{"i":215,"n":"第二百一十五条","txt":"国家建立健全产品的低挥发性有机物含量标识制度，低挥发性有机物含量的产品的生产者应当按照规定标识。"},{"i":216,"n":"第二百一十六条","txt":"石油、化工及其他生产、使用有机溶剂的企业，应当采取有效措施对管道、设备进行日常维护、维修，减少物料泄漏，对泄漏的物料应当及时收集处理。"},{"i":217,"n":"第二百一十七条","txt":"钢铁、建材、有色金属、石油、化工、制药、矿产开采企业和其他工业生产企业，应当加强精细化管理，采取集中收集处理等措施，严格控制粉尘和气态污染物的排放。"},{"i":218,"n":"第二百一十八条","txt":"工业生产、垃圾填埋和其他活动产生的可燃性气体应当回收利用，不具备回收利用条件的，应当进行污染防治处理。"},{"i":219,"n":"第二百一十九条","txt":"国家倡导绿色出行，根据城市规划合理控制燃油机动车保有量，大力发展城市公共交通，提高公共交通出行比例。"},{"i":220,"n":"第二百二十条","txt":"重型货车使用较多的重点用车单位应当按照国家规定，将运输及装卸环节排放管理纳入单位污染防治责任制度，加强重型货车大气污染防治。"},{"i":221,"n":"第二百二十一条","txt":"机动车船、非道路移动机械及其发动机不得超过标准排放大气污染物。"},{"i":222,"n":"第二百二十二条","txt":"机动车、非道路移动机械及其发动机生产企业应当对新生产的机动车、非道路移动机械及其发动机进行排放检验。经检验合格的，方可出厂销售。检验信息应当向社会公开，并报生态环境主管部门备案。"},{"i":223,"n":"第二百二十三条","txt":"在用机动车应当按照规定，由机动车排放检验机构定期对其进行排放检验。经检验合格的，方可上道路行驶。未经检验合格的，公安机关交通管理部门不得核发安全技术检验合格标志。"},{"i":224,"n":"第二百二十四条","txt":"生态环境主管部门会同交通运输、住房城乡建设、农业农村、水行政等有关部门对在用非道路移动机械的大气污染物排放状况、排放控制系统运行情况进行监督检查；排放不合格的，不得使用。"},{"i":225,"n":"第二百二十五条","txt":"机动车、非道路移动机械排放检验机构应当依法通过计量认证，使用经依法检定合格的机动车、非道路移动机械排放检验设备，按照国务院生态环境主管部门制定的规范，对机动车、非道路移动机械进行排放检验，并与生态环境主管部门联网，实现检验数据实时共享。机动车、非道路移动机械排放检验机构及其负责人应当对检验数据的真实性、准确性和完整性负责。"},{"i":226,"n":"第二百二十六条","txt":"机动车、非道路移动机械的生产、进口企业应当向社会公开其生产、进口机动车车型、非道路移动机械机型的排放检验信息、污染控制技术信息和有关维修技术信息。"},{"i":227,"n":"第二百二十七条","txt":"国家建立健全机动车和非道路移动机械环保召回制度。"},{"i":228,"n":"第二百二十八条","txt":"在用重型汽车、船舶、非道路移动机械等未按照规定安装排放控制系统或者排放控制系统不符合要求，不能达标排放的，应当加装或者更换符合要求的排放控制系统，或者采取其他有效措施。"},{"i":229,"n":"第二百二十九条","txt":"在用机动车、非道路移动机械等排放大气污染物超过标准的，应当进行维修；经维修或者采用污染控制技术后，大气污染物排放仍不符合国家排放标准的，应当强制报废。其所有人应当将机动车、非道路移动机械等交售给报废回收拆解企业，由报废回收拆解企业按照国家规定进行登记、拆解、销毁等处理。"},{"i":230,"n":"第二百三十条","txt":"县级以上地方人民政府可以根据大气环境质量状况，划定并公布禁止使用高排放非道路移动机械的区域。"},{"i":231,"n":"第二百三十一条","txt":"船舶检验机构对船舶发动机及有关设备进行排放检验。经检验符合国家排放标准的，船舶方可运营。"},{"i":232,"n":"第二百三十二条","txt":"非道路移动机械检验机构对在用非道路移动机械进行排放检验。经检验符合国家排放标准的，方可运营。"},{"i":233,"n":"第二百三十三条","txt":"禁止生产、进口或者销售用于篡改、屏蔽、伪造机动车船、非道路移动机械及其发动机排放检验数据的装置和为虚假排放检验提供条件的检验设备。"},{"i":234,"n":"第二百三十四条","txt":"内河和江海直达船舶应当使用符合标准的燃油。远洋船舶靠港后应当使用符合大气污染物控制要求的燃油。"},{"i":235,"n":"第二百三十五条","txt":"新建码头应当按照规定规划、设计和建设岸基供电设施；已建成的码头应当按照规定逐步实施岸基供电设施改造。具备岸电使用条件的船舶靠港应当按照国家规定使用岸电，但是使用清洁低碳能源的除外。具备岸电供应能力的港口经营人、岸电供电企业应当按照国家规定为具备岸电使用条件的船舶提供岸电。"},{"i":236,"n":"第二百三十六条","txt":"禁止生产、进口或者销售不符合标准的机动车船、非道路移动机械用燃料和氮氧化物还原剂；禁止向机动车、非道路移动机械、内河和江海直达船舶销售非机动车船用燃料；禁止机动车、非道路移动机械、内河和江海直达船舶使用非机动车船用燃料。"},{"i":237,"n":"第二百三十七条","txt":"发动机油、氮氧化物还原剂、燃料和润滑油添加剂及其他添加剂的有毒有害物质含量和其他大气污染防治指标，应当符合相关标准的要求，不得损害机动车船、非道路移动机械排放控制系统效果和耐久性，不得增加新的大气污染物排放。"},{"i":238,"n":"第二百三十八条","txt":"国家积极推进民用航空器的大气污染防治，鼓励在设计、生产、使用过程中采取有效措施减少大气污染物排放。"},{"i":239,"n":"第二百三十九条","txt":"地方各级人民政府应当加强对建设施工和运输的管理，保持道路清洁，控制料堆和渣土堆放，扩大绿地、水面、湿地和地面铺装面积，防治扬尘污染。"},{"i":240,"n":"第二百四十条","txt":"建设单位应当将扬尘污染防治费用列入工程造价，在施工合同中明确施工单位的扬尘污染防治责任。施工单位应当制定具体的施工扬尘污染防治实施方案。"},{"i":241,"n":"第二百四十一条","txt":"运输煤炭、垃圾、渣土、砂石、土方、灰浆等散装、流体物料的车辆和船舶应当采取密闭或者其他有效措施防止物料遗撒造成扬尘污染，并按照规定路线行驶。"},{"i":242,"n":"第二百四十二条","txt":"市政河道和河道沿线、公共用地的裸露地面及其他城镇裸露地面，有关部门应当按照规划组织实施绿化或者透水铺装。"},{"i":243,"n":"第二百四十三条","txt":"贮存煤炭、煤矸石、煤渣、煤灰、水泥、石灰、石膏、砂土、铁矿石等易产生扬尘的物料应当密闭；不能密闭的，应当设置不低于堆放物高度的严密围挡，并采取有效覆盖措施防治扬尘污染。"},{"i":244,"n":"第二百四十四条","txt":"禁止在人口集中地区对树木、花草喷洒剧毒、高毒农药。"},{"i":245,"n":"第二百四十五条","txt":"各级人民政府及其农业农村等有关部门应当鼓励、支持采用先进适用技术，对秸秆、落叶等进行肥料化、饲料化、能源化、工业原料化、食用菌基料化等综合利用，加大对秸秆还田、收集一体化等农业机械的财政补贴力度。"},{"i":246,"n":"第二百四十六条","txt":"地方各级人民政府应当科学精准加强秸秆、落叶等焚烧的组织、指导和管理。禁止在人口集中地区、机场周围、交通干线附近以及省级以上人民政府划定的其他区域和规定的时段露天焚烧秸秆、落叶等产生烟尘污染的物质。"},{"i":247,"n":"第二百四十七条","txt":"国务院生态环境主管部门会同国务院卫生健康主管部门，根据大气污染物对公众健康、生态环境的危害和影响程度，制定公布有毒有害大气污染物名录并适时更新，实行风险管理。"},{"i":248,"n":"第二百四十八条","txt":"向大气排放持久性有机污染物的企业事业单位和其他生产经营者以及废弃物焚烧设施的运营单位，应当按照国家规定，采取有利于减少持久性有机污染物排放的技术方法和工艺，配备有效的净化装置，实现达标排放。"},{"i":249,"n":"第二百四十九条","txt":"各级人民政府及其有关部门编制国土空间规划和相关规划，应当统筹规划，合理安排土地用途和建设布局，防止、减少恶臭污染。"},{"i":250,"n":"第二百五十条","txt":"地方各级人民政府应当加强对餐饮服务业布局和设置的引导，在经营主体登记注册环节提示选址禁止性要求。"},{"i":251,"n":"第二百五十一条","txt":"禁止在人口集中地区和其他依法需要特殊保护的区域焚烧沥青、油毡、橡胶、塑料、皮革、垃圾及其他产生有毒有害烟尘和恶臭气体的物质。"},{"i":252,"n":"第二百五十二条","txt":"国家鼓励和倡导文明、绿色祭祀。"},{"i":253,"n":"第二百五十三条","txt":"从事服装干洗和机动车维修等服务活动的经营者，应当按照国家相关标准或者要求设置异味和废气处理装置等污染防治设施并保持正常使用，防止影响周边环境。"},{"i":254,"n":"第二百五十四条","txt":"国家鼓励、支持消耗臭氧层物质替代品的生产、使用，逐步减少直至停止消耗臭氧层物质的生产、使用。"},{"i":255,"n":"第二百五十五条","txt":"国家建立健全重点区域大气污染联防联控机制，统筹协调重点区域内大气污染防治工作。国务院生态环境主管部门根据主体功能区划、区域大气环境质量状况和大气污染传输扩散规律，划定国家大气污染防治重点区域，报国务院批准。"},{"i":256,"n":"第二百五十六条","txt":"国务院生态环境主管部门会同有关部门和国家大气污染防治重点区域内有关省、自治区、直辖市人民政府，根据重点区域经济社会发展和大气环境的承载能力，制定重点区域大气污染联合防治行动计划，明确控制目标，优化区域经济布局，统筹交通管理，发展清洁低碳能源，提出重点防治任务和措施，促进重点区域大气环境质量改善。"},{"i":257,"n":"第二百五十七条","txt":"国务院发展改革部门会同国务院生态环境主管部门，结合国家大气污染防治重点区域产业发展实际和大气环境质量状况，进一步提高污染防治、能源消耗等要求。"},{"i":258,"n":"第二百五十八条","txt":"编制可能对国家大气污染防治重点区域的大气环境造成严重污染的有关工业园区、开发区、区域产业和发展等规划，规划编制机关应当与重点区域内有关省、自治区、直辖市人民政府或者有关部门会商。"},{"i":259,"n":"第二百五十九条","txt":"国家大气污染防治重点区域内新建、改建、扩建用煤项目的，应当实行煤炭的等量或者减量替代。"},{"i":260,"n":"第二百六十条","txt":"国务院生态环境主管部门应当组织建立健全国家大气污染防治重点区域的大气环境质量监测、大气污染源监测等相关信息共享机制，利用监测、模拟以及卫星、航测、遥感等新技术分析重点区域内大气污染来源及其变化趋势，并向社会公开。"},{"i":261,"n":"第二百六十一条","txt":"国家建立健全重污染天气监测预警体系。"},{"i":262,"n":"第二百六十二条","txt":"设区的市级以上地方人民政府以及可能发生重污染天气的县级人民政府，应当制定重污染天气应对预案，报上一级人民政府生态环境主管部门备案并公布。"},{"i":263,"n":"第二百六十三条","txt":"设区的市级以上地方人民政府生态环境主管部门会同气象主管机构建立健全会商机制，进行大气环境质量预报。可能发生重污染天气的，应当及时向本级人民政府报告。设区的市级以上地方人民政府依据重污染天气预报信息，进行综合研判，确定预警等级并及时发出预警。预警等级根据情况变化及时调整。任何单位和个人不得擅自发布重污染天气预报预警信息。"},{"i":264,"n":"第二百六十四条","txt":"县级以上地方人民政府应当依据重污染天气的预警等级，及时启动应对预案，根据应对的需要可以采取责令有关企业停产或者限产、限制部分机动车行驶和非道路移动机械使用、禁止燃放烟花爆竹、停止工地土石方作业和建筑物拆除施工、停止露天烧烤、停止幼儿园和学校组织的户外活动、组织开展人工影响天气作业等应对措施。"},{"i":265,"n":"第二百六十五条","txt":"国家加强重污染天气重点行业绩效分级。绩效分级水平作为重污染天气差异化采取应对措施的依据。"},{"i":266,"n":"第二百六十六条","txt":"本分编适用于江河湖泊、运河、渠道、水库等地表水体以及地下水体污染的防治。"},{"i":267,"n":"第二百六十七条","txt":"本法所称水污染，是指水体因某种物质的介入，而导致其化学、物理、生物或者放射性等方面特性的改变，从而影响水的有效利用，危害公众健康或者破坏生态环境，造成水质恶化的现象。"},{"i":268,"n":"第二百六十八条","txt":"水污染防治应当优先保护饮用水水源、保障饮用水安全，严格控制工业污染、城镇生活污染，防治农业面源污染，加强入河排污口设置和管理，积极推进生态治理工程建设，预防、控制和减少水环境污染和生态破坏。"},{"i":269,"n":"第二百六十九条","txt":"国务院生态环境主管部门对全国水污染防治工作实施统一监督管理。国务院生态环境主管部门流域生态环境监督管理机构依法开展流域水污染防治监督管理相关工作。地方人民政府生态环境主管部门对本行政区域水污染防治工作实施统一监督管理。"},{"i":270,"n":"第二百七十条","txt":"防治水污染应当按流域或者按区域进行统一规划。国务院生态环境主管部门会同国务院发展改革、水行政等有关部门编制国家流域水生态环境保护规划，明确长江、黄河、淮河、海河、珠江、松花江、辽河等流域的生态环境保护要求，报国务院批准。"},{"i":271,"n":"第二百七十一条","txt":"有关设区的市、县级人民政府应当按照水生态环境保护规划确定的水生态环境质量改善目标的要求，编制限期达标规划，采取有效措施按期达标。"},{"i":272,"n":"第二百七十二条","txt":"国家建立健全水生态环境质量监测和水污染物排放监测制度。国务院生态环境主管部门会同国务院水行政等有关部门组织监测网络，统一规划国家水生态环境质量监测站点的设置，建立健全监测数据共享机制，加强对水生态环境监测的管理。"},{"i":273,"n":"第二百七十三条","txt":"国务院生态环境主管部门及其流域生态环境监督管理机构负责监测省界水体的水生态环境质量状况。"},{"i":274,"n":"第二百七十四条","txt":"国务院生态环境主管部门会同国务院卫生健康主管部门，根据对公众健康、生态环境的危害和影响程度，制定公布有毒有害水污染物名录并适时更新，实行风险管理。"},{"i":275,"n":"第二百七十五条","txt":"新设、改设、扩大入河排污口，应当按照规定报经有管辖权的生态环境主管部门或者国务院生态环境主管部门流域生态环境监督管理机构同意。新设、改设、扩大可能影响防洪、供水、堤防安全、河势稳定的入河排污口的，审批时应当征求地方人民政府水行政主管部门或者有关流域管理机构的意见。入河排污口设置和管理的具体办法由国务院生态环境主管部门制定。"},{"i":276,"n":"第二百七十六条","txt":"水生态环境质量不达标的水功能区，除城乡污水集中处理设施等重要民生工程的入河排污口外，应当严格控制新设、改设、扩大入河排污口。"},{"i":277,"n":"第二百七十七条","txt":"县级以上地方人民政府应当对本行政区域的入河排污口组织开展排查整治，明确责任主体，实施分类管理。"},{"i":278,"n":"第二百七十八条","txt":"多个单位和个人共用入河排污口的责任主体，应当加强入河排污口监测，按照规定开展监控、自动监测。"},{"i":279,"n":"第二百七十九条","txt":"禁止向水体排放油类、酸液、碱液、剧毒废液。禁止在水体清洗装贮过油类或者有毒有害污染物的车辆和容器。"},{"i":280,"n":"第二百八十条","txt":"向水体排放含热废水，应当采取有效措施，保证水体的水温符合水生态环境质量标准，避免对珍稀濒危水生生物、水产资源造成危害。"},{"i":281,"n":"第二百八十一条","txt":"含病原体的污水应当经过消毒处理，符合国家相关标准后，方可排放。"},{"i":282,"n":"第二百八十二条","txt":"禁止向水体排放、倾倒工业废渣、城镇垃圾和其他废弃物。"},{"i":283,"n":"第二百八十三条","txt":"地方各级人民政府应当组织开展本行政区域的黑臭水体调查和治理工作，建立健全长效机制，制定公布黑臭水体清单，科学制定黑臭水体治理方案，系统推进黑臭水体整治，防止水体返黑返臭。"},{"i":284,"n":"第二百八十四条","txt":"县级以上人民政府应当组织水行政、自然资源、生态环境等有关部门开展地下水状况调查评价，包括地下水资源调查评价、地下水污染调查评价和水文地质勘查评价等。"},{"i":285,"n":"第二百八十五条","txt":"国务院生态环境主管部门会同国务院水行政、自然资源等有关部门，指导全国地下水污染防治重点区划定工作。"},{"i":286,"n":"第二百八十六条","txt":"在泉域保护范围以及岩溶强发育、存在较多落水洞和岩溶漏斗的区域，不得新建、改建、扩建可能造成地下水污染的建设项目。"},{"i":287,"n":"第二百八十七条","txt":"化工园区和化工项目、矿山开采区、尾矿库、危险废物处置场、垃圾填埋场等的运营、管理单位，应当采取防渗漏等措施，并建设地下水水质监测井进行监测，防止地下水污染。"},{"i":288,"n":"第二百八十八条","txt":"多层含水层开采、回灌地下水应当防止串层污染。"},{"i":289,"n":"第二百八十九条","txt":"建设地下工程设施或者进行地下勘探、采矿等活动，应当采取防护措施，防止地下水污染。"},{"i":290,"n":"第二百九十条","txt":"人工回灌补给地下水，应当符合相关水质标准，不得恶化地下水水质。"},{"i":291,"n":"第二百九十一条","txt":"可能发生水污染事故的企业事业单位，应当制定有关水污染事故的应急预案，做好应急准备，并定期进行演练。"},{"i":292,"n":"第二百九十二条","txt":"企业事业单位发生事故或者其他突发性事件，造成或者可能造成水污染事故的，应当立即启动本单位的应急预案，采取隔离等应急措施，防止水污染物进入水体，并向事故发生地县级以上地方人民政府或者生态环境主管部门报告。生态环境主管部门接到报告后，应当及时向本级人民政府报告，并抄送水行政、应急管理等有关部门。"},{"i":293,"n":"第二百九十三条","txt":"设区的市、县级人民政府应当组织制定饮用水安全突发事件应急预案。"},{"i":294,"n":"第二百九十四条","txt":"国家推行重点行业企业污水治理与排放水平绩效分级。"},{"i":295,"n":"第二百九十五条","txt":"各级人民政府应当加强水污染防治，安排必要的资金用于下列事项："},{"i":296,"n":"第二百九十六条","txt":"海洋污染的防治不适用本分编。"},{"i":297,"n":"第二百九十七条","txt":"国务院有关部门和县级以上地方人民政府应当合理规划工业布局，要求造成水污染的企业进行技术改造，采取综合防治措施，提高水的重复利用率，减少废水和污染物排放量。"},{"i":298,"n":"第二百九十八条","txt":"排放工业废水的企业应当采取有效措施，收集和处理产生的全部废水，防止污染环境。含有毒有害水污染物的工业废水应当分类收集和处理，防止渗漏、流失，不得稀释排放。"},{"i":299,"n":"第二百九十九条","txt":"禁止建设不符合国家产业政策的小型造纸、制革、印染、染料、炼焦、炼硫、炼砷、炼汞、炼油、电镀、农药、石棉、水泥、玻璃、钢铁、火电及其他严重污染水环境的生产项目。"},{"i":300,"n":"第三百条","txt":"企业应当采用原材料利用效率高、污染物排放量少的清洁工艺，并加强管理，减少水污染物的产生。"},{"i":301,"n":"第三百零一条","txt":"城镇污水应当集中处理。"},{"i":302,"n":"第三百零二条","txt":"国务院住房城乡建设主管部门会同国务院发展改革部门、生态环境主管部门，根据国土空间规划和水生态环境保护规划，组织编制全国城镇污水处理设施建设相关规划。县级以上地方人民政府组织住房城乡建设、发展改革、生态环境、水行政等有关部门依法编制本行政区域的城镇污水处理设施建设相关规划。县级以上地方人民政府住房城乡建设主管部门应当按照城镇污水处理设施建设相关规划，组织建设城镇污水集中处理设施及配套管网、污泥无害化处理处置设施，并加强监督管理。"},{"i":303,"n":"第三百零三条","txt":"向城镇污水集中处理设施排放水污染物，应当符合水污染物排放标准。"},{"i":304,"n":"第三百零四条","txt":"城镇污水集中处理设施的运营单位和污泥无害化处理处置单位应当无害化处理处置污泥，保证处理处置后的污泥符合国家标准，并对污泥的流向、用途、用量等进行跟踪、记录，并报告城镇排水主管部门、生态环境主管部门。"},{"i":305,"n":"第三百零五条","txt":"国家支持农村污水、垃圾处理设施的建设，因地制宜推进农村污水、垃圾处理和厕所改造。"},{"i":306,"n":"第三百零六条","txt":"制定农药、肥料等产品的质量标准和使用标准，应当适应水生态环境保护的要求。"},{"i":307,"n":"第三百零七条","txt":"运输、贮存农药和处置过期失效农药，应当加强管理，防止造成水污染。"},{"i":308,"n":"第三百零八条","txt":"县级以上地方人民政府农业农村等有关部门应当在各自职责范围内推广高效低毒低残留农药和测土配方施肥技术，控制农药和化肥的过量使用，防止造成水污染。"},{"i":309,"n":"第三百零九条","txt":"国家支持畜禽养殖场建设畜禽粪污的综合利用或者无害化处理设施。"},{"i":310,"n":"第三百一十条","txt":"从事水产养殖活动应当保护水域生态环境，排放水产养殖尾水污染物等应当符合污染物排放标准，防止污染水环境。"},{"i":311,"n":"第三百一十一条","txt":"农田灌溉用水应当符合相应的水质标准，防止污染土壤、地下水和农产品。"},{"i":312,"n":"第三百一十二条","txt":"船舶排放含油污水、生活污水，应当符合船舶污染物排放标准。从事海洋航运的船舶进入内河和港口的，应当遵守内河的船舶污染物排放标准。"},{"i":313,"n":"第三百一十三条","txt":"进入中华人民共和国内河的国际航线船舶排放压载水的，应当采用压载水处理装置或者采取其他等效措施，对压载水进行灭活等处理。禁止排放不符合规定的船舶压载水。"},{"i":314,"n":"第三百一十四条","txt":"船舶应当按照国家规定配备相应的防污设备和器材，并持有合法有效的防治水域环境污染的证书与文书。"},{"i":315,"n":"第三百一十五条","txt":"港口、码头、装卸站和船舶修造厂所在地县级以上地方人民政府应当统筹规划、建设船舶污染物、废弃物的接收、转运、处理处置设施，建立健全相应的接收、转运、处理处置多部门联合监督管理制度。"},{"i":316,"n":"第三百一十六条","txt":"船舶及有关作业单位从事有污染风险的作业活动，应当遵守法律法规、标准和国务院有关部门的规定，采取有效措施，防止造成水污染。海事管理机构、渔业渔政主管部门应当在各自职责范围内加强对船舶及有关作业活动的监督管理。"},{"i":317,"n":"第三百一十七条","txt":"国家建立健全饮用水水源保护区制度。饮用水水源保护区分为一级保护区和二级保护区；必要时，可以在饮用水水源保护区外围划定一定的区域作为准保护区。"},{"i":318,"n":"第三百一十八条","txt":"在饮用水水源保护区内，禁止设置排污口。"},{"i":319,"n":"第三百一十九条","txt":"禁止在饮用水水源一级保护区内新建、改建、扩建与供水设施和保护水源无关的建设项目；已建成的与供水设施和保护水源无关的建设项目，由县级以上人民政府责令拆除或者关闭。"},{"i":320,"n":"第三百二十条","txt":"禁止在饮用水水源二级保护区内新建、改建、扩建排放污染物的建设项目；已建成的排放污染物的建设项目，由县级以上人民政府责令拆除或者关闭。"},{"i":321,"n":"第三百二十一条","txt":"禁止在饮用水水源准保护区内新建、扩建对水体污染严重的建设项目；改建建设项目，不得增加排污量。"},{"i":322,"n":"第三百二十二条","txt":"县级以上地方人民政府应当根据保护饮用水水源的需要，在准保护区内采取工程措施或者建造湿地、水源涵养林等生态保护措施，防止水污染物直接排入饮用水水体，确保饮用水安全。"},{"i":323,"n":"第三百二十三条","txt":"县级以上地方人民政府应当组织生态环境等有关部门，对饮用水水源保护区、地下水型饮用水源的补给区以及供水单位周边区域的生态环境状况和污染风险进行调查评估，筛查可能存在的污染风险因素，并采取相应的风险防范措施。"},{"i":324,"n":"第三百二十四条","txt":"单一水源供水城市的人民政府应当建设应急水源或者备用水源，有条件的地区可以开展区域联网供水。"},{"i":325,"n":"第三百二十五条","txt":"饮用水供水单位应当做好取水口和出水口的水质检测工作。发现取水口水质不符合饮用水水源水质标准或者出水口水质不符合饮用水卫生标准的，应当及时采取相应措施，并向所在地设区的市、县级人民政府供水主管部门报告。供水主管部门接到报告后，应当通报生态环境、卫生健康、水行政等有关部门。"},{"i":326,"n":"第三百二十六条","txt":"县级以上地方人民政府应当组织有关部门监测、评估本行政区域饮用水水源、供水单位供水和用户水龙头出水的水质等饮用水安全状况。"},{"i":327,"n":"第三百二十七条","txt":"省级以上人民政府根据水生态环境保护的需要，可以规定在饮用水水源保护区内，采取禁止或者限制使用含磷洗涤剂、农药、化肥以及限制种植养殖等措施。"},{"i":328,"n":"第三百二十八条","txt":"县级以上人民政府可以对自然保护地水体、重要渔业水体和其他具有特殊经济文化价值的水体划定保护区，并采取有效措施，保证保护区的水质符合规定用途的水生态环境质量标准。"},{"i":329,"n":"第三百二十九条","txt":"在自然保护地水体、重要渔业水体和其他具有特殊经济文化价值的水体的保护区内，禁止新设排污口；法律、行政法规另有规定的除外。在保护区附近新设排污口，应当科学论证，制定水污染防治方案，采取有效措施保证保护区水体不受污染。"},{"i":330,"n":"第三百三十条","txt":"国家加强重点流域水污染的综合治理、系统治理、源头治理，推进重点河湖综合整治。"},{"i":331,"n":"第三百三十一条","txt":"国务院生态环境主管部门会同国务院水行政等有关部门和有关省、自治区、直辖市人民政府，建立健全重要江河湖泊的流域水生态环境联合保护协调机制。"},{"i":332,"n":"第三百三十二条","txt":"对没有国家水污染物排放标准的特色产业、特有污染物，以及国家有明确要求的特定水污染源或者水污染物，重点流域省、自治区、直辖市人民政府应当补充制定地方水污染物排放标准，报国务院生态环境主管部门备案。"},{"i":333,"n":"第三百三十三条","txt":"重点流域产业结构和布局应当与其生态环境的承载能力相适应。禁止重污染企业和项目向重点流域中上游转移。"},{"i":334,"n":"第三百三十四条","txt":"本分编适用于海洋污染的防治。"},{"i":335,"n":"第三百三十五条","txt":"本法所称海洋污染，是指直接或者间接地把物质或者能量引入海洋，导致损害海洋生物资源、危害人体健康、妨害渔业和海上其他合法活动、损害海水使用素质和减损生态环境质量的现象。"},{"i":336,"n":"第三百三十六条","txt":"国务院生态环境主管部门负责全国防治陆源污染物、海岸工程和海洋工程建设项目、海洋倾倒废弃物对海洋环境污染损害的工作。"},{"i":337,"n":"第三百三十七条","txt":"跨部门的重大海洋污染防治工作，由国务院生态环境主管部门协调；协调未能解决的，由国务院作出决定。"},{"i":338,"n":"第三百三十八条","txt":"国务院生态环境主管部门会同有关部门、机构和沿海省、自治区、直辖市人民政府编制全国海洋生态环境保护规划，报国务院批准后实施。"},{"i":339,"n":"第三百三十九条","txt":"国务院生态环境主管部门负责海洋生态环境监测工作，组织实施海洋生态环境质量监测，统一发布国家海洋生态环境状况公报，定期组织对海洋生态环境质量状况进行调查评价。"},{"i":340,"n":"第三百四十条","txt":"国务院有关部门和海警机构应当向国务院生态环境主管部门提供编制国家海洋生态环境状况公报所必需的入海河口和海洋生态环境监测、调查、监视等方面的资料。"},{"i":341,"n":"第三百四十一条","txt":"国家加强海洋辐射环境监测，国务院生态环境主管部门负责制定海洋辐射环境应急监测方案并组织实施。"},{"i":342,"n":"第三百四十二条","txt":"企业事业单位和其他生产经营者应当优先使用清洁低碳能源，采用资源利用率高、污染物排放量少的清洁生产工艺，防止对海洋环境的污染。"},{"i":343,"n":"第三百四十三条","txt":"沿海县级以上地方人民政府因地制宜依法编制并组织实施养殖水域滩涂规划，确定可以用于养殖业的水域和滩涂，科学划定海水养殖限养区和养殖区，建立禁养区内海水养殖的清理和退出机制。"},{"i":344,"n":"第三百四十四条","txt":"因发生事故或者其他突发性事件，造成或者可能造成海洋环境污染、生态破坏事件的单位和个人，应当立即采取有效措施解除或者减轻危害，及时通报可能受到危害者，并向负有海洋生态环境保护监督管理职责的部门、机构报告，接受调查处理。"},{"i":345,"n":"第三百四十五条","txt":"国家根据防止海洋环境污染的需要，制定国家重大海上污染事件应急预案，建立健全海上溢油污染等应急机制，保障应对工作的必要经费。"},{"i":346,"n":"第三百四十六条","txt":"负有海洋生态环境保护监督管理职责的部门、机构，有权对从事影响海洋生态环境活动的单位和个人进行监督检查，可以在海上开展联合执法；在巡航监视中发现违法行为时，应当依法予以制止并调查取证，必要时有权采取有效措施，防止事态扩大，并报告有关部门、机构处理。"},{"i":347,"n":"第三百四十七条","txt":"向海域排放陆源污染物，应当严格执行有关规定和标准。"},{"i":348,"n":"第三百四十八条","txt":"入海排污口位置的选择，应当符合国土空间用途管制要求，根据海水动力条件和有关规定，经科学论证后，报设区的市级以上人民政府生态环境主管部门备案。入海排污口的责任主体应当加强入海排污口监测，按照规定开展监控、自动监测。"},{"i":349,"n":"第三百四十九条","txt":"在自然保护地、重要渔业水域、海水浴场、生态保护红线区域及其他需要特别保护的区域，禁止新设工业排污口和城镇污水集中处理设施排污口；法律、行政法规另有规定的除外。"},{"i":350,"n":"第三百五十条","txt":"经开放式沟、渠向海洋排放污染物的，对开放式沟、渠按照有关规定和标准实施水生态环境质量管理。"},{"i":351,"n":"第三百五十一条","txt":"国务院有关部门、县级以上地方人民政府及其有关部门应当按照河海联动的原则，依照水污染防治有关法律、行政法规的规定，加强入海河流管理，协同推进入海河流污染防治，使入海河口的水质符合入海河口生态环境质量要求。"},{"i":352,"n":"第三百五十二条","txt":"禁止向海域排放油类、酸液、碱液、剧毒废液。"},{"i":353,"n":"第三百五十三条","txt":"含病原体的医疗污水、生活污水和工业废水应当经过处理，符合有关排放标准后，方可排入海域。"},{"i":354,"n":"第三百五十四条","txt":"含有机物和营养物质的工业废水、生活污水，应当严格控制向海湾、半封闭海及其他自净能力较差的海域排放。"},{"i":355,"n":"第三百五十五条","txt":"向海域排放含热废水，应当采取有效措施，保证邻近自然保护地、渔业水域的水温符合海洋生态环境质量标准，避免对珍稀濒危海洋生物、海洋水产资源造成危害。"},{"i":356,"n":"第三百五十六条","txt":"沿海地方各级人民政府应当加强农业面源污染防治。沿海农田、林场施用化学农药，应当执行国家农药安全使用的规定和标准。沿海农田、林场应当合理使用化肥和植物生长调节剂。"},{"i":357,"n":"第三百五十七条","txt":"在沿海陆域弃置、堆放和处理尾矿、矿渣、煤灰渣、垃圾和其他固体废物的，依照法律规定执行，并采取有效措施防止固体废物进入海洋。"},{"i":358,"n":"第三百五十八条","txt":"沿海县级以上地方人民政府负责其管理海域的海洋垃圾污染防治，建立健全海洋垃圾监测、清理制度，统筹规划、建设陆域接收、转运、处理海洋垃圾的设施，明确有关部门、乡镇、街道、企业事业单位等的海洋垃圾管控区域，建立海洋垃圾监测、拦截、收集、打捞、运输、处理体系并组织实施，采取有效措施鼓励、支持公众参与上述活动。"},{"i":359,"n":"第三百五十九条","txt":"禁止经中华人民共和国内水、领海过境转移危险废物。"},{"i":360,"n":"第三百六十条","txt":"沿海县级以上地方人民政府应当建设和完善排水管网，根据改善海洋生态环境质量的需要建设污水处理设施，加强城乡污水处理。"},{"i":361,"n":"第三百六十一条","txt":"国家采取必要措施，防止、减少和控制来自大气层或者通过大气层造成的海洋污染。"},{"i":362,"n":"第三百六十二条","txt":"新建、改建、扩建海岸工程和海洋工程建设项目，应当遵守国家有关建设项目生态环境保护的规定，并把污染防治和生态保护所需资金纳入建设项目投资计划。"},{"i":363,"n":"第三百六十三条","txt":"禁止在沿海陆域建设不符合国家产业政策的化学制浆造纸、化工、印染、制革、电镀、酿造、炼油、岸边冲滩拆船及其他严重污染海洋环境的生产项目。"},{"i":364,"n":"第三百六十四条","txt":"从岸上打井开采海底矿产资源，应当采取有效措施，防止污染海洋环境。"},{"i":365,"n":"第三百六十五条","txt":"海岸工程和海洋工程建设项目不得使用含超标放射性物质或者易溶出有毒有害物质的材料；不得造成领海基点及其周边环境的侵蚀、淤积、损害，不得危及领海基点的稳定。"},{"i":366,"n":"第三百六十六条","txt":"海岸工程和海洋工程建设项目需要爆破作业时，应当采取有效措施，保护海洋生态环境。"},{"i":367,"n":"第三百六十七条","txt":"海岸工程和海洋工程建设项目不得违法向海洋排放污染物、废弃物及其他有害物质。"},{"i":368,"n":"第三百六十八条","txt":"海洋油气钻井平台（船）、生产生活平台、生产储卸装置等海洋油气装备及其有关海上设施，不得向海域处置含油的工业固体废物。处置其他固体废物，不得造成海洋环境污染。"},{"i":369,"n":"第三百六十九条","txt":"海上试油时，应当确保油气充分燃烧，油和油性混合物不得排放入海。"},{"i":370,"n":"第三百七十条","txt":"勘探开发海洋油气资源，应当按照规定制定油气污染应急预案，报国务院生态环境主管部门海域派出机构备案。"},{"i":371,"n":"第三百七十一条","txt":"任何个人和未经批准的单位，不得向中华人民共和国管辖海域倾倒任何废弃物。"},{"i":372,"n":"第三百七十二条","txt":"国务院生态环境主管部门根据废弃物的毒性、有毒物质含量和对海洋生态环境的影响程度，制定海洋倾倒废弃物评价程序和标准。"},{"i":373,"n":"第三百七十三条","txt":"国务院生态环境主管部门会同国务院自然资源主管部门编制全国海洋倾倒区规划，并征求国务院交通运输、渔业渔政等有关部门和海警机构的意见，报国务院批准。"},{"i":374,"n":"第三百七十四条","txt":"国务院生态环境主管部门组织开展海洋倾倒区使用状况评估，根据评估结果予以调整、暂停使用或者封闭海洋倾倒区。"},{"i":375,"n":"第三百七十五条","txt":"获准和实施倾倒废弃物的单位，应当按照许可证注明的期限及条件，到指定的区域进行倾倒。倾倒作业船舶等载运工具应当安装使用符合要求的海洋倾倒在线监控设备，并与国务院生态环境主管部门监管系统联网。"},{"i":376,"n":"第三百七十六条","txt":"获准和实施倾倒废弃物的单位，应当按照规定向颁发许可证的国务院生态环境主管部门海域派出机构报告倾倒情况。倾倒废弃物的船舶应当向驶出港的海事管理机构、海警机构报告。"},{"i":377,"n":"第三百七十七条","txt":"获准倾倒废弃物的单位委托实施废弃物海洋倾倒作业的，应当对受托单位的主体资格、技术能力和信用状况进行核实，依法签订书面合同，在合同中约定污染防治和生态保护要求，并监督实施。"},{"i":378,"n":"第三百七十八条","txt":"向海洋倾倒废弃物，应当按照国家规定缴纳倾倒费。具体办法由国务院发展改革部门、财政部门会同国务院生态环境主管部门制定。"},{"i":379,"n":"第三百七十九条","txt":"禁止海上焚烧废弃物。"},{"i":380,"n":"第三百八十条","txt":"在中华人民共和国管辖海域，任何船舶及有关作业不得违法向海洋排放船舶垃圾、生活污水、含油污水、含有毒有害物质污水、废气等污染物，废弃物，压载水和沉积物及其他有害物质。"},{"i":381,"n":"第三百八十一条","txt":"船舶应当配备相应的防污设备和器材。"},{"i":382,"n":"第三百八十二条","txt":"船舶应当遵守海上交通安全法律法规的规定，防止因碰撞、触礁、搁浅、火灾或者爆炸等引起的海难事故，造成海洋环境污染。"},{"i":383,"n":"第三百八十三条","txt":"国家完善并实施船舶油污损害民事赔偿责任制度；按照船舶油污损害赔偿责任由船东和货主共同承担风险的原则，完善并实施船舶油污保险、油污损害赔偿基金制度，具体办法由国务院制定。"},{"i":384,"n":"第三百八十四条","txt":"载运具有污染危害性货物进出港口的船舶，其承运人、货物所有人或者代理人，应当事先向海事管理机构申报。经批准后，方可进出港口或者装卸作业。"},{"i":385,"n":"第三百八十五条","txt":"交付船舶载运污染危害性货物的，托运人应当将货物的正式名称、污染危害性以及应当采取的防护措施如实告知承运人。污染危害性货物的单证、包装、标志、数量限制等，应当符合对所交付货物的有关规定。"},{"i":386,"n":"第三百八十六条","txt":"港口、码头、装卸站和船舶修造拆解单位所在地县级以上地方人民政府应当统筹规划、建设船舶污染物等的接收、转运、处理处置设施，建立健全相应的接收、转运、处理处置多部门联合监督管理制度。"},{"i":387,"n":"第三百八十七条","txt":"国家海事管理机构组织制定中国籍船舶禁止或者限制安装和使用的有害材料名录。"},{"i":388,"n":"第三百八十八条","txt":"从事船舶拆解的单位，应当采取有效的污染防治措施，在船舶拆解前将船舶污染物减至最小量，对拆解产生的船舶污染物、废弃物和其他有害物质进行安全与环境无害化处置，防止污染海洋环境。拆解的船舶部件不得入水。"},{"i":389,"n":"第三百八十九条","txt":"船舶应当按照国家规定采取有效措施提高能效水平。倡导绿色低碳智能航运，鼓励船舶使用清洁低碳能源，淘汰高耗能高排放老旧船舶，减少温室气体和大气污染物的排放。沿海县级以上地方人民政府应当制定港口岸电、船舶受电等设施建设和改造计划，并组织实施。港口岸电设施的供电能力应当与靠港船舶的用电需求相适应。"},{"i":390,"n":"第三百九十条","txt":"国务院交通运输主管部门可以划定船舶污染物排放控制区。进入控制区的船舶应当符合船舶污染物排放相关控制要求。"},{"i":391,"n":"第三百九十一条","txt":"船舶及有关作业活动应当遵守法律法规、标准和国务院有关部门的规定，采取有效措施，防止造成海洋环境污染。海事管理机构等应当加强对船舶及有关作业活动的监督管理。"},{"i":392,"n":"第三百九十二条","txt":"船舶发生海难事故，造成或者可能造成海洋环境重大污染的，海事管理机构有权强制采取避免或者减少污染的措施。"},{"i":393,"n":"第三百九十三条","txt":"所有船舶均有监视海上污染的义务，在发现海上污染事件或者违反本法规定的行为时，应当立即向就近的负有海洋生态环境保护监督管理职责的部门、机构报告。"},{"i":394,"n":"第三百九十四条","txt":"本分编适用于土壤污染的防治。"},{"i":395,"n":"第三百九十五条","txt":"本法所称土壤污染，是指因人为因素导致某种物质进入陆地表层土壤，引起土壤化学、物理、生物等方面特性的改变，影响土壤功能和有效利用，危害公众健康或者破坏生态环境的现象。"},{"i":396,"n":"第三百九十六条","txt":"土壤污染防治应当坚持风险管控，保障农产品质量安全、人居环境安全，推动土壤资源永续利用。"},{"i":397,"n":"第三百九十七条","txt":"土地使用权人从事土地开发利用活动，企业事业单位和其他生产经营者从事生产经营活动，应当采取有效措施，防止、减少土壤污染，对所造成的土壤污染依法承担责任。"},{"i":398,"n":"第三百九十八条","txt":"国务院生态环境主管部门对全国土壤污染防治工作实施统一监督管理。地方人民政府生态环境主管部门对本行政区域土壤污染防治工作实施统一监督管理。"},{"i":399,"n":"第三百九十九条","txt":"设区的市级以上地方人民政府生态环境主管部门会同发展改革、农业农村、自然资源、住房城乡建设、林业草原等有关部门，根据生态环境保护规划要求、土地用途、土壤污染状况普查和监测结果等，编制土壤污染防治规划，报本级人民政府批准后公布实施。"},{"i":400,"n":"第四百条","txt":"国务院生态环境主管部门根据土壤污染状况、公众健康风险、生态环境风险和科学技术水平，并按照土地用途，制定国家土壤污染风险管控标准，加强土壤污染防治标准体系建设。"},{"i":401,"n":"第四百零一条","txt":"国务院统一领导全国土壤污染状况普查。国务院生态环境主管部门会同国务院农业农村、自然资源、住房城乡建设、林业草原等有关部门，每十年至少组织开展一次全国土壤污染状况普查。"},{"i":402,"n":"第四百零二条","txt":"国务院生态环境主管部门会同国务院农业农村、自然资源、住房城乡建设、水行政、卫生健康、林业草原等有关部门组织监测网络，统一规划国家土壤环境监测站点的设置。"},{"i":403,"n":"第四百零三条","txt":"地方人民政府农业农村主管部门、林业草原主管部门会同生态环境主管部门、自然资源主管部门对下列农用地地块进行重点监测："},{"i":404,"n":"第四百零四条","txt":"地方人民政府生态环境主管部门会同自然资源主管部门对下列建设用地地块进行重点监测："},{"i":405,"n":"第四百零五条","txt":"国务院生态环境主管部门会同国务院农业农村、自然资源、住房城乡建设、水行政、卫生健康、林业草原等有关部门建立健全土壤环境基础数据库，构建全国土壤环境信息平台，实行数据动态更新和信息共享。"},{"i":406,"n":"第四百零六条","txt":"土壤污染状况普查报告、监测数据、调查报告和土壤污染风险评估报告、风险管控效果评估报告、修复效果评估报告等，应当及时上传全国土壤环境信息平台。"},{"i":407,"n":"第四百零七条","txt":"生态环境主管部门应当将涉及主要食用农产品生产区域的重大土壤环境信息，及时通报农业农村主管部门、卫生健康主管部门和市场监督管理部门。"},{"i":408,"n":"第四百零八条","txt":"省级以上人民政府生态环境主管部门和其他负有土壤污染防治监督管理职责的部门，应当在各自职责范围内对从事土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估、后期管理等活动的单位和个人的执业情况，依照法律规定进行信用监管。"},{"i":409,"n":"第四百零九条","txt":"各级人民政府应当加强土壤污染防治，安排必要的资金用于下列事项："},{"i":410,"n":"第四百一十条","txt":"国家加大土壤污染防治资金投入力度，建立健全土壤污染防治基金制度。设立中央土壤污染防治专项资金和省级土壤污染防治基金，主要用于农用地土壤污染防治和土壤污染责任人或者土地使用权人无法认定的土壤污染风险管控和修复以及人民政府规定的其他事项。"},{"i":411,"n":"第四百一十一条","txt":"国家鼓励金融机构加大对土壤污染风险管控和修复项目的信贷投放。"},{"i":412,"n":"第四百一十二条","txt":"生产、贮存、运输、使用、回收、处置、排放有毒有害物质的单位和个人，应当采取有效措施，防止有毒有害物质渗漏、流失、扬散，避免土壤受到污染。"},{"i":413,"n":"第四百一十三条","txt":"国务院生态环境主管部门会同国务院卫生健康、农业农村等有关部门，根据对公众健康、生态环境的危害和影响程度，对土壤中有毒有害物质进行筛查评估，制定公布重点控制的土壤有毒有害物质名录并适时更新。"},{"i":414,"n":"第四百一十四条","txt":"设区的市级以上地方人民政府生态环境主管部门应当按照国务院生态环境主管部门的规定，根据有毒有害物质排放等情况，制定公布本行政区域的土壤污染重点监管单位名录并适时更新。"},{"i":415,"n":"第四百一十五条","txt":"企业事业单位和其他生产经营者拆除设施、设备或者建筑物、构筑物的，应当采取相应的土壤污染防治措施。"},{"i":416,"n":"第四百一十六条","txt":"生态环境主管部门、自然资源主管部门应当在各自职责范围内依法加强对矿产资源开发区域土壤污染防治的监督管理，按照相关标准和总量控制的要求，严格控制可能造成土壤污染的重点污染物排放。"},{"i":417,"n":"第四百一十七条","txt":"地方人民政府应急管理部门应当监督尾矿库运营、管理单位履行防治土壤污染的法定义务，防止其发生可能污染土壤的事故；地方人民政府生态环境主管部门应当加强对尾矿库土壤污染防治情况的监督检查和定期评估，发现风险隐患的，及时督促尾矿库运营、管理单位采取相应措施。"},{"i":418,"n":"第四百一十八条","txt":"国家鼓励在建筑、通信、电力、交通、水利等领域的信息、网络、防雷、接地等建设工程中采用新技术、新材料，防止土壤污染。"},{"i":419,"n":"第四百一十九条","txt":"建设和运行污水集中处理设施、固体废物处置设施，应当依照法律法规规定和相关标准的要求，采取有效措施防止土壤污染。"},{"i":420,"n":"第四百二十条","txt":"国务院农业农村主管部门、林业草原主管部门在各自职责范围内编制规划，完善相关标准和措施，加强农用地农药、化肥使用指导和使用总量控制，加强农用薄膜使用控制。"},{"i":421,"n":"第四百二十一条","txt":"地方人民政府农业农村主管部门、林业草原主管部门应当在各自职责范围内开展农用地土壤污染防治宣传和技术培训活动，扶持农业生产专业化服务，指导农业生产经营者科学合理安全使用农药、兽药、饲料和饲料添加剂、肥料、农用薄膜等农业投入品，控制农药、兽药、化肥等的使用量。"},{"i":422,"n":"第四百二十二条","txt":"禁止向耕地、林地、草地等农用地排放重金属或者其他有毒有害物质含量超标的污水、污泥，以及可能造成土壤污染的清淤底泥、尾矿、矿渣等。"},{"i":423,"n":"第四百二十三条","txt":"国家鼓励、支持农业生产经营者采取下列措施："},{"i":424,"n":"第四百二十四条","txt":"禁止生产、销售或者使用国家明令禁止的农业投入品。"},{"i":425,"n":"第四百二十五条","txt":"国家加强对未污染土壤的保护。"},{"i":426,"n":"第四百二十六条","txt":"地方人民政府及其有关部门应当依法加强对向沙漠、滩涂、盐碱地、沼泽地等未利用地非法排放有毒有害物质等行为的监督检查。"},{"i":427,"n":"第四百二十七条","txt":"县级以上地方人民政府及其有关部门应当按照国土空间规划，严格执行相关行业企业布局选址要求，禁止在居民住宅区和学校、医院、疗养院、养老院等单位周边新建、改建、扩建可能造成土壤污染的建设项目。"},{"i":428,"n":"第四百二十八条","txt":"对开发建设过程中剥离的表土，应当单独收集和存放，符合条件的应当优先用于土地复垦、土壤改良、造地和绿化等。"},{"i":429,"n":"第四百二十九条","txt":"因科学研究等特殊原因，需要进口土壤的，应当遵守国家出入境检验检疫的规定。"},{"i":430,"n":"第四百三十条","txt":"土壤污染风险管控和修复，包括土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估、后期管理等活动。"},{"i":431,"n":"第四百三十一条","txt":"实施土壤污染状况调查活动，应当编制土壤污染状况调查报告。"},{"i":432,"n":"第四百三十二条","txt":"实施土壤污染风险评估活动，应当编制土壤污染风险评估报告。"},{"i":433,"n":"第四百三十三条","txt":"实施风险管控、修复活动，应当因地制宜、科学合理，提高针对性和有效性。"},{"i":434,"n":"第四百三十四条","txt":"实施风险管控、修复活动前，地方人民政府有关部门有权根据实际情况，要求土壤污染责任人、土地使用权人采取移除污染源、防止污染扩散等措施。"},{"i":435,"n":"第四百三十五条","txt":"实施风险管控、修复活动中产生的废水、废气和固体废物，应当按照规定进行处理、处置，并达到相关生态环境保护标准。"},{"i":436,"n":"第四百三十六条","txt":"修复施工单位转运污染土壤的，应当制定转运计划，将运输时间、方式、线路和污染土壤数量、去向、最终处置措施等，提前报送所在地和接受地生态环境主管部门。"},{"i":437,"n":"第四百三十七条","txt":"实施风险管控效果评估、修复效果评估活动，应当编制效果评估报告。"},{"i":438,"n":"第四百三十八条","txt":"从事土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估、后期管理等活动的单位，应当具备相应的专业能力。"},{"i":439,"n":"第四百三十九条","txt":"土壤污染责任人负有实施土壤污染风险管控和修复的义务。土壤污染责任人无法认定的，土地使用权人应当实施土壤污染风险管控和修复。"},{"i":440,"n":"第四百四十条","txt":"因实施或者组织实施土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估、后期管理等活动所支出的费用，由土壤污染责任人承担。"},{"i":441,"n":"第四百四十一条","txt":"土壤污染责任人变更的，由变更后承继其债权、债务的单位和个人履行相关土壤污染风险管控和修复义务并承担相关费用。"},{"i":442,"n":"第四百四十二条","txt":"土壤污染责任人不明确或者存在争议的，农用地由地方人民政府农业农村主管部门、林业草原主管部门会同生态环境主管部门、自然资源主管部门认定，建设用地由地方人民政府生态环境主管部门会同自然资源主管部门认定。认定办法由国务院生态环境主管部门会同有关部门制定。"},{"i":443,"n":"第四百四十三条","txt":"发生突发事件可能造成土壤污染的，地方人民政府及其有关部门、有关企业事业单位和其他生产经营者应当立即采取应急措施，防止土壤污染，并依照本法规定做好土壤污染状况监测、调查和土壤污染风险评估、风险管控、修复等工作。"},{"i":444,"n":"第四百四十四条","txt":"国家建立健全农用地分类管理制度。按照土壤污染程度和相关标准，将农用地划分为优先保护类、安全利用类和严格管控类。"},{"i":445,"n":"第四百四十五条","txt":"县级以上地方人民政府应当依法将符合条件的优先保护类耕地划为永久基本农田，实行严格保护。"},{"i":446,"n":"第四百四十六条","txt":"未利用地、复垦土地等拟开垦为耕地的，地方人民政府农业农村主管部门会同生态环境主管部门、自然资源主管部门进行土壤污染状况调查，依法进行分类管理。"},{"i":447,"n":"第四百四十七条","txt":"对土壤污染状况普查、详查和监测、现场检查表明有土壤污染风险的农用地地块，地方人民政府农业农村主管部门、林业草原主管部门会同生态环境主管部门、自然资源主管部门进行土壤污染状况调查。"},{"i":448,"n":"第四百四十八条","txt":"对安全利用类农用地地块，地方人民政府农业农村主管部门、林业草原主管部门，应当在各自职责范围内结合主要作物品种和种植习惯等情况，制定并实施安全利用方案。"},{"i":449,"n":"第四百四十九条","txt":"对严格管控类农用地地块，地方人民政府农业农村主管部门、林业草原主管部门应当在各自职责范围内采取下列风险管控措施："},{"i":450,"n":"第四百五十条","txt":"安全利用类和严格管控类农用地地块的土壤污染影响或者可能影响地下水、饮用水水源安全的，地方人民政府生态环境主管部门会同农业农村、林业草原等有关部门制定防治污染的方案，并采取相应的措施。"},{"i":451,"n":"第四百五十一条","txt":"对安全利用类和严格管控类农用地地块，土壤污染责任人应当按照国家规定以及土壤污染风险评估报告的要求，采取相应的风险管控措施，并定期向地方人民政府农业农村主管部门、林业草原主管部门报告。"},{"i":452,"n":"第四百五十二条","txt":"对产出的农产品污染物含量超标，需要实施修复的农用地地块，土壤污染责任人应当编制修复方案，报地方人民政府农业农村主管部门、林业草原主管部门备案并实施。修复方案应当包括地下水污染防治的内容。"},{"i":453,"n":"第四百五十三条","txt":"国家实行建设用地土壤污染风险管控和修复名录制度。"},{"i":454,"n":"第四百五十四条","txt":"对土壤污染状况普查、详查和监测、现场检查表明有土壤污染风险的建设用地地块，地方人民政府生态环境主管部门应当要求土地使用权人按照规定进行土壤污染状况调查。"},{"i":455,"n":"第四百五十五条","txt":"对土壤污染状况调查报告评审表明污染物含量超过土壤污染风险管控标准的建设用地地块，土壤污染责任人、土地使用权人应当按照国务院生态环境主管部门的规定进行土壤污染风险评估，并将土壤污染风险评估报告报送省级人民政府生态环境主管部门。"},{"i":456,"n":"第四百五十六条","txt":"省级人民政府生态环境主管部门会同自然资源等有关部门按照国务院生态环境主管部门的规定，对土壤污染风险评估报告组织评审，及时将需要实施风险管控、修复的地块纳入建设用地土壤污染风险管控和修复名录，并定期向国务院生态环境主管部门、自然资源主管部门报告。"},{"i":457,"n":"第四百五十七条","txt":"对建设用地土壤污染风险管控和修复名录中的地块，土壤污染责任人应当按照国家规定以及土壤污染风险评估报告的要求，采取相应的风险管控措施，并定期向地方人民政府生态环境主管部门报告。风险管控措施应当包括地下水污染防治的内容。"},{"i":458,"n":"第四百五十八条","txt":"对建设用地土壤污染风险管控和修复名录中的地块，地方人民政府生态环境主管部门可以根据实际情况采取下列风险管控措施："},{"i":459,"n":"第四百五十九条","txt":"对建设用地土壤污染风险管控和修复名录中需要实施修复的地块，土壤污染责任人应当结合国土空间规划编制修复方案，报地方人民政府生态环境主管部门备案并实施。修复方案应当包括地下水污染防治的内容。"},{"i":460,"n":"第四百六十条","txt":"风险管控、修复活动完成后，土壤污染责任人应当另行委托有关单位对风险管控效果、修复效果进行评估，并将效果评估报告报地方人民政府生态环境主管部门备案。"},{"i":461,"n":"第四百六十一条","txt":"对达到土壤污染风险评估报告确定的风险管控、修复目标的建设用地地块，土壤污染责任人、土地使用权人可以申请省级人民政府生态环境主管部门移出建设用地土壤污染风险管控和修复名录。"},{"i":462,"n":"第四百六十二条","txt":"土壤污染重点监管单位生产经营用地的用途变更或者在其土地使用权收回、转让前，应当由土地使用权人按照规定进行土壤污染状况调查。土壤污染状况调查报告应当作为不动产登记资料送交地方人民政府不动产登记机构，并报地方人民政府生态环境主管部门备案；土地使用权人未送交土壤污染状况调查报告的，地方人民政府不动产登记机构应当要求其补充提供。"},{"i":463,"n":"第四百六十三条","txt":"土地使用权已经被地方人民政府收回，土壤污染责任人为原土地使用权人的，由地方人民政府组织实施土壤污染风险管控和修复。"},{"i":464,"n":"第四百六十四条","txt":"本分编适用于固体废物污染的防治。"},{"i":465,"n":"第四百六十五条","txt":"本法所称固体废物，是指在生产、生活和其他活动中产生的丧失原有利用价值或者虽未丧失利用价值但是被抛弃或者放弃的固态、半固态和置于容器中的气态的物品、物质以及法律、行政法规规定纳入固体废物管理的物品、物质。经无害化加工处理，并且符合强制性国家产品质量标准，不会危害公众健康和生态安全，或者根据固体废物鉴别标准和鉴别程序认定为不属于固体废物的除外。"},{"i":466,"n":"第四百六十六条","txt":"固体废物污染防治坚持减量化、资源化和无害化的原则，加强产生、收集、贮存、运输、利用、处置等全过程管控。"},{"i":467,"n":"第四百六十七条","txt":"国家采取有效措施加强固体废物综合治理，推进城乡固体废物源头减量和资源化充分利用，最大限度降低固体废物填埋量。"},{"i":468,"n":"第四百六十八条","txt":"产生、收集、贮存、运输、利用、处置固体废物的单位和个人，应当采取有效措施，防止或者减少固体废物污染，对所造成的污染依法承担责任。"},{"i":469,"n":"第四百六十九条","txt":"国务院生态环境主管部门对全国固体废物污染防治工作实施统一监督管理。地方人民政府生态环境主管部门对本行政区域固体废物污染防治工作实施统一监督管理。"},{"i":470,"n":"第四百七十条","txt":"省、自治区、直辖市之间可以协商建立跨行政区域固体废物污染联防联控机制，统筹规划制定、设施建设、固体废物转移等工作。"},{"i":471,"n":"第四百七十一条","txt":"设区的市级以上地方人民政府编制固体废物污染防治规划，统筹规划、建设固体废物转运、集中处置等设施、场所，推动固体废物污染防治工作。"},{"i":472,"n":"第四百七十二条","txt":"国务院生态环境主管部门会同有关部门根据国家生态环境质量标准和国家经济、技术条件，制定固体废物鉴别标准、鉴别程序、污染防治技术标准和工业固体废物中有毒有害物质含量控制标准。"},{"i":473,"n":"第四百七十三条","txt":"固体废物综合利用标准应当明确综合利用产品中的有毒有害物质限值。"},{"i":474,"n":"第四百七十四条","txt":"国务院生态环境主管部门会同有关部门建立全国危险废物等固体废物污染防治信息平台，推进固体废物产生、收集、贮存、转移、利用、处置等全过程监控和信息化追溯。"},{"i":475,"n":"第四百七十五条","txt":"产生、收集、贮存、运输、利用、处置固体废物的单位和其他生产经营者，应当采取防扬散、防流失、防渗漏或者其他防止污染环境的措施，不得擅自倾倒、堆放、丢弃、抛撒、遗撒或者焚烧固体废物。"},{"i":476,"n":"第四百七十六条","txt":"转移固体废物出省、自治区、直辖市行政区域贮存、处置的，应当向固体废物移出地省级人民政府生态环境主管部门提出申请。移出地省级人民政府生态环境主管部门应当及时商经接受地省级人民政府生态环境主管部门同意后，在规定期限内批准转移该固体废物出省、自治区、直辖市行政区域。未经批准的，不得转移。"},{"i":477,"n":"第四百七十七条","txt":"禁止中华人民共和国境外的固体废物进境倾倒、堆放、处置。"},{"i":478,"n":"第四百七十八条","txt":"国家实行固体废物零进口，由国务院生态环境主管部门会同国务院商务、发展改革、海关等有关部门组织实施。"},{"i":479,"n":"第四百七十九条","txt":"海关发现进口货物疑似固体废物的，可以委托专业机构开展属性鉴别，并根据鉴别结论依法管理。"},{"i":480,"n":"第四百八十条","txt":"收集、贮存、运输、利用、处置固体废物的单位和其他生产经营者，应当加强对相关设施、设备和场所的管理和维护，保证其正常运行和使用。"},{"i":481,"n":"第四百八十一条","txt":"在生态保护红线区域、永久基本农田集中区域和其他需要特别保护的区域，禁止建设工业固体废物、建筑垃圾、危险废物集中贮存、利用、处置的设施、场所和生活垃圾填埋场。"},{"i":482,"n":"第四百八十二条","txt":"各级人民政府及其有关部门编制国土空间规划和相关规划，应当统筹生活垃圾、建筑垃圾、危险废物等固体废物转运、集中处置等设施、场所建设需求，保障转运、集中处置等设施、场所用地。"},{"i":483,"n":"第四百八十三条","txt":"各级人民政府应当加强固体废物污染防治，安排必要的资金用于下列事项："},{"i":484,"n":"第四百八十四条","txt":"收集、贮存、运输、利用、处置危险废物的单位，应当按照规定投保环境污染责任强制保险。环境污染责任强制保险制度的具体实施办法，由国务院金融监督管理机构会同国务院生态环境主管部门制定。"},{"i":485,"n":"第四百八十五条","txt":"设区的市级人民政府生态环境主管部门会同住房城乡建设、农业农村、卫生健康等有关部门，定期向社会公开固体废物的种类、产生量、处置能力、利用处置状况等信息。"},{"i":486,"n":"第四百八十六条","txt":"固体废物污染海洋的防治和放射性固体废物污染的防治不适用本分编。"},{"i":487,"n":"第四百八十七条","txt":"国务院生态环境主管部门会同国务院发展改革、工业和信息化等有关部门对工业固体废物对公众健康、生态环境的危害和影响程度等作出界定，制定防治工业固体废物污染的技术政策，组织推广先进的防治工业固体废物污染的生产工艺和设备。"},{"i":488,"n":"第四百八十八条","txt":"国务院工业和信息化主管部门会同有关部门组织研究开发、推广减少工业固体废物产生量和降低工业固体废物危害性的生产工艺和设备，制定公布限期淘汰产生严重污染环境的工业固体废物的落后生产工艺、设备的名录。"},{"i":489,"n":"第四百八十九条","txt":"产生工业固体废物的单位应当建立健全工业固体废物产生、收集、贮存、运输、利用、处置全过程的污染防治责任制度，建立工业固体废物管理台账，如实记录产生工业固体废物的种类、数量、流向、贮存、利用、处置等信息，实现工业固体废物可追溯、可查询，并采取防治工业固体废物污染的措施。"},{"i":490,"n":"第四百九十条","txt":"产生工业固体废物的单位委托他人运输、利用、处置工业固体废物的，应当对受托方的主体资格和技术能力进行核实，依法签订书面合同，在合同中约定污染防治要求。"},{"i":491,"n":"第四百九十一条","txt":"实行排污许可管理的产生工业固体废物的单位的排污许可证中应当记载工业固体废物的贮存、利用、处置要求等信息。"},{"i":492,"n":"第四百九十二条","txt":"产生工业固体废物的单位应当向所在地生态环境主管部门提供工业固体废物的种类、数量、流向、贮存、利用、处置等有关资料，以及减少工业固体废物产生、促进综合利用的具体措施。"},{"i":493,"n":"第四百九十三条","txt":"产生、贮存、利用、处置工业固体废物的单位应当按照国家规定，对工业固体废物进行检测、监测，并按照分类管理要求采取必要措施，防止工业固体废物污染。"},{"i":494,"n":"第四百九十四条","txt":"产生工业固体废物的单位应当根据经济、技术条件对工业固体废物加以利用；对暂时不利用或者不能利用的，应当按照国务院生态环境等有关部门的规定建设贮存设施、场所，安全分类存放，或者采取无害化处置措施。贮存工业固体废物应当采取符合国家生态环境保护标准的防护措施。"},{"i":495,"n":"第四百九十五条","txt":"产生工业固体废物的单位终止的，应当在终止前对工业固体废物的贮存、处置的设施、场所采取污染防治措施，并对未处置的工业固体废物作出妥善处置，防止污染环境。"},{"i":496,"n":"第四百九十六条","txt":"矿产资源的勘查、开采，应当采用有利于保护生态环境和防止固体废物污染的勘查、开采方法和工艺技术，减少尾矿、煤矸石、废石等矿业固体废物的产生量和贮存量。"},{"i":497,"n":"第四百九十七条","txt":"尾矿贮存设施污染防治实行分级分类管理。"},{"i":498,"n":"第四百九十八条","txt":"国家鼓励采取先进工艺技术对尾矿、煤矸石、废石等矿业固体废物进行综合利用。"},{"i":499,"n":"第四百九十九条","txt":"国家推行生活垃圾分类制度。"},{"i":500,"n":"第五百条","txt":"县级以上地方人民政府应当加快建立健全分类投放、分类收集、分类运输、分类处理的生活垃圾管理系统，实现生活垃圾分类制度有效覆盖。"},{"i":501,"n":"第五百零一条","txt":"县级以上地方人民政府有关部门应当在各自职责范围内加强产品生产和流通过程管理，避免过度包装，组织净菜上市，减少生活垃圾的产生量。"},{"i":502,"n":"第五百零二条","txt":"县级以上人民政府应当统筹安排建设城乡生活垃圾收集、运输、处理设施、场所，确定设施、场所位置，提高生活垃圾的综合利用和无害化处置水平，促进生活垃圾收集、处理的产业化发展，逐步建立健全生活垃圾污染防治的社会服务体系。"},{"i":503,"n":"第五百零三条","txt":"地方各级人民政府应当加强农村生活垃圾污染的防治，保护和改善农村人居环境。"},{"i":504,"n":"第五百零四条","txt":"设区的市级以上人民政府环境卫生主管部门应当制定生活垃圾清扫、收集、贮存、运输和处理设施、场所建设运行规范，公布生活垃圾分类指导目录，加强监督管理。"},{"i":505,"n":"第五百零五条","txt":"县级以上地方人民政府环境卫生等有关部门应当在各自职责范围内组织对城乡生活垃圾进行清扫、收集、运输和处理，可以通过招标等方式选择具备条件的单位从事生活垃圾的清扫、收集、运输和处理。"},{"i":506,"n":"第五百零六条","txt":"产生生活垃圾的单位、家庭和个人应当依法履行生活垃圾源头减量和分类投放义务，承担生活垃圾产生者责任。"},{"i":507,"n":"第五百零七条","txt":"清扫、收集、运输、处理城乡生活垃圾，应当遵守国家有关生态环境保护和环境卫生管理的规定，防止污染环境。"},{"i":508,"n":"第五百零八条","txt":"从事公共交通运输的经营单位，应当及时清扫、收集运输过程中产生的生活垃圾。"},{"i":509,"n":"第五百零九条","txt":"农贸市场、农产品批发市场等应当加强环境卫生管理，保持环境卫生清洁，对所产生的垃圾及时清扫、分类收集、妥善处理。"},{"i":510,"n":"第五百一十条","txt":"从事城市新区开发、旧区改建和住宅小区开发建设、村镇建设的单位，以及机场、码头、车站、公园、商场、体育场馆等公共设施、场所的经营管理单位，应当按照国家有关环境卫生的规定，配套建设生活垃圾收集设施。"},{"i":511,"n":"第五百一十一条","txt":"从生活垃圾中回收的物质应当按照国家规定的用途、标准使用，不得用于生产可能危害人体健康的产品。"},{"i":512,"n":"第五百一十二条","txt":"建设生活垃圾处理设施、场所，应当符合国务院生态环境主管部门和国务院住房城乡建设主管部门规定的生态环境保护和环境卫生标准。"},{"i":513,"n":"第五百一十三条","txt":"生活垃圾处理单位应当按照国家规定，安装使用监测设备，实时监测污染物的排放情况，将污染排放数据实时向社会公开。监测设备应当与所在地生态环境主管部门的监控设备联网。"},{"i":514,"n":"第五百一十四条","txt":"县级以上地方人民政府环境卫生主管部门负责组织开展厨余垃圾资源化、无害化处理工作。"},{"i":515,"n":"第五百一十五条","txt":"县级以上地方人民政府应当按照产生者付费原则，建立健全生活垃圾处理收费制度。"},{"i":516,"n":"第五百一十六条","txt":"县级以上地方人民政府应当加强建筑垃圾污染的防治，建立健全建筑垃圾分类处理制度。"},{"i":517,"n":"第五百一十七条","txt":"建筑工程应当采用有利于保护生态环境的建筑设计方案、建筑材料和装修材料、建筑构配件及设备，减少建筑垃圾的产生。"},{"i":518,"n":"第五百一十八条","txt":"县级以上地方人民政府环境卫生主管部门负责建筑垃圾污染防治工作，建立健全建筑垃圾全过程管理制度，按照规定实行联单管理，规范建筑垃圾产生、收集、贮存、运输、利用、处置行为，推进综合利用，加强建筑垃圾处置等设施、场所建设，保障处置安全，防止污染环境。建筑垃圾管理的具体办法由国务院住房城乡建设主管部门制定。"},{"i":519,"n":"第五百一十九条","txt":"建设单位应当按照规定将建筑垃圾污染防治费用列入工程造价，在施工合同中明确工程施工单位的建筑垃圾污染防治责任。"},{"i":520,"n":"第五百二十条","txt":"工程施工单位应当编制建筑垃圾处理方案，采取污染防治措施，并报县级以上地方人民政府环境卫生主管部门备案。"},{"i":521,"n":"第五百二十一条","txt":"县级以上人民政府农业农村主管部门负责指导农业固体废物回收利用体系建设，鼓励和引导有关单位和其他生产经营者依法收集、贮存、运输、利用、处置农业固体废物，加强监督管理，防止污染环境。"},{"i":522,"n":"第五百二十二条","txt":"产生农业固体废物的单位和其他生产经营者，应当采取回收利用和其他防止污染环境的措施。"},{"i":523,"n":"第五百二十三条","txt":"退役风电机组叶片、退役光伏组件、废旧动力电池等产品的拆解、处置应当加强污染防治，按照规定开展精细化、无害化拆解、处置。"},{"i":524,"n":"第五百二十四条","txt":"禁止将报废机动车船等交由不符合规定条件的企业或者个人回收、拆解。"},{"i":525,"n":"第五百二十五条","txt":"县级以上人民政府城镇排水主管部门依法将污泥处理处置设施纳入城镇排水与污水处理规划，推动同步建设污泥处理处置设施与污水处理设施，鼓励协同处理处置，污水处理费征收标准和补偿范围应当覆盖污泥处理处置成本和污水处理设施正常运营成本。"},{"i":526,"n":"第五百二十六条","txt":"禁止擅自倾倒、堆放、丢弃、抛撒、遗撒或者焚烧城镇污水处理设施产生的污泥和处理处置后的污泥。"},{"i":527,"n":"第五百二十七条","txt":"各级各类实验室及其设立单位应当加强对实验室产生的固体废物的管理，依法收集、贮存、运输、利用、处置实验室固体废物。实验室固体废物属于危险废物的，应当按照危险废物管理。"},{"i":528,"n":"第五百二十八条","txt":"本法所称危险废物，是指列入国家危险废物名录或者根据国家规定的危险废物鉴别标准和鉴别方法认定的具有危险特性的固体废物。"},{"i":529,"n":"第五百二十九条","txt":"国务院生态环境主管部门会同有关部门制定国家危险废物名录，规定统一的危险废物鉴别标准、鉴别方法、鉴别程序、识别标志和鉴别单位管理要求。国家危险废物名录应当动态调整。"},{"i":530,"n":"第五百三十条","txt":"省、自治区、直辖市人民政府应当组织有关部门编制危险废物集中处置设施、场所的建设规划，科学评估危险废物处置需求，合理布局危险废物集中处置设施、场所，确保本行政区域的危险废物得到妥善处置。"},{"i":531,"n":"第五百三十一条","txt":"对危险废物的容器和包装物以及收集、贮存、运输、利用、处置危险废物的设施、场所，应当按照规定设置危险废物识别标志。"},{"i":532,"n":"第五百三十二条","txt":"产生危险废物的单位，应当按照国家规定制定危险废物管理计划；建立危险废物管理台账，如实记录有关信息，并通过国家危险废物信息管理系统向所在地生态环境主管部门申报危险废物的种类、产生量、流向、贮存、利用、处置等有关资料。"},{"i":533,"n":"第五百三十三条","txt":"产生危险废物的单位，应当按照国家规定和生态环境保护标准的要求贮存、利用、处置危险废物。"},{"i":534,"n":"第五百三十四条","txt":"从事收集、贮存、利用、处置危险废物经营活动的单位，应当按照国家规定取得许可证。许可证的具体管理办法由国务院制定。"},{"i":535,"n":"第五百三十五条","txt":"收集、贮存危险废物，应当按照危险废物特性分类进行。禁止混合收集、贮存、运输或者处置性质不相容而未经安全性处置的危险废物。"},{"i":536,"n":"第五百三十六条","txt":"转移危险废物的，应当按照国家规定填写、运行危险废物电子或者纸质转移联单。"},{"i":537,"n":"第五百三十七条","txt":"运输危险废物，应当采取防止污染环境的措施，并遵守国家有关危险货物运输管理的规定。"},{"i":538,"n":"第五百三十八条","txt":"收集、贮存、运输、利用、处置危险废物的场所、设施、设备和容器、包装物及其他物品转作他用时，应当按照国家规定经过消除污染处理，方可使用。"},{"i":539,"n":"第五百三十九条","txt":"产生、收集、贮存、运输、利用、处置危险废物的单位，应当依法制定意外事故的防范措施和应急预案，并报所在地生态环境主管部门和其他负有固体废物污染防治监督管理职责的部门备案；生态环境主管部门和其他负有固体废物污染防治监督管理职责的部门应当在各自职责范围内进行监督检查。"},{"i":540,"n":"第五百四十条","txt":"因发生事故或者其他突发性事件，造成危险废物严重污染的单位，应当立即采取有效措施消除或者减轻污染危害，及时通报可能受到污染危害者，并向所在地生态环境主管部门和有关部门报告，接受调查处理。"},{"i":541,"n":"第五百四十一条","txt":"在发生或者有证据证明可能发生危险废物严重污染、威胁居民生命财产安全时，生态环境主管部门和其他负有固体废物污染防治监督管理职责的部门应当立即向本级人民政府和上一级人民政府有关部门报告，由人民政府采取防止或者减轻危害的有效措施。有关人民政府可以根据实际需要责令停止导致或者可能导致环境污染事故的作业。"},{"i":542,"n":"第五百四十二条","txt":"重点危险废物集中处置设施、场所退役前，运营单位应当按照国家规定对设施、场所采取污染防治措施。退役的费用应当预提，列入投资概算或者生产成本，专门用于重点危险废物集中处置设施、场所的退役。具体提取和管理办法，由国务院财政部门、价格主管部门会同国务院生态环境主管部门制定。"},{"i":543,"n":"第五百四十三条","txt":"禁止经中华人民共和国过境转移危险废物。"},{"i":544,"n":"第五百四十四条","txt":"医疗废物按照国家危险废物名录管理。县级以上地方人民政府应当加强医疗废物集中处置能力建设。"},{"i":545,"n":"第五百四十五条","txt":"重大传染病疫情等突发事件发生时，县级以上人民政府应当统筹协调医疗废物等危险废物收集、贮存、运输、处置等工作，保障所需的车辆、场地、处置设施和防护物资。卫生健康、生态环境、环境卫生、交通运输等有关部门应当协同配合，依法履行应急处置职责。"},{"i":546,"n":"第五百四十六条","txt":"本分编适用于噪声污染的防治。"},{"i":547,"n":"第五百四十七条","txt":"本法所称噪声污染，是指在工业生产、建筑施工、交通运输和社会生活中超过噪声排放标准或者未依法采取防控措施产生噪声，并干扰他人正常生活、工作和学习的现象。"},{"i":548,"n":"第五百四十八条","txt":"国务院生态环境主管部门对全国噪声污染防治工作实施统一监督管理。地方人民政府生态环境主管部门对本行政区域噪声污染防治工作实施统一监督管理。"},{"i":549,"n":"第五百四十九条","txt":"基层群众性自治组织协助地方人民政府及其有关部门做好噪声污染防治工作。"},{"i":550,"n":"第五百五十条","txt":"排放噪声的单位和公共场所管理者，应当建立噪声污染防治责任制度，明确负责人和相关人员的责任。"},{"i":551,"n":"第五百五十一条","txt":"各级人民政府及其有关部门编制国土空间规划和相关规划，应当充分考虑城乡区域开发、改造和建设项目产生的噪声对周围生活环境的影响，统筹规划，合理安排土地用途和建设布局，防止、减轻噪声污染。"},{"i":552,"n":"第五百五十二条","txt":"未达到国家声环境质量标准的地区所在设区的市、县级人民政府，应当及时编制声环境质量改善规划及其实施方案，采取有效措施，改善声环境质量。"},{"i":553,"n":"第五百五十三条","txt":"县级以上地方人民政府根据国家声环境质量标准和国土空间规划以及用地现状，划定本行政区域各类声环境质量标准的适用区域；将以用于居住、科学研究、医疗卫生、文化教育、机关团体办公、社会福利等的建筑物为主的区域，划定为噪声敏感建筑物集中区域，加强噪声污染防治。"},{"i":554,"n":"第五百五十四条","txt":"国务院生态环境主管部门根据国家声环境质量标准和国家经济、技术条件，制定国家环境振动控制标准。"},{"i":555,"n":"第五百五十五条","txt":"国务院标准化主管部门会同国务院发展改革、生态环境、工业和信息化、住房城乡建设、交通运输、铁路监督管理、民用航空、海事等有关部门，对可能产生噪声污染的工业设备、施工机械、机动车、铁路机车车辆、城市轨道交通车辆、民用航空器、机动船舶、电气电子产品、建筑附属设备等产品，根据噪声污染防治的要求和国家经济、技术条件，在其技术规范或者产品质量标准中规定噪声限值。"},{"i":556,"n":"第五百五十六条","txt":"国务院生态环境主管部门会同有关部门组织开展声环境质量监测，推进监测自动化。地方人民政府生态环境主管部门会同有关部门按照规定设置本行政区域的声环境质量监测站点，组织开展本行政区域的声环境质量监测。"},{"i":557,"n":"第五百五十七条","txt":"确定建设布局，应当根据国家声环境质量标准和民用建筑隔声设计相关标准，合理划定建筑物与交通干线等的防噪声距离，并提出相应的规划设计要求。"},{"i":558,"n":"第五百五十八条","txt":"建设噪声敏感建筑物，应当符合民用建筑隔声设计相关标准的要求，不符合标准要求的，不得通过验收、交付使用；在交通干线两侧、工业企业周边等地方建设噪声敏感建筑物，还应当按照规定间隔一定距离，并采取减少振动、降低噪声的措施。"},{"i":559,"n":"第五百五十九条","txt":"国家鼓励、支持低噪声工艺和设备的研究开发和推广应用。"},{"i":560,"n":"第五百六十条","txt":"国家鼓励开展宁静小区、静音车厢等宁静区域创建活动，共同维护生活环境和谐安宁。"},{"i":561,"n":"第五百六十一条","txt":"在举行中等学校招生考试、高等学校招生统一考试等特殊活动期间，地方人民政府或者其指定的部门可以对可能产生噪声影响的活动，作出时间和区域的限制性规定，并提前向社会公告。"},{"i":562,"n":"第五百六十二条","txt":"排放噪声造成严重污染，被责令改正拒不改正的，生态环境主管部门和其他负有噪声污染防治监督管理职责的部门，可以依法查封、扣押排放噪声的场所、设施、设备、工具、物品。"},{"i":563,"n":"第五百六十三条","txt":"因从事本职生产经营工作受到噪声危害的防治，适用职业病防治法律的有关规定。"},{"i":564,"n":"第五百六十四条","txt":"本法所称工业噪声，是指在工业生产活动中产生的干扰周围生活环境的声音。"},{"i":565,"n":"第五百六十五条","txt":"工业企业选址应当符合国土空间规划以及相关规划要求，县级以上地方人民政府应当按照规划要求优化工业企业布局，防止工业噪声污染。"},{"i":566,"n":"第五百六十六条","txt":"在噪声敏感建筑物集中区域，禁止新建排放噪声的工业企业，改建、扩建工业企业的，应当采取有效措施防止工业噪声污染。"},{"i":567,"n":"第五百六十七条","txt":"排放工业噪声的企业事业单位和其他生产经营者，应当采取有效措施，减少振动、降低噪声。"},{"i":568,"n":"第五百六十八条","txt":"本法所称建筑施工噪声，是指在建筑施工过程中产生的干扰周围生活环境的声音。"},{"i":569,"n":"第五百六十九条","txt":"建设单位应当按照规定将噪声污染防治费用列入工程造价，在施工合同中明确施工单位的噪声污染防治责任。"},{"i":570,"n":"第五百七十条","txt":"在噪声敏感建筑物集中区域施工作业或者因施工作业可能造成严重污染的，应当优先使用低噪声施工工艺和设备。"},{"i":571,"n":"第五百七十一条","txt":"在噪声敏感建筑物集中区域施工作业或者因施工作业可能造成严重污染的，建设单位应当按照国家规定，设置噪声自动监测系统，与监督管理部门联网，保存原始监测记录。"},{"i":572,"n":"第五百七十二条","txt":"在噪声敏感建筑物集中区域禁止夜间进行产生噪声的施工作业，但是抢修、抢险施工作业，因生产工艺要求或者其他特殊需要必须连续施工作业的除外。"},{"i":573,"n":"第五百七十三条","txt":"本法所称交通运输噪声，是指机动车、铁路机车车辆、城市轨道交通车辆、机动船舶、航空器等交通运输工具在运行时产生的干扰周围生活环境的声音。"},{"i":574,"n":"第五百七十四条","txt":"各级人民政府及其有关部门编制国土空间规划和交通运输等相关规划，应当综合考虑公路、城市道路、铁路、城市轨道交通线路、水路、港口和民用机场及其起降航线对周围声环境的影响。"},{"i":575,"n":"第五百七十五条","txt":"制定交通基础设施工程技术规范，应当明确噪声污染防治要求。"},{"i":576,"n":"第五百七十六条","txt":"机动车的消声器和喇叭应当符合国家规定。禁止驾驶拆除或者损坏消声器、加装排气管等擅自改装的机动车以轰鸣、疾驶等方式造成噪声污染。"},{"i":577,"n":"第五百七十七条","txt":"机动车、铁路机车车辆、城市轨道交通车辆、机动船舶等交通运输工具运行时，应当按照规定使用喇叭等声响装置。"},{"i":578,"n":"第五百七十八条","txt":"地方人民政府生态环境主管部门会同公安机关根据噪声污染防治的需要，可以划定禁止机动车行驶和使用喇叭等声响装置的路段和时间，向社会公告，并由公安机关交通管理部门依法设置相关标志、标线。"},{"i":579,"n":"第五百七十九条","txt":"在车站、铁路站场、港口等地方指挥作业时使用广播喇叭的，应当控制音量，减轻噪声污染。"},{"i":580,"n":"第五百八十条","txt":"公路养护管理单位、城市道路养护维修单位应当加强对公路、城市道路的维护和保养，保证减少振动、降低噪声设施正常运行。"},{"i":581,"n":"第五百八十一条","txt":"民用机场所在地人民政府，应当根据生态环境影响评价以及监测结果确定的民用航空器噪声对机场周围生活环境产生影响的范围和程度，划定噪声敏感建筑物禁止建设区域和限制建设区域，并实施控制。"},{"i":582,"n":"第五百八十二条","txt":"民用航空器应当符合国务院民用航空主管部门规定的适航标准中的有关噪声要求。"},{"i":583,"n":"第五百八十三条","txt":"民用机场管理机构负责机场起降航空器噪声的管理，会同航空运输企业、通用航空企业、空中交通管理部门等单位，采取低噪声飞行程序、起降跑道优化、运行架次和时段控制、高噪声航空器运行限制或者周围噪声敏感建筑物隔声降噪等措施，防止、减轻民用航空器噪声污染。"},{"i":584,"n":"第五百八十四条","txt":"因公路、城市道路和城市轨道交通运行排放噪声造成严重污染的，设区的市、县级人民政府应当组织有关部门和其他有关单位对噪声污染情况进行调查评估和责任认定，制定噪声污染综合治理方案。"},{"i":585,"n":"第五百八十五条","txt":"因铁路运行排放噪声造成严重污染的，铁路运输企业和设区的市、县级人民政府应当对噪声污染情况进行调查，制定噪声污染综合治理方案。"},{"i":586,"n":"第五百八十六条","txt":"因民用航空器起降排放噪声造成严重污染的，民用机场所在地人民政府应当组织有关部门和其他有关单位对噪声污染情况进行调查，综合考虑经济、技术和管理措施，制定噪声污染综合治理方案。"},{"i":587,"n":"第五百八十七条","txt":"制定噪声污染综合治理方案，应当征求有关专家、公众等方面的意见。"},{"i":588,"n":"第五百八十八条","txt":"本法所称社会生活噪声，是指人为活动产生的除工业噪声、建筑施工噪声和交通运输噪声外的干扰周围生活环境的声音。"},{"i":589,"n":"第五百八十九条","txt":"全社会应当增强噪声污染防治意识，自觉减少社会生活噪声排放，积极开展噪声污染防治活动，形成人人有责、人人参与、人人受益的良好噪声污染防治氛围，共同维护生活环境和谐安宁。"},{"i":590,"n":"第五百九十条","txt":"文化娱乐、体育、餐饮等场所的经营管理者应当采取有效措施，防止、减轻噪声污染。"},{"i":591,"n":"第五百九十一条","txt":"使用空调器、冷却塔、水泵、油烟净化器、风机、发电机、变压器、锅炉、装卸设备等可能产生社会生活噪声污染的设备、设施的企业事业单位和其他经营管理者等，应当采取优化布局、集中排放等措施，防止、减轻噪声污染。"},{"i":592,"n":"第五百九十二条","txt":"禁止在商业经营活动中使用高音广播喇叭或者采用其他持续反复发出高噪声的方法进行广告宣传。"},{"i":593,"n":"第五百九十三条","txt":"禁止在噪声敏感建筑物集中区域使用高音广播喇叭，但是紧急情况以及地方人民政府规定的特殊情形除外。"},{"i":594,"n":"第五百九十四条","txt":"家庭及其成员应当培养形成减少噪声产生的良好习惯，乘坐公共交通工具、饲养宠物和其他日常活动尽量避免产生噪声对周围人员造成干扰，互谅互让解决噪声纠纷，共同维护声环境质量。"},{"i":595,"n":"第五百九十五条","txt":"对已竣工交付使用的住宅楼、商铺、办公楼等建筑物进行室内装修活动，应当按照规定限定作业时间，采取有效措施，防止、减轻噪声污染。"},{"i":596,"n":"第五百九十六条","txt":"新建居民住房的房地产开发经营者应当在销售场所公示住房可能受到噪声影响的情况以及采取或者拟采取的防治措施，并纳入买卖合同。"},{"i":597,"n":"第五百九十七条","txt":"居民住宅区安装电梯、水泵、变压器等共用设施、设备的，建设单位应当合理设置，采取减少振动、降低噪声的措施，符合民用建筑隔声设计相关标准的要求。"},{"i":598,"n":"第五百九十八条","txt":"基层群众性自治组织指导业主委员会、物业服务人、业主通过制定管理规约或者其他形式，约定本物业管理区域噪声污染防治要求，由业主共同遵守。"},{"i":599,"n":"第五百九十九条","txt":"对噪声敏感建筑物集中区域的社会生活噪声扰民行为，基层群众性自治组织、业主委员会、物业服务人应当及时劝阻、调解；劝阻、调解无效的，可以向负有社会生活噪声污染防治监督管理职责的部门或者地方人民政府指定的部门报告或者投诉，接到报告或者投诉的部门应当依法处理。"},{"i":600,"n":"第六百条","txt":"本分编适用于在核设施选址、建造、运行、退役和核技术、铀（钍）矿、伴生放射性矿开发利用过程中发生的放射性污染的防治活动。"},{"i":601,"n":"第六百零一条","txt":"本法所称放射性污染，是指由于人类活动造成物料、人体、场所、环境介质表面或者内部出现超过国家标准的放射性物质或者射线。"},{"i":602,"n":"第六百零二条","txt":"放射性污染防治应当坚持严格管理、安全第一，促进核能、核技术的开发与和平利用。"},{"i":603,"n":"第六百零三条","txt":"核设施营运单位，核技术利用单位和其他生产经营者，铀（钍）矿和伴生放射性矿开发利用单位，专门从事放射性废物贮存、处理、处置的单位应当采取有效措施，防止、减少放射性污染，依法对其造成的放射性污染承担责任。"},{"i":604,"n":"第六百零四条","txt":"国务院生态环境主管部门对全国放射性污染防治工作实施统一监督管理。"},{"i":605,"n":"第六百零五条","txt":"国务院生态环境主管部门根据环境安全要求和国家经济、技术条件制定国家放射性污染防治标准。"},{"i":606,"n":"第六百零六条","txt":"含有放射性物质的产品和射线装置，应当符合国家放射性污染防治标准；不符合国家放射性污染防治标准的，不得出厂、销售。"},{"i":607,"n":"第六百零七条","txt":"国务院生态环境主管部门会同有关部门组织监测网络，对放射性污染实施监测管理。"},{"i":608,"n":"第六百零八条","txt":"核设施营运单位，核技术利用单位和其他生产经营者，铀（钍）矿和伴生放射性矿开发利用单位，专门从事放射性废物贮存、处理、处置的单位应当采取安全与防护措施，预防发生可能导致放射性污染的各类事故，避免放射性污染危害。"},{"i":609,"n":"第六百零九条","txt":"运输放射性物质应当采取有效措施，防止放射性污染。具体办法由国务院制定。"},{"i":610,"n":"第六百一十条","txt":"放射性物质和射线装置应当设置明显的放射性标识和中文警示说明。生产、贮存、销售、使用、处置放射性物质和射线装置的场所，以及运输放射性物质的工具，应当设置明显的放射性标志。"},{"i":611,"n":"第六百一十一条","txt":"国家对从事放射性污染防治的专业人员实行资格管理制度，对从事放射性污染监测工作的机构实行资质管理制度。"},{"i":612,"n":"第六百一十二条","txt":"国务院生态环境等有关部门应当互通信息、密切配合，在各自职责范围内对核设施、核技术利用、铀（钍）矿开发利用中的放射性污染防治进行监督检查。"},{"i":613,"n":"第六百一十三条","txt":"国家建立符合受控热核聚变特点、促进核聚变应用的放射性污染防治制度，对聚变燃料、聚变装置（设施）放射性污染防治实行分级分类管理。聚变装置（设施）建造等应当依法进行生态环境影响评价。"},{"i":614,"n":"第六百一十四条","txt":"在职业活动中接触放射性物质造成的职业病的防治，适用职业病防治法律的有关规定。"},{"i":615,"n":"第六百一十五条","txt":"核设施营运单位进行核设施选址、建造、运行、退役等活动，应当依法申请核设施安全许可。"},{"i":616,"n":"第六百一十六条","txt":"核设施营运单位应当按照国务院生态环境主管部门的规定在核设施建造、退役，以及选址、运行等环节开展生态环境影响评价。"},{"i":617,"n":"第六百一十七条","txt":"进口核设施，应当符合国家放射性污染防治标准；没有相应的国家放射性污染防治标准的，采用国务院生态环境主管部门指定的相关标准。"},{"i":618,"n":"第六百一十八条","txt":"省、自治区、直辖市人民政府应当依法在核动力厂等重要核设施周围划定规划限制区。禁止在规划限制区内建设可能威胁核设施安全的易燃、易爆、腐蚀性物品的生产、贮存设施以及人口密集场所。规划限制区的划定和管理办法，由国务院制定。"},{"i":619,"n":"第六百一十九条","txt":"核设施营运单位应当对核设施周边环境中所含的放射性核素的种类、浓度以及核设施流出物中的放射性核素总量实施监测，并定期向国务院生态环境主管部门和所在地省级人民政府生态环境主管部门报告监测结果。"},{"i":620,"n":"第六百二十条","txt":"国家建立健全核事故应急制度。"},{"i":621,"n":"第六百二十一条","txt":"核设施营运单位应当制定核设施退役计划。"},{"i":622,"n":"第六百二十二条","txt":"国家加强核技术利用放射性污染防治。国务院生态环境主管部门对可能造成污染的放射性同位素和射线装置实施分级分类管理。"},{"i":623,"n":"第六百二十三条","txt":"生产、销售、使用放射性同位素和射线装置的单位和其他生产经营者，应当按照国务院有关放射性同位素与射线装置放射防护的规定取得许可证。未取得许可证的，不得从事放射性同位素和射线装置生产、销售、使用活动。禁止在网络上销售放射性同位素和射线装置。"},{"i":624,"n":"第六百二十四条","txt":"生产、销售、使用放射性同位素和射线装置的单位和其他生产经营者，应当在申请许可证前依法取得生态环境影响报告书、生态环境影响报告表批准文件或者已经办理生态环境影响登记表备案手续。"},{"i":625,"n":"第六百二十五条","txt":"放射性同位素应当单独存放，不得与易燃、易爆、腐蚀性物品等一起存放，其贮存场所应当采取有效的防火、防盗、防射线泄漏的安全防护措施，并指定专人负责保管。贮存、领取、使用、归还放射性同位素时，应当进行登记、检查，做到账物相符。"},{"i":626,"n":"第六百二十六条","txt":"生产、使用放射性同位素和射线装置的单位和其他生产经营者，应当按照国务院生态环境主管部门的规定对其产生的放射性废物进行收集、包装、贮存。"},{"i":627,"n":"第六百二十七条","txt":"使用对人体健康、生态环境潜在危害程度较高的放射源的场所和生产放射性同位素的场所，以及终结运行后产生放射性污染的射线装置，应当依法实施退役。具体办法由国务院制定。"},{"i":628,"n":"第六百二十八条","txt":"生产、贮存、销售、使用放射源的单位和其他生产经营者，应当建立健全安全保卫制度，指定专人负责，落实安全责任制，制定必要的事故应急措施。发生放射源丢失、被盗和放射性污染事故时，有关单位和个人应当立即采取应急措施，并向公安机关、卫生健康主管部门和生态环境主管部门报告。"},{"i":629,"n":"第六百二十九条","txt":"开发利用或者关闭铀（钍）矿的单位，应当在开工建设或者办理退役审批手续前编制生态环境影响报告书、生态环境影响报告表，报国务院生态环境主管部门审查批准。"},{"i":630,"n":"第六百三十条","txt":"国务院生态环境主管部门根据矿产资源开发利用中放射性核素对人体健康、生态环境的潜在危害程度，制定伴生放射性矿开发利用辐射环境管理名录，统一规定纳入伴生放射性矿开发利用辐射环境管理的判定方法及标准、矿产类别和工业活动。伴生放射性矿开发利用辐射环境管理名录应当动态调整。"},{"i":631,"n":"第六百三十一条","txt":"实行排污许可管理的伴生放射性矿开发利用单位的排污许可证中应当记载排放废液中放射性核素的种类、浓度、排放量，伴生放射性固体废物的类别、物理性状、产生环节、去向，伴生放射性固体废物自行贮存、利用、处置及相关设施等信息。"},{"i":632,"n":"第六百三十二条","txt":"铀（钍）矿开发利用单位应当对铀（钍）矿的流出物和周边环境实施监测，并定期向国务院生态环境主管部门和所在地省级人民政府生态环境主管部门报告监测结果。"},{"i":633,"n":"第六百三十三条","txt":"对铀（钍）矿和伴生放射性矿开发利用过程中产生的尾矿等放射性固体废物，应当建造尾矿库等设施进行贮存、处置；建造的尾矿库等设施应当符合放射性污染防治的要求。"},{"i":634,"n":"第六百三十四条","txt":"铀（钍）矿开发利用单位应当制定铀（钍）矿退役计划。铀矿退役和监护费用由国家财政预算安排。"},{"i":635,"n":"第六百三十五条","txt":"核设施营运单位、核技术利用单位和其他生产经营者、铀（钍）矿和伴生放射性矿开发利用单位，应当合理选择和利用原材料，采用先进的生产工艺和设备，尽量减少放射性废物的产生量。"},{"i":636,"n":"第六百三十六条","txt":"排放放射性废气、废液，应当符合国家放射性污染防治的规定和标准。"},{"i":637,"n":"第六百三十七条","txt":"产生放射性废气、废液的单位排放符合国家放射性污染防治的规定和标准的放射性废气、废液，应当向审批生态环境影响报告书、生态环境影响报告表的生态环境主管部门申请放射性核素排放量，并定期报告排放计量结果。"},{"i":638,"n":"第六百三十八条","txt":"产生放射性废液的单位，应当按照国家放射性污染防治的规定和标准的要求，对不得排放的放射性废液进行处理或者贮存。不能经净化或者贮存衰变达到国家放射性污染防治的规定和标准要求的放射性废液，应当使其转变为符合处置要求的稳定的、标准化的放射性固体废物。"},{"i":639,"n":"第六百三十九条","txt":"低、中水平放射性固体废物应当按照国家规定实行近地表处置或者中等深度处置。"},{"i":640,"n":"第六百四十条","txt":"国务院核工业主管部门会同国务院生态环境主管部门根据地质条件和放射性固体废物处置的需要，在生态环境影响评价的基础上，依法组织编制放射性固体废物处置场所选址规划，报国务院批准后实施。"},{"i":641,"n":"第六百四十一条","txt":"产生放射性固体废物的单位，应当按照国务院生态环境主管部门的规定，对其产生的放射性固体废物进行处理后，送交放射性废物处置单位处置，并承担处置费用。"},{"i":642,"n":"第六百四十二条","txt":"设立专门从事放射性废物贮存、处理、处置的单位，应当经国务院生态环境主管部门审查批准，取得许可证；仅贮存、处理本单位产生的放射性废物的，无需取得许可证。具体办法由国务院制定。"},{"i":643,"n":"第六百四十三条","txt":"禁止违反法律规定将放射性废物和被放射性污染的物品输入中华人民共和国境内或者经中华人民共和国境内转移。"},{"i":644,"n":"第六百四十四条","txt":"国家加强化学物质污染风险管控。生产、进口、储存、运输、销售、使用、处置化学物质，应当遵守国家规定，防止污染环境，保障公众健康。具体办法由国务院制定。"},{"i":645,"n":"第六百四十五条","txt":"国家建立持久性有机污染物等新污染物协同治理和环境风险管控体系。国务院生态环境主管部门会同有关部门，分析研判新污染物环境风险管控形势，制定完善相关标准，组织开展调查监测，有效降低新污染物环境风险。"},{"i":646,"n":"第六百四十六条","txt":"国务院生态环境主管部门对全国化学物质污染风险管控工作实施统一监督管理。国务院发展改革、工业和信息化、农业农村、商务、卫生健康、海关、市场监督管理、疾病预防控制、药品监督管理等有关部门在各自职责范围内对化学物质污染风险管控工作实施监督管理。"},{"i":647,"n":"第六百四十七条","txt":"国务院生态环境主管部门根据化学物质的危害特性等定期组织开展化学物质污染信息调查，生产、进口、销售化学物质和使用化学物质生产产品的企业事业单位应当按照规定提供调查所需的化学物质的物理化学性质、数量、用途、危害特性、排放等信息。"},{"i":648,"n":"第六百四十八条","txt":"国务院有关部门应当在各自职责范围内按照规定采取有效措施，推动有毒有害化学物质替代。"},{"i":649,"n":"第六百四十九条","txt":"国务院生态环境主管部门会同有关部门，组织开展化学物质污染风险评估，制定公布重点管控新污染物清单并适时调整，明确禁止、限制等环境风险管控措施。生产、进口重点管控新污染物清单中化学物质和使用重点管控新污染物清单中化学物质生产产品的，应当遵守上述环境风险管控措施。"},{"i":650,"n":"第六百五十条","txt":"国家实行新化学物质环境管理登记制度。"},{"i":651,"n":"第六百五十一条","txt":"禁止无新化学物质环境管理登记证或者不按照新化学物质环境管理登记证的要求生产、进口新化学物质。禁止使用无新化学物质环境管理登记证的企业事业单位生产、进口的新化学物质生产产品。"},{"i":652,"n":"第六百五十二条","txt":"化学物质污染防治，本章未作规定的，适用本编其他有关规定。"},{"i":653,"n":"第六百五十三条","txt":"本法所称电磁辐射污染，是指人类活动产生的超过国家电磁辐射排放标准的非电离辐射。"},{"i":654,"n":"第六百五十四条","txt":"国务院生态环境主管部门对全国电磁辐射污染防治工作实施统一监督管理。地方人民政府生态环境主管部门对本行政区域电磁辐射污染防治工作实施统一监督管理。"},{"i":655,"n":"第六百五十五条","txt":"各级人民政府及其有关部门编制国土空间规划和相关规划，应当充分考虑电磁辐射设施产生的电磁辐射对周边环境的影响，统筹规划，合理安排土地用途和建设布局，防止、减轻电磁辐射污染。"},{"i":656,"n":"第六百五十六条","txt":"县级以上地方人民政府根据国家电磁环境质量标准和国土空间规划以及用地现状，划定本行政区域各类电磁环境质量标准的适用区域。电磁环境质量标准适用区域范围应当及时公布。"},{"i":657,"n":"第六百五十七条","txt":"国务院标准化主管部门会同国务院生态环境、工业和信息化、交通运输、铁路监督管理、民用航空、海事、广播电视、气象、能源、药品监督管理等有关部门，对可能产生电磁辐射污染的工业设备、无线电发射设备、电信设备、机动车、铁路机车车辆、城市轨道交通车辆、导航设备、机动船舶、气象设备、电气电子设备、医疗设备等产品，根据电磁辐射污染防治的要求和国家经济、技术条件，在其技术规范或者产品质量标准中规定电磁辐射限值。"},{"i":658,"n":"第六百五十八条","txt":"国家对电磁辐射设施实行分类管理，根据电磁辐射排放水平及其对周边环境的影响，将电磁辐射设施分为一类电磁辐射设施、二类电磁辐射设施、三类电磁辐射设施。具体办法由国务院生态环境主管部门会同有关部门制定。"},{"i":659,"n":"第六百五十九条","txt":"运行电磁辐射设施的企业事业单位应当优化布局，合理安排电磁辐射设施，采取有效措施，防止、减轻电磁辐射污染。"},{"i":660,"n":"第六百六十条","txt":"运行一类、二类电磁辐射设施的企业事业单位，应当按照国家规定采取发射功率控制、发射方向调整、紧急制动、屏蔽、接地、隔离等电磁辐射污染防治措施，开展自行监测，保存原始监测记录，监测结果定期向生态环境主管部门报告。"},{"i":661,"n":"第六百六十一条","txt":"运行一类电磁辐射设施的企业事业单位，应当按照国家规定设置警示标识、采取设置围栏防止公众近距离接触等电磁辐射污染防治措施。新建、改建、扩建一类电磁辐射设施应当避让人口密集区域。"},{"i":662,"n":"第六百六十二条","txt":"实行排污许可管理的运行电磁辐射设施的企业事业单位的排污许可证中应当记载电磁辐射设施的工作频率、发射功率、场强以及电磁辐射叠加影响情况等信息。"},{"i":663,"n":"第六百六十三条","txt":"使用移动式信息发射设施应当按照国家规定科学合理划定防护距离，采取设置警戒线、警示标识等防护措施。"},{"i":664,"n":"第六百六十四条","txt":"多个电磁辐射设施共用装置的责任主体，应当合理确定电磁辐射设施的数量、位置、功率等，采取有效措施，防止因电磁辐射叠加造成电磁辐射污染。"},{"i":665,"n":"第六百六十五条","txt":"涉及国家安全、重大社会公共利益的电磁辐射设施造成严重电磁辐射污染的，县级以上地方人民政府应当组织有关部门和其他有关单位对电磁辐射污染情况进行调查评估和责任认定，综合考虑经济、技术和管理措施，制定电磁辐射污染综合治理方案。"},{"i":666,"n":"第六百六十六条","txt":"在职业活动中接触电磁辐射造成的职业病的防治，适用职业病防治法律的有关规定。"},{"i":667,"n":"第六百六十七条","txt":"本法所称光污染，是指过度、不恰当使用人工照明或者不恰当改变日光的照射条件，造成周围生活环境中人的视觉受到干扰的现象。"},{"i":668,"n":"第六百六十八条","txt":"国务院生态环境主管部门对全国光污染防治工作实施统一监督管理。地方人民政府生态环境主管部门对本行政区域光污染防治工作实施统一监督管理。"},{"i":669,"n":"第六百六十九条","txt":"各级人民政府及其有关部门编制国土空间规划和相关规划，应当充分考虑城乡区域开发、改造和建设项目可能产生的光污染影响，统筹规划，合理安排土地用途和建设布局，防止、减轻光污染。"},{"i":670,"n":"第六百七十条","txt":"国务院标准化主管部门会同国务院住房城乡建设、生态环境、交通运输等有关部门根据光污染防治的要求和国家经济、技术条件，对照明产品、户外显示产品、交通补光灯、建筑玻璃和材料等在其技术规范或者产品质量标准中规定合理的光限值。"},{"i":671,"n":"第六百七十一条","txt":"广告屏、广告牌、灯箱、媒体立面墙、道路、体育场、施工场地等，应当按照国家规定合理设计、安装、使用照明设施，定期保养维护，采取有效措施，防止、减轻光污染。"},{"i":672,"n":"第六百七十二条","txt":"建筑物、构筑物外表面采用玻璃幕墙等建筑材料，应当符合国家规定，合理设计和选材，防止、减轻光污染。"},{"i":673,"n":"第六百七十三条","txt":"县级以上地方人民政府应当根据实际情况，实行光污染防治分区管理，加强对需要特殊保护区域的人工照明和日光照射条件的控制。"},{"i":674,"n":"第六百七十四条","txt":"本编适用于生态保护相关活动。"},{"i":675,"n":"第六百七十五条","txt":"国家统筹考虑生态环境要素的复杂性、生态系统的完整性、自然地理单元的连续性、经济社会发展的可持续性，坚持山水林田湖草沙一体化保护和系统治理，提升生态系统多样性、稳定性、持续性，维护生态安全。"},{"i":676,"n":"第六百七十六条","txt":"国家根据主体功能区定位，优化生态空间布局，推进国家重点生态功能区、重要生态廊道保护建设，筑牢生态安全屏障。"},{"i":677,"n":"第六百七十七条","txt":"国家加强对森林、草原、湿地、海洋、海岛、江河湖泊、荒漠、雪山冰川、耕地等生态系统的保护，坚持自然恢复为主、自然恢复与人工修复相结合，推进实施重要生态系统保护和修复重大工程，培育健康稳定、功能完备的生态系统，增强各类生态系统的服务功能。"},{"i":678,"n":"第六百七十八条","txt":"国家加强自然资源的保护，坚持节约集约利用，统筹资源保护与开发利用，制定自然资源保护和利用规划，提升自然资源保护和合理利用水平。"},{"i":679,"n":"第六百七十九条","txt":"国家对各类自然资源依法实行有偿使用，完善反映市场供求和资源稀缺程度、体现生态价值和代际补偿的自然资源有偿使用制度。"},{"i":680,"n":"第六百八十条","txt":"国家建立健全以国家公园为主体的自然保护地体系，实行统一设置、分级管理、分区管控，加强对重要生态系统、自然遗迹、自然景观和生物多样性的系统性保护，满足人民群众对优美生态环境、优良生态产品、优质生态服务的需要。"},{"i":681,"n":"第六百八十一条","txt":"国家统筹规划、协同推进长江、黄河等重要流域和重点海域的生态环境保护修复，构建重要流域上下游贯通一体的生态环境治理体系。"},{"i":682,"n":"第六百八十二条","txt":"国家对重要生态系统、生物物种、生物遗传资源实施有效保护，保护生物多样性相关传统知识，维护生物多样性。"},{"i":683,"n":"第六百八十三条","txt":"国家健全种质资源保护与利用体系，有计划地普查、收集、整理、鉴定、登记、保存、交流和利用种质资源。"},{"i":684,"n":"第六百八十四条","txt":"向境外提供，或者与境外机构、个人或者其设立或者实际控制的机构合作研究利用我国生物遗传资源的，应当依法取得批准，并提出公平、合理的国家共享惠益方案。"},{"i":685,"n":"第六百八十五条","txt":"国家加强生物安全管理，防范外来物种侵害，完善风险监测预警、调查评估、信息发布、应急处置等制度，对入境动植物及其产品依法实行检疫监督，对可能传入我国的外来物种加强动态跟踪和风险评估。"},{"i":686,"n":"第六百八十六条","txt":"县级以上人民政府有关部门可以在各自职责范围内，根据实际需要编制森林、草原、湿地、海洋、海岛、江河湖泊、荒漠、土地、矿产、水、渔业、野生动物及其栖息地保护和水土保持、防沙治沙等生态保护领域的规划。"},{"i":687,"n":"第六百八十七条","txt":"国务院生态环境、自然资源、水行政、农业农村、林业草原和标准化等有关部门，在各自职责范围内建立健全生态系统质量和等级评定、自然资源分类分级和节约集约利用、生物多样性保护以及水土保持、生态修复等标准。"},{"i":688,"n":"第六百八十八条","txt":"国家加强土地、矿产、森林、草原、湿地、海洋、海岛、江河湖泊、雪山冰川、荒漠、野生动植物、水土保持等自然资源状况和生态状况的调查评价，为保障生态安全、合理开发和高效利用国土空间及各类自然资源提供依据。"},{"i":689,"n":"第六百八十九条","txt":"国家实行耕地养护、修复、轮作休耕和森林、草原、湿地、海洋、江河湖泊休养生息制度。"},{"i":690,"n":"第六百九十条","txt":"国家建立严格的水土流失预防保护和监督管理制度，加强荒漠化、石漠化、水土流失的综合治理。"},{"i":691,"n":"第六百九十一条","txt":"国家按照生态系统的整体性、系统性及其内在规律，建立健全源头保护和全过程修复治理相结合的工作机制；按照尊重自然规律，宜林则林、宜草则草、宜沙则沙、宜荒则荒的原则，科学开展生态修复；完善多元化投入机制，鼓励、支持社会资本参与，并加强生态修复的监测、监督、成效评估，巩固生态治理成果。"},{"i":692,"n":"第六百九十二条","txt":"国家统筹城乡绿化，科学开展大规模国土绿化行动，绿化美化城乡。城乡绿化应当因地制宜，科学选择绿化树种草种，加强监测评估，满足健康、安全、宜居的需求。"},{"i":693,"n":"第六百九十三条","txt":"国家建立生态产品调查监测机制，通过开展自然资源统一确权登记探索确定生态产品权责归属。"},{"i":694,"n":"第六百九十四条","txt":"国家建立健全生态风险防控体系，采取有效措施，提高生态风险防控能力和水平。"},{"i":695,"n":"第六百九十五条","txt":"国家实行自然资源督察制度。国家自然资源督察机构根据授权对省、自治区、直辖市人民政府以及国务院确定的城市人民政府自然资源保护和开发利用情况、国土空间规划实施情况及相关法律法规执行情况进行督察。"},{"i":696,"n":"第六百九十六条","txt":"国家坚持平等互利、合作共赢的方针，支持开展生物多样性、野生动物、海洋生态保护和深海极地考察、防沙治沙、生态保护科学技术研究等方面的国际交流与合作。"},{"i":697,"n":"第六百九十七条","txt":"国家坚持生态优先、保护优先、保育结合、可持续发展，加强对森林生态系统和作为森林重要载体的山岭的保护，发挥森林蓄水保土、调节气候、改善生态环境、维护生物多样性和提供林产品等多种功能。"},{"i":698,"n":"第六百九十八条","txt":"国务院林业草原主管部门主管全国林业工作。"},{"i":699,"n":"第六百九十九条","txt":"县级以上人民政府应当落实国土空间开发保护要求，合理规划森林生态系统保护利用结构和布局，提高森林覆盖率、森林蓄积量，提升森林生态系统质量和稳定性。"},{"i":700,"n":"第七百条","txt":"植树造林、保护森林，是公民应尽的义务。"},{"i":701,"n":"第七百零一条","txt":"国家加强森林生态系统调查监测，对森林生态系统的规模、质量、结构、功能及生态状况进行调查监测和评价。"},{"i":702,"n":"第七百零二条","txt":"国家实行天然林全面保护制度，严格限制天然林采伐，加强天然林管护能力建设，科学实施修复措施，保护和修复天然林，逐步提高天然林生态功能。"},{"i":703,"n":"第七百零三条","txt":"国家对公益林和商品林实行分类经营管理，突出主导功能，发挥多种功能，培育稳定、健康、优质、高效的森林生态系统。"},{"i":704,"n":"第七百零四条","txt":"国家根据生态保护的需要，将森林生态区位重要或者生态状况脆弱，以发挥生态效益为主要目的的林地和林地上的森林划定为公益林。"},{"i":705,"n":"第七百零五条","txt":"国家保护古树名木，禁止破坏古树名木及其生存的生态环境。"},{"i":706,"n":"第七百零六条","txt":"国家在不同自然地带的典型森林生态地区、珍贵动物和植物生长繁殖的林区、天然热带雨林区和具有特殊保护价值的其他天然林区，依法建立自然保护地，加强保护管理。"},{"i":707,"n":"第七百零七条","txt":"地方各级人民政府负责本行政区域森林防灭火工作，发挥群防作用；县级以上人民政府组织领导应急管理、林业草原、公安等有关部门密切配合做好森林火灾的科学预防、扑救和处置工作。国家综合性消防救援队伍承担国家规定的森林火灾扑救任务和预防相关工作。"},{"i":708,"n":"第七百零八条","txt":"县级以上人民政府林业草原主管部门负责本行政区域林业有害生物的监测、检疫和防治。"},{"i":709,"n":"第七百零九条","txt":"禁止毁林开垦、采石、采砂、采土以及其他毁坏林木和林地的行为。"},{"i":710,"n":"第七百一十条","txt":"地方人民政府应当组织有关部门建立护林组织，负责护林工作；根据实际需要建设护林设施，加强森林生态系统保护；督促相关组织订立护林公约、组织群众护林、划定护林责任区、配备专职或者兼职护林员。"},{"i":711,"n":"第七百一十一条","txt":"国家提升森林生态系统的功能，增强生态产品供给能力，为人类生活、生产提供优良空气、优美生态环境，发挥休闲游憩、科研教育等生态价值。"},{"i":712,"n":"第七百一十二条","txt":"草原生态系统保护坚持科学规划、全面保护、重点修复、合理利用，发挥草原调节气候、涵养水源、保持水土、防风固沙以及作为野生动植物生存环境等多种功能，促进草原生态系统良性循环和资源可持续利用。"},{"i":713,"n":"第七百一十三条","txt":"国务院林业草原主管部门主管全国草原监督管理工作。"},{"i":714,"n":"第七百一十四条","txt":"县级以上人民政府林业草原主管部门可以根据实际需要，会同有关部门组织编制草原保护修复利用等相关专项规划。"},{"i":715,"n":"第七百一十五条","txt":"国家加强对草原生态系统的调查。县级以上人民政府林业草原主管部门会同有关部门对草原的面积、等级、产草量、载畜量、生态系统稳定性等进行调查。"},{"i":716,"n":"第七百一十六条","txt":"国家实行基本草原保护制度，依法将对维护生态安全、保障草原畜牧业健康发展具有最基本、最重要作用的草原划为基本草原，实行严格保护和管理，确保面积不减少、质量不下降、用途不改变。"},{"i":717,"n":"第七百一十七条","txt":"国家加强草原野生动植物保护，依法建立草原类型自然保护地，增强草原生态系统的完整性和连通性，加强野生动物栖息地、迁徙通道和野生植物生长环境的保护，保障野生动植物生存繁衍的空间，保护草原生物多样性。"},{"i":718,"n":"第七百一十八条","txt":"地方各级人民政府负责本行政区域草原防灭火工作，发挥群防作用；县级以上人民政府组织应急管理、林业草原、公安等有关部门密切配合做好草原火灾的科学预防、扑救和处置工作。国家综合性消防救援队伍承担国家规定的草原火灾扑救任务和预防相关工作。"},{"i":719,"n":"第七百一十九条","txt":"开发利用草原不得破坏草原野生动植物生存环境，不得损害草原生态系统的功能。"},{"i":720,"n":"第七百二十条","txt":"禁止开垦草原。对水土流失严重、有沙化趋势、需要改善生态环境的已垦草原，应当有计划、有步骤地退耕还草；已造成沙化、盐碱化、石漠化的，应当限期治理。"},{"i":721,"n":"第七百二十一条","txt":"国家保护、修复和合理利用草原，在保护草原生态的基础上，引导科学开展草原生态旅游、生态教育、科研等活动，发挥草原生态价值。"},{"i":722,"n":"第七百二十二条","txt":"国家坚持保护优先、严格管理、系统治理、科学修复、合理利用，完善湿地生态系统保护制度，发挥湿地涵养水源、调节气候、改善生态环境、维护生物多样性等多种生态功能，实现生态效益、社会效益、经济效益相统一。"},{"i":723,"n":"第七百二十三条","txt":"国务院林业草原主管部门负责湿地资源的监督管理，负责湿地保护规划和相关国家标准拟定、湿地开发利用的监督管理、湿地生态保护修复工作。国务院自然资源、水行政、住房城乡建设、生态环境、农业农村等其他有关部门，在各自职责范围内承担湿地保护、修复、管理有关工作。"},{"i":724,"n":"第七百二十四条","txt":"国务院林业草原主管部门会同有关部门依法编制全国湿地保护规划。"},{"i":725,"n":"第七百二十五条","txt":"国务院自然资源主管部门应当会同国务院林业草原等有关部门对全国湿地类型、分布、面积、生物多样性、保护与利用情况等进行调查，建立统一的信息发布和共享机制。"},{"i":726,"n":"第七百二十六条","txt":"国家按照生态区位、面积以及维护生态功能、生物多样性的重要程度，将湿地分为重要湿地和一般湿地，实行分级管理。"},{"i":727,"n":"第七百二十七条","txt":"国家实行湿地面积总量管控制度，将湿地面积总量管控目标纳入湿地保护目标责任制。"},{"i":728,"n":"第七百二十八条","txt":"国家严格控制占用湿地。确需占用的，应当依照《中华人民共和国湿地保护法》的规定办理相关手续。"},{"i":729,"n":"第七百二十九条","txt":"地方人民政府及其有关部门应当采取措施，预防和控制人为活动对湿地及其生物多样性的不利影响，加强湿地污染防治，减缓人为因素和自然因素导致的湿地退化，维护湿地生态功能稳定。县级以上地方人民政府应当充分考虑保障重要湿地生态功能的需要，优化重要湿地周边产业布局。"},{"i":730,"n":"第七百三十条","txt":"禁止下列破坏湿地及其生态功能的行为："},{"i":731,"n":"第七百三十一条","txt":"在红树林湿地禁止挖塘，禁止采伐、采挖、移植红树林或者过度采摘红树林种子，禁止投放、种植危害红树林生长的物种。因科研、医药或者红树林湿地保护等需要采伐、采挖、移植、采摘的，应当依照有关法律法规办理。"},{"i":732,"n":"第七百三十二条","txt":"县级以上人民政府应当加强对国家重点保护野生动植物集中分布湿地的保护。任何单位和个人不得破坏鸟类和水生生物的生存环境。"},{"i":733,"n":"第七百三十三条","txt":"县级以上人民政府有关部门应当在各自职责范围内开展湿地有害生物监测工作，及时采取有效措施预防、控制、消除有害生物对湿地生态系统的危害。"},{"i":734,"n":"第七百三十四条","txt":"国家坚持保护优先、预防为主、源头防控、陆海统筹，加强海洋生态系统保护。"},{"i":735,"n":"第七百三十五条","txt":"国务院自然资源主管部门负责海洋、海岛保护和开发利用的监督管理，负责全国海洋生态、海域海岸线和海岛的修复工作。国务院渔业渔政主管部门负责渔业水域生态环境保护工作。其他有关部门和机构在各自职责范围内负责海洋、海岛生态保护相关工作。"},{"i":736,"n":"第七百三十六条","txt":"国务院自然资源主管部门组织开展海洋资源调查和海洋生态预警监测，发布海洋生态预警监测警报和公报。其他负有海洋生态环境保护监督管理职责的部门和机构在各自职责范围内开展监测、监视。"},{"i":737,"n":"第七百三十七条","txt":"国务院和沿海地方各级人民政府应当采取有效措施，重点保护红树林、珊瑚礁、海藻场、海草床、滨海湿地、海岛、海湾、入海河口、重要渔业水域等具有典型性、代表性的海洋生态系统，珍稀濒危海洋生物的天然集中分布区，具有重要经济价值的海洋生物生存区域及有重大科学文化价值的海洋自然遗迹和自然景观。"},{"i":738,"n":"第七百三十八条","txt":"国家健全海洋生物多样性调查、监测、评估和保护体系，维护和修复重要海洋生态廊道，防止对海洋生物多样性的破坏。"},{"i":739,"n":"第七百三十九条","txt":"国家严格保护海洋自然岸线，建立健全自然岸线控制制度。沿海省、自治区、直辖市人民政府负责划定严格保护岸线的范围并发布。"},{"i":740,"n":"第七百四十条","txt":"沿海地方各级人民政府应当结合当地生态环境的特点，建设海岸防护设施、沿海防护林、沿海城镇园林和绿地，对海岸侵蚀和海水入侵地区进行综合治理。"},{"i":741,"n":"第七百四十一条","txt":"国家鼓励发展生态渔业，推广多种生态渔业生产方式，改善海洋生态状况，保护海洋生态环境。"},{"i":742,"n":"第七百四十二条","txt":"国务院自然资源主管部门负责开展全国海洋生态灾害预防、风险评估和隐患排查治理。"},{"i":743,"n":"第七百四十三条","txt":"国务院和沿海地方各级人民政府应当依照《中华人民共和国海岛保护法》等法律法规的规定采取措施，保护海岛的自然资源、自然景观以及自然遗迹、人文遗迹。"},{"i":744,"n":"第七百四十四条","txt":"有居民海岛的开发、建设应当遵守本法和有关生态环境法律法规的规定，保护海岛及其周边海域生态系统。"},{"i":745,"n":"第七百四十五条","txt":"中华人民共和国缔结或者参加的与海洋生态环境保护有关的国际条约与本法有不同规定的，适用国际条约的规定；但是，中华人民共和国声明保留的条款除外。"},{"i":746,"n":"第七百四十六条","txt":"国家加强对江河湖泊生态系统的严格保护，巩固提升江河湖泊生态系统的功能。"},{"i":747,"n":"第七百四十七条","txt":"县级以上人民政府水行政、农业农村等主管部门在各自职责范围内负责江河湖泊生态系统的保护、管理等相关工作。"},{"i":748,"n":"第七百四十八条","txt":"国家加强江河湖泊生态用水保障，县级以上人民政府水行政主管部门、国务院水行政主管部门有关流域管理机构应当按照管理权限，确定重要江河控制断面生态流量和重要湖泊生态水位的管控指标。确定生态流量和生态水位的管控指标，应当进行科学论证，综合考虑水资源条件、气候状况、生态环境保护要求、生活生产用水状况等因素。"},{"i":749,"n":"第七百四十九条","txt":"国家对江河湖泊水域岸线等水生态空间实行分区管理，严格控制开发利用强度，最大程度保持岸线自然形态。沿江河湖泊土地开发利用和产业布局，应与岸线分区要求相衔接，并为经济社会可持续发展预留空间。"},{"i":750,"n":"第七百五十条","txt":"国务院有关部门根据流域生态环境功能需要，明确流域生态环境保护要求，组织开展流域生态环境的承载能力监测、评价，实施流域生态环境的承载能力预警。"},{"i":751,"n":"第七百五十一条","txt":"国家加强江河湖泊管理和保护，建立江河湖泊定期普查制度，按照规定实行江河湖泊名录管理，划定江河湖泊管理范围，实行严格保护。"},{"i":752,"n":"第七百五十二条","txt":"国家科学实施水生生物增殖放流、栖息地修复、迁地保护、生态通道修复等措施，构建水生生物多样性保护网络，并对珍贵、濒危水生野生动植物实行重点保护。"},{"i":753,"n":"第七百五十三条","txt":"国家加大对重要江河湖泊生态保护的支持力度。县级以上地方人民政府应当根据流域生态功能需要，因地制宜建设人工湿地、水源涵养林、沿江河湖泊植被缓冲带和隔离带等生态治理与保护工程，整治黑臭水体，提高流域生态环境的承载能力。"},{"i":754,"n":"第七百五十四条","txt":"国家加强干旱、半干旱地区自然形成的沙漠、砾漠、岩漠等原生荒漠及其生物群落的保护，坚持保护优先、统一规划、因地制宜，建立荒漠生态系统保护制度，发挥荒漠生态系统防风固沙、调节气候、调控水文、保育土壤、维护生物多样性等多种功能。"},{"i":755,"n":"第七百五十五条","txt":"国务院林业草原主管部门负责荒漠生态系统保护工作。"},{"i":756,"n":"第七百五十六条","txt":"县级以上人民政府及其有关部门根据实际需要编制生态保护相关规划时，应当科学规划荒漠生态系统保护利用的结构和布局，稳固和提升荒漠生态系统的功能。"},{"i":757,"n":"第七百五十七条","txt":"国家建立健全原生荒漠保护制度。地方人民政府及其有关部门应当采取措施，预防和控制人为活动对原生荒漠中原生植被、土壤、水、野生动物及其栖息地的扰动，加强地表结皮的保育，及时制止导致土地荒漠化的行为，并采取有效措施进行治理。"},{"i":758,"n":"第七百五十八条","txt":"国家对生态区位重要的原生荒漠实施封禁保护，促进荒漠植被自然修复，综合采用生物措施和工程措施提高荒漠生态系统稳定性。"},{"i":759,"n":"第七百五十九条","txt":"十分珍惜、合理利用土地和切实保护耕地是我国的基本国策。"},{"i":760,"n":"第七百六十条","txt":"国务院自然资源主管部门统一负责全国土地的管理和监督工作，国务院农业农村主管部门负责全国农村宅基地改革和管理有关工作。"},{"i":761,"n":"第七百六十一条","txt":"国家建立土地调查、统计与监测制度。"},{"i":762,"n":"第七百六十二条","txt":"地方各级人民政府应当按照国土空间规划，组织实施田、水、路、林、村综合整治，增加有效耕地面积，提高耕地质量，改善农业生产条件和生态环境。"},{"i":763,"n":"第七百六十三条","txt":"国家加强对土壤资源的保护和合理利用，减少开发利用对土壤生态系统和生物多样性的影响。"},{"i":764,"n":"第七百六十四条","txt":"国家实行耕地数量、质量、生态一体保护。"},{"i":765,"n":"第七百六十五条","txt":"国家实行占用耕地补偿制度，严格控制各类占用耕地行为；确需占用耕地的，应当依法落实补充耕地责任。"},{"i":766,"n":"第七百六十六条","txt":"国家对永久基本农田实行特殊保护。永久基本农田经依法划定后，任何单位和个人不得擅自占用或者改变其用途。"},{"i":767,"n":"第七百六十七条","txt":"国家实行科学、有效的黑土地保护政策，保障黑土地保护财政投入，综合采取工程、农艺、农机、生物等措施，保护黑土地的优良生产能力，确保黑土地总量不减少、功能不退化、质量有提升、产能可持续。"},{"i":768,"n":"第七百六十八条","txt":"国家实行建设用地总量控制，严格限制农用地转为建设用地。确需占用的，应当依照《中华人民共和国土地管理法》、《中华人民共和国森林法》、《中华人民共和国草原法》，以及有关耕地保护和质量提升的法律等的规定办理相关手续。"},{"i":769,"n":"第七百六十九条","txt":"依照法律、行政法规的规定申请临时用地的，应当尽量不占或者少占耕地、避让永久基本农田，不得修建永久性建筑物。"},{"i":770,"n":"第七百七十条","txt":"具有重要生态功能的未利用地应当依法划入生态保护红线，实行严格保护。开垦未利用的土地，应当经过科学论证和评估，经依法批准后进行。"},{"i":771,"n":"第七百七十一条","txt":"矿产资源的勘查、开采以及矿区生态修复，应当坚持开发利用与保护并重，实现绿色发展。"},{"i":772,"n":"第七百七十二条","txt":"国家对矿产资源的勘查、开采实行统一规划、科学布局、综合勘查、合理开采和综合利用的方针。"},{"i":773,"n":"第七百七十三条","txt":"矿业权出让合同应当明确矿区生态修复等有关要求。"},{"i":774,"n":"第七百七十四条","txt":"勘查活动结束后，探矿权人应当及时对勘查区域进行清理；破坏地表植被的，应当及时恢复。"},{"i":775,"n":"第七百七十五条","txt":"开采矿产资源，应当采取合理的开采顺序、开采方法；采取有效措施保护地下水资源，并优先使用矿井水；避免、减少对矿区森林、草原、耕地、湿地、江河湖泊、海洋等生态系统的破坏；加强对尾矿库建设、运行、闭库等活动的管理，防范生态环境风险。"},{"i":776,"n":"第七百七十六条","txt":"禁止在严格保护岸线范围内开采海砂。依法在其他区域开发利用海砂资源，应当采取严格措施，保护海洋生态。载运海砂资源应当持有合法来源证明；海砂开采者应当为载运海砂的船舶提供合法来源证明。"},{"i":777,"n":"第七百七十七条","txt":"国家依法保护煤炭资源，禁止任何乱采、滥挖等破坏煤炭资源的行为。"},{"i":778,"n":"第七百七十八条","txt":"保护、开发、利用、节约水资源和防治水害，应当全面规划、统筹兼顾、标本兼治、综合利用、讲求效益，实现水资源的可持续利用。"},{"i":779,"n":"第七百七十九条","txt":"国家厉行节水，坚持和落实节水优先方针，全面建设节水型社会。"},{"i":780,"n":"第七百八十条","txt":"国家制定水资源综合规划，对水资源合理配置、有效保护和节约集约利用等作出总体安排。"},{"i":781,"n":"第七百八十一条","txt":"国家对水资源实行流域管理与行政区域管理相结合的管理体制。"},{"i":782,"n":"第七百八十二条","txt":"国家加强水文、水资源信息系统建设。县级以上人民政府水行政主管部门和流域管理机构应当加强对水资源的动态监测，提升水文监测预报预警能力。"},{"i":783,"n":"第七百八十三条","txt":"国家建立健全水功能区划制度。"},{"i":784,"n":"第七百八十四条","txt":"制定水资源开发、利用规划和调度水资源时，应当保障维持江河的合理流量和湖泊、水库以及地下水的合理水位，维护水体的自然净化能力。在干旱和半干旱地区开发、利用水资源，应当充分考虑生态用水需要。"},{"i":785,"n":"第七百八十五条","txt":"国家加强饮用水水源地保护，实行饮用水水源地名录管理，将饮用水水源地水量保障作为流域区域水量调度方案和调度计划的优先目标，严格取水管理，防止水源枯竭和水体污染，保证城乡居民饮用水安全。"},{"i":786,"n":"第七百八十六条","txt":"国家加强地下水管理和保护，实行地下水取水总量控制和水位控制制度，划定地下水超采区，实施地下水超采综合治理，保障地下水可持续利用。"},{"i":787,"n":"第七百八十七条","txt":"开发、利用水资源，应当坚持节约保护优先、兴利与除害相结合，兼顾上下游、左右岸、干支流和有关地区之间的利益，充分发挥水资源的综合效益，并服从防洪的总体安排。"},{"i":788,"n":"第七百八十八条","txt":"国民经济和社会发展规划、国土空间总体规划的编制以及重大建设项目的布局，应当与当地水资源条件和防洪要求相适应，并进行科学论证。"},{"i":789,"n":"第七百八十九条","txt":"国家鼓励、支持污水资源化利用，县级以上地方人民政府应当统筹规划、建设污水资源化利用基础设施。"},{"i":790,"n":"第七百九十条","txt":"县级以上人民政府组织实施调水工程，应当进行全面规划和科学论证，统筹兼顾调出区和调入区的用水安全和生态安全，加强对调入区的节水管理，优化水资源配置，提高水资源承载能力，防止对生态环境造成破坏。"},{"i":791,"n":"第七百九十一条","txt":"开发、利用水资源，应当维护水体的生态功能，防止对水生态造成破坏。"},{"i":792,"n":"第七百九十二条","txt":"国家对用水实行总量控制和定额管理相结合的制度，依照《中华人民共和国水法》的规定对水资源实行取水许可制度和有偿使用制度。"},{"i":793,"n":"第七百九十三条","txt":"国家大力推行节约用水措施，推广节约用水新技术、新工艺，发展节水型工业、农业和服务业，推进生活节水，加强生活废水循环利用。"},{"i":794,"n":"第七百九十四条","txt":"渔业生产应当坚持养殖为主、适度捕捞，实现渔业资源的保护和可持续利用。"},{"i":795,"n":"第七百九十五条","txt":"国务院渔业渔政主管部门主管全国的渔业工作。县级以上地方人民政府渔业渔政主管部门主管本行政区域渔业工作。"},{"i":796,"n":"第七百九十六条","txt":"国家保护水产种质资源及其生存环境，并在具有较高经济价值和遗传育种价值的水产种质资源的主要生长繁育区域建立水产种质资源保护区。"},{"i":797,"n":"第七百九十七条","txt":"国家鼓励、支持因地制宜采取增殖放流、建设海洋牧场、投放人工鱼礁、种植海藻场或者海草床等措施，养护水生生物资源，修复、改善渔业水域生态环境。"},{"i":798,"n":"第七百九十八条","txt":"国家对水域、滩涂利用进行统一规划，确定可以用于养殖业的水域和滩涂，建立养殖水域、滩涂保护制度；单位和个人使用国家所有的水域、滩涂从事养殖生产的，应当依照《中华人民共和国渔业法》的规定取得养殖证。"},{"i":799,"n":"第七百九十九条","txt":"国家根据捕捞量低于渔业资源增长量的原则，确定渔业资源的总可捕捞量，实行捕捞限额制度。"},{"i":800,"n":"第八百条","txt":"各级人民政府应当采取有效措施，保护和改善渔业水域生态环境。"},{"i":801,"n":"第八百零一条","txt":"禁止违反禁渔区、禁渔期的规定从事捕捞活动。禁止渔业船舶违反禁渔区、禁渔期的规定航行、停泊。"},{"i":802,"n":"第八百零二条","txt":"国家加强对林木、草原、野生动物和海洋资源等其他自然资源开发利用的管理，实现资源的保护与可持续利用。"},{"i":803,"n":"第八百零三条","txt":"国家实行林木采伐许可制度。采伐林地上的林木应当依法申请采伐许可证，并按照采伐许可证的规定进行采伐。非林地上的农田防护林、防风固沙林、护路林、护岸护堤林和城镇林木等的更新采伐，由有关主管部门按照规定管理。"},{"i":804,"n":"第八百零四条","txt":"国家鼓励、支持人工草地建设、天然草原改良和饲草饲料基地建设，稳定、提高草原生产能力。"},{"i":805,"n":"第八百零五条","txt":"人工繁育野生动物，实行分类分级管理，严格保护和科学利用野生动物资源，并依法办理许可或者备案。"},{"i":806,"n":"第八百零六条","txt":"开发利用海洋资源或者从事影响海洋生态环境的建设活动，应当根据国土空间规划科学合理布局，严格遵守国土空间用途管制要求，严守生态保护红线，不得造成海洋生态环境的损害。沿海省、自治区、直辖市人民政府应当加强对生态保护红线内人为活动的监督管理，定期评估保护成效。"},{"i":807,"n":"第八百零七条","txt":"国家加强对专属经济区和大陆架自然资源开发利用活动的管理。中华人民共和国主管机关依照《中华人民共和国专属经济区和大陆架法》的规定，有权采取必要的措施，防止、减少和控制对海洋生态环境的破坏。"},{"i":808,"n":"第八百零八条","txt":"从事深海海底区域资源勘探、开发活动应当依照《中华人民共和国深海海底区域资源勘探开发法》的规定，采取必要措施，保护和保全稀有或者脆弱的生态系统，以及衰竭、受威胁或者有灭绝危险的物种和其他海洋生物的生存环境，保护海洋生物多样性，维护海洋资源的可持续利用。"},{"i":809,"n":"第八百零九条","txt":"本法规定保护的野生动物，是指珍贵、濒危的陆生、水生野生动物和有重要生态、科学、社会价值的陆生野生动物。"},{"i":810,"n":"第八百一十条","txt":"国家加强野生动物保护，拯救珍贵、濒危野生动物，维护生物多样性和生态平衡。"},{"i":811,"n":"第八百一十一条","txt":"国务院林业草原、渔业渔政主管部门分别主管全国陆生、水生野生动物保护工作。"},{"i":812,"n":"第八百一十二条","txt":"国家对野生动物实行分类分级保护。"},{"i":813,"n":"第八百一十三条","txt":"县级以上人民政府野生动物保护主管部门应当加强信息技术应用，定期组织或者委托有关科学研究机构对野生动物及其栖息地状况进行调查、监测和评估，建立健全野生动物及其栖息地档案。"},{"i":814,"n":"第八百一十四条","txt":"县级以上人民政府野生动物保护主管部门根据野生动物及其栖息地调查、监测和评估情况，对种群数量明显超过生态环境容量的物种，可以采取迁地保护、猎捕等种群调控措施，保障人身财产安全、生态安全和农业生产。"},{"i":815,"n":"第八百一十五条","txt":"国家保护野生动物及其栖息地。"},{"i":816,"n":"第八百一十六条","txt":"县级以上人民政府及其有关部门在依法编制有关开发利用规划时，应当充分考虑野生动物及其栖息地保护的需要，分析、预测和评估规划实施可能对野生动物及其栖息地保护产生的整体影响，避免或者减少规划实施可能造成的不利后果。"},{"i":817,"n":"第八百一十七条","txt":"在自然保护地和禁猎（渔）区、禁猎（渔）期内，禁止猎捕以及其他妨碍野生动物生息繁衍的活动，法律法规另有规定的除外。"},{"i":818,"n":"第八百一十八条","txt":"禁止猎捕、杀害国家重点保护野生动物，因科学研究、种群调控、疫源疫病监测或者其他特殊情况需要猎捕的，应当依法申请特许猎捕证。"},{"i":819,"n":"第八百一十九条","txt":"禁止使用毒药、爆炸物、电击或者电子诱捕装置以及猎套、猎夹、捕鸟网、地枪、排铳、地弓等工具进行猎捕，禁止使用夜间照明行猎、歼灭性围猎、捣毁巢穴、设置陷阱、火攻、烟熏、网捕等方法进行猎捕，但因物种保护、科学研究确需网捕、电子诱捕以及植保作业等除外。"},{"i":820,"n":"第八百二十条","txt":"社会公众应当增强保护野生动物和维护公共卫生安全的意识，防止野生动物源性传染病传播，抵制违法食用野生动物，养成文明健康的生活方式。"},{"i":821,"n":"第八百二十一条","txt":"禁止出售、购买、利用国家重点保护野生动物及其制品。"},{"i":822,"n":"第八百二十二条","txt":"国家重点保护野生动物和有重要生态、科学、社会价值的陆生野生动物或者地方重点保护野生动物受到突发事件威胁时，当地人民政府应当及时采取应急救助措施。"},{"i":823,"n":"第八百二十三条","txt":"国务院野生动物保护主管部门应当会同有关部门加强对放生野生动物活动的规范、引导。任何单位和个人将野生动物放生至野外环境，应当选择适合放生地野外生存的当地物种，不得干扰当地居民的正常生活、生产，避免对生态系统造成危害。"},{"i":824,"n":"第八百二十四条","txt":"外国人在我国对国家重点保护野生动物进行野外考察或者在野外拍摄电影、录像，应当经依法批准，并遵守有关法律法规的规定。"},{"i":825,"n":"第八百二十五条","txt":"国家加强对野生动物遗传资源的保护，对濒危野生动物实施抢救性保护。"},{"i":826,"n":"第八百二十六条","txt":"中华人民共和国缔结或者参加的国际公约禁止或者限制贸易的野生动物或者其制品名录，由国家濒危物种进出口管理机构制定、调整并公布。"},{"i":827,"n":"第八百二十七条","txt":"国家组织开展野生动物保护及相关执法活动的国际交流与合作，加强与毗邻国家的协作，保护候鸟、洄游鱼类等野生动物的迁徙洄游通道；建立防范、打击野生动物及其制品走私和非法贸易的部门协调机制，开展防范、打击走私和非法贸易行动。"},{"i":828,"n":"第八百二十八条","txt":"在野生动物致害严重区域，县级以上地方人民政府应当组织有关单位和个人积极开展野生动物致害综合防控，通过建设隔离防护设施、设置安全警示标志、强化监测预警、开展防护知识宣传等，科学预防野生动物可能造成的危害。"},{"i":829,"n":"第八百二十九条","txt":"本法规定保护的野生植物，是指原生地天然生长的珍贵植物和原生地天然生长并具有重要经济、科学、文化价值的濒危、稀有植物。"},{"i":830,"n":"第八百三十条","txt":"国家加强野生植物保护，严格管理我国野生植物采集、利用、对外提供等活动。"},{"i":831,"n":"第八百三十一条","txt":"国务院林业草原、农业农村主管部门在各自职责范围内分别主管全国野生植物保护和监督管理工作。"},{"i":832,"n":"第八百三十二条","txt":"国家保护野生植物及其生长环境。禁止非法采集野生植物或者破坏其生长环境。"},{"i":833,"n":"第八百三十三条","txt":"国家对野生植物实行分类分级保护。"},{"i":834,"n":"第八百三十四条","txt":"国家鼓励、支持野生植物的就地保护。在国家重点保护野生植物物种和地方重点保护野生植物物种的天然集中分布区域，应当依法建立自然保护地；在其他区域，县级以上地方人民政府野生植物保护主管部门和其他有关部门可以根据实际情况建立重点保护野生植物的保护点或者设立保护标志。"},{"i":835,"n":"第八百三十五条","txt":"各级野生植物保护主管部门和有关单位对生长受到威胁的国家重点保护野生植物和地方重点保护野生植物应当采取拯救措施，恢复其生长环境，必要时应当采取迁地保护、建立种质资源库和野外回归等措施。"},{"i":836,"n":"第八百三十六条","txt":"国家建立健全野生植物迁地保护网络，逐步建立国家植物园体系。"},{"i":837,"n":"第八百三十七条","txt":"国务院野生植物保护主管部门负责组织开展全国野生植物资源调查、监测、评估和信息发布工作。地方人民政府野生植物保护主管部门负责本行政区域相关工作。"},{"i":838,"n":"第八百三十八条","txt":"除因科学研究、人工培育、文化交流等特殊需要外，禁止采集国家一级保护野生植物。"},{"i":839,"n":"第八百三十九条","txt":"国家引导和规范具备条件的单位和个人依法开展野生植物人工培植活动。"},{"i":840,"n":"第八百四十条","txt":"禁止出售、收购国家一级保护野生植物。"},{"i":841,"n":"第八百四十一条","txt":"禁止外国人在中国境内采集或者收购国家重点保护野生植物及其种质资源。"},{"i":842,"n":"第八百四十二条","txt":"出口国家重点保护野生植物及其制品或者进出口中华人民共和国参加的国际公约所限制进出口的野生植物及其制品的，应当经依法批准，并取得允许进出口证明书或者标签，凭允许进出口证明书或者标签办理海关手续。国务院野生植物保护主管部门应当将有关野生植物进出口的资料抄送国务院生态环境主管部门。"},{"i":843,"n":"第八百四十三条","txt":"本法所称外来入侵物种，是指境外传入定殖并对生态系统、物种及其栖息生长环境带来威胁或者危害，影响我国生态环境，损害农林牧渔业可持续发展和生物多样性的外来物种。"},{"i":844,"n":"第八百四十四条","txt":"国家坚持风险预防、源头管控、综合治理、协同配合、公众参与，完善外来物种入侵防控体系，加强外来入侵物种防控管理，保护生物多样性，维护国家生物安全。"},{"i":845,"n":"第八百四十五条","txt":"国务院农业农村主管部门会同有关部门建立外来入侵物种防控协调机制，统筹全国外来入侵物种防控工作，协调解决重大问题。"},{"i":846,"n":"第八百四十六条","txt":"国务院农业农村主管部门会同有关部门制定完善外来入侵物种名录，实行动态调整和分类分级管理，建立外来入侵物种数据库，制定外来入侵物种风险评估、监测预警、防控治理等技术规范。"},{"i":847,"n":"第八百四十七条","txt":"国务院农业农村、自然资源、生态环境、海关、林业草原等有关部门建立健全应急处置机制，组织制定相关领域外来入侵物种突发事件应急预案。"},{"i":848,"n":"第八百四十八条","txt":"国家加强外来物种引入审批管理。因品种培育等特殊需要从境外引进农作物和林草种子苗木、水产苗种等外来物种的，应当依法办理进口审批与检疫审批。"},{"i":849,"n":"第八百四十九条","txt":"国务院农业农村主管部门会同有关部门建立外来入侵物种普查制度，掌握我国外来入侵物种的种类数量、分布范围、危害程度等情况。"},{"i":850,"n":"第八百五十条","txt":"国务院农业农村主管部门会同有关部门建立外来入侵物种监测制度，构建全国外来入侵物种监测网络，在各自职责范围内布设监测站点，组织开展常态化监测和信息共享。"},{"i":851,"n":"第八百五十一条","txt":"国家加强外来入侵物种口岸防控。"},{"i":852,"n":"第八百五十二条","txt":"国务院农业农村、自然资源、生态环境、林业草原等有关部门在各自职责范围内研究制定本领域外来入侵物种防控策略措施，指导地方开展防控。"},{"i":853,"n":"第八百五十三条","txt":"国家以保护自然、服务人民、永续发展为目标，坚持严格保护、科学管理、政府主导、多方参与、合理利用、社会共享，建立健全自然保护地体系，保护生物多样性与地质地貌景观多样性，维护生态系统健康稳定，提升生态产品供给能力，维护生态安全。"},{"i":854,"n":"第八百五十四条","txt":"国务院林业草原主管部门负责各类自然保护地的监督管理工作。"},{"i":855,"n":"第八百五十五条","txt":"国务院林业草原主管部门会同国务院发展改革、财政、自然资源、生态环境、住房城乡建设、交通运输、水行政、农业农村、文化和旅游等有关部门开展保护协作、信息共享等，研究解决自然保护地保护工作中的重大问题。"},{"i":856,"n":"第八百五十六条","txt":"跨两个以上行政区域的自然保护地，由相关行政区域人民政府加强自然保护地保护工作协商，或者由涉及行政区域联合申请，由上级人民政府协调解决；跨两个以上省级行政区域的，由国务院林业草原主管部门商自然保护地所在地省、自治区、直辖市人民政府解决。"},{"i":857,"n":"第八百五十七条","txt":"国家加强自然保护地监测网络体系建设，充分发挥各类监测站点的作用，运用信息化手段加强监测数据集成分析、共享和综合应用，全面掌握生态系统构成、分布、动态变化和生物多样性状况，及时评估和预警生态风险。"},{"i":858,"n":"第八百五十八条","txt":"国家建立健全自然保护地相关标准体系，依法组织制定并适时修订自然保护地相关标准。"},{"i":859,"n":"第八百五十九条","txt":"国家实行自然保护地分类分级管理。自然保护地按生态价值和保护强度高低依次分为国家公园、自然保护区和自然公园。自然保护区和自然公园分为国家级和省级。"},{"i":860,"n":"第八百六十条","txt":"国家公园的设立、名称变更、区域范围或者管控分区调整等，依照《中华人民共和国国家公园法》的规定办理。"},{"i":861,"n":"第八百六十一条","txt":"自然保护地实行分区管控。根据生态系统特性、功能定位和管理目标，国家公园和自然保护区划分为核心保护区和一般控制区。"},{"i":862,"n":"第八百六十二条","txt":"自然保护地周边社区建设应当与自然保护地保护目标相协调，避免或者减少对自然保护地的不利影响。"},{"i":863,"n":"第八百六十三条","txt":"国家对自然保护地实行整体保护，建立健全政府、企业事业单位、社会组织和公众共同参与保护的长效机制，指导、支持自然保护地内原有居民、农村集体经济组织以及自然保护地周边居民、企业等积极参与自然保护地的保护，提供与自然保护地保护目标相一致的生态产品和服务。"},{"i":864,"n":"第八百六十四条","txt":"国家完善自然保护地公共服务体系，提升公共服务功能，促进社会共享自然保护地生态价值。"},{"i":865,"n":"第八百六十五条","txt":"国家加强自然保护地生态建设，尊重自然规律，建设生态廊道，开展重要栖息地恢复和废弃地修复。"},{"i":866,"n":"第八百六十六条","txt":"国家公园管理机构组织编制所管理国家公园的总体规划，明确保护和管理的目标任务、保护对象、保护措施等事项，并对拟开展的生态修复活动和原有居民生产生活活动等作出安排。"},{"i":867,"n":"第八百六十七条","txt":"设立国家公园后，国家公园所在地省、自治区、直辖市人民政府应当及时组织完成国家公园勘界；国家公园管理机构应当根据保护和管理需要及时设置界线标志。"},{"i":868,"n":"第八百六十八条","txt":"对国家公园、自然保护区内自然生态过程、保护对象生息繁衍具有明显季节性变化规律的区域，经科学论证，在不损害生态功能的前提下，可以实行季节性差别管控措施。"},{"i":869,"n":"第八百六十九条","txt":"在国家公园区域内开展经营性服务的，可以由国家公园管理机构以竞争性方式选择服务提供者。"},{"i":870,"n":"第八百七十条","txt":"长江、黄河、青藏高原等重要流域、区域生态环境保护及相关工作，应当坚持生态优先、绿色发展，因地制宜、分类施策，统筹协调、科学规划、创新驱动、系统治理。"},{"i":871,"n":"第八百七十一条","txt":"国家根据需要在长江、黄河、青藏高原等重要流域、区域建立协调机制，统筹指导、综合协调长江、黄河、青藏高原等重要流域、区域的生态环境保护等工作。"},{"i":872,"n":"第八百七十二条","txt":"国务院生态环境主管部门会同国务院发展改革、自然资源、水行政、农业农村等有关部门编制长江、黄河等重要流域生态环境保护规划。"},{"i":873,"n":"第八百七十三条","txt":"长江、黄河等重要流域产业结构和布局应当与流域生态环境的承载能力相适应。禁止在流域重点生态功能区布局对生态系统有严重影响的产业。"},{"i":874,"n":"第八百七十四条","txt":"国家加强长江、黄河等重要流域源头、重点水域、湖泊、库区消落区、河口生态的保护与修复，保护良好生态功能。"},{"i":875,"n":"第八百七十五条","txt":"国家推动建立长江、黄河等重要流域生态系统水生生物完整性指数评价体系，组织开展水生生物完整性评价，并将结果作为评估生态系统总体状况的重要依据。重要流域水生生物完整性指数应当与水生态环境质量标准相衔接。"},{"i":876,"n":"第八百七十六条","txt":"国家对长江流域江河湖泊岸线实施特殊管制，依照《中华人民共和国长江保护法》的规定划定江河湖泊岸线保护范围，制定江河湖泊岸线保护规划，严格控制岸线开发建设，促进岸线合理高效利用。"},{"i":877,"n":"第八百七十七条","txt":"国家对跨长江流域调水实行科学论证，加强控制和管理。实施跨长江流域调水应当优先保障调出区域及其下游区域的用水安全和生态安全，统筹调出区域和调入区域用水需求。"},{"i":878,"n":"第八百七十八条","txt":"黄河流域水资源利用，应当坚持节水优先、统筹兼顾、集约使用、精打细算，优先满足城乡居民生活用水，保障基本生态用水，统筹生产用水。"},{"i":879,"n":"第八百七十九条","txt":"国家依照《中华人民共和国黄河保护法》的规定，实行黄河流域水沙统一调度制度。水沙调控应当尽量减少对水生生物及其栖息地的影响。"},{"i":880,"n":"第八百八十条","txt":"国家加强对黄河流域水土流失重点预防区、治理区、重要支流源头区的水土流失防治和生态脆弱区域保护治理，开展土壤侵蚀和水土流失状况评估，实施重点防治工程。"},{"i":881,"n":"第八百八十一条","txt":"国家加强淮河、海河、珠江、松花江、辽河、洞庭湖、鄱阳湖、太湖、洪泽湖、巢湖等重要江河湖泊治理，巩固提升流域水源涵养、水土保持、生物多样性保护等生态功能，保障流域生态安全。"},{"i":882,"n":"第八百八十二条","txt":"国家依照《中华人民共和国青藏高原生态保护法》的规定，加强对青藏高原森林、草原、湿地、江河湖泊、荒漠、雪山冰川、高原冻土、泉域等生态系统的保护，巩固提升青藏高原内国家重点生态功能区的水源涵养、生物多样性保护、水土保持、防风固沙等生态功能。"},{"i":883,"n":"第八百八十三条","txt":"国家建立健全青藏高原生态风险防控体系，采取有效措施提高防治自然灾害、应对气候变化等生态风险防控能力和水平，保障青藏高原生态安全。"},{"i":884,"n":"第八百八十四条","txt":"国家建立健全青藏高原雪山冰川冻土保护制度，加强对雪山冰川冻土的监测预警和系统保护，对重要雪山冰川实施封禁保护，采取有效措施，严格控制人为扰动。"},{"i":885,"n":"第八百八十五条","txt":"海南岛全岛坚持生态优先、绿色发展，创新生态文明体制机制，持续优化生态环境质量和资源利用效率，加强生态环境损害责任追究。"},{"i":886,"n":"第八百八十六条","txt":"国家加强秦岭地区生态的保护与修复，巩固提升秦岭在气候调节、水土保持、水源涵养和生物多样性保护等方面的生态功能。"},{"i":887,"n":"第八百八十七条","txt":"国务院建立加强荒漠化综合防治和推进“三北”等重点生态工程建设协调机制，统筹协调解决重大问题，推动重点生态工程建设，推进重大政策实施。"},{"i":888,"n":"第八百八十八条","txt":"本法所称水土保持，是指对自然因素和人为活动造成水土流失所采取的预防和治理措施。"},{"i":889,"n":"第八百八十九条","txt":"水土保持工作实行预防为主、保护优先、全面规划、综合治理、因地制宜、突出重点、科学管理、注重效益的方针。"},{"i":890,"n":"第八百九十条","txt":"国务院水行政主管部门主管全国的水土保持工作。"},{"i":891,"n":"第八百九十一条","txt":"国家建立健全水土保持相关标准。国务院水行政主管部门、标准化主管部门组织制定并完善水土流失综合治理、生产建设项目水土保持、水土流失监测等国家标准。国家标准未作规定的，可以依法制定地方标准或者行业标准。"},{"i":892,"n":"第八百九十二条","txt":"国家在水土流失调查结果及水土流失重点预防区和重点治理区划定的基础上，编制水土保持规划。"},{"i":893,"n":"第八百九十三条","txt":"县级以上人民政府水行政主管部门应当加强水土保持监测工作，完善水土保持监测网络，定期组织水土流失调查并公告调查结果，发挥水土保持监测工作在政府决策、经济社会发展和社会公众服务中的作用。"},{"i":894,"n":"第八百九十四条","txt":"地方各级人民政府应当按照水土保持规划，采取封育保护、自然修复、重点治理等措施，组织单位和个人植树种草，扩大林草覆盖面积，涵养水源，加强对取土、挖砂、采石等活动的管理，预防和减轻水土流失。"},{"i":895,"n":"第八百九十五条","txt":"国家按照国土空间规划和用途管控要求，建立水土保持空间管控制度，落实差别化保护治理措施。"},{"i":896,"n":"第八百九十六条","txt":"林木采伐应当采用合理方式，严格控制皆伐；对水源涵养林、水土保持林、防风固沙林等防护林只能进行抚育和更新性质的采伐；对采伐区和集材道应当采取防止水土流失的措施，并在采伐后及时更新造林。"},{"i":897,"n":"第八百九十七条","txt":"县级以上人民政府水行政主管部门应当加强对地表扰动、土石方开挖等人为活动的管理，严格管控因人为活动造成的水土流失。"},{"i":898,"n":"第八百九十八条","txt":"依法应当编制水土保持方案的生产建设项目中的水土保持设施，应当与主体工程同时设计、同时施工、同时投产使用；生产建设项目竣工验收，应当验收水土保持设施；水土保持设施未经验收或者验收不合格的，生产建设项目不得投产使用。"},{"i":899,"n":"第八百九十九条","txt":"国家加强水土流失重点预防区和重点治理区的小流域综合治理提质增效、坡耕地改梯田、淤地坝、侵蚀沟治理、崩岗治理、固沟保塬等水土保持重点工程建设，加大生态修复力度。"},{"i":900,"n":"第九百条","txt":"国家鼓励、支持承包治理荒山、荒沟、荒丘、荒滩，防治水土流失，保护和改善生态环境，促进土地资源的合理开发和可持续利用。"},{"i":901,"n":"第九百零一条","txt":"在水力侵蚀地区，以流域水系为单元一体化推进小流域综合治理，开展坡耕地和沟道水土流失综合整治，因地制宜采取工程措施和植物措施，加强坡耕地改梯田、淤地坝等工程建设，统筹推进保护性耕作和高标准农田建设，完善田间道路、坡面水系等配套设施；建设生态清洁小流域，提供更多更优蕴含水土保持功能的生态产品。"},{"i":902,"n":"第九百零二条","txt":"在饮用水水源保护区，地方人民政府及其有关部门应当组织单位和个人，采取预防保护、自然修复和综合治理措施，配套建设植物过滤带，开展生态清洁小流域建设，严格控制化肥和农药的使用，减少水土流失引起的面源污染，保护饮用水水源。"},{"i":903,"n":"第九百零三条","txt":"已在禁止开垦的陡坡地上开垦种植农作物的，应当按照国家规定进行生态修复；耕地短缺、退耕确有困难的，应当修建梯田或者采取其他水土保持措施。"},{"i":904,"n":"第九百零四条","txt":"对生产建设活动所占用土地的地表土应当进行分层剥离、保存和利用，做到土石方挖填平衡，减少地表扰动范围。依法应当编制水土保持方案的生产建设项目，应当综合利用其排弃的砂、石、土、矸石、尾矿、废渣等；确需废弃的，应当堆放在水土保持方案确定的存放地，并采取拦挡、坡面防护、防洪排导等措施。生产建设活动结束后，应当及时在取土场、开挖面和存放地的裸露土地上植树种草、恢复植被。"},{"i":905,"n":"第九百零五条","txt":"国家鼓励、支持在山区、丘陵区、风沙区以及容易发生水土流失的其他区域，采取下列有利于水土保持的措施："},{"i":906,"n":"第九百零六条","txt":"本法所称土地沙化，是指主要因人类不合理活动所导致的天然沙漠扩张和沙质土壤上植被及覆盖物被破坏，形成流沙及沙土裸露的过程。"},{"i":907,"n":"第九百零七条","txt":"防沙治沙坚持预防为主、防治结合、合理利用、统一规划、因地制宜、因害设防、分类施策的原则。"},{"i":908,"n":"第九百零八条","txt":"国务院林业草原主管部门负责组织、协调、指导全国防沙治沙工作。"},{"i":909,"n":"第九百零九条","txt":"国务院林业草原主管部门会同有关部门依照《中华人民共和国防沙治沙法》的规定编制全国防沙治沙规划。县级以上地方人民政府可以根据实际需要，组织编制本行政区域的防沙治沙规划。"},{"i":910,"n":"第九百一十条","txt":"国家加强荒漠化综合防治，积极推进防沙治沙，重点开展沙漠边缘、沙源区和路径区生态修复，加强自然生态空间管控以及沙生植物保护，推行保护性耕作措施，实施防护林建设等生态工程，在岩溶地区开展石漠化综合治理。"},{"i":911,"n":"第九百一十一条","txt":"沙化土地所在地区的县级以上地方人民政府应当按照防沙治沙规划，划出一定比例的土地，因地制宜营造防风固沙林网、林带，种植多年生灌木和草本植物。"},{"i":912,"n":"第九百一十二条","txt":"禁止在沙化土地上砍挖灌木、药材及其他固沙植物，法律、行政法规另有规定的除外。"},{"i":913,"n":"第九百一十三条","txt":"沙化土地所在地区的县级以上地方人民政府水行政主管部门，应当加强流域和区域水资源的统一调配和管理，防止因地下水和上游水资源的过度开发利用，导致植被破坏和土地沙化。"},{"i":914,"n":"第九百一十四条","txt":"国家建立沙化土地封禁保护区制度。对暂不具备治理条件的连片沙化土地，应当规划为沙化土地封禁保护区。"},{"i":915,"n":"第九百一十五条","txt":"沙化土地所在地区的地方各级人民政府，应当按照防沙治沙规划，组织有关部门、单位和个人，因地制宜采取工程措施、生物措施和合理调配生态用水等措施，恢复和增加植被，防止土地沙化，治理已经沙化的土地。"},{"i":916,"n":"第九百一十六条","txt":"国家鼓励单位和个人在自愿的前提下，捐资或者以其他形式开展公益性的治沙活动。"},{"i":917,"n":"第九百一十七条","txt":"使用已经沙化的国有土地的使用权人和农民集体所有土地的承包经营权人，应当采取治理措施，改善土地质量。"},{"i":918,"n":"第九百一十八条","txt":"在沙化土地范围内从事种植、养殖、旅游、风电、光伏发电等生产经营活动，应当采取措施防止土地沙化。"},{"i":919,"n":"第九百一十九条","txt":"沙化土地所在地区的地方各级人民政府，可以组织当地农村集体经济组织及其成员在自愿的前提下，对已经沙化的土地进行集中治理。"},{"i":920,"n":"第九百二十条","txt":"各级人民政府及有关部门开展生态修复活动，以及依法承担生态修复责任的单位和个人开展生态修复活动，应当遵守本章的有关规定。"},{"i":921,"n":"第九百二十一条","txt":"生态修复应当建立健全源头保护和全过程修复治理相结合的工作机制，实现整体保护、系统修复、综合治理。"},{"i":922,"n":"第九百二十二条","txt":"国务院自然资源主管部门应当会同有关部门组织实施重大生态修复项目，统筹重点流域和重要区域生态的保护与修复工作。"},{"i":923,"n":"第九百二十三条","txt":"县级以上人民政府自然资源主管部门会同有关部门依法编制国土空间生态修复规划。"},{"i":924,"n":"第九百二十四条","txt":"编制生态修复规划、设计项目方案，应当充分征求有关方面的意见、科学论证，确定生态修复的目标、内容、实施方案、修复技术措施等。"},{"i":925,"n":"第九百二十五条","txt":"国务院自然资源、生态环境主管部门会同有关部门对重大生态修复项目的实施开展动态监测。"},{"i":926,"n":"第九百二十六条","txt":"国务院有关部门在各自职责范围内建立健全生态修复实施过程的监督机制，对重大生态修复项目进行跟踪检查。"},{"i":927,"n":"第九百二十七条","txt":"生态修复项目竣工后，县级以上人民政府有关部门在各自职责范围内针对各类生态修复项目的不同特点，组织开展生态修复项目的验收。"},{"i":928,"n":"第九百二十八条","txt":"国家实施生态修复项目后期管护制度。"},{"i":929,"n":"第九百二十九条","txt":"国家鼓励、支持生态修复的科学技术研究开发和推广应用，提升生态修复领域自主创新能力，提升生态修复科学化、专业化水平。"},{"i":930,"n":"第九百三十条","txt":"国家坚持政策支持、企业和社会参与、市场化运作，采取有效措施鼓励社会资本参与生态修复项目投资、设计、修复、管护等全过程活动。"},{"i":931,"n":"第九百三十一条","txt":"各级人民政府应当科学保护和修复森林生态系统，加强生态脆弱地区森林生态系统的保护与修复。新造幼林地和其他应当封山育林的地方，由当地人民政府组织封山育林。"},{"i":932,"n":"第九百三十二条","txt":"国家加强生态脆弱草原保护。对退化、沙化、盐碱化、石漠化和水土流失的草原，地方各级人民政府应当按照草原保护修复利用规划，组织生态的保护与修复，提高生态系统稳定性。"},{"i":933,"n":"第九百三十三条","txt":"县级以上人民政府应当坚持系统治理，加强湿地修复工作，恢复湿地面积，提高湿地生态系统质量。"},{"i":934,"n":"第九百三十四条","txt":"对遭到破坏的具有重要生态、经济、社会价值的海洋生态系统，应当进行修复。海洋生态修复应当以改善动植物栖息生长环境、恢复生物多样性和生态系统基本功能为重点，以自然恢复为主、人工修复为辅，并优先修复具有典型性、代表性的海洋生态系统。"},{"i":935,"n":"第九百三十五条","txt":"县级以上人民政府应当加强对生态恶化江河湖泊的治理和修复，统筹运用生态补水、生物净化、生态清淤、江河湖泊连通等措施，对江河湖泊生态系统进行综合治理，改善和恢复江河湖泊生态系统。"},{"i":936,"n":"第九百三十六条","txt":"开采矿产资源前，采矿权人应当依法编制矿区生态修复方案。采矿权人应当按照经批准的矿区生态修复方案进行矿区生态修复。"},{"i":937,"n":"第九百三十七条","txt":"国家建立健全生态修复成效评估机制，制定和完善生态修复效果的评估标准、技术指南等。"},{"i":938,"n":"第九百三十八条","txt":"本编适用于发展循环经济、能源节约与绿色低碳转型、应对气候变化等绿色低碳发展相关活动。"},{"i":939,"n":"第九百三十九条","txt":"国家建立健全绿色低碳发展机制，完善绿色低碳转型政策体系，加快经济社会发展全面绿色转型，形成有利于节约资源和保护生态环境的空间格局、产业结构、生产方式、生活方式。"},{"i":940,"n":"第九百四十条","txt":"国家采取有效措施推动各类资源节约集约循环利用，促进生产、流通、消费过程中减少污染物和温室气体的产生、排放，提高资源利用效率，建设绿色低碳循环发展经济体系。"},{"i":941,"n":"第九百四十一条","txt":"国家推进节能降碳增效，加强化石能源清洁高效利用和安全可靠有序替代，大力发展非化石能源，稳妥推进能源绿色低碳转型，加快建设清洁低碳安全高效的新型能源体系，建设能源强国。"},{"i":942,"n":"第九百四十二条","txt":"国家采取积极应对气候变化的政策和措施，控制和减少温室气体排放，积极稳妥推进碳达峰碳中和，增强适应气候变化能力，提高全社会的应对气候变化意识。"},{"i":943,"n":"第九百四十三条","txt":"国家强化区域重大战略实施中的绿色低碳发展导向和任务要求，构建绿色低碳高质量发展空间格局。"},{"i":944,"n":"第九百四十四条","txt":"国家推动钢铁、有色金属、石化、化工、建材、造纸、印染等行业绿色低碳转型，推广节能低碳和清洁生产技术装备，推进工艺流程更新升级，完善能源效率、碳排放等相关约束性标准，促进传统产业优化升级。"},{"i":945,"n":"第九百四十五条","txt":"国家优化交通运输结构，完善交通运输网络，推动铁路、公路、水运、航空不同运输方式合理分工、有效衔接，构建绿色高效交通运输体系。"},{"i":946,"n":"第九百四十六条","txt":"国家倡导绿色低碳规划设计理念，推广绿色建造方式，优化建筑用能结构，支持超低能耗、低碳建筑规模化发展，推动绿色低碳和气候适应型城市建设。"},{"i":947,"n":"第九百四十七条","txt":"国家推动农业农村绿色低碳发展，加快绿色技术推广应用，引导农业生产经营者科学合理使用生产资料，加强农业废弃物资源化利用，优先发展生态农业。"},{"i":948,"n":"第九百四十八条","txt":"国家建立健全绿色低碳标准体系。"},{"i":949,"n":"第九百四十九条","txt":"国家机关和其他使用财政性资金的公共机构应当率先贯彻绿色低碳理念，厉行节约、反对浪费，推进绿色办公、绿色采购，使用绿色低碳产品，发挥绿色低碳转型示范引领作用。"},{"i":950,"n":"第九百五十条","txt":"国家优化绿色转型投资机制，加大对绿色低碳先进适用技术示范、重点行业节能降碳、资源高效循环利用等领域重点项目的财政投入，引导和规范社会资本参与绿色低碳项目投资、建设、运营，鼓励社会资本以市场化方式设立绿色低碳产业投资基金。"},{"i":951,"n":"第九百五十一条","txt":"国家加强绿色低碳领域应用基础研究，鼓励、支持资源节约与循环利用、能源绿色低碳转型、减缓和适应气候变化相关技术研究开发，加快先进适用技术示范和推广应用。"},{"i":952,"n":"第九百五十二条","txt":"国家加强绿色经贸、技术、金融、标准等领域国际合作，鼓励绿色低碳技术、产品和服务进出口，积极参与国际规则和标准制定，引领全球绿色转型。"},{"i":953,"n":"第九百五十三条","txt":"发展循环经济应当坚持减量化、再利用、资源化，遵循统筹规划、合理布局，因地制宜、注重实效，政府推动、市场引导，企业实施、公众参与的方针。"},{"i":954,"n":"第九百五十四条","txt":"国务院发展改革部门负责组织协调、监督管理全国的循环经济发展工作；国务院生态环境、工业和信息化、住房城乡建设等有关部门在各自职责范围内，负责有关循环经济的监督管理工作。"},{"i":955,"n":"第九百五十五条","txt":"国务院发展改革部门会同国务院生态环境等有关部门编制全国循环经济发展规划，报国务院批准后公布实施。"},{"i":956,"n":"第九百五十六条","txt":"国家制定产业政策，应当符合发展循环经济的要求。"},{"i":957,"n":"第九百五十七条","txt":"国务院标准化主管部门会同国务院发展改革、生态环境、工业和信息化等有关部门制定绿色设计、绿色制造、产业废弃物综合利用、生活垃圾回收利用等循环经济标准。"},{"i":958,"n":"第九百五十八条","txt":"国家建立健全循环经济统计制度，加强资源消耗、综合利用、废弃物产生等的统计管理，并将主要统计指标定期向社会公布。"},{"i":959,"n":"第九百五十九条","txt":"国家建立健全生产者责任延伸制度，促进资源循环利用。"},{"i":960,"n":"第九百六十条","txt":"国家鼓励通过开展绿色设计、使用清洁的能源和原料、采用先进适用的工艺技术与设备等措施，从源头降低资源消耗，减少污染物和温室气体的产生、排放，推进清洁生产。"},{"i":961,"n":"第九百六十一条","txt":"国务院发展改革部门会同国务院生态环境、工业和信息化等有关部门编制全国清洁生产推行方案，报国务院批准后公布。全国清洁生产推行方案应当包括推进清洁生产的目标、主要任务和保障措施，确定开展清洁生产的重点领域、重点行业和重点工程。"},{"i":962,"n":"第九百六十二条","txt":"中央预算应当加强对清洁生产推进工作的资金投入，包括中央财政清洁生产专项资金和中央预算安排的其他清洁生产资金，用于支持全国清洁生产推行方案确定的重点领域、重点行业、重点工程实施清洁生产及其技术推广工作，以及生态脆弱地区实施清洁生产的项目。中央预算用于支持清洁生产推进工作的资金使用的具体办法，由国务院财政、发展改革部门会同有关部门制定。"},{"i":963,"n":"第九百六十三条","txt":"国务院发展改革部门会同国务院生态环境、工业和信息化、科学技术、住房城乡建设、农业农村、林业草原等有关部门定期发布清洁生产技术、工艺、设备和产品导向目录。"},{"i":964,"n":"第九百六十四条","txt":"省级以上人民政府发展改革、生态环境、工业和信息化部门会同有关部门，组织编制重点行业或者地区的清洁生产指南，指导实施清洁生产。"},{"i":965,"n":"第九百六十五条","txt":"企业在进行技术改造过程中，应当采取以下清洁生产措施："},{"i":966,"n":"第九百六十六条","txt":"企业应当对生产和服务过程中的资源消耗以及废弃物的产生情况进行监测，并根据需要对生产和服务实施清洁生产审核。"},{"i":967,"n":"第九百六十七条","txt":"有下列情形之一的企业，应当实施强制性清洁生产审核："},{"i":968,"n":"第九百六十八条","txt":"本法第九百六十七条第一款规定以外的企业可以按照国家规定，自愿与发展改革、生态环境、工业和信息化部门签订节约资源、减少污染物排放的协议。发展改革、生态环境、工业和信息化部门应当采取便于公众知晓的方式，公布企业的名称和节约资源、防治污染的成果。"},{"i":969,"n":"第九百六十九条","txt":"生产大型机电设备、机动运输工具以及国务院工业和信息化主管部门指定的其他产品的企业，应当按照国务院标准化主管部门或者其授权机构制定的技术规范，在产品的主体构件上注明材料成分的标准牌号。"},{"i":970,"n":"第九百七十条","txt":"国务院和省、自治区、直辖市人民政府的有关部门，应当组织和支持建立清洁生产信息系统和技术咨询服务体系。"},{"i":971,"n":"第九百七十一条","txt":"企业用于清洁生产审核和培训的费用，可以列入企业经营成本。"},{"i":972,"n":"第九百七十二条","txt":"国家鼓励产品的生产经营者开展绿色设计，推动绿色设计应用。"},{"i":973,"n":"第九百七十三条","txt":"国家鼓励产品的生产经营者使用绿色包装、减量包装。"},{"i":974,"n":"第九百七十四条","txt":"电子商务、快递、外卖等行业应当减少包装物的使用，优先采用可重复使用、易回收利用的包装物，并积极回收利用。县级以上地方人民政府商务、邮政管理等有关部门应当加强监督管理。"},{"i":975,"n":"第九百七十五条","txt":"国家推进废弃物循环利用体系建设，促进生产生活各领域废弃物精细管理、有效回收、高效利用，提升废弃物循环利用水平。"},{"i":976,"n":"第九百七十六条","txt":"企业应当采用先进适用的回收技术、工艺和设备，对生产过程中产生的余热、余压、废水、废液等进行综合利用。"},{"i":977,"n":"第九百七十七条","txt":"生产、进口、销售依法列入强制回收名录的产品和包装物的企业，应当按照国家规定对该产品和包装物进行回收。对其中可以利用的，由企业负责利用；对因不具备技术经济条件而不适合利用的，由企业负责无害化处置。"},{"i":978,"n":"第九百七十八条","txt":"电器电子、机动车、铅蓄电池、动力电池等产品的生产者应当按照国家规定，以自建或者委托等方式建立与产品销售量相匹配的废旧产品回收体系，并向社会公开，履行回收和利用责任。"},{"i":979,"n":"第九百七十九条","txt":"国家建立健全风电和光伏发电退役设备处理责任制度。"},{"i":980,"n":"第九百八十条","txt":"国家支持生产经营者建立产业废弃物交换信息系统，促进企业交流产业废弃物信息。"},{"i":981,"n":"第九百八十一条","txt":"国家鼓励、支持农业生产经营者和相关企业采用先进适用技术，对农作物秸秆、畜禽粪便、农产品加工业副产品、废农用薄膜等进行综合利用。"},{"i":982,"n":"第九百八十二条","txt":"国家鼓励采用先进适用技术、工艺、设备、材料和管理措施，推进建筑垃圾源头减量，建立健全建筑垃圾回收利用体系。"},{"i":983,"n":"第九百八十三条","txt":"国家加强生活垃圾分类收集、处理和资源化利用，推进生活垃圾减量化、资源化。"},{"i":984,"n":"第九百八十四条","txt":"国家推进生活垃圾分类网点和废旧物资回收网点融合建设，完善城乡废旧物资回收网络。"},{"i":985,"n":"第九百八十五条","txt":"国家完善低值可回收物目录，促进废玻璃、废塑料、废旧纺织品等回收利用。"},{"i":986,"n":"第九百八十六条","txt":"国家加强废钢铁、废有色金属等高效利用，推动再生金属加工利用产业集聚化发展。"},{"i":987,"n":"第九百八十七条","txt":"企业利用废弃物和从废弃物中回收原料生产产品，应当采用先进适用的技术、工艺和设备，提高回收利用率和加工利用水平。"},{"i":988,"n":"第九百八十八条","txt":"国家对废弃电器电子产品等实行多渠道回收和集中处理制度。废弃电器电子产品等回收处理的具体管理办法由国务院制定。"},{"i":989,"n":"第九百八十九条","txt":"国家支持企业开展机动车零部件、工程机械、机床、文化办公设备等产品的再制造和轮胎翻新，推动风电、光伏发电、航空等领域高端装备再制造产业发展，鼓励再制造产品推广使用。"},{"i":990,"n":"第九百九十条","txt":"国家鼓励再生材料推广应用，建立健全再生材料标准和认证制度，支持机动车、电器电子等产品的生产者提高再生材料使用比例。"},{"i":991,"n":"第九百九十一条","txt":"依法利用废弃物和从废弃物中回收原料生产产品的，按照国家规定享受税收等优惠。"},{"i":992,"n":"第九百九十二条","txt":"国家建立健全绿色消费激励机制，扩大绿色低碳产品供给，加强绿色消费宣传教育，推广绿色低碳生活方式，推动消费模式绿色转型。"},{"i":993,"n":"第九百九十三条","txt":"国家实行有利于资源节约和合理利用的价格、税收等政策，引导单位和个人节约和合理使用水、电、气等资源性产品。"},{"i":994,"n":"第九百九十四条","txt":"国家建立健全政府绿色采购制度，鼓励、支持将再生材料和产品纳入政府绿色采购范围。"},{"i":995,"n":"第九百九十五条","txt":"国家鼓励、支持二手商品流通交易，推动二手商品交易市场和平台建设。二手商品流通管理办法由国务院商务部门会同有关部门制定。"},{"i":996,"n":"第九百九十六条","txt":"国家鼓励、引导消费者使用绿色包装、减量包装。"},{"i":997,"n":"第九百九十七条","txt":"国家在保障产品安全和卫生的前提下，限制一次性用品的生产和销售。"},{"i":998,"n":"第九百九十八条","txt":"国家依法禁止和限制生产、销售、使用不可降解塑料袋等一次性塑料制品，鼓励、引导减少使用和积极回收一次性塑料制品，推广应用可循环、易回收、可降解且无害的替代产品。"},{"i":999,"n":"第九百九十九条","txt":"公民应当增强绿色消费意识，养成绿色消费习惯，积极购买和使用绿色低碳产品，主动减少使用一次性用品、一次性塑料制品，自觉抵制过度包装。"},{"i":1000,"n":"第一千条","txt":"企业应当按照国家规定实施绿色采购，建立绿色供应链，优先采购和使用节能、节水、节材等有利于保护生态环境的原材料、产品和服务，促进上下游企业协同绿色转型。"},{"i":1001,"n":"第一千零一条","txt":"餐饮、娱乐、宾馆等服务性企业应当按照国家规定，采用节能、节水、节材等有利于保护生态环境的技术、设备和设施，提供绿色低碳产品，减少使用或者不使用浪费资源、污染环境的消费品。"},{"i":1002,"n":"第一千零二条","txt":"能源绿色低碳发展应当坚持节约优先、集约高效、创新驱动、保障安全、有序转型的原则。"},{"i":1003,"n":"第一千零三条","txt":"国家完善能源开发利用政策，优化能源供应结构和消费结构，积极推动能源绿色低碳发展。"},{"i":1004,"n":"第一千零四条","txt":"国家推动节约能源和提高能源利用效率，鼓励发展分布式能源和多能互补、多能联供综合能源服务，积极推广合同能源管理等市场化节约能源服务，通过完善阶梯价格、分时价格等制度，引导能源用户合理调整用能方式、时间、数量等，提高终端能源消费清洁化、低碳化、高效化、智能化水平。"},{"i":1005,"n":"第一千零五条","txt":"国家鼓励、支持化石能源清洁高效开发利用、可再生能源开发利用、核能安全利用以及储能、节约能源等能源绿色低碳发展相关领域基础性、关键性和前沿性重大技术、装备及相关新材料的研究开发、推广应用和产业化发展。能源绿色低碳科技创新应当纳入国家科技发展和高技术产业发展相关规划的重点支持领域。"},{"i":1006,"n":"第一千零六条","txt":"县级以上人民政府应当加强农业农村节能工作，增加对农业农村节能技术、节能产品推广应用的资金投入。"},{"i":1007,"n":"第一千零七条","txt":"国务院发展改革部门负责全国的节能监督管理工作。国务院有关部门在各自职责范围内负责节能监督管理工作，并接受国务院发展改革部门的指导。"},{"i":1008,"n":"第一千零八条","txt":"国务院标准化主管部门和国务院有关部门依法组织制定并适时修订有关节能的国家标准、行业标准。"},{"i":1009,"n":"第一千零九条","txt":"国家实行固定资产投资项目节能审查制度，对项目用能和碳排放情况开展综合评价。具体办法由国务院发展改革部门会同有关部门制定。"},{"i":1010,"n":"第一千零一十条","txt":"县级以上人民政府节能主管部门应当会同有关部门加强对重点用能单位的节能管理。"},{"i":1011,"n":"第一千零一十一条","txt":"国家对家用电器等使用面广、耗能量大的用能产品，实行能源效率标识管理。能源效率标识管理的产品目录和具体管理办法，由国务院发展改革部门会同国务院市场监督管理部门制定并公布。"},{"i":1012,"n":"第一千零一十二条","txt":"国家支持优先开发利用可再生能源，合理开发、清洁高效利用化石能源，推进非化石能源安全可靠有序替代化石能源，提高非化石能源消费比重。"},{"i":1013,"n":"第一千零一十三条","txt":"国务院能源主管部门和国务院有关部门依照本法和《中华人民共和国能源法》、《中华人民共和国可再生能源法》等法律的规定，负责能源绿色低碳转型有关工作。"},{"i":1014,"n":"第一千零一十四条","txt":"国家建立健全煤炭清洁高效利用机制，支持洁净煤技术的研究开发、推广应用，积极有序推进散煤替代，推动煤炭清洁高效燃烧和转化，促进煤炭分质分级利用，提升煤炭清洁高效利用水平。"},{"i":1015,"n":"第一千零一十五条","txt":"国家鼓励、支持煤炭绿色智能开采，因地制宜采用保水开采、充填开采等绿色开采技术，减少对地质地貌和生态环境的影响。"},{"i":1016,"n":"第一千零一十六条","txt":"国家鼓励石油、天然气绿色高效开发，支持石油、天然气勘探开发与可再生能源融合发展。"},{"i":1017,"n":"第一千零一十七条","txt":"国家推进风能、太阳能开发利用，坚持集中式与分布式并举，加快风电和光伏发电基地建设，支持分布式风电和光伏发电就近开发利用，合理有序开发海上风电，积极发展光热发电。"},{"i":1018,"n":"第一千零一十八条","txt":"国务院能源主管部门会同有关部门制定非化石能源开发利用中长期发展目标，按年度监测非化石能源开发利用情况，并向社会公布。"},{"i":1019,"n":"第一千零一十九条","txt":"国务院能源主管部门会同有关部门制定并组织实施可再生能源在能源消费中的最低比重目标。"},{"i":1020,"n":"第一千零二十条","txt":"国家完善可再生能源电力消纳保障机制。供电企业、售电企业、相关电力用户和使用自备电厂供电的企业等应当按照国家规定，承担消纳可再生能源发电量的责任。"},{"i":1021,"n":"第一千零二十一条","txt":"国家建立健全绿色能源消费促进机制，实施可再生能源绿色电力证书等制度，鼓励能源用户优先使用可再生能源等清洁低碳能源。"},{"i":1022,"n":"第一千零二十二条","txt":"国家加快构建新型电力系统，加强电源电网协同建设，优化电力跨区域通道布局，发挥特高压输电通道稳定安全可靠作用，推进电网基础设施智能化改造和智能微电网建设，提高电网对可再生能源的接纳、配置和调控能力。"},{"i":1023,"n":"第一千零二十三条","txt":"国家合理布局、积极有序开发建设抽水蓄能电站，推进新型储能高质量发展，发挥各类储能在电力系统中的调节作用。"},{"i":1024,"n":"第一千零二十四条","txt":"国家积极有序推进氢能开发利用，促进氢能产业高质量发展。"},{"i":1025,"n":"第一千零二十五条","txt":"国家坚持减缓与适应并重，采取有效措施积极应对气候变化。"},{"i":1026,"n":"第一千零二十六条","txt":"国务院生态环境主管部门负责全国的应对气候变化工作。国务院发展改革部门负责全国碳达峰碳中和工作的管理协调。国务院其他有关部门在各自职责范围内，负责应对气候变化与碳达峰碳中和有关工作。"},{"i":1027,"n":"第一千零二十七条","txt":"国家建立健全国务院有关部门参与的决策协调机制，统一部署应对气候变化与碳达峰碳中和有关工作，协调解决相关重大问题，督促重要目标任务落实。"},{"i":1028,"n":"第一千零二十八条","txt":"国家加强温室气体与气候系统监测，建立健全气候变化监测发布制度。"},{"i":1029,"n":"第一千零二十九条","txt":"国家建立应对气候变化信息共享机制，推动相关资源、数据交流共享。"},{"i":1030,"n":"第一千零三十条","txt":"国家通过加强生态系统保护、修复和可持续管理，发挥生态系统服务功能，增强应对气候变化的能力。"},{"i":1031,"n":"第一千零三十一条","txt":"国家强化应对气候变化基础研究和科技支撑，把应对气候变化作为国家基础研究和科技创新的重点领域，加强关键核心技术研究开发、推广应用。"},{"i":1032,"n":"第一千零三十二条","txt":"国家将碳达峰碳中和目标要求全面融入国家发展规划，通过碳达峰碳中和目标推动减缓气候变化。"},{"i":1033,"n":"第一千零三十三条","txt":"推进碳达峰碳中和应当坚持全国统筹、节约优先、双轮驱动、内外通畅、防范风险的原则。"},{"i":1034,"n":"第一千零三十四条","txt":"国务院发展改革部门会同有关部门编制国家碳达峰碳中和行动方案并组织实施。省、自治区、直辖市人民政府结合实际情况，制定本行政区域碳达峰碳中和行动方案并组织实施。"},{"i":1035,"n":"第一千零三十五条","txt":"国家建立健全碳排放统计核算制度。"},{"i":1036,"n":"第一千零三十六条","txt":"国务院生态环境、市场监督管理、发展改革等有关部门在各自职责范围内开展产品碳足迹管理，制定产品碳足迹核算标准和技术规范，建立产品碳足迹核算、分级管理、标识认证和信息披露制度。"},{"i":1037,"n":"第一千零三十七条","txt":"国家建立全国碳排放权交易市场。纳入全国碳排放权交易市场的温室气体重点排放单位，应当按照国家规定履行强制减排责任。"},{"i":1038,"n":"第一千零三十八条","txt":"国家建立全国温室气体自愿减排交易市场，鼓励温室气体自愿减排交易。"},{"i":1039,"n":"第一千零三十九条","txt":"国务院生态环境主管部门负责碳排放权交易、温室气体自愿减排交易及相关活动的监督管理。国务院有关部门在各自职责范围内，负责碳排放权交易、温室气体自愿减排交易及相关活动的监督管理。"},{"i":1040,"n":"第一千零四十条","txt":"国家建立健全生态系统碳汇监测核算体系，开展森林、草原、湿地、海洋、土壤等碳储量本底调查和评估，加强生态的保护与修复，巩固和提升生态系统碳汇能力。"},{"i":1041,"n":"第一千零四十一条","txt":"国家制定实施适应气候变化战略，坚持预防为主、科学适应，采取有效措施降低气候变化不利影响和风险，建设气候适应型社会。"},{"i":1042,"n":"第一千零四十二条","txt":"国家根据不同区域特点开展区域适应气候变化行动，提升重大战略区域适应气候变化的能力。"},{"i":1043,"n":"第一千零四十三条","txt":"编制国土空间规划应当充分考虑气候变化的影响和风险，加强对气候资源条件、气候变化影响和风险的评估。"},{"i":1044,"n":"第一千零四十四条","txt":"国务院有关部门在各自职责范围内，加强对水、陆地、海洋等生态系统，以及农业与粮食安全、健康与公共卫生、基础设施与重大工程、城市与人居环境、气候变化敏感产业、文化遗产等经济社会重点领域的气候变化影响和风险评估，提升重点领域适应气候变化的能力。"},{"i":1045,"n":"第一千零四十五条","txt":"国家建立健全气候变化影响下灾害综合风险监测预警和评估制度，提升多灾种、灾害链风险综合预警和评估能力。"},{"i":1046,"n":"第一千零四十六条","txt":"国家加强对极端天气气候事件引发的自然灾害综合治理，采取有效措施改善城乡防灾基础条件，优化重大基础设施空间布局，强化应急指挥处置、抢险队伍建设，加强应急装备物资储备，提升极端天气气候事件下综合救援和公众安全保障能力。"},{"i":1047,"n":"第一千零四十七条","txt":"国家鼓励开展气候变化健康风险和适应能力评估，加强气候敏感疾病的监测预警和防控，推进气候变化健康适应行动，提高气候变化和极端天气气候事件下公众健康适应水平。"},{"i":1048,"n":"第一千零四十八条","txt":"国家坚持共同但有区别的责任原则、公平原则、各自能力原则，积极参与和引领全球气候治理，推动构建公平合理、合作共赢的全球气候治理体系。"},{"i":1049,"n":"第一千零四十九条","txt":"国家根据国情、发展阶段和实际能力，承担应对气候变化领域相应的国际义务。"},{"i":1050,"n":"第一千零五十条","txt":"国务院有关部门在各自职责范围内开展应对气候变化多边、双边国际交流与合作，推动应对气候变化领域规则和标准衔接互认。"},{"i":1051,"n":"第一千零五十一条","txt":"国家加强应对气候变化领域的国际科学技术合作与交流，支持国内外优秀科学技术人才合作研究开发，鼓励企业、高等学校、科研机构开展可再生能源、储能、氢能、碳捕集利用与封存等技术交流。"},{"i":1052,"n":"第一千零五十二条","txt":"任何单位和个人有污染环境、破坏生态和违反绿色低碳义务的行为的，应当严格依法追究其法律责任。"},{"i":1053,"n":"第一千零五十三条","txt":"实施污染环境、破坏生态等违法行为的，除有证据足以证明其没有过错外，应当承担行政责任。"},{"i":1054,"n":"第一千零五十四条","txt":"造成环境污染、生态破坏等危害后果的违法行为在五年内被发现的，应当依法给予行政处罚；其他违法行为在二年内被发现的，应当依法给予行政处罚。上述期限自违法行为发生之日起计算，违法行为有连续或者继续状态的，从行为终了之日起计算。"},{"i":1055,"n":"第一千零五十五条","txt":"同一个违法行为违反多个生态环境法律规范应当给予罚款处罚的，按照罚款数额高的规定处罚。"},{"i":1056,"n":"第一千零五十六条","txt":"实施污染环境、破坏生态等违法行为，有恶意损害生态环境、拒不改正违法行为、造成严重危害后果、多次实施违法行为被处罚等法定情形的，依法从重处罚。"},{"i":1057,"n":"第一千零五十七条","txt":"实施行政处罚，适用违法行为发生时的生态环境法律、法规、规章的规定。但是，作出行政处罚决定时，生态环境法律、法规、规章已被修改或者废止，且新的规定处罚较轻或者不认为是违法的，适用新的规定。"},{"i":1058,"n":"第一千零五十八条","txt":"因污染环境、破坏生态等行为应当承担民事责任、行政责任、刑事责任的，承担行政责任或者刑事责任不影响承担民事责任。财产不足以支付的，优先承担民事责任。"},{"i":1059,"n":"第一千零五十九条","txt":"由于不可抗力造成污染环境、破坏生态损害的，不承担赔偿责任；法律另有规定的除外。对海洋环境造成污染损害的，适用本条第三款规定。"},{"i":1060,"n":"第一千零六十条","txt":"企业事业单位和其他生产经营者违法排放、倾倒、处置污染物、废弃物或者其他物质，受到罚款处罚，被责令改正的，依法作出处罚决定的部门或者机构应当组织复查，发现其继续实施该违法行为、拒不改正或者拒绝、阻挠复查的，可以自责令改正之日的次日起，按照原罚款数额按日连续处罚，并及时采取措施制止违法行为。"},{"i":1061,"n":"第一千零六十一条","txt":"地方人民政府不依法履行职责，致使本地区生态环境质量问题突出、生态环境状况恶化的，应当对其负责人依法给予处分或者处理，并可以向社会公开。"},{"i":1062,"n":"第一千零六十二条","txt":"地方各级人民政府、负有生态环境保护监督管理职责的部门、机构有下列情形之一的，对负有责任的领导人员和直接责任人员给予记过、记大过或者降级处分；造成严重后果的，给予撤职或者开除处分："},{"i":1063,"n":"第一千零六十三条","txt":"规划编制机关未依法组织生态环境影响评价，或者组织生态环境影响评价时弄虚作假或者有失职行为，造成生态环境影响评价严重失实的；规划审批机关对依法应当编写有关生态环境影响的篇章或者说明而未编写的规划草案，依法应当附送生态环境影响报告书而未附送的专项规划草案，违法予以批准的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":1064,"n":"第一千零六十四条","txt":"企业事业单位、其他生产经营者和个人污染环境、破坏生态或者有本法规定的其他违法情形的，应当依法承担法律责任；造成环境污染、生态破坏事故或者有其他法定情形的，企业事业单位、其他生产经营者的法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员应当依法承担法律责任。"},{"i":1065,"n":"第一千零六十五条","txt":"企业事业单位、其他生产经营者和个人造成环境污染、生态破坏的，应当依法承担消除污染、修复受损生态环境的责任；无法消除或者修复的，实施替代性治理或者修复措施。"},{"i":1066,"n":"第一千零六十六条","txt":"土壤污染及其相关的地下水污染责任人无法认定，土地使用权人未依照本法规定履行污染风险管控和修复义务，造成他人民事权益损害的，应当依法承担民事侵权责任。"},{"i":1067,"n":"第一千零六十七条","txt":"受委托从事生态环境服务活动的生态环境技术服务机构违反本法规定，对造成的环境污染、生态破坏等负有责任的，除依照本法及有关法律法规的规定予以处罚外，还应当与造成环境污染、生态破坏等的委托人承担连带责任。"},{"i":1068,"n":"第一千零六十八条","txt":"获准倾倒海洋废弃物的单位和产生工业固体废物的单位违反本法规定，未尽到核实、监督等义务委托他人实施废弃物海洋倾倒作业或者运输、利用、处置工业固体废物的，除依照本法及有关法律法规的规定予以处罚外，还应当与造成环境污染、生态破坏的受托人承担连带责任。"},{"i":1069,"n":"第一千零六十九条","txt":"企业事业单位有本法规定的违法情形，其负有责任的领导人员和直接责任人员属于公职人员的，依法给予处分。"},{"i":1070,"n":"第一千零七十条","txt":"因污染环境、破坏生态等造成他人民事权益损害应当承担民事责任，本法未作规定的，依照《中华人民共和国民法典》的规定承担民事责任。"},{"i":1071,"n":"第一千零七十一条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":1072,"n":"第一千零七十二条","txt":"负有生态环境保护监督管理职责的部门、机构应当按照职责分工及时查处生态环境违法案件，依法追究法律责任。"},{"i":1073,"n":"第一千零七十三条","txt":"违反法律规定，污染环境、破坏生态等给国家造成损失的，由设区的市级以上地方人民政府或者其指定的部门、机构与责任人按照有关规定进行磋商，要求其承担生态环境损害赔偿责任；磋商未达成一致的，可以向人民法院提起诉讼。"},{"i":1074,"n":"第一千零七十四条","txt":"污染海洋环境、破坏海洋生态给国家造成损失的，由依照本法规定行使海洋生态环境监督管理权的部门对责任人提出损害赔偿要求，可以向人民法院提起诉讼。"},{"i":1075,"n":"第一千零七十五条","txt":"违反法律规定，污染环境、破坏生态等损害社会公共利益的，人民检察院或者符合本法规定的社会组织可以依法向人民法院提起诉讼。"},{"i":1076,"n":"第一千零七十六条","txt":"人民检察院在履行职责中发现地方人民政府或者负有生态环境保护监督管理职责的部门、机构违法行使职权或者不作为，给国家造成损失或者损害社会公共利益的，可以依法提起诉讼。"},{"i":1077,"n":"第一千零七十七条","txt":"污染环境、破坏生态等侵害他人合法权益的，可以由当事人协商解决，也可以向负有生态环境保护监督管理职责的部门、机构申请调解处理；调解不成的，可以向人民法院提起诉讼。当事人也可以直接向人民法院提起诉讼。"},{"i":1078,"n":"第一千零七十八条","txt":"国家鼓励排放噪声、油烟、异味的单位和公共场所管理者等与受到侵害的单位和个人友好协商，通过调整生产经营、施工作业时间等，采取预防、补救措施，支付补偿金、异地安置等方式，妥善解决纠纷。"},{"i":1079,"n":"第一千零七十九条","txt":"对正在实施或者即将实施的污染环境、破坏生态等行为，不及时制止将使当事人合法权益或者生态环境受到难以弥补的损害重大风险的，可以依照《中华人民共和国民事诉讼法》的有关规定，向人民法院申请采取禁止令保全措施，责令立即停止污染环境、破坏生态等行为。"},{"i":1080,"n":"第一千零八十条","txt":"因污染环境、破坏生态等造成他人损害的，行为人应当就法律规定的不承担责任或者减轻责任的情形，及其行为与损害之间不存在因果关系依法承担举证责任。"},{"i":1081,"n":"第一千零八十一条","txt":"依据本法第一千零七十三条、第一千零七十五条规定向人民法院提起诉讼的机关和组织，应当提供以下证明："},{"i":1082,"n":"第一千零八十二条","txt":"负有生态环境保护监督管理职责的部门、机构以及人民检察院等，可以依法支持因污染环境、破坏生态受到损害的当事人向人民法院提起诉讼。"},{"i":1083,"n":"第一千零八十三条","txt":"相关部门在受理举报、监督检查或者在查处案件等工作中，发现违法线索或者案件属于负有生态环境保护监督管理职责的部门、机构职责的，应当及时移送。"},{"i":1084,"n":"第一千零八十四条","txt":"上级人民政府及其生态环境主管部门应当加强对下级人民政府及其有关部门、机构生态环境保护工作的监督。发现有关工作人员有违法行为，依法应当给予处分的，应当移送其任免机关、单位或者监察机关依法处理。"},{"i":1085,"n":"第一千零八十五条","txt":"违反本法第一编第四章等规定，适用本节规定予以行政处罚。"},{"i":1086,"n":"第一千零八十六条","txt":"违反本法规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处二万元以上二十万元以下的罚款；拒不改正的，可以责令限制生产、停产整治："},{"i":1087,"n":"第一千零八十七条","txt":"违反本法规定，企业事业单位和其他生产经营者开展生态环境监测使用不符合法律、行政法规规定和国家标准的监测设施、设备，或者未遵守监测规范导致监测数据失真的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处二万元以上二十万元以下的罚款；拒不改正的，责令限制生产、停产整治。"},{"i":1088,"n":"第一千零八十八条","txt":"违反本法规定，企业事业单位和其他生产经营者对生态环境监测数据弄虚作假，或者指使其委托的生态环境监测机构对监测数据弄虚作假的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处十万元以上一百万元以下的罚款，并对其直接负责的主管人员和其他直接责任人员处五万元以上二十万元以下的罚款；情节严重的，责令限制生产、停产整治。"},{"i":1089,"n":"第一千零八十九条","txt":"违反本法规定，生态环境监测机构不具备相应的设施、设备、技术人员、技术能力、管理能力，或者不依法备案的，由生态环境主管部门责令改正，没收违法所得，并处二万元以上二十万元以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业。"},{"i":1090,"n":"第一千零九十条","txt":"违反本法规定，生态环境监测机构使用不符合法律、行政法规规定和国家标准的监测设施、设备，或者未遵守监测规范导致监测数据失真的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，没收违法所得，并处二万元以上二十万元以下的罚款；拒不改正的，有许可证的吊销许可证，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1091,"n":"第一千零九十一条","txt":"违反本法规定，生态环境监测机构对监测数据弄虚作假的，由负有生态环境保护监督管理职责的部门、机构按照职责分工没收违法所得，并处十万元以上五十万元以下的罚款；情节严重的，并处五十万元以上二百万元以下的罚款，有许可证的吊销许可证，禁止从事监测业务，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1092,"n":"第一千零九十二条","txt":"违反本法规定，生产、进口、销售不符合法律、行政法规规定和国家标准的监测设施、设备的，由市场监督管理部门、海关按照职责分工责令停止生产、进口、销售，没收违法所得和违法生产、进口、销售的设施、设备，并处违法生产、进口、销售的设施、设备货值金额一倍以上五倍以下的罚款，货值金额不足五万元的，以五万元计算；情节严重的，吊销许可证。"},{"i":1093,"n":"第一千零九十三条","txt":"违反本法规定，单位和个人以侵占、损毁或者擅自移动、改变等方式干扰、破坏生态环境监测设施、设备或者指使干扰、破坏生态环境监测设施、设备的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处二万元以上二十万元以下的罚款；构成违反治安管理行为的，由公安机关依法予以处罚。"},{"i":1094,"n":"第一千零九十四条","txt":"违反本法第一编第五章等规定，适用本节规定予以行政处罚。"},{"i":1095,"n":"第一千零九十五条","txt":"违反本法规定，建设单位未依法报批，或者未依照本法有关规定重新报批或者报请重新审核生态环境影响报告书、报告表，建设项目生态环境影响报告书、报告表未经批准或者未经原审批部门重新审核同意，擅自开工建设的，由生态环境主管部门、海警机构按照职责分工责令其停止建设，并可以责令恢复原状，报批、审核类型为生态环境影响报告书的，处二十万元以上一百万元以下的罚款，情节严重的，处一百万元以上一千万元以下的罚款；报批、审核类型为生态环境影响报告表的，处十万元以上五十万元以下的罚款，情节严重的，处五十万元以上五百万元以下的罚款。"},{"i":1096,"n":"第一千零九十六条","txt":"违反本法规定，建设项目生态环境影响报告书、报告表存在基础资料明显不实，内容存在重大缺陷、遗漏或者虚假，生态环境影响评价结论不正确或者不合理等严重质量问题的，由生态环境主管部门、海警机构按照职责分工对建设单位处五十万元以上二百万元以下的罚款，并对建设单位的法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员，处五万元以上二十万元以下的罚款；情节严重的，责令限制生产、停产整治。"},{"i":1097,"n":"第一千零九十七条","txt":"违反本法规定，接受委托为建设单位编制建设项目生态环境影响报告书、报告表的技术单位违反国家有关生态环境影响评价标准和技术规范等规定，致使其编制的报告书、报告表存在基础资料明显不实，内容存在重大缺陷、遗漏或者虚假，生态环境影响评价结论不正确或者不合理等严重后果的，由生态环境主管部门、海警机构按照职责分工没收违法所得，并处十万元以上五十万元以下的罚款；情节严重的，并处五十万元以上二百万元以下的罚款，禁止从事生态环境影响报告书、报告表编制工作，报经有批准权的人民政府批准，责令停业。"},{"i":1098,"n":"第一千零九十八条","txt":"违反本法规定，接受委托为建设单位编制建设项目生态环境影响报告书、报告表的技术单位和人员，与负责审批的部门存在利益关系的，或者该技术单位未依法报生态环境主管部门备案的，由生态环境主管部门、海警机构按照职责分工责令改正，处二万元以上二十万元以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业。"},{"i":1099,"n":"第一千零九十九条","txt":"违反本法规定，在建设项目建设、运行过程中，未实施生态环境影响报告书、报告表及其审批部门审批意见中提出的生态环境保护对策措施的，由生态环境主管部门、海警机构按照职责分工对建设单位处五万元以上五十万元以下的罚款；情节严重的，处五十万元以上二百万元以下的罚款。本法另有规定的，适用其规定。"},{"i":1100,"n":"第一千一百条","txt":"违反本法规定，生态环境保护设施未与主体工程同时设计、同时施工、同时投产使用，或者生态环境保护设施未建成、未达到规定要求即投入生产、使用的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处二十万元以上一百万元以下的罚款，拒不改正的，处一百万元以上二百万元以下的罚款；对直接负责的主管人员和其他直接责任人员处五万元以上二十万元以下的罚款；造成重大环境污染、生态破坏的，责令其停止生产、使用，或者报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1101,"n":"第一千一百零一条","txt":"违反本法第二编第一分编第二章等规定，适用本节规定予以行政处罚。"},{"i":1102,"n":"第一千一百零二条","txt":"违反本法规定，未依法取得排污许可证排放污染物的，由生态环境主管部门责令改正，处二十万元以上一百万元以下的罚款，并可以责令限制生产、停产整治；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。其中，污染物为工业噪声的，罚款数额为二万元以上二十万元以下。拒不停止排放污染物的，由生态环境主管部门将案件移送公安机关，由公安机关对其直接负责的主管人员和其他直接责任人员，处十日以上十五日以下拘留；情节较轻的，处五日以上十日以下拘留。"},{"i":1103,"n":"第一千一百零三条","txt":"违反本法规定，未按照排污许可证载明的污染物排放种类，或者超过载明的许可排放浓度、许可排放量、许可排放限值排放污染物的，由生态环境主管部门责令改正，处十万元以上一百万元以下的罚款，并可以责令限制生产、停产整治；情节严重的，吊销排污许可证，报经有批准权的人民政府批准，责令停业、关闭。其中，污染物为工业噪声的，罚款数额为二万元以上二十万元以下。"},{"i":1104,"n":"第一千一百零四条","txt":"违反本法规定，未按照排污许可证的规定运行和维护污染防治设施的，由生态环境主管部门责令改正，处二万元以上五万元以下的罚款；致使污染防治设施不能正常发挥作用，但不属于以逃避监管方式排放污染物的，由生态环境主管部门责令改正，处五万元以上二十万元以下的罚款；情节严重的，责令限制生产、停产整治。"},{"i":1105,"n":"第一千一百零五条","txt":"违反本法规定，以欺骗、贿赂等不正当手段申请取得排污许可证的，由生态环境主管部门依法撤销其排污许可证，处二十万元以上五十万元以下的罚款。"},{"i":1106,"n":"第一千一百零六条","txt":"违反本法规定，需要填报排污登记表的企业事业单位和其他生产经营者未依法填报排污信息的，由生态环境主管部门责令改正，可以处五万元以下的罚款。"},{"i":1107,"n":"第一千一百零七条","txt":"违反本法规定，超过污染物排放标准或者超过重点污染物排放总量控制指标排放污染物的，由生态环境主管部门责令改正，处十万元以上一百万元以下的罚款，可以责令限制生产、停产整治；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。其中，污染物为工业噪声的，罚款数额为二万元以上二十万元以下。"},{"i":1108,"n":"第一千一百零八条","txt":"违反本法规定，通过暗管、渗井、渗坑、灌注、裂隙、溶洞、篡改或者伪造监测数据、以逃避现场检查为目的的临时停产、非紧急情况下开启应急排放通道、不正常运行污染防治设施等逃避监管的方式排放污染物的，由生态环境主管部门责令改正，处十万元以上一百万元以下的罚款，责令限制生产、停产整治，并将案件移送公安机关，由公安机关对其直接负责的主管人员和其他直接责任人员，处五日以上十日以下拘留；情节严重的，吊销排污许可证，报经有批准权的地方人民政府批准，责令停业、关闭，并由公安机关对其直接负责的主管人员和其他直接责任人员，处十日以上十五日以下拘留。"},{"i":1109,"n":"第一千一百零九条","txt":"违反本法和其他法律法规、国务院生态环境主管部门的规定、排污许可证规定设置排污口的，除本条第二款规定外，由生态环境主管部门责令限期拆除，逾期不拆除的，强制拆除，所需费用由违法者承担，处二万元以上十万元以下的罚款；情节严重的，处十万元以上五十万元以下的罚款，责令限制生产、停产整治。"},{"i":1110,"n":"第一千一百一十条","txt":"违反本法规定，未向社会公开或者不如实公开污染物排放信息、温室气体排放信息等生态环境信息的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处二万元以上二十万元以下的罚款；拒不改正的，责令限制生产、停产整治，并公告上述生态环境信息。"},{"i":1111,"n":"第一千一百一十一条","txt":"违反本法规定，建设单位未将污染防治所需资金列入工程造价的，由生态环境主管部门责令改正，处二万元以上十万元以下的罚款；拒不改正的，处十万元以上一百万元以下的罚款，责令停产整治。"},{"i":1112,"n":"第一千一百一十二条","txt":"违反本法规定，将中华人民共和国境外的固体废物、放射性废物和被放射性污染的物品输入境内的，由海关责令退运该固体废物、放射性废物和被放射性污染的物品，处五十万元以上五百万元以下的罚款。已经非法入境的，由省级以上人民政府生态环境主管部门依法向海关提出处理意见，由海关按照前述规定予以处理；已经造成环境污染的，由省级以上人民政府生态环境主管部门责令进口者消除污染。"},{"i":1113,"n":"第一千一百一十三条","txt":"违反本法第二编第二分编规定，适用本节规定予以行政处罚。"},{"i":1114,"n":"第一千一百一十四条","txt":"违反本法规定，有下列情形之一的，由能源主管部门责令改正，处十万元以上一百万元以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":1115,"n":"第一千一百一十五条","txt":"违反本法规定，有下列情形之一的，由市场监督管理部门责令改正，没收原材料、产品和违法所得，并处货值金额一倍以上五倍以下的罚款："},{"i":1116,"n":"第一千一百一十六条","txt":"违反本法规定，有下列情形之一的，由海关责令退运，没收违法所得，并处货值金额一倍以上五倍以下的罚款；无法退运的，没收原材料和产品："},{"i":1117,"n":"第一千一百一十七条","txt":"违反本法规定，单位燃用不符合质量标准的煤炭或者使用不符合质量标准的石油焦的，由生态环境主管部门责令改正，处货值金额一倍以上五倍以下的罚款。"},{"i":1118,"n":"第一千一百一十八条","txt":"违反本法规定，船舶使用不符合标准或者要求的燃油的，由海事管理机构、渔业渔政主管部门按照职责分工处一万元以上十万元以下的罚款。"},{"i":1119,"n":"第一千一百一十九条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门没收燃用高污染燃料的设施、燃煤供热锅炉并组织拆除，处二万元以上二十万元以下的罚款："},{"i":1120,"n":"第一千一百二十条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门责令改正，处二万元以上二十万元以下的罚款；拒不改正的，责令停产整治："},{"i":1121,"n":"第一千一百二十一条","txt":"违反本法规定，生产不符合大气污染物排放标准的机动车船、非道路移动机械、发动机的，由省级以上人民政府生态环境主管部门责令改正，没收违法所得，并处货值金额三倍以下的罚款，没收销毁无法达到污染物排放标准的机动车船、非道路移动机械、发动机；拒不改正的，责令限制生产、停产整治，并由国务院有关生产主管部门按照职责分工责令停止生产该车（船、机）型。"},{"i":1122,"n":"第一千一百二十二条","txt":"违反本法规定，进口、销售超过污染物排放标准的机动车船、非道路移动机械、发动机的，由市场监督管理部门、海关按照职责分工没收违法所得，并处货值金额三倍以下的罚款，没收销毁无法达到污染物排放标准的机动车船、非道路移动机械、发动机。"},{"i":1123,"n":"第一千一百二十三条","txt":"违反本法规定，机动车、非道路移动机械生产、进口企业未按照规定向社会公开其生产、进口机动车车型、非道路移动机械机型的排放检验信息或者污染控制技术信息的，由省级以上人民政府生态环境主管部门责令改正，处五万元以上五十万元以下的罚款。"},{"i":1124,"n":"第一千一百二十四条","txt":"违反本法规定，以临时更换、篡改、屏蔽、伪造排放控制系统等弄虚作假的方式通过机动车船、非道路移动机械排放检验或者破坏、拆除、篡改、屏蔽、伪造机动车船、非道路移动机械排放控制系统的，由生态环境主管部门、海事管理机构、渔业渔政主管部门按照职责分工责令改正，对所有人处每辆（艘）五千元的罚款，对维修单位处每辆（艘）五千元的罚款。"},{"i":1125,"n":"第一千一百二十五条","txt":"违反本法规定，生产、进口或者销售能够篡改、屏蔽、伪造机动车船、非道路移动机械、发动机排放检验数据的装置或者为虚假排放检验提供条件的检验设备的，由生态环境主管部门、市场监督管理部门、海关按照职责分工没收违法所得，没收销毁违法装置和检验设备，并处货值金额一倍以上五倍以下的罚款，货值金额不足五万元的，以五万元计算；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1126,"n":"第一千一百二十六条","txt":"违反本法规定，机动车驾驶人驾驶排放检验不合格的机动车上道路行驶的，由公安机关交通管理部门依法予以处罚。"},{"i":1127,"n":"第一千一百二十七条","txt":"违反本法规定，使用排放不合格的非道路移动机械、铁路内燃机车、船舶，或者在用重型汽车、船舶、非道路移动机械未加装、更换符合要求的排放控制系统或者采取其他有效措施的，由生态环境、海事管理、渔业渔政等部门按照职责分工责令改正，处每辆（艘）五千元的罚款。"},{"i":1128,"n":"第一千一百二十八条","txt":"违反本法规定，施工单位有下列情形之一的，由住房城乡建设等部门按照职责分工责令改正，处一万元以上十万元以下的罚款；拒不改正的，责令停工整治："},{"i":1129,"n":"第一千一百二十九条","txt":"违反本法规定，运输煤炭、垃圾、渣土、砂石、土方、灰浆等散装、流体物料的车辆和船舶，未采取密闭或者其他措施防止物料遗撒，或者未按照规定路线行驶的，由县级以上地方人民政府确定的监督管理部门、海事管理机构按照职责分工责令改正，处二千元以上二万元以下的罚款；拒不改正的，车辆不得上道路行驶。"},{"i":1130,"n":"第一千一百三十条","txt":"违反本法规定，有下列情形之一的，由生态环境等部门按照职责分工责令改正，处一万元以上十万元以下的罚款；拒不改正的，责令停工整治或者停业整治："},{"i":1131,"n":"第一千一百三十一条","txt":"违反本法规定，在人口集中地区对树木、花草喷洒剧毒、高毒农药，或者在禁止焚烧的区域和时段露天焚烧秸秆、落叶等产生烟尘污染的物质的，由县级以上地方人民政府确定的监督管理部门责令改正，可以处五百元以上二千元以下的罚款。"},{"i":1132,"n":"第一千一百三十二条","txt":"违反本法规定，排放油烟的餐饮服务业经营者未安装油烟净化等污染防治设施，未保持正常使用油烟净化等污染防治设施，或者未采取其他油烟净化措施，致使超过排放标准排放油烟污染物的，由县级以上地方人民政府确定的监督管理部门责令改正，处五千元以上五万元以下的罚款；拒不改正的，责令停业整治。"},{"i":1133,"n":"第一千一百三十三条","txt":"违反本法规定，从事服装干洗和机动车维修等服务活动，未设置异味和废气处理装置等污染防治设施并保持正常使用的，由生态环境主管部门责令改正，处二千元以上二万元以下的罚款；拒不改正的，责令停业整治。"},{"i":1134,"n":"第一千一百三十四条","txt":"违反本法规定，擅自向社会发布重污染天气预报预警信息，构成违反治安管理行为的，由公安机关依法予以处罚。"},{"i":1135,"n":"第一千一百三十五条","txt":"违反本法第二编第三分编规定，适用本节规定予以行政处罚。"},{"i":1136,"n":"第一千一百三十六条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门责令停止违法行为，采取治理措施消除污染，处以罚款，可以责令采取限制生产、停产整治等措施；拒不采取治理措施的，可以指定有治理能力的单位代为治理，所需费用由违法者承担；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":1137,"n":"第一千一百三十七条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门责令停止违法行为，采取治理措施消除污染，处以罚款，可以责令采取限制生产、停产整治等措施；拒不采取治理措施的，指定有治理能力的单位代为治理，所需费用由违法者承担；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":1138,"n":"第一千一百三十八条","txt":"违反本法规定，在泉域保护范围以及岩溶强发育、存在较多落水洞和岩溶漏斗的区域内，新建、改建、扩建造成地下水污染的建设项目的，由生态环境主管部门处十万元以上五十万元以下的罚款，并报经有批准权的人民政府批准，责令拆除或者关闭。"},{"i":1139,"n":"第一千一百三十九条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门责令改正，处以罚款，可以责令采取限制生产、停产整治等措施；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":1140,"n":"第一千一百四十条","txt":"违反本法规定，向污水集中处理设施排放不符合处理工艺要求的工业废水的，由生态环境主管部门责令改正或者责令限制生产、停产整治，处十万元以上一百万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1141,"n":"第一千一百四十一条","txt":"违反本法规定，建设不符合国家产业政策的小型造纸、制革、印染、染料、炼焦、炼硫、炼砷、炼汞、炼油、电镀、农药、石棉、水泥、玻璃、钢铁、火电以及其他严重污染水环境的生产项目的，由所在地设区的市、县级人民政府责令关闭。"},{"i":1142,"n":"第一千一百四十二条","txt":"违反本法规定，船舶未配备相应的防污设备和器材，或者未持有合法有效的防治水域环境污染的证书与文书的，由海事管理机构、渔业渔政主管部门按照职责分工责令限期改正，处五千元以上五万元以下的罚款；逾期不改正的，责令船舶临时停航。"},{"i":1143,"n":"第一千一百四十三条","txt":"违反本法规定，有下列情形之一的，由海事管理机构、渔业渔政主管部门按照职责分工责令停止违法行为，处一万元以上十万元以下的罚款；造成水污染的，责令限期采取治理措施消除污染，处二万元以上二十万元以下的罚款；逾期不采取治理措施的，指定有治理能力的单位代为治理，所需费用由船舶承担："},{"i":1144,"n":"第一千一百四十四条","txt":"违反本法规定，有下列情形之一的，由海事管理机构、渔业渔政主管部门按照职责分工责令改正，处二万元以上二十万元以下的罚款："},{"i":1145,"n":"第一千一百四十五条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门责令停止违法行为，处十万元以上五十万元以下的罚款，并报经有批准权的人民政府批准，责令拆除或者关闭："},{"i":1146,"n":"第一千一百四十六条","txt":"违反本法第二编第四分编规定，适用本节规定予以行政处罚。"},{"i":1147,"n":"第一千一百四十七条","txt":"违反本法规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款，可以责令采取限制生产、停产整治等措施；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":1148,"n":"第一千一百四十八条","txt":"违反本法规定，从事海水养殖活动有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处五千元以上五万元以下的罚款；情节严重的，处五万元以上二十万元以下的罚款，报经有批准权的人民政府批准，责令停业、关闭："},{"i":1149,"n":"第一千一百四十九条","txt":"违反本法规定，在依法划定的自然保护地、重要渔业水域及其他需要特别保护的区域建设污染环境、破坏生态的海岸工程和海洋工程建设项目或者从事其他活动，或者在沿海陆域建设不符合国家产业政策的生产项目的，由县级以上人民政府按照管理权限责令关闭。"},{"i":1150,"n":"第一千一百五十条","txt":"违反本法规定，海岸工程和海洋工程建设项目有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令停止违法行为、消除危害，处二十万元以上一百万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":1151,"n":"第一千一百五十一条","txt":"违反本法规定进行海洋油气勘探开发活动，造成海洋环境污染的，由海警机构责令改正，给予警告，并处二十万元以上一百万元以下的罚款。"},{"i":1152,"n":"第一千一百五十二条","txt":"违反本法规定，有下列情形之一的，由国务院生态环境主管部门及其海域派出机构、海事管理机构或者海警机构按照职责分工责令改正，处以罚款，暂扣或者吊销倾倒许可证，必要时可以扣押船舶；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":1153,"n":"第一千一百五十三条","txt":"违反本法规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款："},{"i":1154,"n":"第一千一百五十四条","txt":"违反本法规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款："},{"i":1155,"n":"第一千一百五十五条","txt":"违反本法规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款："},{"i":1156,"n":"第一千一百五十六条","txt":"违反本法规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款："},{"i":1157,"n":"第一千一百五十七条","txt":"违反本法规定，未按照国家规定缴纳倾倒费的，由国务院生态环境主管部门及其海域派出机构责令限期缴纳；逾期拒不缴纳的，处应缴纳倾倒费数额一倍以上三倍以下的罚款，并可以报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1158,"n":"第一千一百五十八条","txt":"违反本法第二编第五分编规定，适用本节规定予以行政处罚。"},{"i":1159,"n":"第一千一百五十九条","txt":"违反本法规定，有下列情形之一的，由地方人民政府负有生态环境保护监督管理职责的部门按照职责分工责令改正，处以罚款；拒不改正的，责令限制生产、停产整治："},{"i":1160,"n":"第一千一百六十条","txt":"违反本法规定，向农用地排放重金属或者其他有毒有害物质含量超标的污水、污泥，以及可能造成土壤污染的清淤底泥、尾矿、矿渣等的，由生态环境主管部门责令改正，没收违法所得，并处十万元以上五十万元以下的罚款；情节严重的，并处五十万元以上二百万元以下的罚款，并将案件移送公安机关，由公安机关对直接负责的主管人员和其他直接责任人员处五日以上十五日以下拘留。"},{"i":1161,"n":"第一千一百六十一条","txt":"违反本法规定，农业投入品生产者、销售者、使用者未及时回收农药、肥料等农业投入品的包装废弃物或者农用薄膜，或者未将农药包装废弃物交由专门的机构或者组织进行无害化处理的，由农业农村主管部门责令改正，处一万元以上十万元以下的罚款；农业投入品使用者为个人的，可以处二百元以上二千元以下的罚款。"},{"i":1162,"n":"第一千一百六十二条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门责令改正，没收违法所得，并处十万元以上五十万元以下的罚款；情节严重的，并处五十万元以上一百万元以下的罚款；对直接负责的主管人员和其他直接责任人员处五千元以上二万元以下的罚款："},{"i":1163,"n":"第一千一百六十三条","txt":"违反本法规定，将重金属或者其他有毒有害物质含量超标的工业固体废物、生活垃圾或者污染土壤用于土地复垦的，由生态环境主管部门责令改正，没收违法所得，并处十万元以上一百万元以下的罚款。"},{"i":1164,"n":"第一千一百六十四条","txt":"违反本法规定，土壤污染责任人或者土地使用权人未按照要求实施后期管理的，由负有生态环境保护监督管理职责的部门按照职责分工责令改正，处一万元以上五万元以下的罚款；情节严重的，处五万元以上五十万元以下的罚款。"},{"i":1165,"n":"第一千一百六十五条","txt":"违反本法规定，土壤污染责任人或者土地使用权人有下列情形之一的，由地方人民政府负有生态环境保护监督管理职责的部门按照职责分工责令改正，处二万元以上二十万元以下的罚款；拒不改正的，处二十万元以上一百万元以下的罚款，并委托他人代为履行，所需费用由土壤污染责任人或者土地使用权人承担；对直接负责的主管人员和其他直接责任人员处五千元以上二万元以下的罚款："},{"i":1166,"n":"第一千一百六十六条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门、农业农村主管部门、林业草原主管部门按照职责分工责令改正；拒不改正的，处二万元以上十万元以下的罚款："},{"i":1167,"n":"第一千一百六十七条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门、工业和信息化主管部门按照职责分工责令改正；拒不改正的，处一万元以上五万元以下的罚款："},{"i":1168,"n":"第一千一百六十八条","txt":"违反本法第二编第六分编规定，适用本节规定予以行政处罚。"},{"i":1169,"n":"第一千一百六十九条","txt":"违反本法规定，擅自倾倒、堆放、丢弃、抛撒、遗撒、焚烧固体废物的，由生态环境主管部门、城镇排水主管部门、环境卫生主管部门按照职责分工责令停止违法行为，采取治理措施消除污染，没收违法所得，并处十万元以上一百万元以下的罚款；情节严重的，责令限制生产、停产整治；拒不采取治理措施的，指定有治理能力的单位代为治理，所需费用由违法者承担。"},{"i":1170,"n":"第一千一百七十条","txt":"违反本法规定，未采取防范措施，造成工业固体废物扬散、流失、渗漏或者其他环境污染的，由生态环境主管部门责令改正，处十万元以上一百万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。工业固体废物为危险废物的，罚款数额为二十万元以上二百万元以下。"},{"i":1171,"n":"第一千一百七十一条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门责令改正，没收违法所得，并处以罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":1172,"n":"第一千一百七十二条","txt":"违反本法规定，城镇污水集中处理设施的运营单位或者污泥无害化处理处置单位对污泥流向、用途、用量等未进行跟踪、记录，或者处理处置后的污泥不符合国家标准的，由城镇排水主管部门责令改正，给予警告；造成严重后果的，并处十万元以上二十万元以下的罚款；拒不改正的，指定有治理能力的单位代为治理，所需费用由违法者承担。"},{"i":1173,"n":"第一千一百七十三条","txt":"违反本法规定，尾矿、煤矸石、废石等矿业固体废物贮存设施停止使用后，未按照国家有关生态环境保护等规定进行封场的，由生态环境主管部门责令改正，处二十万元以上一百万元以下的罚款。"},{"i":1174,"n":"第一千一百七十四条","txt":"违反本法规定，有下列情形之一的，由环境卫生主管部门责令改正，没收违法所得，并处以罚款："},{"i":1175,"n":"第一千一百七十五条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门责令改正，没收违法所得，并处以罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":1176,"n":"第一千一百七十六条","txt":"生产、销售和使用有毒有害物质超过国家标准的建筑材料和装修材料的，依照《中华人民共和国产品质量法》和有关民事、刑事法律的规定追究法律责任。"},{"i":1177,"n":"第一千一百七十七条","txt":"违反本法规定，危险废物产生者未按照规定处置其产生的危险废物，被责令改正后拒不改正的，由生态环境主管部门组织代为处置，处置费用由危险废物产生者承担，处十万元以上一百万元以下的罚款。"},{"i":1178,"n":"第一千一百七十八条","txt":"违反本法规定，企业事业单位无许可证从事收集、贮存、利用、处置危险废物经营活动的，由生态环境主管部门责令改正，没收违法所得，对收集、贮存危险废物经营活动并处二十万元以上一百万元以下的罚款，对利用、处置危险废物经营活动并处一百万元以上五百万元以下的罚款，报经有批准权的人民政府批准，责令停业、关闭；对法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员，处十万元以上一百万元以下的罚款。"},{"i":1179,"n":"第一千一百七十九条","txt":"违反本法规定，有下列情形之一的，由公安机关对法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员处十日以上十五日以下拘留；情节较轻的，处五日以上十日以下拘留："},{"i":1180,"n":"第一千一百八十条","txt":"执法过程中查获的固体废物无法确定责任人或者无法退运的，由所在地县级以上地方人民政府组织处理。"},{"i":1181,"n":"第一千一百八十一条","txt":"违反本法第二编第七分编规定，适用本节规定予以行政处罚。"},{"i":1182,"n":"第一千一百八十二条","txt":"违反本法规定，生产、进口、销售超过噪声限值的产品的，由市场监督管理部门、海关按照职责分工责令改正，没收违法所得，并处货值金额一倍以上五倍以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1183,"n":"第一千一百八十三条","txt":"违反本法规定，建设单位建设噪声敏感建筑物不符合民用建筑隔声设计标准要求的，由住房城乡建设主管部门责令改正，处建设工程合同价款百分之二以上百分之四以下的罚款。"},{"i":1184,"n":"第一千一百八十四条","txt":"违反本法规定，在噪声敏感建筑物集中区域新建排放噪声的工业企业的，由生态环境主管部门责令停止违法行为，处十万元以上五十万元以下的罚款，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1185,"n":"第一千一百八十五条","txt":"违反本法规定，建设单位、施工单位有下列情形之一的，由工程所在地人民政府指定的部门责令改正，处一万元以上十万元以下的罚款；拒不改正的，可以责令暂停施工："},{"i":1186,"n":"第一千一百八十六条","txt":"违反本法规定，有下列情形之一的，由工程所在地人民政府指定的部门责令改正，处五千元以上五万元以下的罚款；拒不改正的，处五万元以上二十万元以下的罚款："},{"i":1187,"n":"第一千一百八十七条","txt":"违反本法规定，驾驶拆除或者损坏消声器、加装排气管等擅自改装的机动车轰鸣、疾驶，机动车运行时未按照规定使用声响装置，或者违反禁止机动车行驶和使用声响装置的路段和时间规定的，由公安机关交通管理部门给予警告，处二百元以上二千元以下的罚款、暂扣机动车驾驶证等处罚。"},{"i":1188,"n":"第一千一百八十八条","txt":"违反本法规定，有下列情形之一的，由交通运输主管部门、铁路监督管理部门、民用航空主管部门或者地方人民政府指定的城市道路、城市轨道交通有关部门按照职责分工责令改正，处五千元以上五万元以下的罚款；拒不改正的，处五万元以上二十万元以下的罚款："},{"i":1189,"n":"第一千一百八十九条","txt":"违反本法规定，有下列情形之一的，由地方人民政府指定的部门责令改正，处五千元以上五万元以下的罚款；拒不改正的，处五万元以上二十万元以下的罚款，并可以报经有批准权的人民政府批准，责令停业："},{"i":1190,"n":"第一千一百九十条","txt":"违反本法规定，有下列情形之一的，由地方人民政府指定的部门说服教育，责令改正；拒不改正的，给予警告，对个人可以处二百元以上一千元以下的罚款，对单位可以处二千元以上二万元以下的罚款："},{"i":1191,"n":"第一千一百九十一条","txt":"违反本法规定，新建居民住房的房地产开发经营者未在销售场所公示住房可能受到噪声影响的情况以及采取或者拟采取的防治措施，或者未纳入买卖合同，未在买卖合同中明确住房的共用设施设备位置或者建筑隔声情况的，由住房城乡建设主管部门责令改正，处一万元以上五万元以下的罚款；拒不改正的，责令暂停销售。"},{"i":1192,"n":"第一千一百九十二条","txt":"违反本法规定，产生社会生活噪声，经劝阻、调解和处理未能制止，持续干扰他人正常生活、工作和学习，或者有其他扰乱公共秩序、妨害社会管理等违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":1193,"n":"第一千一百九十三条","txt":"违反本法第二编第八分编等规定，适用本节规定予以行政处罚。"},{"i":1194,"n":"第一千一百九十四条","txt":"违反本法规定，向环境排放禁止排放的放射性废气、废液，倾倒放射性固体废物的，由生态环境主管部门责令停止违法行为，限期采取治理措施消除污染，处二十万元以上二百万元以下的罚款；逾期不采取治理措施的，指定有治理能力的单位代为治理，所需费用由违法者承担；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1195,"n":"第一千一百九十五条","txt":"违反本法规定，在内河水域和海上处置放射性固体废物、放射性物质的，由生态环境主管部门责令停止违法行为，限期采取治理措施消除污染，处五十万元以上二百万元以下的罚款；逾期不采取治理措施的，指定有治理能力的单位代为治理，所需费用由违法者承担。"},{"i":1196,"n":"第一千一百九十六条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门、核工业主管部门按照职责分工责令限期改正，处二万元以上二十万元以下的罚款；逾期不改正的，责令限制生产、停产整治："},{"i":1197,"n":"第一千一百九十七条","txt":"违反本法规定，未经核设施安全许可，核设施营运单位擅自进行核设施的选址、建造、运行、退役等活动的，依照《中华人民共和国核安全法》的规定追究法律责任。"},{"i":1198,"n":"第一千一百九十八条","txt":"违反本法规定，生产、销售、使用、转让、进出口、贮存放射性同位素和射线装置以及装备有放射性同位素的仪表的，由生态环境主管部门、市场监督管理部门、海关按照职责分工责令停止违法行为，限期改正，没收违法所得，并处五万元以上五十万元以下的罚款；逾期不改正的，处违法所得一倍以上五倍以下的罚款，违法所得不足五十万元的，以五十万元计算，责令限制生产、停产整治或者吊销许可证。"},{"i":1199,"n":"第一千一百九十九条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门责令停止违法行为，限期改正，处五万元以上五十万元以下的罚款；逾期不改正的，由原发证机关指定有处理能力的单位代为处理或者实施退役，费用由生产、销售、使用放射性同位素和射线装置的单位承担："},{"i":1200,"n":"第一千二百条","txt":"违反本法规定，不按照规定报告放射源丢失、被盗情况的，由公安机关、卫生健康主管部门、生态环境主管部门按照职责分工责令限期改正，处五万元以上五十万元以下的罚款；情节严重的，责令限制生产、停产整治。"},{"i":1201,"n":"第一千二百零一条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门责令停止违法行为，限期改正，处以罚款："},{"i":1202,"n":"第一千二百零二条","txt":"违反本法规定，放射性固体废物产生者，不按照国家规定对其产生的放射性固体废物进行处理和处置的，由生态环境主管部门责令停止违法行为，限期改正，处五万元以上二十万元以下的罚款；逾期不改正的，指定有处理能力的单位代为处理、处置，所需费用由放射性固体废物产生者承担，并处二十万元以上一百万元以下的罚款。"},{"i":1203,"n":"第一千二百零三条","txt":"违反本法规定，未经许可擅自从事贮存、处理和处置放射性废物活动的，由省级以上人民政府生态环境主管部门没收违法所得，并处一百万元以上五百万元以下的罚款，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1204,"n":"第一千二百零四条","txt":"违反本法第二编第九分编规定，适用本节规定予以行政处罚。"},{"i":1205,"n":"第一千二百零五条","txt":"违反本法规定，未按照重点管控新污染物禁止或者限制环境风险管控措施要求，生产或者进口重点管控新污染物清单中的化学物质，或者使用重点管控新污染物清单中化学物质生产产品的，由生态环境主管部门或者其他负有化学物质生产、进口、使用监督管理职责的部门按照职责分工责令改正，处十万元以上五十万元以下的罚款；拒不改正的，处五十万元以上一百万元以下的罚款，责令限制生产、停产整治；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1206,"n":"第一千二百零六条","txt":"违反本法规定，不按照新化学物质环境管理登记证的要求生产、进口新化学物质的，由生态环境主管部门或者其他负有化学物质生产、进口监督管理职责的部门按照职责分工责令改正，处二十万元以上一百万元以下的罚款；拒不改正的，处一百万元以上二百万元以下的罚款，责令限制生产、停产整治；情节严重的，吊销新化学物质环境管理登记证书，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1207,"n":"第一千二百零七条","txt":"违反本法规定，无新化学物质环境管理登记证，生产、进口新化学物质，或者使用无新化学物质环境管理登记证的企业事业单位生产、进口的新化学物质生产产品的，由生态环境主管部门或者其他负有化学物质生产、进口、使用监督管理职责的部门按照职责分工责令改正，处二十万元以上一百万元以下的罚款；拒不改正的，处一百万元以上二百万元以下的罚款，责令限制生产、停产整治；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1208,"n":"第一千二百零八条","txt":"违反本法规定，未实行排污许可管理的企业事业单位，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处二万元以上二十万元以下的罚款；拒不改正的，可以责令限制生产、停产整治："},{"i":1209,"n":"第一千二百零九条","txt":"违反本法规定，生产、进口、销售超过电磁辐射限值的产品的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，没收违法所得，并处货值金额一倍以上五倍以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1210,"n":"第一千二百一十条","txt":"违反本法规定，广告屏、广告牌、灯箱、媒体立面墙、道路、体育场、施工场地等，未采取有效措施防止、减轻光污染，干扰他人正常生活、交通出行的，由住房城乡建设主管部门、生态环境主管部门、交通运输主管部门、公安机关交通管理部门按照职责分工责令改正；拒不改正的，处五千元以上五万元以下的罚款。"},{"i":1211,"n":"第一千二百一十一条","txt":"违反本法规定，违反国土空间规划，在禁止开垦的范围内从事土地开发利用活动，或者未经批准，擅自改变土地或者海域用途的，由自然资源、林业草原等部门按照职责分工，依照《中华人民共和国土地管理法》、《中华人民共和国海域使用管理法》、《中华人民共和国水法》等法律法规的规定予以处罚。"},{"i":1212,"n":"第一千二百一十二条","txt":"违反本法规定，破坏森林、草原、湿地等重要生态系统，或者非法侵占、违法利用、违法占用江河湖泊水域或者岸线的，由林业草原、水行政、生态环境等部门按照职责分工，依照《中华人民共和国森林法》、《中华人民共和国草原法》、《中华人民共和国湿地保护法》等法律法规的规定予以处罚。"},{"i":1213,"n":"第一千二百一十三条","txt":"违反本法规定，擅自引进、释放或者丢弃外来物种的，由农业农村主管部门、林业草原主管部门、海关按照职责分工，依照《中华人民共和国生物安全法》、《中华人民共和国野生动物保护法》等法律法规的规定予以没收或者责令限期捕回、找回，并处以罚款。"},{"i":1214,"n":"第一千二百一十四条","txt":"违反本法规定，在长江、黄河等重要流域非法侵占、违法利用、违法占用江河湖泊岸线，或者未经批准在水土流失严重、生态脆弱区域开展可能造成水土流失的生产建设活动等的，依照《中华人民共和国长江保护法》、《中华人民共和国黄河保护法》等法律法规的规定予以处罚。"},{"i":1215,"n":"第一千二百一十五条","txt":"违反本法规定，在自然保护地、青藏高原等重要区域，有破坏保护界线标志、损害野生动植物等情形的，依照《中华人民共和国国家公园法》、《中华人民共和国青藏高原生态保护法》等法律法规的规定予以处罚。"},{"i":1216,"n":"第一千二百一十六条","txt":"违反本法有关海洋生态保护的规定，造成珊瑚礁等海洋生态系统破坏的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正、采取补救措施，处每平方米一千元以上一万元以下的罚款，有违法所得的，没收违法所得。"},{"i":1217,"n":"第一千二百一十七条","txt":"违反本法有关海洋生态保护的规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款："},{"i":1218,"n":"第一千二百一十八条","txt":"违反本法和有关法律法规的规定，未经批准擅自取用地下水的，由水行政主管部门责令停止违法行为，限期采取补救措施，处二万元以上二十万元以下的罚款；其中，在地下水禁止开采区、限制开采区范围内擅自取用地下水的，处五万元以上五十万元以下的罚款。"},{"i":1219,"n":"第一千二百一十九条","txt":"违反本法有关生态保护义务，本节未规定行政处罚的，依照有关法律的规定予以处罚。"},{"i":1220,"n":"第一千二百二十条","txt":"违反本法规定，生产大型机电设备、机动运输工具以及国务院工业和信息化主管部门指定的其他产品的企业未注明产品材料成分或者不如实注明的，由市场监督管理部门责令限期改正；拒不改正的，处五万元以下的罚款。"},{"i":1221,"n":"第一千二百二十一条","txt":"违反本法规定，不实施强制性清洁生产审核或者在清洁生产审核中弄虚作假，或者实施强制性清洁生产审核的企业不报告或者不如实报告审核结果的，由发展改革部门、生态环境主管部门按照职责分工责令限期改正；拒不改正的，处五万元以上五十万元以下的罚款。"},{"i":1222,"n":"第一千二百二十二条","txt":"违反本法规定，生产、进口、销售或者使用国家有关目录、名录中禁止或者淘汰的设备、材料、产品，采用国家有关目录、名录中禁止或者淘汰的技术、工艺，或者将淘汰或者限期淘汰的设备、材料、产品转让给他人使用的，由县级以上人民政府指定的部门、海关按照职责分工责令改正，没收违法所得，并处货值金额一倍以上五倍以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1223,"n":"第一千二百二十三条","txt":"违反本法规定，电器电子、机动车、铅蓄电池、动力电池等产品的生产者未按照规定建立与产品销售量相匹配的废旧产品回收体系并向社会公开的，由工业和信息化、商务等部门按照职责分工责令改正；拒不改正的，处五万元以上五十万元以下的罚款。"},{"i":1224,"n":"第一千二百二十四条","txt":"违反本法规定，生产经营者未遵守限制商品过度包装的强制性标准的，由市场监督管理部门和有关部门按照职责分工责令改正；拒不改正的，处二千元以上二万元以下的罚款；情节严重的，处二万元以上十万元以下的罚款。"},{"i":1225,"n":"第一千二百二十五条","txt":"违反本法规定，未遵守国家有关禁止、限制生产、销售不可降解塑料袋等一次性塑料制品的规定的，由市场监督管理部门责令停止生产、销售，没收违法生产、销售的产品，并处违法生产、销售产品货值金额一倍以上三倍以下的罚款；有违法所得的，没收违法所得；情节严重的，吊销许可证。"},{"i":1226,"n":"第一千二百二十六条","txt":"违反本法规定，纳入全国碳排放权交易市场的温室气体重点排放单位未报送排放统计核算数据、年度排放报告的，由生态环境主管部门责令改正，处五万元以上五十万元以下的罚款；拒不改正的，可以责令停产整治。"},{"i":1227,"n":"第一千二百二十七条","txt":"违反本法有关绿色低碳义务，本节未规定行政处罚的，依照《中华人民共和国循环经济促进法》、《中华人民共和国能源法》、《中华人民共和国节约能源法》、《中华人民共和国可再生能源法》等法律法规的规定予以处罚。"},{"i":1228,"n":"第一千二百二十八条","txt":"除本章第一节至第十三节外，违反本法规定的，适用本节规定予以行政处罚。"},{"i":1229,"n":"第一千二百二十九条","txt":"违反本法规定，以拖延、围堵、滞留执法人员等方式拒绝、阻挠监督检查和突发生态环境事件调查处理，或者在接受监督检查和调查处理时弄虚作假或者拒不提供必要资料的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处五万元以上二十万元以下的罚款；对直接负责的主管人员和其他直接责任人员，处五千元以上五万元以下的罚款；构成违反治安管理行为的，由公安机关、海警机构按照职责分工依法予以处罚。"},{"i":1230,"n":"第一千二百三十条","txt":"违反本法规定，从事机动车船排放检验、土壤污染调查和评估、污染防治设施维护或者运营、固体废物或者危险废物鉴别等活动的生态环境技术服务机构，未使用符合法律、行政法规规定和国家标准的设施、设备，或者未遵守有关技术规范导致数据失真的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，没收违法所得，并处二万元以上二十万元以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业。"},{"i":1231,"n":"第一千二百三十一条","txt":"违反本法规定，有下列情形之一的，由生态环境主管部门、环境卫生主管部门按照职责分工责令改正，可以处十万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭："},{"i":1232,"n":"第一千二百三十二条","txt":"违反本法规定，经中华人民共和国过境转移危险废物，以及将放射性废物和被放射性污染的物品输入中华人民共和国境内或者经境内转移的，由海关、海事管理机构按照职责分工责令退运或者责令非法运输该危险废物的船舶退出中华人民共和国管辖海域，并处五十万元以上五百万元以下的罚款。"},{"i":1233,"n":"第一千二百三十三条","txt":"违反本法规定，排放污染物的企业事业单位未建立污染防治责任制度的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正；拒不改正的，处二万元以上二十万元以下的罚款；情节严重的，可以责令限制生产、停产整治。"},{"i":1234,"n":"第一千二百三十四条","txt":"违反本法规定，未按照生态环境准入清单的规定进行生产建设活动的，由生态环境主管部门、自然资源主管部门按照职责分工，责令停止违法行为，没收违法所得，限期拆除并恢复原状，所需费用由违法者承担，并处五十万元以上五百万元以下的罚款，对直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。"},{"i":1235,"n":"第一千二百三十五条","txt":"违反本法规定，企业事业单位和其他生产经营者有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正；情节严重的，处一万元以上五万元以下的罚款："},{"i":1236,"n":"第一千二百三十六条","txt":"违反本法规定，造成环境污染、生态破坏事故的，除依法承担赔偿责任外，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令限期采取治理措施，适用本条第二款、第三款的规定处以罚款；对直接负责的主管人员和其他直接责任人员可以处上一年度从本企业事业单位取得收入百分之五十以下的罚款；对造成重大或者特别重大环境污染、生态破坏事故的，报经有批准权的人民政府批准，责令停业、关闭。未按照要求采取治理措施的，指定有治理能力的单位代为治理，所需费用由违法者承担。"},{"i":1237,"n":"第一千二百三十七条","txt":"违反本法规定，因发生事故或者其他突发性事件，造成或者可能造成环境污染、生态破坏事件，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款："},{"i":1238,"n":"第一千二百三十八条","txt":"违反本法规定，对举报人以解除、变更劳动合同、聘用合同或者以其他方式打击报复的，应当依照有关法律的规定承担责任。"},{"i":1239,"n":"第一千二百三十九条","txt":"其他法律对生态保护、绿色低碳发展等生态环境保护相关领域有具体或者进一步规定的，适用其规定。"},{"i":1240,"n":"第一千二百四十条","txt":"国家根据实际需要，对生态环境监督管理体制作出调整的，依照其规定。"},{"i":1241,"n":"第一千二百四十一条","txt":"国务院、中央军事委员会可以依照本法规定的原则制定有关军队生态环境保护工作的具体管理办法。"},{"i":1242,"n":"第一千二百四十二条","txt":"本法自2026年8月15日起施行。《中华人民共和国环境保护法》、《中华人民共和国环境影响评价法》、《中华人民共和国海洋环境保护法》、《中华人民共和国大气污染防治法》、《中华人民共和国水污染防治法》、《中华人民共和国土壤污染防治法》、《中华人民共和国固体废物污染环境防治法》、《中华人民共和国噪声污染防治法》、《中华人民共和国放射性污染防治法》、《中华人民共和国清洁生产促进法》同时废止。"}],"shengwuanquanfa":[{"i":1,"n":"第一条","txt":"为了维护国家安全，防范和应对生物安全风险，保障人民生命健康，保护生物资源和生态环境，促进生物技术健康发展，推动构建人类命运共同体，实现人与自然和谐共生，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称生物安全，是指国家有效防范和应对危险生物因子及相关因素威胁，生物技术能够稳定健康发展，人民生命健康和生态系统相对处于没有危险和不受威胁的状态，生物领域具备维护国家安全和持续发展的能力。"},{"i":3,"n":"第三条","txt":"生物安全是国家安全的重要组成部分。维护生物安全应当贯彻总体国家安全观，统筹发展和安全，坚持以人为本、风险预防、分类管理、协同配合的原则。"},{"i":4,"n":"第四条","txt":"坚持中国共产党对国家生物安全工作的领导，建立健全国家生物安全领导体制，加强国家生物安全风险防控和治理体系建设，提高国家生物安全治理能力。"},{"i":5,"n":"第五条","txt":"国家鼓励生物科技创新，加强生物安全基础设施和生物科技人才队伍建设，支持生物产业发展，以创新驱动提升生物科技水平，增强生物安全保障能力。"},{"i":6,"n":"第六条","txt":"国家加强生物安全领域的国际合作，履行中华人民共和国缔结或者参加的国际条约规定的义务，支持参与生物科技交流合作与生物安全事件国际救援，积极参与生物安全国际规则的研究与制定，推动完善全球生物安全治理。"},{"i":7,"n":"第七条","txt":"各级人民政府及其有关部门应当加强生物安全法律法规和生物安全知识宣传普及工作，引导基层群众性自治组织、社会组织开展生物安全法律法规和生物安全知识宣传，促进全社会生物安全意识的提升。"},{"i":8,"n":"第八条","txt":"任何单位和个人不得危害生物安全。"},{"i":9,"n":"第九条","txt":"对在生物安全工作中做出突出贡献的单位和个人，县级以上人民政府及其有关部门按照国家规定予以表彰和奖励。"},{"i":10,"n":"第十条","txt":"中央国家安全领导机构负责国家生物安全工作的决策和议事协调，研究制定、指导实施国家生物安全战略和有关重大方针政策，统筹协调国家生物安全的重大事项和重要工作，建立国家生物安全工作协调机制。"},{"i":11,"n":"第十一条","txt":"国家生物安全工作协调机制由国务院卫生健康、农业农村、科学技术、外交等主管部门和有关军事机关组成，分析研判国家生物安全形势，组织协调、督促推进国家生物安全相关工作。国家生物安全工作协调机制设立办公室，负责协调机制的日常工作。"},{"i":12,"n":"第十二条","txt":"国家生物安全工作协调机制设立专家委员会，为国家生物安全战略研究、政策制定及实施提供决策咨询。"},{"i":13,"n":"第十三条","txt":"地方各级人民政府对本行政区域内生物安全工作负责。"},{"i":14,"n":"第十四条","txt":"国家建立生物安全风险监测预警制度。国家生物安全工作协调机制组织建立国家生物安全风险监测预警体系，提高生物安全风险识别和分析能力。"},{"i":15,"n":"第十五条","txt":"国家建立生物安全风险调查评估制度。国家生物安全工作协调机制应当根据风险监测的数据、资料等信息，定期组织开展生物安全风险调查评估。"},{"i":16,"n":"第十六条","txt":"国家建立生物安全信息共享制度。国家生物安全工作协调机制组织建立统一的国家生物安全信息平台，有关部门应当将生物安全数据、资料等信息汇交国家生物安全信息平台，实现信息共享。"},{"i":17,"n":"第十七条","txt":"国家建立生物安全信息发布制度。国家生物安全总体情况、重大生物安全风险警示信息、重大生物安全事件及其调查处理信息等重大生物安全信息，由国家生物安全工作协调机制成员单位根据职责分工发布；其他生物安全信息由国务院有关部门和县级以上地方人民政府及其有关部门根据职责权限发布。"},{"i":18,"n":"第十八条","txt":"国家建立生物安全名录和清单制度。国务院及其有关部门根据生物安全工作需要，对涉及生物安全的材料、设备、技术、活动、重要生物资源数据、传染病、动植物疫病、外来入侵物种等制定、公布名录或者清单，并动态调整。"},{"i":19,"n":"第十九条","txt":"国家建立生物安全标准制度。国务院标准化主管部门和国务院其他有关部门根据职责分工，制定和完善生物安全领域相关标准。"},{"i":20,"n":"第二十条","txt":"国家建立生物安全审查制度。对影响或者可能影响国家安全的生物领域重大事项和活动，由国务院有关部门进行生物安全审查，有效防范和化解生物安全风险。"},{"i":21,"n":"第二十一条","txt":"国家建立统一领导、协同联动、有序高效的生物安全应急制度。"},{"i":22,"n":"第二十二条","txt":"国家建立生物安全事件调查溯源制度。发生重大新发突发传染病、动植物疫情和不明原因的生物安全事件，国家生物安全工作协调机制应当组织开展调查溯源，确定事件性质，全面评估事件影响，提出意见建议。"},{"i":23,"n":"第二十三条","txt":"国家建立首次进境或者暂停后恢复进境的动植物、动植物产品、高风险生物因子国家准入制度。"},{"i":24,"n":"第二十四条","txt":"国家建立境外重大生物安全事件应对制度。境外发生重大生物安全事件的，海关依法采取生物安全紧急防控措施，加强证件核验，提高查验比例，暂停相关人员、运输工具、货物、物品等进境。必要时经国务院同意，可以采取暂时关闭有关口岸、封锁有关国境等措施。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府有关部门应当依法开展生物安全监督检查工作，被检查单位和个人应当配合，如实说明情况，提供资料，不得拒绝、阻挠。"},{"i":26,"n":"第二十六条","txt":"县级以上人民政府有关部门实施生物安全监督检查，可以依法采取下列措施："},{"i":27,"n":"第二十七条","txt":"国务院卫生健康、农业农村、林业草原、海关、生态环境主管部门应当建立新发突发传染病、动植物疫情、进出境检疫、生物技术环境安全监测网络，组织监测站点布局、建设，完善监测信息报告系统，开展主动监测和病原检测，并纳入国家生物安全风险监测预警体系。"},{"i":28,"n":"第二十八条","txt":"疾病预防控制机构、动物疫病预防控制机构、植物病虫害预防控制机构（以下统称专业机构）应当对传染病、动植物疫病和列入监测范围的不明原因疾病开展主动监测，收集、分析、报告监测信息，预测新发突发传染病、动植物疫病的发生、流行趋势。"},{"i":29,"n":"第二十九条","txt":"任何单位和个人发现传染病、动植物疫病的，应当及时向医疗机构、有关专业机构或者部门报告。"},{"i":30,"n":"第三十条","txt":"国家建立重大新发突发传染病、动植物疫情联防联控机制。"},{"i":31,"n":"第三十一条","txt":"国家加强国境、口岸传染病和动植物疫情联合防控能力建设，建立传染病、动植物疫情防控国际合作网络，尽早发现、控制重大新发突发传染病、动植物疫情。"},{"i":32,"n":"第三十二条","txt":"国家保护野生动物，加强动物防疫，防止动物源性传染病传播。"},{"i":33,"n":"第三十三条","txt":"国家加强对抗生素药物等抗微生物药物使用和残留的管理，支持应对微生物耐药的基础研究和科技攻关。"},{"i":34,"n":"第三十四条","txt":"国家加强对生物技术研究、开发与应用活动的安全管理，禁止从事危及公众健康、损害生物资源、破坏生态系统和生物多样性等危害生物安全的生物技术研究、开发与应用活动。"},{"i":35,"n":"第三十五条","txt":"从事生物技术研究、开发与应用活动的单位应当对本单位生物技术研究、开发与应用的安全负责，采取生物安全风险防控措施，制定生物安全培训、跟踪检查、定期报告等工作制度，强化过程管理。"},{"i":36,"n":"第三十六条","txt":"国家对生物技术研究、开发活动实行分类管理。根据对公众健康、工业农业、生态环境等造成危害的风险程度，将生物技术研究、开发活动分为高风险、中风险、低风险三类。"},{"i":37,"n":"第三十七条","txt":"从事生物技术研究、开发活动，应当遵守国家生物技术研究开发安全管理规范。"},{"i":38,"n":"第三十八条","txt":"从事高风险、中风险生物技术研究、开发活动，应当由在我国境内依法成立的法人组织进行，并依法取得批准或者进行备案。"},{"i":39,"n":"第三十九条","txt":"国家对涉及生物安全的重要设备和特殊生物因子实行追溯管理。购买或者引进列入管控清单的重要设备和特殊生物因子，应当进行登记，确保可追溯，并报国务院有关部门备案。"},{"i":40,"n":"第四十条","txt":"从事生物医学新技术临床研究，应当通过伦理审查，并在具备相应条件的医疗机构内进行；进行人体临床研究操作的，应当由符合相应条件的卫生专业技术人员执行。"},{"i":41,"n":"第四十一条","txt":"国务院有关部门依法对生物技术应用活动进行跟踪评估，发现存在生物安全风险的，应当及时采取有效补救和管控措施。"},{"i":42,"n":"第四十二条","txt":"国家加强对病原微生物实验室生物安全的管理，制定统一的实验室生物安全标准。病原微生物实验室应当符合生物安全国家标准和要求。"},{"i":43,"n":"第四十三条","txt":"国家根据病原微生物的传染性、感染后对人和动物的个体或者群体的危害程度，对病原微生物实行分类管理。"},{"i":44,"n":"第四十四条","txt":"设立病原微生物实验室，应当依法取得批准或者进行备案。"},{"i":45,"n":"第四十五条","txt":"国家根据对病原微生物的生物安全防护水平，对病原微生物实验室实行分等级管理。"},{"i":46,"n":"第四十六条","txt":"高等级病原微生物实验室从事高致病性或者疑似高致病性病原微生物实验活动，应当经省级以上人民政府卫生健康或者农业农村主管部门批准，并将实验活动情况向批准部门报告。"},{"i":47,"n":"第四十七条","txt":"病原微生物实验室应当采取措施，加强对实验动物的管理，防止实验动物逃逸，对使用后的实验动物按照国家规定进行无害化处理，实现实验动物可追溯。禁止将使用后的实验动物流入市场。"},{"i":48,"n":"第四十八条","txt":"病原微生物实验室的设立单位负责实验室的生物安全管理，制定科学、严格的管理制度，定期对有关生物安全规定的落实情况进行检查，对实验室设施、设备、材料等进行检查、维护和更新，确保其符合国家标准。"},{"i":49,"n":"第四十九条","txt":"病原微生物实验室的设立单位应当建立和完善安全保卫制度，采取安全保卫措施，保障实验室及其病原微生物的安全。"},{"i":50,"n":"第五十条","txt":"病原微生物实验室的设立单位应当制定生物安全事件应急预案，定期组织开展人员培训和应急演练。发生高致病性病原微生物泄漏、丢失和被盗、被抢或者其他生物安全风险的，应当按照应急预案的规定及时采取控制措施，并按照国家规定报告。"},{"i":51,"n":"第五十一条","txt":"病原微生物实验室所在地省级人民政府及其卫生健康主管部门应当加强实验室所在地感染性疾病医疗资源配置，提高感染性疾病医疗救治能力。"},{"i":52,"n":"第五十二条","txt":"企业对涉及病原微生物操作的生产车间的生物安全管理，依照有关病原微生物实验室的规定和其他生物安全管理规范进行。"},{"i":53,"n":"第五十三条","txt":"国家加强对我国人类遗传资源和生物资源采集、保藏、利用、对外提供等活动的管理和监督，保障人类遗传资源和生物资源安全。"},{"i":54,"n":"第五十四条","txt":"国家开展人类遗传资源和生物资源调查。"},{"i":55,"n":"第五十五条","txt":"采集、保藏、利用、对外提供我国人类遗传资源，应当符合伦理原则，不得危害公众健康、国家安全和社会公共利益。"},{"i":56,"n":"第五十六条","txt":"从事下列活动，应当经国务院卫生健康主管部门批准："},{"i":57,"n":"第五十七条","txt":"将我国人类遗传资源信息向境外组织、个人及其设立或者实际控制的机构提供或者开放使用的，应当向国务院卫生健康主管部门事先报告并提交信息备份。"},{"i":58,"n":"第五十八条","txt":"采集、保藏、利用、运输出境我国珍贵、濒危、特有物种及其可用于再生或者繁殖传代的个体、器官、组织、细胞、基因等遗传资源，应当遵守有关法律法规。"},{"i":59,"n":"第五十九条","txt":"利用我国生物资源开展国际科学研究合作，应当依法取得批准。"},{"i":60,"n":"第六十条","txt":"国家加强对外来物种入侵的防范和应对，保护生物多样性。国务院农业农村主管部门会同国务院其他有关部门制定外来入侵物种名录和管理办法。"},{"i":61,"n":"第六十一条","txt":"国家采取一切必要措施防范生物恐怖与生物武器威胁。"},{"i":62,"n":"第六十二条","txt":"国务院有关部门制定、修改、公布可被用于生物恐怖活动、制造生物武器的生物体、生物毒素、设备或者技术清单，加强监管，防止其被用于制造生物武器或者恐怖目的。"},{"i":63,"n":"第六十三条","txt":"国务院有关部门和有关军事机关根据职责分工，加强对可被用于生物恐怖活动、制造生物武器的生物体、生物毒素、设备或者技术进出境、进出口、获取、制造、转移和投放等活动的监测、调查，采取必要的防范和处置措施。"},{"i":64,"n":"第六十四条","txt":"国务院有关部门、省级人民政府及其有关部门负责组织遭受生物恐怖袭击、生物武器攻击后的人员救治与安置、环境消毒、生态修复、安全监测和社会秩序恢复等工作。"},{"i":65,"n":"第六十五条","txt":"国家组织开展对我国境内战争遗留生物武器及其危害结果、潜在影响的调查。"},{"i":66,"n":"第六十六条","txt":"国家制定生物安全事业发展规划，加强生物安全能力建设，提高应对生物安全事件的能力和水平。"},{"i":67,"n":"第六十七条","txt":"国家采取措施支持生物安全科技研究，加强生物安全风险防御与管控技术研究，整合优势力量和资源，建立多学科、多部门协同创新的联合攻关机制，推动生物安全核心关键技术和重大防御产品的成果产出与转化应用，提高生物安全的科技保障能力。"},{"i":68,"n":"第六十八条","txt":"国家统筹布局全国生物安全基础设施建设。国务院有关部门根据职责分工，加快建设生物信息、人类遗传资源保藏、菌（毒）种保藏、动植物遗传资源保藏、高等级病原微生物实验室等方面的生物安全国家战略资源平台，建立共享利用机制，为生物安全科技创新提供战略保障和支撑。"},{"i":69,"n":"第六十九条","txt":"国务院有关部门根据职责分工，加强生物基础科学研究人才和生物领域专业技术人才培养，推动生物基础科学学科建设和科学研究。"},{"i":70,"n":"第七十条","txt":"国家加强重大新发突发传染病、动植物疫情等生物安全风险防控的物资储备。"},{"i":71,"n":"第七十一条","txt":"国家对从事高致病性病原微生物实验活动、生物安全事件现场处置等高风险生物安全工作的人员，提供有效的防护措施和医疗保障。"},{"i":72,"n":"第七十二条","txt":"违反本法规定，履行生物安全管理职责的工作人员在生物安全工作中滥用职权、玩忽职守、徇私舞弊或者有其他违法行为的，依法给予处分。"},{"i":73,"n":"第七十三条","txt":"违反本法规定，医疗机构、专业机构或者其工作人员瞒报、谎报、缓报、漏报，授意他人瞒报、谎报、缓报，或者阻碍他人报告传染病、动植物疫病或者不明原因的聚集性疾病的，由县级以上人民政府有关部门责令改正，给予警告；对法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员，依法给予处分，并可以依法暂停一定期限的执业活动直至吊销相关执业证书。"},{"i":74,"n":"第七十四条","txt":"违反本法规定，从事国家禁止的生物技术研究、开发与应用活动的，由县级以上人民政府卫生健康、科学技术、农业农村主管部门根据职责分工，责令停止违法行为，没收违法所得、技术资料和用于违法行为的工具、设备、原材料等物品，处一百万元以上一千万元以下的罚款，违法所得在一百万元以上的，处违法所得十倍以上二十倍以下的罚款，并可以依法禁止一定期限内从事相应的生物技术研究、开发与应用活动，吊销相关许可证件；对法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员，依法给予处分，处十万元以上二十万元以下的罚款，十年直至终身禁止从事相应的生物技术研究、开发与应用活动，依法吊销相关执业证书。"},{"i":75,"n":"第七十五条","txt":"违反本法规定，从事生物技术研究、开发活动未遵守国家生物技术研究开发安全管理规范的，由县级以上人民政府有关部门根据职责分工，责令改正，给予警告，可以并处二万元以上二十万元以下的罚款；拒不改正或者造成严重后果的，责令停止研究、开发活动，并处二十万元以上二百万元以下的罚款。"},{"i":76,"n":"第七十六条","txt":"违反本法规定，从事病原微生物实验活动未在相应等级的实验室进行，或者高等级病原微生物实验室未经批准从事高致病性、疑似高致病性病原微生物实验活动的，由县级以上地方人民政府卫生健康、农业农村主管部门根据职责分工，责令停止违法行为，监督其将用于实验活动的病原微生物销毁或者送交保藏机构，给予警告；造成传染病传播、流行或者其他严重后果的，对法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员依法给予撤职、开除处分。"},{"i":77,"n":"第七十七条","txt":"违反本法规定，将使用后的实验动物流入市场的，由县级以上人民政府科学技术主管部门责令改正，没收违法所得，并处二十万元以上一百万元以下的罚款，违法所得在二十万元以上的，并处违法所得五倍以上十倍以下的罚款；情节严重的，由发证部门吊销相关许可证件。"},{"i":78,"n":"第七十八条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府有关部门根据职责分工，责令改正，没收违法所得，给予警告，可以并处十万元以上一百万元以下的罚款："},{"i":79,"n":"第七十九条","txt":"违反本法规定，未经批准，采集、保藏我国人类遗传资源或者利用我国人类遗传资源开展国际科学研究合作的，由国务院卫生健康主管部门责令停止违法行为，没收违法所得和违法采集、保藏的人类遗传资源，并处五十万元以上五百万元以下的罚款，违法所得在一百万元以上的，并处违法所得五倍以上十倍以下的罚款；情节严重的，对法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员，依法给予处分，五年内禁止从事相应活动。"},{"i":80,"n":"第八十条","txt":"违反本法规定，境外组织、个人及其设立或者实际控制的机构在我国境内采集、保藏我国人类遗传资源，或者向境外提供我国人类遗传资源的，由国务院卫生健康主管部门责令停止违法行为，没收违法所得和违法采集、保藏的人类遗传资源，并处一百万元以上一千万元以下的罚款；违法所得在一百万元以上的，并处违法所得十倍以上二十倍以下的罚款。"},{"i":81,"n":"第八十一条","txt":"违反本法规定，未经批准，擅自引进外来物种的，由县级以上人民政府有关部门根据职责分工，没收引进的外来物种，并处五万元以上二十五万元以下的罚款。"},{"i":82,"n":"第八十二条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任；造成人身、财产或者其他损害的，依法承担民事责任。"},{"i":83,"n":"第八十三条","txt":"违反本法规定的生物安全违法行为，本法未规定法律责任，其他有关法律、行政法规有规定的，依照其规定。"},{"i":84,"n":"第八十四条","txt":"境外组织或者个人通过运输、邮寄、携带危险生物因子入境或者以其他方式危害我国生物安全的，依法追究法律责任，并可以采取其他必要措施。"},{"i":85,"n":"第八十五条","txt":"本法下列术语的含义："},{"i":86,"n":"第八十六条","txt":"生物安全信息属于国家秘密的，应当依照《中华人民共和国保守国家秘密法》和国家其他有关保密规定实施保密管理。"},{"i":87,"n":"第八十七条","txt":"中国人民解放军、中国人民武装警察部队的生物安全活动，由中央军事委员会依照本法规定的原则另行规定。"},{"i":88,"n":"第八十八条","txt":"本法自2021年4月15日起施行。"}],"kuangchanziyuanfa":[{"i":1,"n":"第一条","txt":"为了促进矿产资源合理开发利用，加强矿产资源和生态环境保护，维护矿产资源国家所有者权益和矿业权人合法权益，推动矿业高质量发展，保障国家矿产资源安全，适应全面建设社会主义现代化国家的需要，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域及管辖的其他海域勘查、开采矿产资源，开展矿区生态修复等活动，适用本法。"},{"i":3,"n":"第三条","txt":"矿产资源开发利用和保护工作应当坚持中国共产党的领导，贯彻总体国家安全观，统筹发展和安全，统筹国内国际，坚持开发利用与保护并重，遵循保障安全、节约集约、科技支撑、绿色发展的原则。"},{"i":4,"n":"第四条","txt":"矿产资源属于国家所有，由国务院代表国家行使矿产资源的所有权。地表或者地下的矿产资源的国家所有权，不因其所依附的土地的所有权或者使用权的不同而改变。"},{"i":5,"n":"第五条","txt":"勘查、开采矿产资源应当依法分别取得探矿权、采矿权，本法另有规定的除外。"},{"i":6,"n":"第六条","txt":"勘查、开采矿产资源应当按照国家有关规定缴纳费用。国务院可以根据不同情况规定减收或者免收有关费用。"},{"i":7,"n":"第七条","txt":"国家建立健全地质调查制度，加强基础性地质调查工作，为矿产资源勘查、开采和保护等提供基础地质资料。"},{"i":8,"n":"第八条","txt":"国家完善政策措施，加大对战略性矿产资源勘查、开采、贸易、储备等的支持力度，推动战略性矿产资源增加储量和提高产能，推进战略性矿产资源产业优化升级，提升矿产资源安全保障水平。"},{"i":9,"n":"第九条","txt":"国家对矿产资源勘查、开采实行统一规划、合理布局、综合勘查、合理开采和综合利用的方针。"},{"i":10,"n":"第十条","txt":"国家加强战略性矿产资源储备体系和矿产资源应急体系建设，提升矿产资源应急保供能力和水平。"},{"i":11,"n":"第十一条","txt":"国家鼓励、支持矿产资源勘查、开采、保护和矿区生态修复等领域的科技创新、科技成果应用推广，推动数字化、智能化、绿色化建设，提高矿产资源相关领域的科学技术水平。"},{"i":12,"n":"第十二条","txt":"对在矿产资源勘查、开采、保护和矿区生态修复工作中做出突出贡献以及在矿产资源相关领域科技创新等方面取得显著成绩的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":13,"n":"第十三条","txt":"国家在民族自治地方开采矿产资源，应当照顾民族自治地方的利益，作出有利于民族自治地方经济建设的安排，照顾当地群众的生产和生活。"},{"i":14,"n":"第十四条","txt":"国务院自然资源主管部门会同有关部门负责全国矿产资源勘查、开采和矿区生态修复等活动的监督管理工作。"},{"i":15,"n":"第十五条","txt":"国家坚持平等互利、合作共赢的方针，积极促进矿产资源领域国际合作。"},{"i":16,"n":"第十六条","txt":"国家实行探矿权、采矿权有偿取得的制度。"},{"i":17,"n":"第十七条","txt":"矿业权应当通过招标、拍卖、挂牌等竞争性方式出让，法律、行政法规或者国务院规定可以通过协议出让或者其他方式设立的除外。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府自然资源主管部门应当加强对矿业权出让工作的统筹安排，优化矿业权出让工作流程，提高工作效率，保障矿业权出让工作与加强矿产资源勘查、开采的实际需要相适应。矿业权出让应当考虑不同矿产资源特点、矿山最低开采规模、生态环境保护和安全要求等因素。"},{"i":19,"n":"第十九条","txt":"通过竞争性方式出让矿业权的，出让矿业权的自然资源主管部门（以下称矿业权出让部门）应当提前公告拟出让矿业权的基本情况、竞争规则、受让人的技术能力等条件及其权利义务等事项，不得以不合理的条件对市场主体实行差别待遇或者歧视待遇。"},{"i":20,"n":"第二十条","txt":"出让矿业权的，矿业权出让部门应当与依法确定的受让人以书面形式签订矿业权出让合同。"},{"i":21,"n":"第二十一条","txt":"矿业权出让合同约定的矿业权出让收益数额与缴纳方式等，应当符合国家有关矿业权出让收益征收的规定。"},{"i":22,"n":"第二十二条","txt":"设立矿业权的，应当向矿业权出让部门申请矿业权登记。符合登记条件的，矿业权出让部门应当将相关事项记载于矿业权登记簿，并向矿业权人发放矿业权证书。"},{"i":23,"n":"第二十三条","txt":"探矿权人在登记的勘查区域内，享有勘查有关矿产资源并依法取得采矿权的权利。"},{"i":24,"n":"第二十四条","txt":"探矿权的期限为五年。探矿权期限届满，可以续期，续期最多不超过三次，每次期限为五年；续期时应当按照规定核减勘查区域面积。法律、行政法规另有规定的除外。"},{"i":25,"n":"第二十五条","txt":"探矿权人探明可供开采的矿产资源后可以在探矿权期限内申请将其探矿权转为采矿权；法律、行政法规另有规定的除外。原矿业权出让部门应当与该探矿权人签订采矿权出让合同，设立采矿权。"},{"i":26,"n":"第二十六条","txt":"矿业权期限届满前，为了公共利益的需要，原矿业权出让部门可以依法收回矿业权；矿业权被收回的，应当依法给予公平、合理的补偿。"},{"i":27,"n":"第二十七条","txt":"矿业权可以依法转让或者出资、抵押等，国家另有规定或者矿业权出让合同另有约定的除外。"},{"i":28,"n":"第二十八条","txt":"有下列情形之一的，无需取得探矿权："},{"i":29,"n":"第二十九条","txt":"有下列情形之一的，无需取得采矿权："},{"i":30,"n":"第三十条","txt":"县级以上人民政府自然资源主管部门会同有关部门组织开展基础性地质调查；省级以上人民政府自然资源主管部门会同有关部门组织开展战略性矿产资源、重点成矿区远景调查和潜力评价。"},{"i":31,"n":"第三十一条","txt":"开展地质调查和矿产资源勘查、开采活动，应当按照国家有关规定及时汇交原始地质资料、实物地质资料和成果地质资料。"},{"i":32,"n":"第三十二条","txt":"编制国土空间规划应当合理规划建设项目的空间布局，避免、减少压覆矿产资源。"},{"i":33,"n":"第三十三条","txt":"矿业权人依照本法有关规定取得矿业权后，进行矿产资源勘查、开采作业前，应当按照矿业权出让合同以及相关标准、技术规范等，分别编制勘查方案、开采方案，报原矿业权出让部门批准，取得勘查许可证、采矿许可证；未取得许可证的，不得进行勘查、开采作业。"},{"i":34,"n":"第三十四条","txt":"国家完善与矿产资源勘查、开采相适应的矿业用地制度。编制国土空间规划应当考虑矿产资源勘查、开采用地实际需求。勘查、开采矿产资源应当节约集约使用土地。"},{"i":35,"n":"第三十五条","txt":"矿业权所在地的县级人民政府自然资源主管部门应当公告矿业权人勘查、开采区域范围。矿业权人在勘查、开采区域内勘查、开采矿产资源，可以依法在相邻区域通行，架设供电、供水、通讯等相关设施。"},{"i":36,"n":"第三十六条","txt":"石油、天然气等矿产资源勘查过程中发现可供开采的石油、天然气等矿产资源的，探矿权人依法履行相关程序后，可以进行开采，但应当在国务院自然资源主管部门规定的期限内依法取得采矿权和采矿许可证。"},{"i":37,"n":"第三十七条","txt":"国家鼓励、支持矿业绿色低碳转型发展，加强绿色矿山建设。"},{"i":38,"n":"第三十八条","txt":"勘查活动结束后，探矿权人应当及时对勘查区域进行清理，清除可能危害公共安全的设施、设备等，对废弃的探坑、探井等实施回填、封堵；破坏地表植被的，应当及时恢复。"},{"i":39,"n":"第三十九条","txt":"开采矿产资源，应当采取合理的开采顺序、开采方法，并采取有效措施确保矿产资源开采回采率、选矿回收率和综合利用率达到有关国家标准的要求。"},{"i":40,"n":"第四十条","txt":"国家建立矿产资源储量管理制度，具体办法由国务院制定。"},{"i":41,"n":"第四十一条","txt":"采矿权人应当按照国家有关规定将闭坑地质报告报送县级以上地方人民政府自然资源主管部门。"},{"i":42,"n":"第四十二条","txt":"勘查、开采矿产资源，应当遵守有关生态环境保护、安全生产、职业病防治等法律、法规的规定，防止污染环境、破坏生态，预防和减少生产安全事故，预防发生职业病。"},{"i":43,"n":"第四十三条","txt":"勘查、开采矿产资源时发现重要地质遗迹、古生物化石和文物的，应当加以保护并及时报告有关部门。"},{"i":44,"n":"第四十四条","txt":"矿区生态修复应当坚持自然恢复与人工修复相结合，遵循因地制宜、科学规划、系统治理、合理利用的原则，采取工程、技术、生物等措施，做好地质环境恢复治理、地貌重塑、植被恢复、土地复垦等。涉及矿区污染治理的，应当遵守相关法律法规和技术标准等要求。"},{"i":45,"n":"第四十五条","txt":"因开采矿产资源导致矿区生态破坏的，采矿权人应当依法履行生态修复义务。采矿权人的生态修复义务不因采矿权消灭而免除。"},{"i":46,"n":"第四十六条","txt":"开采矿产资源前，采矿权人应当依照法律、法规和国务院自然资源主管部门的规定以及矿业权出让合同编制矿区生态修复方案，随开采方案报原矿业权出让部门批准。矿区生态修复方案应当包括尾矿库生态修复的专门措施。"},{"i":47,"n":"第四十七条","txt":"采矿权人应当按照经批准的矿区生态修复方案进行矿区生态修复。能够边开采、边修复的，应当边开采、边修复；能够分区、分期修复的，应当分区、分期修复；不能边开采、边修复或者分区、分期修复的，应当在矿山闭坑前或者闭坑后的合理期限内及时修复。"},{"i":48,"n":"第四十八条","txt":"矿区生态修复由县级以上地方人民政府自然资源主管部门会同生态环境主管部门等有关部门组织验收。验收应当邀请有关专家以及矿区涉及的居民委员会、村民委员会、农村集体经济组织和居民代表、村民代表参加，验收结果应当向社会公布。"},{"i":49,"n":"第四十九条","txt":"采矿权人应当按照规定提取矿区生态修复费用，专门用于矿区生态修复。矿区生态修复费用计入成本。"},{"i":50,"n":"第五十条","txt":"国家构建产品储备、产能储备和产地储备相结合的战略性矿产资源储备体系，科学合理确定储备结构、规模和布局并动态调整。"},{"i":51,"n":"第五十一条","txt":"国务院发展改革、财政、物资储备、能源等有关部门和省、自治区、直辖市人民政府应当按照国家有关规定加强战略性矿产资源储备设施建设，组织实施矿产品储备，建立灵活高效的收储、轮换、动用机制。"},{"i":52,"n":"第五十二条","txt":"开采战略性矿产资源的采矿权人应当按照国家有关规定，落实产能储备责任，合理规划生产能力，确保应急增产需要。"},{"i":53,"n":"第五十三条","txt":"国务院自然资源主管部门会同有关部门，根据保障国家矿产资源安全需要，结合资源储量、分布情况及其稀缺和重要程度等因素，划定战略性矿产资源储备地。"},{"i":54,"n":"第五十四条","txt":"国家建立和完善矿产资源供应安全预测预警体系，提高预测预警能力和水平，及时对矿产品供求变化、价格波动以及安全风险状况等进行预测预警。"},{"i":55,"n":"第五十五条","txt":"出现矿产品供需严重失衡、经济社会发展和人民生活受到重大影响等矿产资源应急状态的，省级以上人民政府应当按照职责权限及时启动应急响应，可以依法采取下列应急处置措施："},{"i":56,"n":"第五十六条","txt":"县级以上人民政府自然资源主管部门和其他有关部门应当按照职责分工，加强对矿产资源勘查、开采和矿区生态修复等活动的监督检查，依法及时查处违法行为。"},{"i":57,"n":"第五十七条","txt":"县级以上人民政府自然资源主管部门和其他有关部门实施监督检查，可以采取下列措施："},{"i":58,"n":"第五十八条","txt":"国家建立矿产资源开发利用水平调查评估制度。"},{"i":59,"n":"第五十九条","txt":"国务院自然资源主管部门建立全国矿业权分布底图和动态数据库。"},{"i":60,"n":"第六十条","txt":"县级以上人民政府自然资源主管部门应当按照国家有关规定，将矿业权人和从事矿区生态修复等活动的其他单位和个人的信用信息记入信用记录。"},{"i":61,"n":"第六十一条","txt":"任何单位和个人对违反矿产资源法律、法规的行为，有权向县级以上人民政府自然资源主管部门和其他有关部门举报，接到举报的部门应当及时依法处理。"},{"i":62,"n":"第六十二条","txt":"县级以上人民政府自然资源主管部门和其他有关部门的工作人员在矿产资源勘查、开采和矿区生态修复等活动的监督管理工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":63,"n":"第六十三条","txt":"违反本法规定，未取得探矿权勘查矿产资源的，由县级以上人民政府自然资源主管部门责令停止违法行为，没收违法所得以及直接用于违法勘查的工具、设备，并处十万元以上一百万元以下罚款；拒不停止违法行为的，可以责令停业整顿。"},{"i":64,"n":"第六十四条","txt":"违反本法规定，未取得采矿权开采矿产资源的，由县级以上人民政府自然资源主管部门责令停止违法行为，没收直接用于违法开采的工具、设备以及违法采出的矿产品，并处违法采出的矿产品市场价值三倍以上五倍以下罚款；没有采出矿产品或者违法采出的矿产品市场价值不足十万元的，并处十万元以上一百万元以下罚款；拒不停止违法行为的，可以责令停业整顿。"},{"i":65,"n":"第六十五条","txt":"违反本法规定，建设项目未经批准压覆战略性矿产资源的，由县级以上人民政府自然资源主管部门责令改正，处十万元以上一百万元以下罚款。"},{"i":66,"n":"第六十六条","txt":"违反本法规定，探矿权人未取得勘查许可证进行矿产资源勘查作业的，由县级以上人民政府自然资源主管部门责令改正；拒不改正的，没收违法所得以及直接用于违法勘查的工具、设备，处十万元以上五十万元以下罚款，并可以责令停业整顿。"},{"i":67,"n":"第六十七条","txt":"违反本法规定，采矿权人未取得采矿许可证进行矿产资源开采作业的，由县级以上人民政府自然资源主管部门责令改正；拒不改正的，没收直接用于违法开采的工具、设备以及违法采出的矿产品，处违法采出的矿产品市场价值一倍以上三倍以下罚款，没有采出矿产品或者违法采出的矿产品市场价值不足十万元的，处十万元以上五十万元以下罚款，并可以责令停业整顿。"},{"i":68,"n":"第六十八条","txt":"违反本法规定，有下列情形之一，造成矿产资源破坏的，由县级以上人民政府自然资源主管部门责令改正，处十万元以上五十万元以下罚款；拒不改正的，可以责令停业整顿；情节严重的，原矿业权出让部门可以吊销其勘查许可证、采矿许可证："},{"i":69,"n":"第六十九条","txt":"违反本法规定，勘查活动结束后探矿权人未及时对勘查区域进行清理或者未及时恢复受到破坏的地表植被的，由县级以上人民政府自然资源主管部门责令改正，可以处五万元以下罚款；拒不改正的，处五万元以上十万元以下罚款，由县级以上人民政府自然资源主管部门确定有关单位代为清理、恢复，所需费用由探矿权人承担。"},{"i":70,"n":"第七十条","txt":"未按照规定汇交地质资料，或者矿业权人未按照规定编制并报送矿产资源储量报告的，由县级以上人民政府自然资源主管部门责令改正，处二万元以上十万元以下罚款；情节严重的，处十万元以上五十万元以下罚款。"},{"i":71,"n":"第七十一条","txt":"违反本法规定，采矿权人不履行矿区生态修复义务或者未按照经批准的矿区生态修复方案进行矿区生态修复的，由县级以上人民政府自然资源主管部门责令改正，可以处矿区生态修复所需费用二倍以下罚款；拒不改正的，处矿区生态修复所需费用二倍以上五倍以下罚款，由县级以上人民政府自然资源主管部门确定有关单位代为修复，所需费用由采矿权人承担。"},{"i":72,"n":"第七十二条","txt":"出现矿产资源应急状态时，有关单位和个人违反本法规定，不服从统一指挥和安排、不承担相应的应急义务或者不配合采取应急处置措施的，由省级以上人民政府自然资源主管部门或者其他有关部门责令改正，给予警告或者通报批评；拒不改正的，对单位处十万元以上五十万元以下罚款，根据情节轻重，可以责令停业整顿或者依法吊销相关许可证件，对个人处一万元以上五万元以下罚款。"},{"i":73,"n":"第七十三条","txt":"违反本法规定，矿业权人拒绝、阻碍监督检查，或者在接受监督检查时弄虚作假的，由县级以上人民政府自然资源主管部门或者其他有关部门责令改正；拒不改正的，处二万元以上十万元以下罚款。"},{"i":74,"n":"第七十四条","txt":"违反本法规定，破坏矿产资源或者污染环境、破坏生态，损害国家利益、社会公共利益的，人民检察院、法律规定的机关和有关组织可以依法向人民法院提起诉讼。"},{"i":75,"n":"第七十五条","txt":"违反本法规定，造成他人人身财产损害或者生态环境损害的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":76,"n":"第七十六条","txt":"勘查、开采矿产资源、开展矿区生态修复，违反有关生态环境保护、安全生产、职业病防治、土地管理、林业草原、文物保护等法律、行政法规的，依照有关法律、行政法规的规定处理、处罚。"},{"i":77,"n":"第七十七条","txt":"外商投资勘查、开采矿产资源，法律、行政法规另有规定的，依照其规定。"},{"i":78,"n":"第七十八条","txt":"中华人民共和国境外的组织和个人，实施危害中华人民共和国国家矿产资源安全行为的，依法追究其法律责任。"},{"i":79,"n":"第七十九条","txt":"中华人民共和国缔结或者参加的国际条约与本法有不同规定的，适用国际条约的规定；但是，中华人民共和国声明保留的条款除外。"},{"i":80,"n":"第八十条","txt":"本法自2025年7月1日起施行。"}],"gengdibaohuhezhiliangtishengfa":[{"i":1,"n":"第一条","txt":"为了加强耕地保护，提升耕地质量，保障国家粮食安全和重要农产品有效供给，推进乡村全面振兴，加快建设农业强国，促进经济社会高质量发展，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"耕地保护和质量提升及其监督管理等活动，适用本法。"},{"i":3,"n":"第三条","txt":"耕地是我国最为宝贵的资源。十分珍惜、合理利用土地和切实保护耕地是我国的基本国策。"},{"i":4,"n":"第四条","txt":"耕地保护和质量提升工作坚持中国共产党的领导，贯彻党和国家路线方针政策和决策部署，遵循量质并重、严格执法、系统推进、永续利用的原则，实行耕地数量、质量、生态一体保护。"},{"i":5,"n":"第五条","txt":"国家建立耕地保护和粮食安全责任制，实行耕地保护和粮食安全党政同责。"},{"i":6,"n":"第六条","txt":"国务院自然资源主管部门、农业农村主管部门按照职责分工，负责全国耕地保护和质量提升的监督管理工作。国务院生态环境、水行政等有关部门按照职责分工，负责全国耕地保护和质量提升的有关监督管理工作。"},{"i":7,"n":"第七条","txt":"县级以上人民政府自然资源主管部门会同同级农业农村等有关部门，根据国土空间规划等，结合实际情况，可以编制耕地保护和质量提升相关专项规划，按程序报批实施。"},{"i":8,"n":"第八条","txt":"县级以上人民政府应当将耕地保护和质量提升工作纳入国民经济和社会发展规划、年度计划，所需经费列入本级预算。"},{"i":9,"n":"第九条","txt":"各级人民政府及其有关部门应当加强耕地保护和质量提升宣传教育，提高全社会的耕地保护和质量提升意识；鼓励村民委员会、农村集体经济组织、农业生产经营者、社会组织、志愿者等开展耕地保护和质量提升法律法规以及相关知识的宣传教育。"},{"i":10,"n":"第十条","txt":"国家鼓励、支持土地整理、土壤改良、地力培肥、水土保持、生态保护等耕地保护和质量提升以及节约集约用地方面的科学研究和科研成果推广应用；鼓励高等学校、科研院所、农业技术推广机构、企业等开展产学研合作，协同进行科技攻关和人才培养。"},{"i":11,"n":"第十一条","txt":"国家采取措施，充分调动农业生产经营者在耕地保护和质量提升中的积极性，保障其合法权益。"},{"i":12,"n":"第十二条","txt":"国家支持开展耕地保护和质量提升国际合作与交流。"},{"i":13,"n":"第十三条","txt":"对在耕地保护和质量提升、节约集约用地以及有关科学研究等工作中做出显著成绩的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":14,"n":"第十四条","txt":"编制国土空间规划应当落实主体功能区战略，统筹布局农业、生态、城镇等功能空间，划定落实耕地和永久基本农田保护红线、生态保护红线和城镇开发边界等，坚持耕地保护优先，明确耕地保有量、永久基本农田保护面积等耕地保护目标，严格控制新增建设用地规模。"},{"i":15,"n":"第十五条","txt":"省、自治区、直辖市人民政府应当确保国土空间规划确定的本行政区域内耕地总量不减少、质量有提升、生态功能稳定；耕地总量减少的，由国务院责令在规定期限内组织补充与所减少耕地的数量和质量相当的耕地；耕地质量降低、生态功能遭到破坏的，由国务院责令在规定期限内组织整治。新补充和整治的耕地由国务院自然资源主管部门会同国务院农业农村主管部门验收。"},{"i":16,"n":"第十六条","txt":"地方各级人民政府应当根据国土空间规划，统筹耕地和林地、草地、园地等其他农用地保护；有条件的地区应当推动在生态适宜的荒山荒坡上种植果树、林木，按照国家规定将地势比较平坦、适宜恢复为优质耕地的其他农用地有序恢复为耕地，逐步优化耕地和林地、草地、园地等其他农用地的空间布局。"},{"i":17,"n":"第十七条","txt":"县级以上人民政府自然资源主管部门应当将耕地保有量、永久基本农田保护面积和布局安排、适宜补充耕地的区域等，纳入国土空间规划实施监督系统并及时更新，对耕地和永久基本农田变动情况进行动态监管和评估预警。"},{"i":18,"n":"第十八条","txt":"国家实行永久基本农田保护制度。下列耕地应当根据国土空间规划划为永久基本农田，实行严格保护："},{"i":19,"n":"第十九条","txt":"下列耕地不得划为永久基本农田，已经划为永久基本农田的，应当根据国土空间规划实施监测评估的结果逐步优化调整："},{"i":20,"n":"第二十条","txt":"永久基本农田划定以乡镇为单位进行，由县级人民政府自然资源主管部门会同同级农业农村主管部门组织实施。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府自然资源、农业农村等主管部门按照职责分工，依法定期组织开展耕地资源和耕地质量调查、监测及评价，适时开展土壤普查和耕地后备资源调查。有关标准和规程由国务院自然资源、农业农村等主管部门按照职责分工制定。自然资源、农业农村等主管部门应当加强信息共享。"},{"i":22,"n":"第二十二条","txt":"国家实行建设用地总量和强度控制，坚持“以补定占”，加强建设占用耕地管理。"},{"i":23,"n":"第二十三条","txt":"非农业建设应当节约使用土地，可以利用荒地的，不得占用耕地；可以利用劣地的，不得占用好地；确需占用土地，涉及耕地转为建设用地的，应当依法办理农用地转用审批手续。"},{"i":24,"n":"第二十四条","txt":"永久基本农田经依法划定后，任何单位和个人不得擅自占用或者改变其用途。国家能源、交通、水利、军事设施等重点建设项目选址确实难以避让永久基本农田，涉及农用地转用或者土地征收的，应当经国务院批准。"},{"i":25,"n":"第二十五条","txt":"禁止占用耕地挖湖造景或者擅自在耕地上绿化造林、种植草皮、堆放固体废物、填埋垃圾，以及从事法律、行政法规规定禁止占用耕地的其他活动。"},{"i":26,"n":"第二十六条","txt":"建设项目确需占用耕地的，应当对占用耕地的必要性、合理性和用地规模进行分析论证，按照有关规定编制建设项目用地综合论证报告。综合论证报告应当作为用地预审申报材料提交审查，审查通过后按照有关规定纳入项目可行性研究报告或者项目申请报告。"},{"i":27,"n":"第二十七条","txt":"国家严格控制耕地转为林地、草地、园地等其他农用地。除法律、行政法规另有规定外，禁止将永久基本农田转为其他农用地；确需将永久基本农田以外的耕地转为其他农用地的，应当尽量选择质量较低、零星分散、难以长期稳定利用的耕地。"},{"i":28,"n":"第二十八条","txt":"国家实行占用耕地补偿制度，将各类占用耕地行为统一纳入耕地占补平衡管理；确需占用耕地的，应当补充与所占用耕地的数量和质量相当的耕地，不得占多补少、占优补劣、占整补散。"},{"i":29,"n":"第二十九条","txt":"县级以上地方人民政府补充耕地应当坚持以恢复优质耕地为主、新开垦耕地为辅的原则，统筹考虑生态保护、水资源等因素，在国土空间规划确定的适宜补充耕地的区域内分类稳妥实施补充耕地。"},{"i":30,"n":"第三十条","txt":"自然保护地、生态保护红线内禁止新开垦耕地。"},{"i":31,"n":"第三十一条","txt":"实施土地开发整理复垦等新增加的耕地符合规定的，可以依法用作补充耕地；质量不达标的，不得用于补充耕地。"},{"i":32,"n":"第三十二条","txt":"建设项目施工和地质勘查需要临时使用土地的，应当尽量不占或者少占耕地、避让永久基本农田，不得修建永久性建筑物。"},{"i":33,"n":"第三十三条","txt":"建设项目占用耕地的，建设单位应当按照省、自治区、直辖市的规定，将所占用耕地耕作层的土壤用于新开垦耕地、劣质地或者其他耕地的土壤改良以及被污染耕地的治理、高标准农田建设、土地复垦等。"},{"i":34,"n":"第三十四条","txt":"国家建立严格的耕地质量建设和保护制度，健全完善耕地质量提升多元投入保障机制，加强高标准农田建设和退化耕地治理，促进耕地质量提升，逐步把具备条件的永久基本农田全部建成高标准农田。"},{"i":35,"n":"第三十五条","txt":"国家完善耕地质量调查评价制度，建立统一的耕地质量评价方法、标准、指标，建立健全耕地质量监测网络体系。"},{"i":36,"n":"第三十六条","txt":"县级以上地方人民政府应当采取综合措施提升本行政区域耕地质量，保护耕地地力。"},{"i":37,"n":"第三十七条","txt":"各级人民政府应当组织完善田间道路、灌排渠系、农电设施、防护林网、农田气象设施等农田基础设施，改善耕地种植条件。"},{"i":38,"n":"第三十八条","txt":"国家完善高标准农田立项、建设、验收、管护机制和相关标准，严格全周期质量管理，健全高标准农田建设工程全周期责任倒查和终身追责机制。"},{"i":39,"n":"第三十九条","txt":"高标准农田建设应当坚持政府主导、社会参与、统筹规划、因地制宜、分步实施、用养结合、量质并重、建管并举的原则，充分考虑当地耕地数量、质量、分布和利用等基本情况，优先选取永久基本农田以及其他具有良好建设条件的耕地，并听取农村集体经济组织、新型农业经营主体、农户等的意见，保障其合法权益。"},{"i":40,"n":"第四十条","txt":"高标准农田建设应当严格按照国家有关规定开展测绘、勘察、设计、施工、监理，确保工程质量。具体办法由国务院农业农村主管部门制定。"},{"i":41,"n":"第四十一条","txt":"高标准农田建设应当按照国家有关规定进行竣工验收。验收时应当邀请农村集体经济组织、新型农业经营主体、农户等参加。"},{"i":42,"n":"第四十二条","txt":"县级以上人民政府农业农村主管部门应当依法加强对高标准农田建设的监督管理，建立健全高标准农田建设质量监督检验体系，加强对高标准农田工程质量的监督检查，会同有关部门开展高标准农田建设从业机构信用评价，并及时公示有关信息，接受社会监督。"},{"i":43,"n":"第四十三条","txt":"县级以上地方人民政府应当加强高标准农田管护，建立管护机制，明确管护主体，落实管护责任，合理保障管护经费，完善管护措施。"},{"i":44,"n":"第四十四条","txt":"国家鼓励、支持因地制宜推动盐碱地综合改造利用，鼓励耐盐碱农作物选育、种植等方面的科技创新。"},{"i":45,"n":"第四十五条","txt":"国家鼓励在具备水资源条件的地区探索开发利用荒漠、戈壁等非传统耕地资源用于农业生产。"},{"i":46,"n":"第四十六条","txt":"国家加强退化耕地治理，促进耕地可持续利用。"},{"i":47,"n":"第四十七条","txt":"县级以上地方人民政府应当支持采取施用有机肥、粪肥还田、秸秆还田、绿肥种植、粮豆轮作、测土配方施肥等措施，提升耕地土壤有机质和氮、磷、钾等营养元素供给能力。"},{"i":48,"n":"第四十八条","txt":"国家支持现代耕作技术应用，在适宜区域推行保护性耕作模式，促进耕地用养结合。"},{"i":49,"n":"第四十九条","txt":"国家建立黑土地保护制度，依法加强黑土地的保护、利用和治理、修复，稳步恢复提升黑土地基础地力，保护黑土地的优良生产能力，确保黑土地总量不减少、功能不退化、质量有提升、产能可持续。"},{"i":50,"n":"第五十条","txt":"国家建立耕地生态保护修复制度，鼓励采取农艺、生物、化学、工程等修复措施，恢复和提升耕地生态功能，维持生态系统整体稳定，促进农业绿色发展。"},{"i":51,"n":"第五十一条","txt":"县级以上人民政府应当坚持山水林田湖草沙一体化保护，加强耕地生态保护修复和耕地周边林地、草地、湿地、沙地等系统治理，加强农田防护林体系建设，加强传统梯田保护和有效利用，提升自然生态系统涵养水源、保持水土、防风固沙、维护生物多样性等生态功能，维持有利于耕地保护的生态环境。"},{"i":52,"n":"第五十二条","txt":"国家鼓励发展生态农业，推广无土栽培、精准施肥和病虫害绿色防控等生态环保种植技术。"},{"i":53,"n":"第五十三条","txt":"县级以上地方人民政府及其农业农村主管部门应当加强与农业生产有关的生物物种资源保护，选用、推广有利于保护环境、稳定生态的农作物，保护生物多样性，维护耕地生态功能。"},{"i":54,"n":"第五十四条","txt":"县级以上人民政府应当鼓励发展生态循环农业，加快构建生态循环农业产业体系，推广应用绿色高效农机具，加强农产品采收后的秸秆及其他剩余物质综合利用，科学开展畜禽粪污无害化处理和资源化利用，促进绿色种养循环农业发展。"},{"i":55,"n":"第五十五条","txt":"县级以上地方人民政府应当采取措施，防治废水、废气和固体废物对耕地的污染。禁止向耕地排放重金属或者其他有毒有害物质含量超标的污水、污泥，以及可能造成土壤污染的清淤底泥、尾矿、矿渣等。"},{"i":56,"n":"第五十六条","txt":"因突发性事件造成或者可能造成耕地污染的，当事人应当立即采取措施消除或者减轻对耕地的污染危害，并向所在地县级以上人民政府或者生态环境、农业农村等主管部门报告。相关人民政府及其有关部门应当依法处置。"},{"i":57,"n":"第五十七条","txt":"国家按照政府主导、多方参与的原则，建立健全耕地保护和质量提升投入保障机制。县级以上人民政府应当依法保障耕地保护和质量提升的投入，并按照“谁投资、谁受益”的原则鼓励和引导社会资金参与耕地保护和质量提升，保护社会投资者的合法权益。"},{"i":58,"n":"第五十八条","txt":"国家建立耕地保护和质量提升补偿制度，对永久基本农田等耕地保护任务重、高标准农田建设力度大、耕地保护目标责任完成好、粮食产量和粮食商品率高的地区，以及承担耕地保护任务的农村集体经济组织、农业生产经营者等给予补偿或者奖励。具体办法由国务院自然资源、农业农村、财政等主管部门制定。"},{"i":59,"n":"第五十九条","txt":"耕地上依法设立的土地承包经营权等受法律保护，任何组织和个人不得侵犯。"},{"i":60,"n":"第六十条","txt":"县级以上地方人民政府应当根据耕地保护和粮食安全目标责任，结合本行政区域实际情况，压实下一级人民政府耕地保护和粮食安全责任。"},{"i":61,"n":"第六十一条","txt":"国家自然资源督察机构按照国务院授权开展耕地保护督察。被督察的地方应当落实整改主体责任，认真组织整改，并及时报告整改情况。国务院有关主管部门对地方整改情况进行指导和监督。被督察的地方落实耕地保护督察意见不力，国家自然资源督察机构责令限期整改的，限期整改期间，暂停该地区农用地转用和土地征收的受理和审批。"},{"i":62,"n":"第六十二条","txt":"县级以上人民政府自然资源、农业农村等有关部门应当加强对耕地保护和质量提升活动的监督检查。有关部门履行监督检查职责时，可以依法采取下列措施："},{"i":63,"n":"第六十三条","txt":"国家运用卫星遥感、互联网、大数据、云计算、人工智能等现代信息技术和手段，提高耕地保护和质量提升工作的水平，科学精准加强对耕地保护和质量提升工作的监督。"},{"i":64,"n":"第六十四条","txt":"县级以上人民政府自然资源、农业农村、生态环境、水行政等有关部门应当建立健全执法协作机制和信息共享机制，加强监督管理能力建设，依法共享耕地保护和质量提升以及管理执法等信息。针对同一检查对象的多个检查事项，应当合并或者纳入跨部门联合抽查范围。"},{"i":65,"n":"第六十五条","txt":"县级以上人民政府自然资源、农业农村、生态环境、水行政等主管部门依法履行监督检查职责时，发现违法行为涉嫌犯罪的，应当及时将案件移送有关机关。有关机关依法查处案件需要自然资源、农业农村、生态环境、水行政等主管部门提供检验结论、认定意见等协助的，有关部门应当予以协助。"},{"i":66,"n":"第六十六条","txt":"违反本法规定，地方各级人民政府及其有关部门、单位有下列情形之一的，对负有责任的领导人员和直接责任人员给予警告、记过、记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分："},{"i":67,"n":"第六十七条","txt":"违反本法规定，占用耕地挖湖造景或者擅自在耕地上绿化造林、种植草皮、堆放固体废物、填埋垃圾等，破坏种植条件的，由县级以上人民政府自然资源、农业农村、生态环境等主管部门按照职责分工责令限期改正或者治理，可以按占用面积处当地耕地开垦费五倍以上十倍以下的罚款。"},{"i":68,"n":"第六十八条","txt":"违反本法规定，侵占、损毁高标准农田工程设施或者危害设施安全的，由县级以上人民政府农业农村主管部门责令停止违法行为、限期恢复原状；逾期不恢复的，可以由县级以上人民政府农业农村主管部门、水行政主管部门等按照职责分工代为恢复，所需费用由违法者承担，并处恢复费用一倍以上三倍以下的罚款。"},{"i":69,"n":"第六十九条","txt":"依照本法规定，责令限期拆除在非法占用的耕地上新建的建筑物和其他设施，恢复耕地原种植条件的，建设单位、个人必须立即停止施工，自行拆除并恢复原种植条件；对继续施工的，作出决定的机关可以查封施工现场、扣押与涉嫌非法占用耕地行为直接相关的施工设备工具和建筑材料等；对拒不自行拆除的，作出决定的机关可以依法申请人民法院强制执行。"},{"i":70,"n":"第七十条","txt":"对违反本法规定的行为，本法未作行政处罚规定的，适用《中华人民共和国生态环境法典》、《中华人民共和国土地管理法》等有关法律、行政法规的规定。"},{"i":71,"n":"第七十一条","txt":"违反本法规定，造成他人损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":72,"n":"第七十二条","txt":"本法自2027年1月1日起施行。"}],"nengyuanfa":[{"i":1,"n":"第一条","txt":"为了推动能源高质量发展，保障国家能源安全，促进经济社会绿色低碳转型和可持续发展，积极稳妥推进碳达峰碳中和，适应全面建设社会主义现代化国家需要，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称能源，是指直接或者通过加工、转换而取得有用能的各种资源，包括煤炭、石油、天然气、核能、水能、风能、太阳能、生物质能、地热能、海洋能以及电力、热力、氢能等。"},{"i":3,"n":"第三条","txt":"能源工作应当坚持中国共产党的领导，贯彻新发展理念和总体国家安全观，统筹发展和安全，实施推动能源消费革命、能源供给革命、能源技术革命、能源体制革命和全方位加强国际合作的能源安全新战略，坚持立足国内、多元保障、节约优先、绿色发展，加快构建清洁低碳、安全高效的新型能源体系。"},{"i":4,"n":"第四条","txt":"国家坚持多措并举、精准施策、科学管理、社会共治的原则，完善节约能源政策，加强节约能源管理，综合采取经济、技术、宣传教育等措施，促进经济社会发展全过程和各领域全面降低能源消耗，防止能源浪费。"},{"i":5,"n":"第五条","txt":"国家完善能源开发利用政策，优化能源供应结构和消费结构，积极推动能源清洁低碳发展，提高能源利用效率。"},{"i":6,"n":"第六条","txt":"国家加快建立主体多元、统一开放、竞争有序、监管有效的能源市场体系，依法规范能源市场秩序，平等保护能源市场各类主体的合法权益。"},{"i":7,"n":"第七条","txt":"国家完善能源产供储销体系，健全能源储备制度和能源应急机制，提升能源供给能力，保障能源安全、稳定、可靠、有效供给。"},{"i":8,"n":"第八条","txt":"国家建立健全能源标准体系，保障能源安全和绿色低碳转型，促进能源新技术、新产业、新业态发展。"},{"i":9,"n":"第九条","txt":"国家加强能源科技创新能力建设，支持能源开发利用的科技研究、应用示范和产业化发展，为能源高质量发展提供科技支撑。"},{"i":10,"n":"第十条","txt":"国家坚持平等互利、合作共赢的方针，积极促进能源国际合作。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府应当加强对能源工作的组织领导和统筹协调，及时研究解决能源工作中的重大问题。"},{"i":12,"n":"第十二条","txt":"国务院能源主管部门负责全国能源工作。国务院其他有关部门在各自职责范围内负责相关的能源工作。"},{"i":13,"n":"第十三条","txt":"县级以上人民政府及其有关部门应当采取多种形式，加强对节约能源、能源安全和能源绿色低碳发展的宣传教育，增强全社会的节约能源意识、能源安全意识，促进形成绿色低碳的生产生活方式。"},{"i":14,"n":"第十四条","txt":"对在能源工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":15,"n":"第十五条","txt":"国家制定和完善能源规划，发挥能源规划对能源发展的引领、指导和规范作用。"},{"i":16,"n":"第十六条","txt":"全国综合能源规划由国务院能源主管部门会同国务院有关部门组织编制。全国综合能源规划应当依据国民经济和社会发展规划编制，并与国土空间规划等相关规划衔接。"},{"i":17,"n":"第十七条","txt":"省、自治区、直辖市人民政府能源主管部门会同有关部门，依据全国综合能源规划、相关全国分领域能源规划、相关区域能源规划，组织编制本省、自治区、直辖市的能源规划。"},{"i":18,"n":"第十八条","txt":"编制能源规划，应当遵循能源发展规律，坚持统筹兼顾，强化科学论证。组织编制能源规划的部门应当征求有关部门、相关企业和行业组织以及有关专家等方面的意见。"},{"i":19,"n":"第十九条","txt":"能源规划按照规定的权限和程序报经批准后实施。"},{"i":20,"n":"第二十条","txt":"组织编制能源规划的部门应当就能源规划实施情况组织开展评估。根据评估结果确需对能源规划进行调整的，应当报经原批准机关同意，国家另有规定的除外。"},{"i":21,"n":"第二十一条","txt":"国家根据能源资源禀赋情况和经济社会可持续发展的需要，统筹保障能源安全、优化能源结构、促进能源转型和节约能源、保护生态环境等因素，分类制定和完善能源开发利用政策。"},{"i":22,"n":"第二十二条","txt":"国家支持优先开发利用可再生能源，合理开发和清洁高效利用化石能源，推进非化石能源安全可靠有序替代化石能源，提高非化石能源消费比重。"},{"i":23,"n":"第二十三条","txt":"国务院能源主管部门会同国务院有关部门制定并组织实施可再生能源在能源消费中的最低比重目标。"},{"i":24,"n":"第二十四条","txt":"国家统筹水电开发和生态保护，严格控制开发建设小型水电站。"},{"i":25,"n":"第二十五条","txt":"国家推进风能、太阳能开发利用，坚持集中式与分布式并举，加快风电和光伏发电基地建设，支持分布式风电和光伏发电就近开发利用，合理有序开发海上风电，积极发展光热发电。"},{"i":26,"n":"第二十六条","txt":"国家鼓励合理开发利用生物质能，因地制宜发展生物质发电、生物质能清洁供暖和生物液体燃料、生物天然气。"},{"i":27,"n":"第二十七条","txt":"国家积极安全有序发展核电。"},{"i":28,"n":"第二十八条","txt":"国家优化煤炭开发布局和产业结构，鼓励发展煤矿矿区循环经济，优化煤炭消费结构，促进煤炭清洁高效利用，发挥煤炭在能源供应体系中的基础保障和系统调节作用。"},{"i":29,"n":"第二十九条","txt":"国家采取多种措施，加大石油、天然气资源勘探开发力度，增强石油、天然气国内供应保障能力。"},{"i":30,"n":"第三十条","txt":"国家推动燃煤发电清洁高效发展，根据电力系统稳定运行和电力供应保障的需要，合理布局燃煤发电建设，提高燃煤发电的调节能力。"},{"i":31,"n":"第三十一条","txt":"国家加快构建新型电力系统，加强电源电网协同建设，推进电网基础设施智能化改造和智能微电网建设，提高电网对可再生能源的接纳、配置和调控能力。"},{"i":32,"n":"第三十二条","txt":"国家合理布局、积极有序开发建设抽水蓄能电站，推进新型储能高质量发展，发挥各类储能在电力系统中的调节作用。"},{"i":33,"n":"第三十三条","txt":"国家积极有序推进氢能开发利用，促进氢能产业高质量发展。"},{"i":34,"n":"第三十四条","txt":"国家推动提高能源利用效率，鼓励发展分布式能源和多能互补、多能联供综合能源服务，积极推广合同能源管理等市场化节约能源服务，提高终端能源消费清洁化、低碳化、高效化、智能化水平。"},{"i":35,"n":"第三十五条","txt":"能源企业、能源用户应当按照国家有关规定配备、使用能源和碳排放计量器具。"},{"i":36,"n":"第三十六条","txt":"承担电力、燃气、热力等能源供应的企业，应当依照法律、法规和国家有关规定，保障营业区域内的能源用户获得安全、持续、可靠的能源供应服务，没有法定或者约定事由不得拒绝或者中断能源供应服务，不得擅自提高价格、违法收取费用、减少供应数量或者限制购买数量。"},{"i":37,"n":"第三十七条","txt":"国家加强能源基础设施建设和保护。任何单位或者个人不得从事危及能源基础设施安全的活动。"},{"i":38,"n":"第三十八条","txt":"国家按照城乡融合、因地制宜、多能互补、综合利用、提升服务的原则，鼓励和扶持农村的能源发展，重点支持革命老区、民族地区、边疆地区、欠发达地区农村的能源发展，提高农村的能源供应能力和服务水平。"},{"i":39,"n":"第三十九条","txt":"从事能源开发利用活动，应当遵守有关生态环境保护、安全生产和职业病防治等法律、法规的规定，减少污染物和温室气体排放，防止对生态环境的破坏，预防、减少生产安全事故和职业病危害。"},{"i":40,"n":"第四十条","txt":"国家鼓励、引导各类经营主体依法投资能源开发利用、能源基础设施建设等，促进能源市场发展。"},{"i":41,"n":"第四十一条","txt":"国家推动能源领域自然垄断环节独立运营和竞争性环节市场化改革，依法加强对能源领域自然垄断性业务的监管和调控，支持各类经营主体依法按照市场规则公平参与能源领域竞争性业务。"},{"i":42,"n":"第四十二条","txt":"国务院能源主管部门会同国务院有关部门协调推动全国统一的煤炭、电力、石油、天然气等能源交易市场建设，推动建立功能完善、运营规范的市场交易机构或者交易平台，依法拓展交易方式和交易产品范围，完善交易机制和交易规则。"},{"i":43,"n":"第四十三条","txt":"县级以上人民政府及其有关部门应当强化统筹调度组织，保障能源运输畅通。"},{"i":44,"n":"第四十四条","txt":"国家鼓励能源领域上下游企业通过订立长期协议等方式，依法按照市场化方式加强合作、协同发展，提升能源市场风险应对能力。"},{"i":45,"n":"第四十五条","txt":"国家推动建立与社会主义市场经济体制相适应，主要由能源资源状况、产品和服务成本、市场供求状况、可持续发展状况等因素决定的能源价格形成机制。"},{"i":46,"n":"第四十六条","txt":"国家积极促进能源领域国际投资和贸易合作，有效防范和应对国际能源市场风险。"},{"i":47,"n":"第四十七条","txt":"国家按照政府主导、社会共建、多元互补的原则，建立健全高效协同的能源储备体系，科学合理确定能源储备的种类、规模和方式，发挥能源储备的战略保障、宏观调控和应对急需等功能。"},{"i":48,"n":"第四十八条","txt":"能源储备实行政府储备和企业储备相结合，实物储备和产能储备、矿产地储备相统筹。"},{"i":49,"n":"第四十九条","txt":"政府储备承储运营机构应当依照法律、行政法规和国家有关规定，建立健全内部管理制度，加强储备管理，确保政府储备安全。"},{"i":50,"n":"第五十条","txt":"国家完善能源储备监管体制，加快能源储备设施建设，提高能源储备运营主体专业化水平，加强能源储备信息化建设，持续提升能源储备综合效能。"},{"i":51,"n":"第五十一条","txt":"国家建立和完善能源预测预警体系，提高能源预测预警能力和水平，及时有效对能源供求变化、能源价格波动以及能源安全风险状况等进行预测预警。"},{"i":52,"n":"第五十二条","txt":"国家建立统一领导、分级负责、协调联动的能源应急管理体制。"},{"i":53,"n":"第五十三条","txt":"国务院能源主管部门会同国务院有关部门拟定全国的能源应急预案，报国务院批准后实施。"},{"i":54,"n":"第五十四条","txt":"出现能源供应严重短缺、供应中断等能源应急状态时，有关人民政府应当按照权限及时启动应急响应，根据实际情况和需要，可以依法采取下列应急处置措施："},{"i":55,"n":"第五十五条","txt":"出现本法第五十四条规定的能源应急状态时，能源企业、能源用户以及其他有关单位和个人应当服从有关人民政府的统一指挥和安排，按照规定承担相应的能源应急义务，配合采取应急处置措施，协助维护能源市场秩序。"},{"i":56,"n":"第五十六条","txt":"国家制定鼓励和支持能源科技创新的政策措施，推动建立以国家战略科技力量为引领、企业为主体、市场为导向、产学研深度融合的能源科技创新体系。"},{"i":57,"n":"第五十七条","txt":"国家鼓励和支持能源资源勘探开发、化石能源清洁高效利用、可再生能源开发利用、核能安全利用、氢能开发利用以及储能、节约能源等领域基础性、关键性和前沿性重大技术、装备及相关新材料的研究、开发、示范、推广应用和产业化发展。"},{"i":58,"n":"第五十八条","txt":"国家制定和完善产业、金融、政府采购等政策，鼓励、引导社会资金投入能源科技创新。"},{"i":59,"n":"第五十九条","txt":"国家建立重大能源科技创新平台，支持重大能源科技基础设施和能源技术研发、试验、检测、认证等公共服务平台建设，提高能源科技创新能力和服务能力。"},{"i":60,"n":"第六十条","txt":"国家支持依托重大能源工程集中开展科技攻关和集成应用示范，推动产学研以及能源上下游产业链、供应链协同创新。"},{"i":61,"n":"第六十一条","txt":"国家支持先进信息技术在能源领域的应用，推动能源生产和供应的数字化、智能化发展，以及多种能源协同转换与集成互补。"},{"i":62,"n":"第六十二条","txt":"国家加大能源科技专业人才培养力度，鼓励、支持教育机构、科研机构与企业合作培养能源科技高素质专业人才。"},{"i":63,"n":"第六十三条","txt":"县级以上人民政府能源主管部门和其他有关部门应当按照职责分工，加强对有关能源工作的监督检查，及时查处违法行为。"},{"i":64,"n":"第六十四条","txt":"县级以上人民政府能源主管部门和其他有关部门按照职责分工依法履行监督检查职责，可以采取下列措施："},{"i":65,"n":"第六十五条","txt":"县级以上人民政府能源主管部门和其他有关部门应当加强能源监管协同，提升监管效能，并可以根据工作需要建立能源监管信息系统。"},{"i":66,"n":"第六十六条","txt":"国务院能源主管部门会同国务院有关部门加强能源行业信用体系建设，按照国家有关规定建立信用记录制度。"},{"i":67,"n":"第六十七条","txt":"因能源输送管网设施的接入、使用发生的争议，可以由省级以上人民政府能源主管部门进行协调，协调不成的，当事人可以向人民法院提起诉讼；当事人也可以直接向人民法院提起诉讼。"},{"i":68,"n":"第六十八条","txt":"任何单位和个人对违反本法和其他有关能源的法律、法规的行为，有权向县级以上人民政府能源主管部门或者其他有关部门举报。接到举报的部门应当及时依法处理。"},{"i":69,"n":"第六十九条","txt":"县级以上人民政府能源主管部门或者其他有关部门的工作人员违反本法规定，滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":70,"n":"第七十条","txt":"违反本法规定，承担电力、燃气、热力等能源供应的企业没有法定或者约定事由拒绝或者中断对营业区域内能源用户的能源供应服务，或者擅自提高价格、违法收取费用、减少供应数量、限制购买数量的，由县级以上人民政府能源主管部门或者其他有关部门按照职责分工责令改正，依法给予行政处罚；情节严重的，对有关主管人员和直接责任人员依法给予处分。"},{"i":71,"n":"第七十一条","txt":"违反本法规定，能源输送管网设施运营企业未向符合条件的企业等经营主体公平、无歧视开放并提供能源输送服务的，由省级以上人民政府能源主管部门或者其他有关部门按照职责分工责令改正，给予警告或者通报批评；拒不改正的，处相关经营主体经济损失额二倍以下的罚款；情节严重的，对有关主管人员和直接责任人员依法给予处分。"},{"i":72,"n":"第七十二条","txt":"违反本法规定，有下列情形之一的，由县级以上人民政府能源主管部门或者其他有关部门按照职责分工责令改正，给予警告或者通报批评；拒不改正的，处十万元以上二十万元以下的罚款："},{"i":73,"n":"第七十三条","txt":"违反本法规定，能源企业、能源用户以及其他有关单位或者个人在能源应急状态时不服从有关人民政府的统一指挥和安排、未按照规定承担能源应急义务或者不配合采取应急处置措施的，由县级以上人民政府能源主管部门或者其他有关部门按照职责分工责令改正，给予警告或者通报批评；拒不改正的，对个人处一万元以上五万元以下的罚款，对单位处十万元以上五十万元以下的罚款，并可以根据情节轻重责令停业整顿或者依法吊销相关许可证件。"},{"i":74,"n":"第七十四条","txt":"违反本法规定，造成财产损失或者其他损害的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":75,"n":"第七十五条","txt":"本法中下列用语的含义："},{"i":76,"n":"第七十六条","txt":"军队的能源开发利用管理，按照国家和军队有关规定执行。"},{"i":77,"n":"第七十七条","txt":"中华人民共和国缔结或者参加的涉及能源的国际条约与本法有不同规定的，适用国际条约的规定，但中华人民共和国声明保留的条款除外。"},{"i":78,"n":"第七十八条","txt":"任何国家或者地区在可再生能源产业或者其他能源领域对中华人民共和国采取歧视性的禁止、限制或者其他类似措施的，中华人民共和国可以根据实际情况对该国家或者该地区采取相应的措施。"},{"i":79,"n":"第七十九条","txt":"中华人民共和国境外的组织和个人实施危害中华人民共和国国家能源安全行为的，依法追究法律责任。"},{"i":80,"n":"第八十条","txt":"本法自2025年1月1日起施行。"}],"jieyuenengyuanfa":[{"i":1,"n":"第一条","txt":"为了推动全社会节约能源，提高能源利用效率，保护和改善环境，促进经济社会全面协调可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称能源，是指煤炭、石油、天然气、生物质能和电力、热力以及其他直接或者通过加工、转换而取得有用能的各种资源。"},{"i":3,"n":"第三条","txt":"本法所称节约能源（以下简称节能），是指加强用能管理，采取技术上可行、经济上合理以及环境和社会可以承受的措施，从能源生产到消费的各个环节，降低消耗、减少损失和污染物排放、制止浪费，有效、合理地利用能源。"},{"i":4,"n":"第四条","txt":"节约资源是我国的基本国策。国家实施节约与开发并举、把节约放在首位的能源发展战略。"},{"i":5,"n":"第五条","txt":"国务院和县级以上地方各级人民政府应当将节能工作纳入国民经济和社会发展规划、年度计划，并组织编制和实施节能中长期专项规划、年度节能计划。"},{"i":6,"n":"第六条","txt":"国家实行节能目标责任制和节能考核评价制度，将节能目标完成情况作为对地方人民政府及其负责人考核评价的内容。"},{"i":7,"n":"第七条","txt":"国家实行有利于节能和环境保护的产业政策，限制发展高耗能、高污染行业，发展节能环保型产业。"},{"i":8,"n":"第八条","txt":"国家鼓励、支持节能科学技术的研究、开发、示范和推广，促进节能技术创新与进步。"},{"i":9,"n":"第九条","txt":"任何单位和个人都应当依法履行节能义务，有权检举浪费能源的行为。"},{"i":10,"n":"第十条","txt":"国务院管理节能工作的部门主管全国的节能监督管理工作。国务院有关部门在各自的职责范围内负责节能监督管理工作，并接受国务院管理节能工作的部门的指导。"},{"i":11,"n":"第十一条","txt":"国务院和县级以上地方各级人民政府应当加强对节能工作的领导，部署、协调、监督、检查、推动节能工作。"},{"i":12,"n":"第十二条","txt":"县级以上人民政府管理节能工作的部门和有关部门应当在各自的职责范围内，加强对节能法律、法规和节能标准执行情况的监督检查，依法查处违法用能行为。"},{"i":13,"n":"第十三条","txt":"国务院标准化主管部门和国务院有关部门依法组织制定并适时修订有关节能的国家标准、行业标准，建立健全节能标准体系。"},{"i":14,"n":"第十四条","txt":"建筑节能的国家标准、行业标准由国务院建设主管部门组织制定，并依照法定程序发布。"},{"i":15,"n":"第十五条","txt":"国家实行固定资产投资项目节能评估和审查制度。不符合强制性节能标准的项目，建设单位不得开工建设；已经建成的，不得投入生产、使用。政府投资项目不符合强制性节能标准的，依法负责项目审批的机关不得批准建设。具体办法由国务院管理节能工作的部门会同国务院有关部门制定。"},{"i":16,"n":"第十六条","txt":"国家对落后的耗能过高的用能产品、设备和生产工艺实行淘汰制度。淘汰的用能产品、设备、生产工艺的目录和实施办法，由国务院管理节能工作的部门会同国务院有关部门制定并公布。"},{"i":17,"n":"第十七条","txt":"禁止生产、进口、销售国家明令淘汰或者不符合强制性能源效率标准的用能产品、设备；禁止使用国家明令淘汰的用能设备、生产工艺。"},{"i":18,"n":"第十八条","txt":"国家对家用电器等使用面广、耗能量大的用能产品，实行能源效率标识管理。实行能源效率标识管理的产品目录和实施办法，由国务院管理节能工作的部门会同国务院市场监督管理部门制定并公布。"},{"i":19,"n":"第十九条","txt":"生产者和进口商应当对列入国家能源效率标识管理产品目录的用能产品标注能源效率标识，在产品包装物上或者说明书中予以说明，并按照规定报国务院市场监督管理部门和国务院管理节能工作的部门共同授权的机构备案。"},{"i":20,"n":"第二十条","txt":"用能产品的生产者、销售者，可以根据自愿原则，按照国家有关节能产品认证的规定，向经国务院认证认可监督管理部门认可的从事节能产品认证的机构提出节能产品认证申请；经认证合格后，取得节能产品认证证书，可以在用能产品或者其包装物上使用节能产品认证标志。"},{"i":21,"n":"第二十一条","txt":"县级以上各级人民政府统计部门应当会同同级有关部门，建立健全能源统计制度，完善能源统计指标体系，改进和规范能源统计方法，确保能源统计数据真实、完整。"},{"i":22,"n":"第二十二条","txt":"国家鼓励节能服务机构的发展，支持节能服务机构开展节能咨询、设计、评估、检测、审计、认证等服务。"},{"i":23,"n":"第二十三条","txt":"国家鼓励行业协会在行业节能规划、节能标准的制定和实施、节能技术推广、能源消费统计、节能宣传培训和信息咨询等方面发挥作用。"},{"i":24,"n":"第二十四条","txt":"用能单位应当按照合理用能的原则，加强节能管理，制定并实施节能计划和节能技术措施，降低能源消耗。"},{"i":25,"n":"第二十五条","txt":"用能单位应当建立节能目标责任制，对节能工作取得成绩的集体、个人给予奖励。"},{"i":26,"n":"第二十六条","txt":"用能单位应当定期开展节能教育和岗位节能培训。"},{"i":27,"n":"第二十七条","txt":"用能单位应当加强能源计量管理，按照规定配备和使用经依法检定合格的能源计量器具。"},{"i":28,"n":"第二十八条","txt":"能源生产经营单位不得向本单位职工无偿提供能源。任何单位不得对能源消费实行包费制。"},{"i":29,"n":"第二十九条","txt":"国务院和省、自治区、直辖市人民政府推进能源资源优化开发利用和合理配置，推进有利于节能的行业结构调整，优化用能结构和企业布局。"},{"i":30,"n":"第三十条","txt":"国务院管理节能工作的部门会同国务院有关部门制定电力、钢铁、有色金属、建材、石油加工、化工、煤炭等主要耗能行业的节能技术政策，推动企业节能技术改造。"},{"i":31,"n":"第三十一条","txt":"国家鼓励工业企业采用高效、节能的电动机、锅炉、窑炉、风机、泵类等设备，采用热电联产、余热余压利用、洁净煤以及先进的用能监测和控制等技术。"},{"i":32,"n":"第三十二条","txt":"电网企业应当按照国务院有关部门制定的节能发电调度管理的规定，安排清洁、高效和符合规定的热电联产、利用余热余压发电的机组以及其他符合资源综合利用规定的发电机组与电网并网运行，上网电价执行国家有关规定。"},{"i":33,"n":"第三十三条","txt":"禁止新建不符合国家规定的燃煤发电机组、燃油发电机组和燃煤热电机组。"},{"i":34,"n":"第三十四条","txt":"国务院建设主管部门负责全国建筑节能的监督管理工作。"},{"i":35,"n":"第三十五条","txt":"建筑工程的建设、设计、施工和监理单位应当遵守建筑节能标准。"},{"i":36,"n":"第三十六条","txt":"房地产开发企业在销售房屋时，应当向购买人明示所售房屋的节能措施、保温工程保修期等信息，在房屋买卖合同、质量保证书和使用说明书中载明，并对其真实性、准确性负责。"},{"i":37,"n":"第三十七条","txt":"使用空调采暖、制冷的公共建筑应当实行室内温度控制制度。具体办法由国务院建设主管部门制定。"},{"i":38,"n":"第三十八条","txt":"国家采取措施，对实行集中供热的建筑分步骤实行供热分户计量、按照用热量收费的制度。新建建筑或者对既有建筑进行节能改造，应当按照规定安装用热计量装置、室内温度调控装置和供热系统调控装置。具体办法由国务院建设主管部门会同国务院有关部门制定。"},{"i":39,"n":"第三十九条","txt":"县级以上地方各级人民政府有关部门应当加强城市节约用电管理，严格控制公用设施和大型建筑物装饰性景观照明的能耗。"},{"i":40,"n":"第四十条","txt":"国家鼓励在新建建筑和既有建筑节能改造中使用新型墙体材料等节能建筑材料和节能设备，安装和使用太阳能等可再生能源利用系统。"},{"i":41,"n":"第四十一条","txt":"国务院有关交通运输主管部门按照各自的职责负责全国交通运输相关领域的节能监督管理工作。"},{"i":42,"n":"第四十二条","txt":"国务院及其有关部门指导、促进各种交通运输方式协调发展和有效衔接，优化交通运输结构，建设节能型综合交通运输体系。"},{"i":43,"n":"第四十三条","txt":"县级以上地方各级人民政府应当优先发展公共交通，加大对公共交通的投入，完善公共交通服务体系，鼓励利用公共交通工具出行；鼓励使用非机动交通工具出行。"},{"i":44,"n":"第四十四条","txt":"国务院有关交通运输主管部门应当加强交通运输组织管理，引导道路、水路、航空运输企业提高运输组织化程度和集约化水平，提高能源利用效率。"},{"i":45,"n":"第四十五条","txt":"国家鼓励开发、生产、使用节能环保型汽车、摩托车、铁路机车车辆、船舶和其他交通运输工具，实行老旧交通运输工具的报废、更新制度。"},{"i":46,"n":"第四十六条","txt":"国务院有关部门制定交通运输营运车船的燃料消耗量限值标准；不符合标准的，不得用于营运。"},{"i":47,"n":"第四十七条","txt":"公共机构应当厉行节约，杜绝浪费，带头使用节能产品、设备，提高能源利用效率。"},{"i":48,"n":"第四十八条","txt":"国务院和县级以上地方各级人民政府管理机关事务工作的机构会同同级有关部门制定和组织实施本级公共机构节能规划。公共机构节能规划应当包括公共机构既有建筑节能改造计划。"},{"i":49,"n":"第四十九条","txt":"公共机构应当制定年度节能目标和实施方案，加强能源消费计量和监测管理，向本级人民政府管理机关事务工作的机构报送上年度的能源消费状况报告。"},{"i":50,"n":"第五十条","txt":"公共机构应当加强本单位用能系统管理，保证用能系统的运行符合国家相关标准。"},{"i":51,"n":"第五十一条","txt":"公共机构采购用能产品、设备，应当优先采购列入节能产品、设备政府采购名录中的产品、设备。禁止采购国家明令淘汰的用能产品、设备。"},{"i":52,"n":"第五十二条","txt":"国家加强对重点用能单位的节能管理。"},{"i":53,"n":"第五十三条","txt":"重点用能单位应当每年向管理节能工作的部门报送上年度的能源利用状况报告。能源利用状况包括能源消费情况、能源利用效率、节能目标完成情况和节能效益分析、节能措施等内容。"},{"i":54,"n":"第五十四条","txt":"管理节能工作的部门应当对重点用能单位报送的能源利用状况报告进行审查。对节能管理制度不健全、节能措施不落实、能源利用效率低的重点用能单位，管理节能工作的部门应当开展现场调查，组织实施用能设备能源效率检测，责令实施能源审计，并提出书面整改要求，限期整改。"},{"i":55,"n":"第五十五条","txt":"重点用能单位应当设立能源管理岗位，在具有节能专业知识、实际经验以及中级以上技术职称的人员中聘任能源管理负责人，并报管理节能工作的部门和有关部门备案。"},{"i":56,"n":"第五十六条","txt":"国务院管理节能工作的部门会同国务院科技主管部门发布节能技术政策大纲，指导节能技术研究、开发和推广应用。"},{"i":57,"n":"第五十七条","txt":"县级以上各级人民政府应当把节能技术研究开发作为政府科技投入的重点领域，支持科研单位和企业开展节能技术应用研究，制定节能标准，开发节能共性和关键技术，促进节能技术创新与成果转化。"},{"i":58,"n":"第五十八条","txt":"国务院管理节能工作的部门会同国务院有关部门制定并公布节能技术、节能产品的推广目录，引导用能单位和个人使用先进的节能技术、节能产品。"},{"i":59,"n":"第五十九条","txt":"县级以上各级人民政府应当按照因地制宜、多能互补、综合利用、讲求效益的原则，加强农业和农村节能工作，增加对农业和农村节能技术、节能产品推广应用的资金投入。"},{"i":60,"n":"第六十条","txt":"中央财政和省级地方财政安排节能专项资金，支持节能技术研究开发、节能技术和产品的示范与推广、重点节能工程的实施、节能宣传培训、信息服务和表彰奖励等。"},{"i":61,"n":"第六十一条","txt":"国家对生产、使用列入本法第五十八条规定的推广目录的需要支持的节能技术、节能产品，实行税收优惠等扶持政策。"},{"i":62,"n":"第六十二条","txt":"国家实行有利于节约能源资源的税收政策，健全能源矿产资源有偿使用制度，促进能源资源的节约及其开采利用水平的提高。"},{"i":63,"n":"第六十三条","txt":"国家运用税收等政策，鼓励先进节能技术、设备的进口，控制在生产过程中耗能高、污染重的产品的出口。"},{"i":64,"n":"第六十四条","txt":"政府采购监督管理部门会同有关部门制定节能产品、设备政府采购名录，应当优先列入取得节能产品认证证书的产品、设备。"},{"i":65,"n":"第六十五条","txt":"国家引导金融机构增加对节能项目的信贷支持，为符合条件的节能技术研究开发、节能产品生产以及节能技术改造等项目提供优惠贷款。"},{"i":66,"n":"第六十六条","txt":"国家实行有利于节能的价格政策，引导用能单位和个人节能。"},{"i":67,"n":"第六十七条","txt":"各级人民政府对在节能管理、节能科学技术研究和推广应用中有显著成绩以及检举严重浪费能源行为的单位和个人，给予表彰和奖励。"},{"i":68,"n":"第六十八条","txt":"负责审批政府投资项目的机关违反本法规定，对不符合强制性节能标准的项目予以批准建设的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":69,"n":"第六十九条","txt":"生产、进口、销售国家明令淘汰的用能产品、设备的，使用伪造的节能产品认证标志或者冒用节能产品认证标志的，依照《中华人民共和国产品质量法》的规定处罚。"},{"i":70,"n":"第七十条","txt":"生产、进口、销售不符合强制性能源效率标准的用能产品、设备的，由市场监督管理部门责令停止生产、进口、销售，没收违法生产、进口、销售的用能产品、设备和违法所得，并处违法所得一倍以上五倍以下罚款；情节严重的，吊销营业执照。"},{"i":71,"n":"第七十一条","txt":"使用国家明令淘汰的用能设备或者生产工艺的，由管理节能工作的部门责令停止使用，没收国家明令淘汰的用能设备；情节严重的，可以由管理节能工作的部门提出意见，报请本级人民政府按照国务院规定的权限责令停业整顿或者关闭。"},{"i":72,"n":"第七十二条","txt":"生产单位超过单位产品能耗限额标准用能，情节严重，经限期治理逾期不治理或者没有达到治理要求的，可以由管理节能工作的部门提出意见，报请本级人民政府按照国务院规定的权限责令停业整顿或者关闭。"},{"i":73,"n":"第七十三条","txt":"违反本法规定，应当标注能源效率标识而未标注的，由市场监督管理部门责令改正，处三万元以上五万元以下罚款。"},{"i":74,"n":"第七十四条","txt":"用能单位未按照规定配备、使用能源计量器具的，由市场监督管理部门责令限期改正；逾期不改正的，处一万元以上五万元以下罚款。"},{"i":75,"n":"第七十五条","txt":"瞒报、伪造、篡改能源统计资料或者编造虚假能源统计数据的，依照《中华人民共和国统计法》的规定处罚。"},{"i":76,"n":"第七十六条","txt":"从事节能咨询、设计、评估、检测、审计、认证等服务的机构提供虚假信息的，由管理节能工作的部门责令改正，没收违法所得，并处五万元以上十万元以下罚款。"},{"i":77,"n":"第七十七条","txt":"违反本法规定，无偿向本单位职工提供能源或者对能源消费实行包费制的，由管理节能工作的部门责令限期改正；逾期不改正的，处五万元以上二十万元以下罚款。"},{"i":78,"n":"第七十八条","txt":"电网企业未按照本法规定安排符合规定的热电联产和利用余热余压发电的机组与电网并网运行，或者未执行国家有关上网电价规定的，由国家电力监管机构责令改正；造成发电企业经济损失的，依法承担赔偿责任。"},{"i":79,"n":"第七十九条","txt":"建设单位违反建筑节能标准的，由建设主管部门责令改正，处二十万元以上五十万元以下罚款。"},{"i":80,"n":"第八十条","txt":"房地产开发企业违反本法规定，在销售房屋时未向购买人明示所售房屋的节能措施、保温工程保修期等信息的，由建设主管部门责令限期改正，逾期不改正的，处三万元以上五万元以下罚款；对以上信息作虚假宣传的，由建设主管部门责令改正，处五万元以上二十万元以下罚款。"},{"i":81,"n":"第八十一条","txt":"公共机构采购用能产品、设备，未优先采购列入节能产品、设备政府采购名录中的产品、设备，或者采购国家明令淘汰的用能产品、设备的，由政府采购监督管理部门给予警告，可以并处罚款；对直接负责的主管人员和其他直接责任人员依法给予处分，并予通报。"},{"i":82,"n":"第八十二条","txt":"重点用能单位未按照本法规定报送能源利用状况报告或者报告内容不实的，由管理节能工作的部门责令限期改正；逾期不改正的，处一万元以上五万元以下罚款。"},{"i":83,"n":"第八十三条","txt":"重点用能单位无正当理由拒不落实本法第五十四条规定的整改要求或者整改没有达到要求的，由管理节能工作的部门处十万元以上三十万元以下罚款。"},{"i":84,"n":"第八十四条","txt":"重点用能单位未按照本法规定设立能源管理岗位，聘任能源管理负责人，并报管理节能工作的部门和有关部门备案的，由管理节能工作的部门责令改正；拒不改正的，处一万元以上三万元以下罚款。"},{"i":85,"n":"第八十五条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":86,"n":"第八十六条","txt":"国家工作人员在节能管理工作中滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":87,"n":"第八十七条","txt":"本法自2008年4月1日起施行。"}],"caoyuanfa":[{"i":1,"n":"第一条","txt":"为了保护、建设和合理利用草原，改善生态环境，维护生物多样性，发展现代畜牧业，促进经济和社会的可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域内从事草原规划、保护、建设、利用和管理活动，适用本法。"},{"i":3,"n":"第三条","txt":"国家对草原实行科学规划、全面保护、重点建设、合理利用的方针，促进草原的可持续利用和生态、经济、社会的协调发展。"},{"i":4,"n":"第四条","txt":"各级人民政府应当加强对草原保护、建设和利用的管理，将草原的保护、建设和利用纳入国民经济和社会发展计划。"},{"i":5,"n":"第五条","txt":"任何单位和个人都有遵守草原法律法规、保护草原的义务，同时享有对违反草原法律法规、破坏草原的行为进行监督、检举和控告的权利。"},{"i":6,"n":"第六条","txt":"国家鼓励与支持开展草原保护、建设、利用和监测方面的科学研究，推广先进技术和先进成果，培养科学技术人才。"},{"i":7,"n":"第七条","txt":"国家对在草原管理、保护、建设、合理利用和科学研究等工作中做出显著成绩的单位和个人，给予奖励。"},{"i":8,"n":"第八条","txt":"国务院草原行政主管部门主管全国草原监督管理工作。"},{"i":9,"n":"第九条","txt":"草原属于国家所有，由法律规定属于集体所有的除外。国家所有的草原，由国务院代表国家行使所有权。"},{"i":10,"n":"第十条","txt":"国家所有的草原，可以依法确定给全民所有制单位、集体经济组织等使用。"},{"i":11,"n":"第十一条","txt":"依法确定给全民所有制单位、集体经济组织等使用的国家所有的草原，由县级以上人民政府登记，核发使用权证，确认草原使用权。"},{"i":12,"n":"第十二条","txt":"依法登记的草原所有权和使用权受法律保护，任何单位或者个人不得侵犯。"},{"i":13,"n":"第十三条","txt":"集体所有的草原或者依法确定给集体经济组织使用的国家所有的草原，可以由本集体经济组织内的家庭或者联户承包经营。"},{"i":14,"n":"第十四条","txt":"承包经营草原，发包方和承包方应当签订书面合同。草原承包合同的内容应当包括双方的权利和义务、承包草原四至界限、面积和等级、承包期和起止日期、承包草原用途和违约责任等。承包期届满，原承包经营者在同等条件下享有优先承包权。"},{"i":15,"n":"第十五条","txt":"草原承包经营权受法律保护，可以按照自愿、有偿的原则依法转让。"},{"i":16,"n":"第十六条","txt":"草原所有权、使用权的争议，由当事人协商解决；协商不成的，由有关人民政府处理。"},{"i":17,"n":"第十七条","txt":"国家对草原保护、建设、利用实行统一规划制度。国务院草原行政主管部门会同国务院有关部门编制全国草原保护、建设、利用规划，报国务院批准后实施。"},{"i":18,"n":"第十八条","txt":"编制草原保护、建设、利用规划，应当依据国民经济和社会发展规划并遵循下列原则："},{"i":19,"n":"第十九条","txt":"草原保护、建设、利用规划应当包括：草原保护、建设、利用的目标和措施，草原功能分区和各项建设的总体部署，各项专业规划等。"},{"i":20,"n":"第二十条","txt":"草原保护、建设、利用规划应当与土地利用总体规划相衔接，与环境保护规划、水土保持规划、防沙治沙规划、水资源规划、林业长远规划、城市总体规划、村庄和集镇规划以及其他有关规划相协调。"},{"i":21,"n":"第二十一条","txt":"草原保护、建设、利用规划一经批准，必须严格执行。"},{"i":22,"n":"第二十二条","txt":"国家建立草原调查制度。"},{"i":23,"n":"第二十三条","txt":"国务院草原行政主管部门会同国务院有关部门制定全国草原等级评定标准。"},{"i":24,"n":"第二十四条","txt":"国家建立草原统计制度。"},{"i":25,"n":"第二十五条","txt":"国家建立草原生产、生态监测预警系统。"},{"i":26,"n":"第二十六条","txt":"县级以上人民政府应当增加草原建设的投入，支持草原建设。"},{"i":27,"n":"第二十七条","txt":"国家鼓励与支持人工草地建设、天然草原改良和饲草饲料基地建设，稳定和提高草原生产能力。"},{"i":28,"n":"第二十八条","txt":"县级以上人民政府应当支持、鼓励和引导农牧民开展草原围栏、饲草饲料储备、牲畜圈舍、牧民定居点等生产生活设施的建设。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府应当按照草原保护、建设、利用规划加强草种基地建设，鼓励选育、引进、推广优良草品种。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府应当有计划地进行火情监测、防火物资储备、防火隔离带等草原防火设施的建设，确保防火需要。"},{"i":31,"n":"第三十一条","txt":"对退化、沙化、盐碱化、石漠化和水土流失的草原，地方各级人民政府应当按照草原保护、建设、利用规划，划定治理区，组织专项治理。"},{"i":32,"n":"第三十二条","txt":"县级以上人民政府应当根据草原保护、建设、利用规划，在本级国民经济和社会发展计划中安排资金用于草原改良、人工种草和草种生产，任何单位或者个人不得截留、挪用；县级以上人民政府财政部门和审计部门应当加强监督管理。"},{"i":33,"n":"第三十三条","txt":"草原承包经营者应当合理利用草原，不得超过草原行政主管部门核定的载畜量；草原承包经营者应当采取种植和储备饲草饲料、增加饲草饲料供应量、调剂处理牲畜、优化畜群结构、提高出栏率等措施，保持草畜平衡。"},{"i":34,"n":"第三十四条","txt":"牧区的草原承包经营者应当实行划区轮牧，合理配置畜群，均衡利用草原。"},{"i":35,"n":"第三十五条","txt":"国家提倡在农区、半农半牧区和有条件的牧区实行牲畜圈养。草原承包经营者应当按照饲养牲畜的种类和数量，调剂、储备饲草饲料，采用青贮和饲草饲料加工等新技术，逐步改变依赖天然草地放牧的生产方式。"},{"i":36,"n":"第三十六条","txt":"县级以上地方人民政府草原行政主管部门对割草场和野生草种基地应当规定合理的割草期、采种期以及留茬高度和采割强度，实行轮割轮采。"},{"i":37,"n":"第三十七条","txt":"遇到自然灾害等特殊情况，需要临时调剂使用草原的，按照自愿互利的原则，由双方协商解决；需要跨县临时调剂使用草原的，由有关县级人民政府或者共同的上级人民政府组织协商解决。"},{"i":38,"n":"第三十八条","txt":"进行矿藏开采和工程建设，应当不占或者少占草原；确需征收、征用或者使用草原的，必须经省级以上人民政府草原行政主管部门审核同意后，依照有关土地管理的法律、行政法规办理建设用地审批手续。"},{"i":39,"n":"第三十九条","txt":"因建设征收、征用集体所有的草原的，应当依照《中华人民共和国土地管理法》的规定给予补偿；因建设使用国家所有的草原的，应当依照国务院有关规定对草原承包经营者给予补偿。"},{"i":40,"n":"第四十条","txt":"需要临时占用草原的，应当经县级以上地方人民政府草原行政主管部门审核同意。"},{"i":41,"n":"第四十一条","txt":"在草原上修建直接为草原保护和畜牧业生产服务的工程设施，需要使用草原的，由县级以上人民政府草原行政主管部门批准；修筑其他工程，需要将草原转为非畜牧业生产用地的，必须依法办理建设用地审批手续。"},{"i":42,"n":"第四十二条","txt":"国家实行基本草原保护制度。下列草原应当划为基本草原，实施严格管理："},{"i":43,"n":"第四十三条","txt":"国务院草原行政主管部门或者省、自治区、直辖市人民政府可以按照自然保护区管理的有关规定在下列地区建立草原自然保护区："},{"i":44,"n":"第四十四条","txt":"县级以上人民政府应当依法加强对草原珍稀濒危野生植物和种质资源的保护、管理。"},{"i":45,"n":"第四十五条","txt":"国家对草原实行以草定畜、草畜平衡制度。县级以上地方人民政府草原行政主管部门应当按照国务院草原行政主管部门制定的草原载畜量标准，结合当地实际情况，定期核定草原载畜量。各级人民政府应当采取有效措施，防止超载过牧。"},{"i":46,"n":"第四十六条","txt":"禁止开垦草原。对水土流失严重、有沙化趋势、需要改善生态环境的已垦草原，应当有计划、有步骤地退耕还草；已造成沙化、盐碱化、石漠化的，应当限期治理。"},{"i":47,"n":"第四十七条","txt":"对严重退化、沙化、盐碱化、石漠化的草原和生态脆弱区的草原，实行禁牧、休牧制度。"},{"i":48,"n":"第四十八条","txt":"国家支持依法实行退耕还草和禁牧、休牧。具体办法由国务院或者省、自治区、直辖市人民政府制定。"},{"i":49,"n":"第四十九条","txt":"禁止在荒漠、半荒漠和严重退化、沙化、盐碱化、石漠化、水土流失的草原以及生态脆弱区的草原上采挖植物和从事破坏草原植被的其他活动。"},{"i":50,"n":"第五十条","txt":"在草原上从事采土、采砂、采石等作业活动，应当报县级人民政府草原行政主管部门批准；开采矿产资源的，并应当依法办理有关手续。"},{"i":51,"n":"第五十一条","txt":"在草原上种植牧草或者饲料作物，应当符合草原保护、建设、利用规划；县级以上地方人民政府草原行政主管部门应当加强监督管理，防止草原沙化和水土流失。"},{"i":52,"n":"第五十二条","txt":"在草原上开展经营性旅游活动，应当符合有关草原保护、建设、利用规划，并不得侵犯草原所有者、使用者和承包经营者的合法权益，不得破坏草原植被。"},{"i":53,"n":"第五十三条","txt":"草原防火工作贯彻预防为主、防消结合的方针。"},{"i":54,"n":"第五十四条","txt":"县级以上地方人民政府应当做好草原鼠害、病虫害和毒害草防治的组织管理工作。县级以上地方人民政府草原行政主管部门应当采取措施，加强草原鼠害、病虫害和毒害草监测预警、调查以及防治工作，组织研究和推广综合防治的办法。"},{"i":55,"n":"第五十五条","txt":"除抢险救灾和牧民搬迁的机动车辆外，禁止机动车辆离开道路在草原上行驶，破坏草原植被；因从事地质勘探、科学考察等活动确需离开道路在草原上行驶的，应当事先向所在地县级人民政府草原行政主管部门报告行驶区域和行驶路线，并按照报告的行驶区域和行驶路线在草原上行驶。"},{"i":56,"n":"第五十六条","txt":"国务院草原行政主管部门和草原面积较大的省、自治区的县级以上地方人民政府草原行政主管部门设立草原监督管理机构，负责草原法律、法规执行情况的监督检查，对违反草原法律、法规的行为进行查处。"},{"i":57,"n":"第五十七条","txt":"草原监督检查人员履行监督检查职责时，有权采取下列措施："},{"i":58,"n":"第五十八条","txt":"国务院草原行政主管部门和省、自治区、直辖市人民政府草原行政主管部门，应当加强对草原监督检查人员的培训和考核。"},{"i":59,"n":"第五十九条","txt":"有关单位和个人对草原监督检查人员的监督检查工作应当给予支持、配合，不得拒绝或者阻碍草原监督检查人员依法执行职务。"},{"i":60,"n":"第六十条","txt":"对违反草原法律、法规的行为，应当依法作出行政处理，有关草原行政主管部门不作出行政处理决定的，上级草原行政主管部门有权责令有关草原行政主管部门作出行政处理决定或者直接作出行政处理决定。"},{"i":61,"n":"第六十一条","txt":"草原行政主管部门工作人员及其他国家机关有关工作人员玩忽职守、滥用职权，不依法履行监督管理职责，或者发现违法行为不予查处，造成严重后果，构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，依法给予行政处分。"},{"i":62,"n":"第六十二条","txt":"截留、挪用草原改良、人工种草和草种生产资金或者草原植被恢复费，构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，依法给予行政处分。"},{"i":63,"n":"第六十三条","txt":"无权批准征收、征用、使用草原的单位或者个人非法批准征收、征用、使用草原的，超越批准权限非法批准征收、征用、使用草原的，或者违反法律规定的程序批准征收、征用、使用草原，构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，依法给予行政处分。非法批准征收、征用、使用草原的文件无效。非法批准征收、征用、使用的草原应当收回，当事人拒不归还的，以非法使用草原论处。"},{"i":64,"n":"第六十四条","txt":"买卖或者以其他形式非法转让草原，构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，由县级以上人民政府草原行政主管部门依据职权责令限期改正，没收违法所得，并处违法所得一倍以上五倍以下的罚款。"},{"i":65,"n":"第六十五条","txt":"未经批准或者采取欺骗手段骗取批准，非法使用草原，构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，由县级以上人民政府草原行政主管部门依据职权责令退还非法使用的草原，对违反草原保护、建设、利用规划擅自将草原改为建设用地的，限期拆除在非法使用的草原上新建的建筑物和其他设施，恢复草原植被，并处草原被非法使用前三年平均产值六倍以上十二倍以下的罚款。"},{"i":66,"n":"第六十六条","txt":"非法开垦草原，构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，由县级以上人民政府草原行政主管部门依据职权责令停止违法行为，限期恢复植被，没收非法财物和违法所得，并处违法所得一倍以上五倍以下的罚款；没有违法所得的，并处五万元以下的罚款；给草原所有者或者使用者造成损失的，依法承担赔偿责任。"},{"i":67,"n":"第六十七条","txt":"在荒漠、半荒漠和严重退化、沙化、盐碱化、石漠化、水土流失的草原，以及生态脆弱区的草原上采挖植物或者从事破坏草原植被的其他活动的，由县级以上地方人民政府草原行政主管部门依据职权责令停止违法行为，没收非法财物和违法所得，可以并处违法所得一倍以上五倍以下的罚款；没有违法所得的，可以并处五万元以下的罚款；给草原所有者或者使用者造成损失的，依法承担赔偿责任。"},{"i":68,"n":"第六十八条","txt":"未经批准或者未按照规定的时间、区域和采挖方式在草原上进行采土、采砂、采石等活动的，由县级人民政府草原行政主管部门责令停止违法行为，限期恢复植被，没收非法财物和违法所得，可以并处违法所得一倍以上二倍以下的罚款；没有违法所得的，可以并处二万元以下的罚款；给草原所有者或者使用者造成损失的，依法承担赔偿责任。"},{"i":69,"n":"第六十九条","txt":"违反本法第五十二条规定，在草原上开展经营性旅游活动，破坏草原植被的，由县级以上地方人民政府草原行政主管部门依据职权责令停止违法行为，限期恢复植被，没收违法所得，可以并处违法所得一倍以上二倍以下的罚款；没有违法所得的，可以并处草原被破坏前三年平均产值六倍以上十二倍以下的罚款；给草原所有者或者使用者造成损失的，依法承担赔偿责任。"},{"i":70,"n":"第七十条","txt":"非抢险救灾和牧民搬迁的机动车辆离开道路在草原上行驶，或者从事地质勘探、科学考察等活动，未事先向所在地县级人民政府草原行政主管部门报告或者未按照报告的行驶区域和行驶路线在草原上行驶，破坏草原植被的，由县级人民政府草原行政主管部门责令停止违法行为，限期恢复植被，可以并处草原被破坏前三年平均产值三倍以上九倍以下的罚款；给草原所有者或者使用者造成损失的，依法承担赔偿责任。"},{"i":71,"n":"第七十一条","txt":"在临时占用的草原上修建永久性建筑物、构筑物的，由县级以上地方人民政府草原行政主管部门依据职权责令限期拆除；逾期不拆除的，依法强制拆除，所需费用由违法者承担。"},{"i":72,"n":"第七十二条","txt":"未经批准，擅自改变草原保护、建设、利用规划的，由县级以上人民政府责令限期改正；对直接负责的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":73,"n":"第七十三条","txt":"对违反本法有关草畜平衡制度的规定，牲畜饲养量超过县级以上地方人民政府草原行政主管部门核定的草原载畜量标准的纠正或者处罚措施，由省、自治区、直辖市人民代表大会或者其常务委员会规定。"},{"i":74,"n":"第七十四条","txt":"本法第二条第二款中所称的天然草原包括草地、草山和草坡，人工草地包括改良草地和退耕还草地，不包括城镇草地。"},{"i":75,"n":"第七十五条","txt":"本法自2003年3月1日起施行。"}],"yeshengdongwubaohufa":[{"i":1,"n":"第一条","txt":"为了保护野生动物，拯救珍贵、濒危野生动物，维护生物多样性和生态平衡，推进生态文明建设，促进人与自然和谐共生，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域及管辖的其他海域，从事野生动物保护及相关活动，适用本法。"},{"i":3,"n":"第三条","txt":"野生动物资源属于国家所有。"},{"i":4,"n":"第四条","txt":"国家加强重要生态系统保护和修复，对野生动物实行保护优先、规范利用、严格监管的原则，鼓励和支持开展野生动物科学研究与应用，秉持生态文明理念，推动绿色发展。"},{"i":5,"n":"第五条","txt":"国家保护野生动物及其栖息地。县级以上人民政府应当制定野生动物及其栖息地相关保护规划和措施，并将野生动物保护经费纳入预算。"},{"i":6,"n":"第六条","txt":"任何组织和个人有保护野生动物及其栖息地的义务。禁止违法猎捕、运输、交易野生动物，禁止破坏野生动物栖息地。"},{"i":7,"n":"第七条","txt":"国务院林业草原、渔业主管部门分别主管全国陆生、水生野生动物保护工作。"},{"i":8,"n":"第八条","txt":"各级人民政府应当加强野生动物保护的宣传教育和科学知识普及工作，鼓励和支持基层群众性自治组织、社会组织、企业事业单位、志愿者开展野生动物保护法律法规、生态保护等知识的宣传活动；组织开展对相关从业人员法律法规和专业知识培训；依法公开野生动物保护和管理信息。"},{"i":9,"n":"第九条","txt":"在野生动物保护和科学研究方面成绩显著的组织和个人，由县级以上人民政府按照国家有关规定给予表彰和奖励。"},{"i":10,"n":"第十条","txt":"国家对野生动物实行分类分级保护。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府野生动物保护主管部门应当加强信息技术应用，定期组织或者委托有关科学研究机构对野生动物及其栖息地状况进行调查、监测和评估，建立健全野生动物及其栖息地档案。"},{"i":12,"n":"第十二条","txt":"国务院野生动物保护主管部门应当会同国务院有关部门，根据野生动物及其栖息地状况的调查、监测和评估结果，确定并发布野生动物重要栖息地名录。"},{"i":13,"n":"第十三条","txt":"县级以上人民政府及其有关部门在编制有关开发利用规划时，应当充分考虑野生动物及其栖息地保护的需要，分析、预测和评估规划实施可能对野生动物及其栖息地保护产生的整体影响，避免或者减少规划实施可能造成的不利后果。"},{"i":14,"n":"第十四条","txt":"各级野生动物保护主管部门应当监测环境对野生动物的影响，发现环境影响对野生动物造成危害时，应当会同有关部门及时进行调查处理。"},{"i":15,"n":"第十五条","txt":"国家重点保护野生动物和有重要生态、科学、社会价值的陆生野生动物或者地方重点保护野生动物受到自然灾害、重大环境污染事故等突发事件威胁时，当地人民政府应当及时采取应急救助措施。"},{"i":16,"n":"第十六条","txt":"野生动物疫源疫病监测、检疫和与人畜共患传染病有关的动物传染病的防治管理，适用《中华人民共和国动物防疫法》等有关法律法规的规定。"},{"i":17,"n":"第十七条","txt":"国家加强对野生动物遗传资源的保护，对濒危野生动物实施抢救性保护。"},{"i":18,"n":"第十八条","txt":"有关地方人民政府应当根据实际情况和需要建设隔离防护设施、设置安全警示标志等，预防野生动物可能造成的危害。"},{"i":19,"n":"第十九条","txt":"因保护本法规定保护的野生动物，造成人员伤亡、农作物或者其他财产损失的，由当地人民政府给予补偿。具体办法由省、自治区、直辖市人民政府制定。有关地方人民政府可以推动保险机构开展野生动物致害赔偿保险业务。"},{"i":20,"n":"第二十条","txt":"在自然保护地和禁猎（渔）区、禁猎（渔）期内，禁止猎捕以及其他妨碍野生动物生息繁衍的活动，但法律法规另有规定的除外。"},{"i":21,"n":"第二十一条","txt":"禁止猎捕、杀害国家重点保护野生动物。"},{"i":22,"n":"第二十二条","txt":"猎捕有重要生态、科学、社会价值的陆生野生动物和地方重点保护野生动物的，应当依法取得县级以上地方人民政府野生动物保护主管部门核发的狩猎证，并服从猎捕量限额管理。"},{"i":23,"n":"第二十三条","txt":"猎捕者应当严格按照特许猎捕证、狩猎证规定的种类、数量或者限额、地点、工具、方法和期限进行猎捕。猎捕作业完成后，应当将猎捕情况向核发特许猎捕证、狩猎证的野生动物保护主管部门备案。具体办法由国务院野生动物保护主管部门制定。猎捕国家重点保护野生动物应当由专业机构和人员承担；猎捕有重要生态、科学、社会价值的陆生野生动物，有条件的地方可以由专业机构有组织开展。"},{"i":24,"n":"第二十四条","txt":"禁止使用毒药、爆炸物、电击或者电子诱捕装置以及猎套、猎夹、捕鸟网、地枪、排铳等工具进行猎捕，禁止使用夜间照明行猎、歼灭性围猎、捣毁巢穴、火攻、烟熏、网捕等方法进行猎捕，但因物种保护、科学研究确需网捕、电子诱捕以及植保作业等除外。"},{"i":25,"n":"第二十五条","txt":"人工繁育野生动物实行分类分级管理，严格保护和科学利用野生动物资源。国家支持有关科学研究机构因物种保护目的人工繁育国家重点保护野生动物。"},{"i":26,"n":"第二十六条","txt":"人工繁育野生动物应当有利于物种保护及其科学研究，不得违法猎捕野生动物，破坏野外种群资源，并根据野生动物习性确保其具有必要的活动空间和生息繁衍、卫生健康条件，具备与其繁育目的、种类、发展规模相适应的场所、设施、技术，符合有关技术标准和防疫要求，不得虐待野生动物。"},{"i":27,"n":"第二十七条","txt":"人工繁育野生动物应当采取安全措施，防止野生动物伤人和逃逸。人工繁育的野生动物造成他人损害、危害公共安全或者破坏生态的，饲养人、管理人等应当依法承担法律责任。"},{"i":28,"n":"第二十八条","txt":"禁止出售、购买、利用国家重点保护野生动物及其制品。"},{"i":29,"n":"第二十九条","txt":"对人工繁育技术成熟稳定的国家重点保护野生动物或者有重要生态、科学、社会价值的陆生野生动物，经科学论证评估，纳入国务院野生动物保护主管部门制定的人工繁育国家重点保护野生动物名录或者有重要生态、科学、社会价值的陆生野生动物名录，并适时调整。对列入名录的野生动物及其制品，可以凭人工繁育许可证或者备案，按照省、自治区、直辖市人民政府野生动物保护主管部门或者其授权的部门核验的年度生产数量直接取得专用标识，凭专用标识出售和利用，保证可追溯。"},{"i":30,"n":"第三十条","txt":"利用野生动物及其制品的，应当以人工繁育种群为主，有利于野外种群养护，符合生态文明建设的要求，尊重社会公德，遵守法律法规和国家有关规定。"},{"i":31,"n":"第三十一条","txt":"禁止食用国家重点保护野生动物和国家保护的有重要生态、科学、社会价值的陆生野生动物以及其他陆生野生动物。"},{"i":32,"n":"第三十二条","txt":"禁止为出售、购买、利用野生动物或者禁止使用的猎捕工具发布广告。禁止为违法出售、购买、利用野生动物制品发布广告。"},{"i":33,"n":"第三十三条","txt":"禁止网络平台、商品交易市场、餐饮场所等，为违法出售、购买、食用及利用野生动物及其制品或者禁止使用的猎捕工具提供展示、交易、消费服务。"},{"i":34,"n":"第三十四条","txt":"运输、携带、寄递国家重点保护野生动物及其制品，或者依照本法第二十九条第二款规定调出国家重点保护野生动物名录的野生动物及其制品出县境的，应当持有或者附有本法第二十一条、第二十五条、第二十八条或者第二十九条规定的许可证、批准文件的副本或者专用标识。"},{"i":35,"n":"第三十五条","txt":"县级以上人民政府野生动物保护主管部门应当对科学研究、人工繁育、公众展示展演等利用野生动物及其制品的活动进行规范和监督管理。"},{"i":36,"n":"第三十六条","txt":"县级以上人民政府野生动物保护主管部门和其他负有野生动物保护职责的部门，在履行本法规定的职责时，可以采取下列措施："},{"i":37,"n":"第三十七条","txt":"中华人民共和国缔结或者参加的国际公约禁止或者限制贸易的野生动物或者其制品名录，由国家濒危物种进出口管理机构制定、调整并公布。"},{"i":38,"n":"第三十八条","txt":"禁止向境外机构或者人员提供我国特有的野生动物遗传资源。开展国际科学研究合作的，应当依法取得批准，有我国科研机构、高等学校、企业及其研究人员实质性参与研究，按照规定提出国家共享惠益的方案，并遵守我国法律、行政法规的规定。"},{"i":39,"n":"第三十九条","txt":"国家组织开展野生动物保护及相关执法活动的国际合作与交流，加强与毗邻国家的协作，保护野生动物迁徙通道；建立防范、打击野生动物及其制品的走私和非法贸易的部门协调机制，开展防范、打击走私和非法贸易行动。"},{"i":40,"n":"第四十条","txt":"从境外引进野生动物物种的，应当经国务院野生动物保护主管部门批准。从境外引进列入本法第三十七条第一款名录的野生动物，还应当依法取得允许进出口证明书。海关凭进口批准文件或者允许进出口证明书办理进境检疫，并依法办理其他海关手续。"},{"i":41,"n":"第四十一条","txt":"国务院野生动物保护主管部门应当会同国务院有关部门加强对放生野生动物活动的规范、引导。任何组织和个人将野生动物放生至野外环境，应当选择适合放生地野外生存的当地物种，不得干扰当地居民的正常生活、生产，避免对生态系统造成危害。具体办法由国务院野生动物保护主管部门制定。随意放生野生动物，造成他人人身、财产损害或者危害生态系统的，依法承担法律责任。"},{"i":42,"n":"第四十二条","txt":"禁止伪造、变造、买卖、转让、租借特许猎捕证、狩猎证、人工繁育许可证及专用标识，出售、购买、利用国家重点保护野生动物及其制品的批准文件，或者允许进出口证明书、进出口等批准文件。"},{"i":43,"n":"第四十三条","txt":"外国人在我国对国家重点保护野生动物进行野外考察或者在野外拍摄电影、录像，应当经省、自治区、直辖市人民政府野生动物保护主管部门或者其授权的单位批准，并遵守有关法律法规的规定。"},{"i":44,"n":"第四十四条","txt":"省、自治区、直辖市人民代表大会或者其常务委员会可以根据地方实际情况制定对地方重点保护野生动物等的管理办法。"},{"i":45,"n":"第四十五条","txt":"野生动物保护主管部门或者其他有关部门不依法作出行政许可决定，发现违法行为或者接到对违法行为的举报不依法处理，或者有其他滥用职权、玩忽职守、徇私舞弊等不依法履行职责的行为的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"违反本法第十二条第三款、第十三条第二款规定的，依照有关法律法规的规定处罚。"},{"i":47,"n":"第四十七条","txt":"违反本法第十五条第四款规定，以收容救护为名买卖野生动物及其制品的，由县级以上人民政府野生动物保护主管部门没收野生动物及其制品、违法所得，并处野生动物及其制品价值二倍以上二十倍以下罚款，将有关违法信息记入社会信用记录，并向社会公布；构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"违反本法第二十条、第二十一条、第二十三条第一款、第二十四条第一款规定，有下列行为之一的，由县级以上人民政府野生动物保护主管部门、海警机构和有关自然保护地管理机构按照职责分工没收猎获物、猎捕工具和违法所得，吊销特许猎捕证，并处猎获物价值二倍以上二十倍以下罚款；没有猎获物或者猎获物价值不足五千元的，并处一万元以上十万元以下罚款；构成犯罪的，依法追究刑事责任："},{"i":49,"n":"第四十九条","txt":"违反本法第二十条、第二十二条、第二十三条第一款、第二十四条第一款规定，有下列行为之一的，由县级以上地方人民政府野生动物保护主管部门和有关自然保护地管理机构按照职责分工没收猎获物、猎捕工具和违法所得，吊销狩猎证，并处猎获物价值一倍以上十倍以下罚款；没有猎获物或者猎获物价值不足二千元的，并处二千元以上二万元以下罚款；构成犯罪的，依法追究刑事责任："},{"i":50,"n":"第五十条","txt":"违反本法第三十一条第二款规定，以食用为目的猎捕、交易、运输在野外环境自然生长繁殖的国家重点保护野生动物或者有重要生态、科学、社会价值的陆生野生动物的，依照本法第四十八条、第四十九条、第五十二条的规定从重处罚。"},{"i":51,"n":"第五十一条","txt":"违反本法第二十五条第二款规定，未取得人工繁育许可证，繁育国家重点保护野生动物或者依照本法第二十九条第二款规定调出国家重点保护野生动物名录的野生动物的，由县级以上人民政府野生动物保护主管部门没收野生动物及其制品，并处野生动物及其制品价值一倍以上十倍以下罚款。"},{"i":52,"n":"第五十二条","txt":"违反本法第二十八条第一款和第二款、第二十九条第一款、第三十四条第一款规定，未经批准、未取得或者未按照规定使用专用标识，或者未持有、未附有人工繁育许可证、批准文件的副本或者专用标识出售、购买、利用、运输、携带、寄递国家重点保护野生动物及其制品或者依照本法第二十九条第二款规定调出国家重点保护野生动物名录的野生动物及其制品的，由县级以上人民政府野生动物保护主管部门和市场监督管理部门按照职责分工没收野生动物及其制品和违法所得，责令关闭违法经营场所，并处野生动物及其制品价值二倍以上二十倍以下罚款；情节严重的，吊销人工繁育许可证、撤销批准文件、收回专用标识；构成犯罪的，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"违反本法第三十一条第一款、第四款规定，食用或者为食用非法购买本法规定保护的野生动物及其制品的，由县级以上人民政府野生动物保护主管部门和市场监督管理部门按照职责分工责令停止违法行为，没收野生动物及其制品，并处野生动物及其制品价值二倍以上二十倍以下罚款；食用或者为食用非法购买其他陆生野生动物及其制品的，责令停止违法行为，给予批评教育，没收野生动物及其制品，情节严重的，并处野生动物及其制品价值一倍以上五倍以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":54,"n":"第五十四条","txt":"违反本法第三十二条规定，为出售、购买、利用野生动物及其制品或者禁止使用的猎捕工具发布广告的，依照《中华人民共和国广告法》的规定处罚。"},{"i":55,"n":"第五十五条","txt":"违反本法第三十三条规定，为违法出售、购买、食用及利用野生动物及其制品或者禁止使用的猎捕工具提供展示、交易、消费服务的，由县级以上人民政府市场监督管理部门责令停止违法行为，限期改正，没收违法所得，并处违法所得二倍以上十倍以下罚款；没有违法所得或者违法所得不足五千元的，处一万元以上十万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":56,"n":"第五十六条","txt":"违反本法第三十七条规定，进出口野生动物及其制品的，由海关、公安机关、海警机构依照法律、行政法规和国家有关规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"违反本法第三十八条规定，向境外机构或者人员提供我国特有的野生动物遗传资源的，由县级以上人民政府野生动物保护主管部门没收野生动物及其制品和违法所得，并处野生动物及其制品价值或者违法所得一倍以上五倍以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"违反本法第四十条第一款规定，从境外引进野生动物物种的，由县级以上人民政府野生动物保护主管部门没收所引进的野生动物，并处五万元以上五十万元以下罚款；未依法实施进境检疫的，依照《中华人民共和国进出境动植物检疫法》的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":59,"n":"第五十九条","txt":"违反本法第四十条第二款规定，将从境外引进的野生动物放生、丢弃的，由县级以上人民政府野生动物保护主管部门责令限期捕回，处一万元以上十万元以下罚款；逾期不捕回的，由有关野生动物保护主管部门代为捕回或者采取降低影响的措施，所需费用由被责令限期捕回者承担；构成犯罪的，依法追究刑事责任。"},{"i":60,"n":"第六十条","txt":"违反本法第四十二条第一款规定，伪造、变造、买卖、转让、租借有关证件、专用标识或者有关批准文件的，由县级以上人民政府野生动物保护主管部门没收违法证件、专用标识、有关批准文件和违法所得，并处五万元以上五十万元以下罚款；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":61,"n":"第六十一条","txt":"县级以上人民政府野生动物保护主管部门和其他负有野生动物保护职责的部门、机构应当按照有关规定处理罚没的野生动物及其制品，具体办法由国务院野生动物保护主管部门会同国务院有关部门制定。"},{"i":62,"n":"第六十二条","txt":"县级以上人民政府野生动物保护主管部门应当加强对野生动物及其制品鉴定、价值评估工作的规范、指导。本法规定的猎获物价值、野生动物及其制品价值的评估标准和方法，由国务院野生动物保护主管部门制定。"},{"i":63,"n":"第六十三条","txt":"对违反本法规定破坏野生动物资源、生态环境，损害社会公共利益的行为，可以依照《中华人民共和国环境保护法》、《中华人民共和国民事诉讼法》、《中华人民共和国行政诉讼法》等法律的规定向人民法院提起诉讼。"},{"i":64,"n":"第六十四条","txt":"本法自2023年5月1日起施行。"}],"changjiangbaohufa":[{"i":1,"n":"第一条","txt":"为了加强长江流域生态环境保护和修复，促进资源合理高效利用，保障生态安全，实现人与自然和谐共生、中华民族永续发展，制定本法。"},{"i":2,"n":"第二条","txt":"在长江流域开展生态环境保护和修复以及长江流域各类生产生活、开发建设活动，应当遵守本法。"},{"i":3,"n":"第三条","txt":"长江流域经济社会发展，应当坚持生态优先、绿色发展，共抓大保护、不搞大开发；长江保护应当坚持统筹协调、科学规划、创新驱动、系统治理。"},{"i":4,"n":"第四条","txt":"国家建立长江流域协调机制，统一指导、统筹协调长江保护工作，审议长江保护重大政策、重大规划，协调跨地区跨部门重大事项，督促检查长江保护重要工作的落实情况。"},{"i":5,"n":"第五条","txt":"国务院有关部门和长江流域省级人民政府负责落实国家长江流域协调机制的决策，按照职责分工负责长江保护相关工作。"},{"i":6,"n":"第六条","txt":"长江流域相关地方根据需要在地方性法规和政府规章制定、规划编制、监督执法等方面建立协作机制，协同推进长江流域生态环境保护和修复。"},{"i":7,"n":"第七条","txt":"国务院生态环境、自然资源、水行政、农业农村和标准化等有关主管部门按照职责分工，建立健全长江流域水环境质量和污染物排放、生态环境修复、水资源节约集约利用、生态流量、生物多样性保护、水产养殖、防灾减灾等标准体系。"},{"i":8,"n":"第八条","txt":"国务院自然资源主管部门会同国务院有关部门定期组织长江流域土地、矿产、水流、森林、草原、湿地等自然资源状况调查，建立资源基础数据库，开展资源环境承载能力评价，并向社会公布长江流域自然资源状况。"},{"i":9,"n":"第九条","txt":"国家长江流域协调机制应当统筹协调国务院有关部门在已经建立的台站和监测项目基础上，健全长江流域生态环境、资源、水文、气象、航运、自然灾害等监测网络体系和监测信息共享机制。"},{"i":10,"n":"第十条","txt":"国务院生态环境主管部门会同国务院有关部门和长江流域省级人民政府建立健全长江流域突发生态环境事件应急联动工作机制，与国家突发事件应急体系相衔接，加强对长江流域船舶、港口、矿山、化工厂、尾矿库等发生的突发生态环境事件的应急管理。"},{"i":11,"n":"第十一条","txt":"国家加强长江流域洪涝干旱、森林草原火灾、地质灾害、地震等灾害的监测预报预警、防御、应急处置与恢复重建体系建设，提高防灾、减灾、抗灾、救灾能力。"},{"i":12,"n":"第十二条","txt":"国家长江流域协调机制设立专家咨询委员会，组织专业机构和人员对长江流域重大发展战略、政策、规划等开展科学技术等专业咨询。"},{"i":13,"n":"第十三条","txt":"国家长江流域协调机制统筹协调国务院有关部门和长江流域省级人民政府建立健全长江流域信息共享系统。国务院有关部门和长江流域省级人民政府及其有关部门应当按照规定，共享长江流域生态环境、自然资源以及管理执法等信息。"},{"i":14,"n":"第十四条","txt":"国务院有关部门和长江流域县级以上地方人民政府及其有关部门应当加强长江流域生态环境保护和绿色发展的宣传教育。"},{"i":15,"n":"第十五条","txt":"国务院有关部门和长江流域县级以上地方人民政府及其有关部门应当采取措施，保护长江流域历史文化名城名镇名村，加强长江流域文化遗产保护工作，继承和弘扬长江流域优秀特色文化。"},{"i":16,"n":"第十六条","txt":"国家鼓励、支持单位和个人参与长江流域生态环境保护和修复、资源合理利用、促进绿色发展的活动。"},{"i":17,"n":"第十七条","txt":"国家建立以国家发展规划为统领，以空间规划为基础，以专项规划、区域规划为支撑的长江流域规划体系，充分发挥规划对推进长江流域生态环境保护和绿色发展的引领、指导和约束作用。"},{"i":18,"n":"第十八条","txt":"国务院和长江流域县级以上地方人民政府应当将长江保护工作纳入国民经济和社会发展规划。"},{"i":19,"n":"第十九条","txt":"国务院自然资源主管部门会同国务院有关部门组织编制长江流域国土空间规划，科学有序统筹安排长江流域生态、农业、城镇等功能空间，划定生态保护红线、永久基本农田、城镇开发边界，优化国土空间结构和布局，统领长江流域国土空间利用任务，报国务院批准后实施。涉及长江流域国土空间利用的专项规划应当与长江流域国土空间规划相衔接。"},{"i":20,"n":"第二十条","txt":"国家对长江流域国土空间实施用途管制。长江流域县级以上地方人民政府自然资源主管部门依照国土空间规划，对所辖长江流域国土空间实施分区、分类用途管制。"},{"i":21,"n":"第二十一条","txt":"国务院水行政主管部门统筹长江流域水资源合理配置、统一调度和高效利用，组织实施取用水总量控制和消耗强度控制管理制度。"},{"i":22,"n":"第二十二条","txt":"长江流域省级人民政府根据本行政区域的生态环境和资源利用状况，制定生态环境分区管控方案和生态环境准入清单，报国务院生态环境主管部门备案后实施。生态环境分区管控方案和生态环境准入清单应当与国土空间规划相衔接。"},{"i":23,"n":"第二十三条","txt":"国家加强对长江流域水能资源开发利用的管理。因国家发展战略和国计民生需要，在长江流域新建大中型水电工程，应当经科学论证，并报国务院或者国务院授权的部门批准。"},{"i":24,"n":"第二十四条","txt":"国家对长江干流和重要支流源头实行严格保护，设立国家公园等自然保护地，保护国家生态安全屏障。"},{"i":25,"n":"第二十五条","txt":"国务院水行政主管部门加强长江流域河道、湖泊保护工作。长江流域县级以上地方人民政府负责划定河道、湖泊管理范围，并向社会公告，实行严格的河湖保护，禁止非法侵占河湖水域。"},{"i":26,"n":"第二十六条","txt":"国家对长江流域河湖岸线实施特殊管制。国家长江流域协调机制统筹协调国务院自然资源、水行政、生态环境、住房和城乡建设、农业农村、交通运输、林业和草原等部门和长江流域省级人民政府划定河湖岸线保护范围，制定河湖岸线保护规划，严格控制岸线开发建设，促进岸线合理高效利用。"},{"i":27,"n":"第二十七条","txt":"国务院交通运输主管部门会同国务院自然资源、水行政、生态环境、农业农村、林业和草原主管部门在长江流域水生生物重要栖息地科学划定禁止航行区域和限制航行区域。"},{"i":28,"n":"第二十八条","txt":"国家建立长江流域河道采砂规划和许可制度。长江流域河道采砂应当依法取得国务院水行政主管部门有关流域管理机构或者县级以上地方人民政府水行政主管部门的许可。"},{"i":29,"n":"第二十九条","txt":"长江流域水资源保护与利用，应当根据流域综合规划，优先满足城乡居民生活用水，保障基本生态用水，并统筹农业、工业用水以及航运等需要。"},{"i":30,"n":"第三十条","txt":"国务院水行政主管部门有关流域管理机构商长江流域省级人民政府依法制定跨省河流水量分配方案，报国务院或者国务院授权的部门批准后实施。制定长江流域跨省河流水量分配方案应当征求国务院有关部门的意见。长江流域省级人民政府水行政主管部门制定本行政区域的长江流域水量分配方案，报本级人民政府批准后实施。"},{"i":31,"n":"第三十一条","txt":"国家加强长江流域生态用水保障。国务院水行政主管部门会同国务院有关部门提出长江干流、重要支流和重要湖泊控制断面的生态流量管控指标。其他河湖生态流量管控指标由长江流域县级以上地方人民政府水行政主管部门会同本级人民政府有关部门确定。"},{"i":32,"n":"第三十二条","txt":"国务院有关部门和长江流域地方各级人民政府应当采取措施，加快病险水库除险加固，推进堤防和蓄滞洪区建设，提升洪涝灾害防御工程标准，加强水工程联合调度，开展河道泥沙观测和河势调查，建立与经济社会发展相适应的防洪减灾工程和非工程体系，提高防御水旱灾害的整体能力。"},{"i":33,"n":"第三十三条","txt":"国家对跨长江流域调水实行科学论证，加强控制和管理。实施跨长江流域调水应当优先保障调出区域及其下游区域的用水安全和生态安全，统筹调出区域和调入区域用水需求。"},{"i":34,"n":"第三十四条","txt":"国家加强长江流域饮用水水源地保护。国务院水行政主管部门会同国务院有关部门制定长江流域饮用水水源地名录。长江流域省级人民政府水行政主管部门会同本级人民政府有关部门制定本行政区域的其他饮用水水源地名录。"},{"i":35,"n":"第三十五条","txt":"长江流域县级以上地方人民政府及其有关部门应当合理布局饮用水水源取水口，制定饮用水安全突发事件应急预案，加强饮用水备用应急水源建设，对饮用水水源的水环境质量进行实时监测。"},{"i":36,"n":"第三十六条","txt":"丹江口库区及其上游所在地县级以上地方人民政府应当按照饮用水水源地安全保障区、水质影响控制区、水源涵养生态建设区管理要求，加强山水林田湖草整体保护，增强水源涵养能力，保障水质稳定达标。"},{"i":37,"n":"第三十七条","txt":"国家加强长江流域地下水资源保护。长江流域县级以上地方人民政府及其有关部门应当定期调查评估地下水资源状况，监测地下水水量、水位、水环境质量，并采取相应风险防范措施，保障地下水资源安全。"},{"i":38,"n":"第三十八条","txt":"国务院水行政主管部门会同国务院有关部门确定长江流域农业、工业用水效率目标，加强用水计量和监测设施建设；完善规划和建设项目水资源论证制度；加强对高耗水行业、重点用水单位的用水定额管理，严格控制高耗水项目建设。"},{"i":39,"n":"第三十九条","txt":"国家统筹长江流域自然保护地体系建设。国务院和长江流域省级人民政府在长江流域重要典型生态系统的完整分布区、生态环境敏感区以及珍贵野生动植物天然集中分布区和重要栖息地、重要自然遗迹分布区等区域，依法设立国家公园、自然保护区、自然公园等自然保护地。"},{"i":40,"n":"第四十条","txt":"国务院和长江流域省级人民政府应当依法在长江流域重要生态区、生态状况脆弱区划定公益林，实施严格管理。国家对长江流域天然林实施严格保护，科学划定天然林保护重点区域。"},{"i":41,"n":"第四十一条","txt":"国务院农业农村主管部门会同国务院有关部门和长江流域省级人民政府建立长江流域水生生物完整性指数评价体系，组织开展长江流域水生生物完整性评价，并将结果作为评估长江流域生态系统总体状况的重要依据。长江流域水生生物完整性指数应当与长江流域水环境质量标准相衔接。"},{"i":42,"n":"第四十二条","txt":"国务院农业农村主管部门和长江流域县级以上地方人民政府应当制定长江流域珍贵、濒危水生野生动植物保护计划，对长江流域珍贵、濒危水生野生动植物实行重点保护。"},{"i":43,"n":"第四十三条","txt":"国务院生态环境主管部门和长江流域地方各级人民政府应当采取有效措施，加大对长江流域的水污染防治、监管力度，预防、控制和减少水环境污染。"},{"i":44,"n":"第四十四条","txt":"国务院生态环境主管部门负责制定长江流域水环境质量标准，对国家水环境质量标准中未作规定的项目可以补充规定；对国家水环境质量标准中已经规定的项目，可以作出更加严格的规定。制定长江流域水环境质量标准应当征求国务院有关部门和有关省级人民政府的意见。长江流域省级人民政府可以制定严于长江流域水环境质量标准的地方水环境质量标准，报国务院生态环境主管部门备案。"},{"i":45,"n":"第四十五条","txt":"长江流域省级人民政府应当对没有国家水污染物排放标准的特色产业、特有污染物，或者国家有明确要求的特定水污染源或者水污染物，补充制定地方水污染物排放标准，报国务院生态环境主管部门备案。"},{"i":46,"n":"第四十六条","txt":"长江流域省级人民政府制定本行政区域的总磷污染控制方案，并组织实施。对磷矿、磷肥生产集中的长江干支流，有关省级人民政府应当制定更加严格的总磷排放管控要求，有效控制总磷排放总量。"},{"i":47,"n":"第四十七条","txt":"长江流域县级以上地方人民政府应当统筹长江流域城乡污水集中处理设施及配套管网建设，并保障其正常运行，提高城乡污水收集处理能力。"},{"i":48,"n":"第四十八条","txt":"国家加强长江流域农业面源污染防治。长江流域农业生产应当科学使用农业投入品，减少化肥、农药施用，推广有机肥使用，科学处置农用薄膜、农作物秸秆等农业废弃物。"},{"i":49,"n":"第四十九条","txt":"禁止在长江流域河湖管理范围内倾倒、填埋、堆放、弃置、处理固体废物。长江流域县级以上地方人民政府应当加强对固体废物非法转移和倾倒的联防联控。"},{"i":50,"n":"第五十条","txt":"长江流域县级以上地方人民政府应当组织对沿河湖垃圾填埋场、加油站、矿山、尾矿库、危险废物处置场、化工园区和化工项目等地下水重点污染源及周边地下水环境风险隐患开展调查评估，并采取相应风险防范和整治措施。"},{"i":51,"n":"第五十一条","txt":"国家建立长江流域危险货物运输船舶污染责任保险与财务担保相结合机制。具体办法由国务院交通运输主管部门会同国务院有关部门制定。"},{"i":52,"n":"第五十二条","txt":"国家对长江流域生态系统实行自然恢复为主、自然恢复与人工修复相结合的系统治理。国务院自然资源主管部门会同国务院有关部门编制长江流域生态环境修复规划，组织实施重大生态环境修复工程，统筹推进长江流域各项生态环境修复工作。"},{"i":53,"n":"第五十三条","txt":"国家对长江流域重点水域实行严格捕捞管理。在长江流域水生生物保护区全面禁止生产性捕捞；在国家规定的期限内，长江干流和重要支流、大型通江湖泊、长江河口规定区域等重点水域全面禁止天然渔业资源的生产性捕捞。具体办法由国务院农业农村主管部门会同国务院有关部门制定。"},{"i":54,"n":"第五十四条","txt":"国务院水行政主管部门会同国务院有关部门制定并组织实施长江干流和重要支流的河湖水系连通修复方案，长江流域省级人民政府制定并组织实施本行政区域的长江流域河湖水系连通修复方案，逐步改善长江流域河湖连通状况，恢复河湖生态流量，维护河湖水系生态功能。"},{"i":55,"n":"第五十五条","txt":"国家长江流域协调机制统筹协调国务院自然资源、水行政、生态环境、住房和城乡建设、农业农村、交通运输、林业和草原等部门和长江流域省级人民政府制定长江流域河湖岸线修复规范，确定岸线修复指标。"},{"i":56,"n":"第五十六条","txt":"国务院有关部门会同长江流域有关省级人民政府加强对三峡库区、丹江口库区等重点库区消落区的生态环境保护和修复，因地制宜实施退耕还林还草还湿，禁止施用化肥、农药，科学调控水库水位，加强库区水土保持和地质灾害防治工作，保障消落区良好生态功能。"},{"i":57,"n":"第五十七条","txt":"长江流域县级以上地方人民政府林业和草原主管部门负责组织实施长江流域森林、草原、湿地修复计划，科学推进森林、草原、湿地修复工作，加大退化天然林、草原和受损湿地修复力度。"},{"i":58,"n":"第五十八条","txt":"国家加大对太湖、鄱阳湖、洞庭湖、巢湖、滇池等重点湖泊实施生态环境修复的支持力度。"},{"i":59,"n":"第五十九条","txt":"国务院林业和草原、农业农村主管部门应当对长江流域数量急剧下降或者极度濒危的野生动植物和受到严重破坏的栖息地、天然集中分布区、破碎化的典型生态系统制定修复方案和行动计划，修建迁地保护设施，建立野生动植物遗传资源基因库，进行抢救性修复。"},{"i":60,"n":"第六十条","txt":"国务院水行政主管部门会同国务院有关部门和长江河口所在地人民政府按照陆海统筹、河海联动的要求，制定实施长江河口生态环境修复和其他保护措施方案，加强对水、沙、盐、潮滩、生物种群的综合监测，采取有效措施防止海水入侵和倒灌，维护长江河口良好生态功能。"},{"i":61,"n":"第六十一条","txt":"长江流域水土流失重点预防区和重点治理区的县级以上地方人民政府应当采取措施，防治水土流失。生态保护红线范围内的水土流失地块，以自然恢复为主，按照规定有计划地实施退耕还林还草还湿；划入自然保护地核心保护区的永久基本农田，依法有序退出并予以补划。"},{"i":62,"n":"第六十二条","txt":"长江流域县级以上地方人民政府应当因地制宜采取消除地质灾害隐患、土地复垦、恢复植被、防治污染等措施，加快历史遗留矿山生态环境修复工作，并加强对在建和运行中矿山的监督管理，督促采矿权人切实履行矿山污染防治和生态环境修复责任。"},{"i":63,"n":"第六十三条","txt":"长江流域中下游地区县级以上地方人民政府应当因地制宜在项目、资金、人才、管理等方面，对长江流域江河源头和上游地区实施生态环境修复和其他保护措施给予支持，提升长江流域生态脆弱区实施生态环境修复和其他保护措施的能力。"},{"i":64,"n":"第六十四条","txt":"国务院有关部门和长江流域地方各级人民政府应当按照长江流域发展规划、国土空间规划的要求，调整产业结构，优化产业布局，推进长江流域绿色发展。"},{"i":65,"n":"第六十五条","txt":"国务院和长江流域地方各级人民政府及其有关部门应当协同推进乡村振兴战略和新型城镇化战略的实施，统筹城乡基础设施建设和产业发展，建立健全全民覆盖、普惠共享、城乡一体的基本公共服务体系，促进长江流域城乡融合发展。"},{"i":66,"n":"第六十六条","txt":"长江流域县级以上地方人民政府应当推动钢铁、石油、化工、有色金属、建材、船舶等产业升级改造，提升技术装备水平；推动造纸、制革、电镀、印染、有色金属、农药、氮肥、焦化、原料药制造等企业实施清洁化改造。企业应当通过技术创新减少资源消耗和污染物排放。"},{"i":67,"n":"第六十七条","txt":"国务院有关部门会同长江流域省级人民政府建立开发区绿色发展评估机制，并组织对各类开发区的资源能源节约集约利用、生态环境保护等情况开展定期评估。"},{"i":68,"n":"第六十八条","txt":"国家鼓励和支持在长江流域实施重点行业和重点用水单位节水技术改造，提高水资源利用效率。"},{"i":69,"n":"第六十九条","txt":"长江流域县级以上地方人民政府应当按照绿色发展的要求，统筹规划、建设与管理，提升城乡人居环境质量，建设美丽城镇和美丽乡村。"},{"i":70,"n":"第七十条","txt":"长江流域县级以上地方人民政府应当编制并组织实施养殖水域滩涂规划，合理划定禁养区、限养区、养殖区，科学确定养殖规模和养殖密度；强化水产养殖投入品管理，指导和规范水产养殖、增殖活动。"},{"i":71,"n":"第七十一条","txt":"国家加强长江流域综合立体交通体系建设，完善港口、航道等水运基础设施，推动交通设施互联互通，实现水陆有机衔接、江海直达联运，提升长江黄金水道功能。"},{"i":72,"n":"第七十二条","txt":"长江流域县级以上地方人民政府应当统筹建设船舶污染物接收转运处置设施、船舶液化天然气加注站，制定港口岸电设施、船舶受电设施建设和改造计划，并组织实施。具备岸电使用条件的船舶靠港应当按照国家有关规定使用岸电，但使用清洁能源的除外。"},{"i":73,"n":"第七十三条","txt":"国务院和长江流域县级以上地方人民政府对长江流域港口、航道和船舶升级改造，液化天然气动力船舶等清洁能源或者新能源动力船舶建造，港口绿色设计等按照规定给予资金支持或者政策扶持。"},{"i":74,"n":"第七十四条","txt":"长江流域地方各级人民政府加强对城乡居民绿色消费的宣传教育，并采取有效措施，支持、引导居民绿色消费。"},{"i":75,"n":"第七十五条","txt":"国务院和长江流域县级以上地方人民政府应当加大长江流域生态环境保护和修复的财政投入。"},{"i":76,"n":"第七十六条","txt":"国家建立长江流域生态保护补偿制度。"},{"i":77,"n":"第七十七条","txt":"国家加强长江流域司法保障建设，鼓励有关单位为长江流域生态环境保护提供法律服务。"},{"i":78,"n":"第七十八条","txt":"国家实行长江流域生态环境保护责任制和考核评价制度。上级人民政府应当对下级人民政府生态环境保护和修复目标完成情况等进行考核。"},{"i":79,"n":"第七十九条","txt":"国务院有关部门和长江流域县级以上地方人民政府有关部门应当依照本法规定和职责分工，对长江流域各类保护、开发、建设活动进行监督检查，依法查处破坏长江流域自然资源、污染长江流域环境、损害长江流域生态系统等违法行为。"},{"i":80,"n":"第八十条","txt":"国务院有关部门和长江流域地方各级人民政府及其有关部门对长江流域跨行政区域、生态敏感区域和生态环境违法案件高发区域以及重大违法案件，依法开展联合执法。"},{"i":81,"n":"第八十一条","txt":"国务院有关部门和长江流域省级人民政府对长江保护工作不力、问题突出、群众反映集中的地区，可以约谈所在地区县级以上地方人民政府及其有关部门主要负责人，要求其采取措施及时整改。"},{"i":82,"n":"第八十二条","txt":"国务院应当定期向全国人民代表大会常务委员会报告长江流域生态环境状况及保护和修复工作等情况。"},{"i":83,"n":"第八十三条","txt":"国务院有关部门和长江流域地方各级人民政府及其有关部门违反本法规定，有下列行为之一的，对直接负责的主管人员和其他直接责任人员依法给予警告、记过、记大过或者降级处分；造成严重后果的，给予撤职或者开除处分，其主要负责人应当引咎辞职："},{"i":84,"n":"第八十四条","txt":"违反本法规定，有下列行为之一的，由有关主管部门按照职责分工，责令停止违法行为，给予警告，并处一万元以上十万元以下罚款；情节严重的，并处十万元以上五十万元以下罚款："},{"i":85,"n":"第八十五条","txt":"违反本法规定，在长江流域开放水域养殖、投放外来物种或者其他非本地物种种质资源的，由县级以上人民政府农业农村主管部门责令限期捕回，处十万元以下罚款；造成严重后果的，处十万元以上一百万元以下罚款；逾期不捕回的，由有关人民政府农业农村主管部门代为捕回或者采取降低负面影响的措施，所需费用由违法者承担。"},{"i":86,"n":"第八十六条","txt":"违反本法规定，在长江流域水生生物保护区内从事生产性捕捞，或者在长江干流和重要支流、大型通江湖泊、长江河口规定区域等重点水域禁捕期间从事天然渔业资源的生产性捕捞的，由县级以上人民政府农业农村主管部门没收渔获物、违法所得以及用于违法活动的渔船、渔具和其他工具，并处一万元以上五万元以下罚款；采取电鱼、毒鱼、炸鱼等方式捕捞，或者有其他严重情节的，并处五万元以上五十万元以下罚款。"},{"i":87,"n":"第八十七条","txt":"违反本法规定，非法侵占长江流域河湖水域，或者违法利用、占用河湖岸线的，由县级以上人民政府水行政、自然资源等主管部门按照职责分工，责令停止违法行为，限期拆除并恢复原状，所需费用由违法者承担，没收违法所得，并处五万元以上五十万元以下罚款。"},{"i":88,"n":"第八十八条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府生态环境、自然资源等主管部门按照职责分工，责令停止违法行为，限期拆除并恢复原状，所需费用由违法者承担，没收违法所得，并处五十万元以上五百万元以下罚款，对直接负责的主管人员和其他直接责任人员处五万元以上十万元以下罚款；情节严重的，报经有批准权的人民政府批准，责令关闭："},{"i":89,"n":"第八十九条","txt":"长江流域磷矿开采加工、磷肥和含磷农药制造等企业违反本法规定，超过排放标准或者总量控制指标排放含磷水污染物的，由县级以上人民政府生态环境主管部门责令停止违法行为，并处二十万元以上二百万元以下罚款，对直接负责的主管人员和其他直接责任人员处五万元以上十万元以下罚款；情节严重的，责令停产整顿，或者报经有批准权的人民政府批准，责令关闭。"},{"i":90,"n":"第九十条","txt":"违反本法规定，在长江流域水上运输剧毒化学品和国家规定禁止通过内河运输的其他危险化学品的，由县级以上人民政府交通运输主管部门或者海事管理机构责令改正，没收违法所得，并处二十万元以上二百万元以下罚款，对直接负责的主管人员和其他直接责任人员处五万元以上十万元以下罚款；情节严重的，责令停业整顿，或者吊销相关许可证。"},{"i":91,"n":"第九十一条","txt":"违反本法规定，在长江流域未依法取得许可从事采砂活动，或者在禁止采砂区和禁止采砂期从事采砂活动的，由国务院水行政主管部门有关流域管理机构或者县级以上地方人民政府水行政主管部门责令停止违法行为，没收违法所得以及用于违法活动的船舶、设备、工具，并处货值金额二倍以上二十倍以下罚款；货值金额不足十万元的，并处二十万元以上二百万元以下罚款；已经取得河道采砂许可证的，吊销河道采砂许可证。"},{"i":92,"n":"第九十二条","txt":"对破坏长江流域自然资源、污染长江流域环境、损害长江流域生态系统等违法行为，本法未作行政处罚规定的，适用有关法律、行政法规的规定。"},{"i":93,"n":"第九十三条","txt":"因污染长江流域环境、破坏长江流域生态造成他人损害的，侵权人应当承担侵权责任。"},{"i":94,"n":"第九十四条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":95,"n":"第九十五条","txt":"本法下列用语的含义："},{"i":96,"n":"第九十六条","txt":"本法自2021年3月1日起施行。"}],"fangshazhishafa":[{"i":1,"n":"第一条","txt":"为预防土地沙化，治理沙化土地，维护生态安全，促进经济和社会的可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，从事土地沙化的预防、沙化土地的治理和开发利用活动，必须遵守本法。"},{"i":3,"n":"第三条","txt":"防沙治沙工作应当遵循以下原则："},{"i":4,"n":"第四条","txt":"国务院和沙化土地所在地区的县级以上地方人民政府，应当将防沙治沙纳入国民经济和社会发展计划，保障和支持防沙治沙工作的开展。"},{"i":5,"n":"第五条","txt":"在国务院领导下，国务院林业草原行政主管部门负责组织、协调、指导全国防沙治沙工作。"},{"i":6,"n":"第六条","txt":"使用土地的单位和个人，有防止该土地沙化的义务。"},{"i":7,"n":"第七条","txt":"国家支持防沙治沙的科学研究和技术推广工作，发挥科研部门、机构在防沙治沙工作中的作用，培养防沙治沙专门技术人员，提高防沙治沙的科学技术水平。"},{"i":8,"n":"第八条","txt":"在防沙治沙工作中作出显著成绩的单位和个人，由人民政府给予表彰和奖励；对保护和改善生态质量作出突出贡献的应当给予重奖。"},{"i":9,"n":"第九条","txt":"沙化土地所在地区的各级人民政府应当组织有关部门开展防沙治沙知识的宣传教育，增强公民的防沙治沙意识，提高公民防沙治沙的能力。"},{"i":10,"n":"第十条","txt":"防沙治沙实行统一规划。从事防沙治沙活动，以及在沙化土地范围内从事开发利用活动，必须遵循防沙治沙规划。"},{"i":11,"n":"第十一条","txt":"国务院林业草原行政主管部门会同国务院农业、水利、土地、生态环境等有关部门编制全国防沙治沙规划，报国务院批准后实施。"},{"i":12,"n":"第十二条","txt":"编制防沙治沙规划，应当根据沙化土地所处的地理位置、土地类型、植被状况、气候和水资源状况、土地沙化程度等自然条件及其所发挥的生态、经济功能，对沙化土地实行分类保护、综合治理和合理利用。"},{"i":13,"n":"第十三条","txt":"防沙治沙规划应当与土地利用总体规划相衔接；防沙治沙规划中确定的沙化土地用途，应当符合本级人民政府的土地利用总体规划。"},{"i":14,"n":"第十四条","txt":"国务院林业草原行政主管部门组织其他有关行政主管部门对全国土地沙化情况进行监测、统计和分析，并定期公布监测结果。"},{"i":15,"n":"第十五条","txt":"县级以上地方人民政府林业草原或者其他有关行政主管部门，在土地沙化监测过程中，发现土地发生沙化或者沙化程度加重的，应当及时报告本级人民政府。收到报告的人民政府应当责成有关行政主管部门制止导致土地沙化的行为，并采取有效措施进行治理。"},{"i":16,"n":"第十六条","txt":"沙化土地所在地区的县级以上地方人民政府应当按照防沙治沙规划，划出一定比例的土地，因地制宜地营造防风固沙林网、林带，种植多年生灌木和草本植物。由林业草原行政主管部门负责确定植树造林的成活率、保存率的标准和具体任务，并逐片组织实施，明确责任，确保完成。"},{"i":17,"n":"第十七条","txt":"禁止在沙化土地上砍挖灌木、药材及其他固沙植物。"},{"i":18,"n":"第十八条","txt":"草原地区的地方各级人民政府，应当加强草原的管理和建设，由林业草原行政主管部门会同畜牧业行政主管部门负责指导、组织农牧民建设人工草场，控制载畜量，调整牲畜结构，改良牲畜品种，推行牲畜圈养和草场轮牧，消灭草原鼠害、虫害，保护草原植被，防止草原退化和沙化。"},{"i":19,"n":"第十九条","txt":"沙化土地所在地区的县级以上地方人民政府水行政主管部门，应当加强流域和区域水资源的统一调配和管理，在编制流域和区域水资源开发利用规划和供水计划时，必须考虑整个流域和区域植被保护的用水需求，防止因地下水和上游水资源的过度开发利用，导致植被破坏和土地沙化。该规划和计划经批准后，必须严格实施。"},{"i":20,"n":"第二十条","txt":"沙化土地所在地区的县级以上地方人民政府，不得批准在沙漠边缘地带和林地、草原开垦耕地；已经开垦并对生态产生不良影响的，应当有计划地组织退耕还林还草。"},{"i":21,"n":"第二十一条","txt":"在沙化土地范围内从事开发建设活动的，必须事先就该项目可能对当地及相关地区生态产生的影响进行环境影响评价，依法提交环境影响报告；环境影响报告应当包括有关防沙治沙的内容。"},{"i":22,"n":"第二十二条","txt":"在沙化土地封禁保护区范围内，禁止一切破坏植被的活动。"},{"i":23,"n":"第二十三条","txt":"沙化土地所在地区的地方各级人民政府，应当按照防沙治沙规划，组织有关部门、单位和个人，因地制宜地采取人工造林种草、飞机播种造林种草、封沙育林育草和合理调配生态用水等措施，恢复和增加植被，治理已经沙化的土地。"},{"i":24,"n":"第二十四条","txt":"国家鼓励单位和个人在自愿的前提下，捐资或者以其他形式开展公益性的治沙活动。"},{"i":25,"n":"第二十五条","txt":"使用已经沙化的国有土地的使用权人和农民集体所有土地的承包经营权人，必须采取治理措施，改善土地质量；确实无能力完成治理任务的，可以委托他人治理或者与他人合作治理。委托或者合作治理的，应当签订协议，明确各方的权利和义务。"},{"i":26,"n":"第二十六条","txt":"不具有土地所有权或者使用权的单位和个人从事营利性治沙活动的，应当先与土地所有权人或者使用权人签订协议，依法取得土地使用权。"},{"i":27,"n":"第二十七条","txt":"本法第二十六条第二款第二项所称治理方案，应当包括以下内容："},{"i":28,"n":"第二十八条","txt":"从事营利性治沙活动的单位和个人，必须按照治理方案进行治理。"},{"i":29,"n":"第二十九条","txt":"治理者完成治理任务后，应当向县级以上地方人民政府受理治理申请的行政主管部门提出验收申请。经验收合格的，受理治理申请的行政主管部门应当发给治理合格证明文件；经验收不合格的，治理者应当继续治理。"},{"i":30,"n":"第三十条","txt":"已经沙化的土地范围内的铁路、公路、河流和水渠两侧，城镇、村庄、厂矿和水库周围，实行单位治理责任制，由县级以上地方人民政府下达治理责任书，由责任单位负责组织造林种草或者采取其他治理措施。"},{"i":31,"n":"第三十一条","txt":"沙化土地所在地区的地方各级人民政府，可以组织当地农村集体经济组织及其成员在自愿的前提下，对已经沙化的土地进行集中治理。农村集体经济组织及其成员投入的资金和劳力，可以折算为治理项目的股份、资本金，也可以采取其他形式给予补偿。"},{"i":32,"n":"第三十二条","txt":"国务院和沙化土地所在地区的地方各级人民政府应当在本级财政预算中按照防沙治沙规划通过项目预算安排资金，用于本级人民政府确定的防沙治沙工程。在安排扶贫、农业、水利、道路、矿产、能源、农业综合开发等项目时，应当根据具体情况，设立若干防沙治沙子项目。"},{"i":33,"n":"第三十三条","txt":"国务院和省、自治区、直辖市人民政府应当制定优惠政策，鼓励和支持单位和个人防沙治沙。"},{"i":34,"n":"第三十四条","txt":"使用已经沙化的国有土地从事治沙活动的，经县级以上人民政府依法批准，可以享有不超过七十年的土地使用权。具体年限和管理办法，由国务院规定。"},{"i":35,"n":"第三十五条","txt":"因保护生态的特殊要求，将治理后的土地批准划为自然保护区或者沙化土地封禁保护区的，批准机关应当给予治理者合理的经济补偿。"},{"i":36,"n":"第三十六条","txt":"国家根据防沙治沙的需要，组织设立防沙治沙重点科研项目和示范、推广项目，并对防沙治沙、沙区能源、沙生经济作物、节水灌溉、防止草原退化、沙地旱作农业等方面的科学研究与技术推广给予资金补助、税费减免等政策优惠。"},{"i":37,"n":"第三十七条","txt":"任何单位和个人不得截留、挪用防沙治沙资金。"},{"i":38,"n":"第三十八条","txt":"违反本法第二十二条第一款规定，在沙化土地封禁保护区范围内从事破坏植被活动的，由县级以上地方人民政府林业草原行政主管部门责令停止违法行为；有违法所得的，没收其违法所得；构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"违反本法第二十五条第一款规定，国有土地使用权人和农民集体所有土地承包经营权人未采取防沙治沙措施，造成土地严重沙化的，由县级以上地方人民政府林业草原行政主管部门责令限期治理；造成国有土地严重沙化的，县级以上人民政府可以收回国有土地使用权。"},{"i":40,"n":"第四十条","txt":"违反本法规定，进行营利性治沙活动，造成土地沙化加重的，由县级以上地方人民政府负责受理营利性治沙申请的行政主管部门责令停止违法行为，可以并处每公顷五千元以上五万元以下的罚款。"},{"i":41,"n":"第四十一条","txt":"违反本法第二十八条第一款规定，不按照治理方案进行治理的，或者违反本法第二十九条规定，经验收不合格又不按要求继续治理的，由县级以上地方人民政府负责受理营利性治沙申请的行政主管部门责令停止违法行为，限期改正，可以并处相当于治理费用一倍以上三倍以下的罚款。"},{"i":42,"n":"第四十二条","txt":"违反本法第二十八条第二款规定，未经治理者同意，擅自在他人的治理范围内从事治理或者开发利用活动的，由县级以上地方人民政府负责受理营利性治沙申请的行政主管部门责令停止违法行为；给治理者造成损失的，应当赔偿损失。"},{"i":43,"n":"第四十三条","txt":"违反本法规定，有下列情形之一的，对直接负责的主管人员和其他直接责任人员，由所在单位、监察机关或者上级行政主管部门依法给予行政处分："},{"i":44,"n":"第四十四条","txt":"违反本法第三十七条第一款规定，截留、挪用防沙治沙资金的，对直接负责的主管人员和其他直接责任人员，由监察机关或者上级行政主管部门依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"防沙治沙监督管理人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"本法第五条第二款中所称的有关法律，是指《中华人民共和国森林法》《中华人民共和国草原法》《中华人民共和国水土保持法》《中华人民共和国土地管理法》《中华人民共和国环境保护法》和《中华人民共和国气象法》。"},{"i":47,"n":"第四十七条","txt":"本法自2002年1月1日起施行。"}],"qingzanggaoyuanshengtaibaohufa":[{"i":1,"n":"第一条","txt":"为了加强青藏高原生态保护，防控生态风险，保障生态安全，建设国家生态文明高地，促进经济社会可持续发展，实现人与自然和谐共生，制定本法。"},{"i":2,"n":"第二条","txt":"从事或者涉及青藏高原生态保护相关活动，适用本法；本法未作规定的，适用其他有关法律的规定。"},{"i":3,"n":"第三条","txt":"青藏高原生态保护应当尊重自然、顺应自然、保护自然；坚持生态保护第一，自然恢复为主，守住自然生态安全边界；坚持统筹协调、分类施策、科学防控、系统治理。"},{"i":4,"n":"第四条","txt":"国家建立青藏高原生态保护协调机制，统筹指导、综合协调青藏高原生态保护工作，审议青藏高原生态保护重大政策、重大规划、重大项目，协调跨地区跨部门重大问题，督促检查相关重要工作的落实情况。"},{"i":5,"n":"第五条","txt":"青藏高原地方各级人民政府应当落实本行政区域的生态保护修复、生态风险防控、优化产业结构和布局、维护青藏高原生态安全等责任。"},{"i":6,"n":"第六条","txt":"国务院和青藏高原县级以上地方人民政府应当将青藏高原生态保护工作纳入国民经济和社会发展规划。"},{"i":7,"n":"第七条","txt":"国家加强青藏高原土地、森林、草原、河流、湖泊、湿地、冰川、荒漠、野生动植物等自然资源状况和生态环境状况调查，开展区域资源环境承载能力和国土空间开发适宜性评价，健全青藏高原生态环境、自然资源、生物多样性、水文、气象、地质、水土保持、自然灾害等监测网络体系，推进综合监测、协同监测和常态化监测。调查、评价和监测信息应当按照国家有关规定共享。"},{"i":8,"n":"第八条","txt":"国家鼓励和支持开展青藏高原科学考察与研究，加强青藏高原气候变化、生物多样性、生态保护修复、水文水资源、雪山冰川冻土、水土保持、荒漠化防治、河湖演变、地质环境、自然灾害监测预警与防治、能源和气候资源开发利用与保护、生态系统碳汇等领域的重大科技问题研究和重大科技基础设施建设，推动长期研究工作，掌握青藏高原生态本底及其变化。"},{"i":9,"n":"第九条","txt":"国务院有关部门和地方各级人民政府应当采取有效措施，保护青藏高原传统生态文化遗产，弘扬青藏高原优秀生态文化。"},{"i":10,"n":"第十条","txt":"对在青藏高原生态保护工作中做出突出贡献的单位和个人，按照国家有关规定予以表彰和奖励。"},{"i":11,"n":"第十一条","txt":"国家统筹青藏高原生态安全布局，推进山水林田湖草沙冰综合治理、系统治理、源头治理，实施重要生态系统保护修复重大工程，优化以水源涵养、生物多样性保护、水土保持、防风固沙、生态系统碳汇等为主要生态功能的青藏高原生态安全屏障体系，提升生态系统质量和多样性、稳定性、持续性，增强生态产品供给能力和生态系统服务功能，建设国家生态安全屏障战略地。"},{"i":12,"n":"第十二条","txt":"青藏高原县级以上地方人民政府组织编制本行政区域的国土空间规划，应当落实国家对青藏高原国土空间开发保护的有关要求，细化安排农业、生态、城镇等功能空间，统筹划定耕地和永久基本农田、生态保护红线、城镇开发边界。涉及青藏高原国土空间利用的专项规划应当与国土空间规划相衔接。"},{"i":13,"n":"第十三条","txt":"青藏高原国土空间开发利用活动应当符合国土空间用途管制要求。青藏高原生态空间内的用途转换，应当有利于增强森林、草原、河流、湖泊、湿地、冰川、荒漠等生态系统的生态功能。"},{"i":14,"n":"第十四条","txt":"青藏高原省级人民政府根据本行政区域的生态环境和资源利用状况，按照生态保护红线、环境质量底线、资源利用上线的要求，从严制定生态环境分区管控方案和生态环境准入清单，报国务院生态环境主管部门备案后实施。生态环境分区管控方案和生态环境准入清单应当与国土空间规划相衔接。"},{"i":15,"n":"第十五条","txt":"国家加强对青藏高原森林、高寒草甸、草原、河流、湖泊、湿地、雪山冰川、高原冻土、荒漠、泉域等生态系统的保护，巩固提升三江源（长江、黄河、澜沧江发源地）草原草甸湿地生态功能区、若尔盖草原湿地生态功能区、甘南黄河重要水源补给生态功能区、祁连山冰川与水源涵养生态功能区、阿尔金草原荒漠化防治生态功能区、川滇森林及生物多样性生态功能区、藏东南高原边缘森林生态功能区、藏西北羌塘高原荒漠生态功能区、珠穆朗玛峰生物多样性保护与水源涵养生态功能区等国家重点生态功能区的水源涵养、生物多样性保护、水土保持、防风固沙等生态功能。"},{"i":16,"n":"第十六条","txt":"国家支持青藏高原自然保护地体系建设。国务院和青藏高原省级人民政府在青藏高原重要典型生态系统的完整分布区、生态环境敏感区以及珍贵濒危或者特有野生动植物天然集中分布区和重要栖息地、重要自然遗迹、重要自然景观分布区等区域，依法设立国家公园、自然保护区、自然公园等自然保护地，推进三江源、祁连山、羌塘、珠穆朗玛峰、高黎贡山、贡嘎山等自然保护地建设，保持重要自然生态系统原真性和完整性。"},{"i":17,"n":"第十七条","txt":"青藏高原产业结构和布局应当与青藏高原生态系统和资源环境承载能力相适应。国务院有关部门和青藏高原县级以上地方人民政府应当按照国土空间规划要求，调整产业结构，优化生产力布局，优先发展资源节约型、环境友好型产业，适度发展生态旅游、特色文化、特色农牧业、民族特色手工业等区域特色生态产业，建立健全绿色、低碳、循环经济体系。"},{"i":18,"n":"第十八条","txt":"国家加强青藏高原生态保护修复，坚持山水林田湖草沙冰一体化保护修复，实行自然恢复为主、自然恢复与人工修复相结合的系统治理。"},{"i":19,"n":"第十九条","txt":"国务院有关部门和有关地方人民政府加强三江源地区的生态保护修复工作，对依法设立的国家公园进行系统保护和分区分类管理，科学采取禁牧封育等措施，加大退化草原、退化湿地、沙化土地治理和水土流失防治的力度，综合整治重度退化土地；严格禁止破坏生态功能或者不符合差别化管控要求的各类资源开发利用活动。"},{"i":20,"n":"第二十条","txt":"国务院有关部门和青藏高原县级以上地方人民政府应当建立健全青藏高原雪山冰川冻土保护制度，加强对雪山冰川冻土的监测预警和系统保护。"},{"i":21,"n":"第二十一条","txt":"国务院有关部门和青藏高原地方各级人民政府建立健全青藏高原江河、湖泊管理和保护制度，完善河湖长制，加大对长江、黄河、澜沧江、雅鲁藏布江、怒江等重点河流和青海湖、扎陵湖、鄂陵湖、色林错、纳木错、羊卓雍错、玛旁雍错等重点湖泊的保护力度。"},{"i":22,"n":"第二十二条","txt":"青藏高原水资源开发利用，应当符合流域综合规划，坚持科学开发、合理利用，统筹各类用水需求，兼顾上下游、干支流、左右岸利益，充分发挥水资源的综合效益，保障用水安全和生态安全。"},{"i":23,"n":"第二十三条","txt":"国家严格保护青藏高原大江大河源头等重要生态区位的天然草原，依法将维护国家生态安全、保障草原畜牧业健康发展发挥最基本、最重要作用的草原划为基本草原。青藏高原县级以上地方人民政府应当加强青藏高原草原保护，对基本草原实施更加严格的保护和管理，确保面积不减少、质量不下降、用途不改变。"},{"i":24,"n":"第二十四条","txt":"青藏高原县级以上地方人民政府及其有关部门应当统筹协调草原生态保护和畜牧业发展，结合当地实际情况，定期核定草原载畜量，落实草畜平衡，科学划定禁牧区，防止超载过牧。对严重退化、沙化、盐碱化、石漠化的草原和生态脆弱区的草原，实行禁牧、休牧制度。"},{"i":25,"n":"第二十五条","txt":"国家全面加强青藏高原天然林保护，严格限制采伐天然林，加强原生地带性植被保护，优化森林生态系统结构，健全重要流域防护林体系。国务院和青藏高原省级人民政府应当依法在青藏高原重要生态区、生态状况脆弱区划定公益林，实施严格管理。"},{"i":26,"n":"第二十六条","txt":"国家加强青藏高原湿地保护修复，增强湿地水源涵养、气候调节、生物多样性保护等生态功能，提升湿地固碳能力。"},{"i":27,"n":"第二十七条","txt":"青藏高原地方各级人民政府及其有关部门应当落实最严格耕地保护制度，采取有效措施提升耕地基础地力，增强耕地生态功能，保护和改善耕地生态环境；鼓励和支持农业生产经营者采取养用结合、盐碱地改良、生态循环、废弃物综合利用等方式，科学利用耕地，推广使用绿色、高效农业生产技术，严格控制化肥、农药施用，科学处置农用薄膜、农作物秸秆等农业废弃物。"},{"i":28,"n":"第二十八条","txt":"国务院林业草原、农业农村主管部门会同国务院有关部门和青藏高原省级人民政府按照职责分工，开展野生动植物物种调查，根据调查情况提出实施保护措施的意见，完善相关名录制度，加强野生动物重要栖息地、迁徙洄游通道和野生植物原生境保护，对野牦牛、藏羚、普氏原羚、雪豹、大熊猫、高黎贡白眉长臂猿、黑颈鹤、川陕哲罗鲑、骨唇黄河鱼、黑斑原鮡、扁吻鱼、尖裸鲤和大花红景天、西藏杓兰、雪兔子等青藏高原珍贵濒危或者特有野生动植物物种实行重点保护。"},{"i":29,"n":"第二十九条","txt":"国家加强青藏高原生物多样性保护，实施生物多样性保护重大工程，防止对生物多样性的破坏。"},{"i":30,"n":"第三十条","txt":"青藏高原县级以上地方人民政府及其林业草原主管部门，应当采取荒漠化土地封禁保护、植被保护与恢复等措施，加强荒漠生态保护与荒漠化土地综合治理。"},{"i":31,"n":"第三十一条","txt":"青藏高原省级人民政府应当采取封禁抚育、轮封轮牧、移民搬迁等措施，实施高原山地以及农田风沙地带、河岸地带、生态防护带等重点治理工程，提升水土保持功能。"},{"i":32,"n":"第三十二条","txt":"国务院水行政主管部门和青藏高原省级人民政府应当采取有效措施，加强对三江源、祁连山黑河流域、金沙江和岷江上游、雅鲁藏布江以及金沙江、澜沧江、怒江三江并流地区等重要江河源头区和水土流失重点预防区、治理区，人口相对密集高原河谷区的水土流失防治。"},{"i":33,"n":"第三十三条","txt":"在青藏高原设立探矿权、采矿权应当符合国土空间规划和矿产资源规划要求。依法禁止在长江、黄河、澜沧江、雅鲁藏布江、怒江等江河源头自然保护地内从事不符合生态保护管控要求的采砂、采矿活动。"},{"i":34,"n":"第三十四条","txt":"青藏高原县级以上地方人民政府应当因地制宜采取消除地质灾害隐患、土地复垦、恢复植被、防治污染等措施，加快历史遗留矿山生态修复工作，加强对在建和运行中矿山的监督管理，督促采矿权人依法履行矿山污染防治和生态修复责任。"},{"i":35,"n":"第三十五条","txt":"国家建立健全青藏高原生态风险防控体系，采取有效措施提高自然灾害防治、气候变化应对等生态风险防控能力和水平，保障青藏高原生态安全。"},{"i":36,"n":"第三十六条","txt":"国家加强青藏高原自然灾害调查评价和监测预警。"},{"i":37,"n":"第三十七条","txt":"国务院有关部门和青藏高原县级以上地方人民政府应当加强自然灾害综合治理，提高地震、山洪、冰湖溃决、地质灾害等自然灾害防御工程标准，建立与青藏高原生态保护相适应的自然灾害防治工程和非工程体系。"},{"i":38,"n":"第三十八条","txt":"重大工程建设可能造成生态和地质环境影响的，建设单位应当根据工程沿线生态和地质环境敏感脆弱区域状况，制定沿线生态和地质环境监测方案，开展生态和地质环境影响的全生命周期监测，包括工程开工前的本底监测、工程建设中的生态和地质环境影响监测、工程运营期的生态和地质环境变化与保护修复跟踪监测。"},{"i":39,"n":"第三十九条","txt":"青藏高原县级以上地方人民政府应当加强对青藏高原种质资源的保护和管理，组织开展种质资源调查与收集，完善相关资源保护设施和数据库。"},{"i":40,"n":"第四十条","txt":"国务院有关部门和青藏高原省级人民政府按照职责分工，统筹推进区域外来入侵物种防控，实行外来物种引入审批管理，强化入侵物种口岸防控，加强外来入侵物种调查、监测、预警、控制、评估、清除、生态修复等工作。"},{"i":41,"n":"第四十一条","txt":"国家加强对气候变化及其综合影响的监测，建立气候变化对青藏高原生态系统、气候系统、水资源、珍贵濒危或者特有野生动植物、雪山冰川冻土和自然灾害影响的预测体系，完善生态风险报告和预警机制，强化气候变化对青藏高原影响和高原生态系统演变的评估。"},{"i":42,"n":"第四十二条","txt":"国家加大对青藏高原生态保护修复的财政投入，中央财政安排专项资金用于青藏高原生态保护修复、生态风险防控等。中央预算内投资对青藏高原基础设施和基本公共服务设施建设予以倾斜。"},{"i":43,"n":"第四十三条","txt":"国家加大财政转移支付力度，通过提高转移支付系数、加计生态环保支出等方式，对青藏高原生态功能重要区域予以补偿。青藏高原省级人民政府应当将生态功能重要区域全面纳入省级对下生态保护补偿转移支付范围，促进生态保护同民生改善相结合。"},{"i":44,"n":"第四十四条","txt":"国家为青藏高原生态保护提供支持，实行有利于节水、节能、水土保持、环境保护和资源综合利用的金融、税收政策，鼓励发展绿色信贷、绿色债券、绿色保险等金融产品。"},{"i":45,"n":"第四十五条","txt":"国家支持在青藏高原因地制宜建设以风电、光伏发电、水电、水风光互补发电、光热、地热等清洁能源为主体的能源体系，加强清洁能源输送通道建设，推进能源绿色低碳转型。"},{"i":46,"n":"第四十六条","txt":"在青藏高原发展生态旅游应当符合资源和生态保护要求，尊重和维护当地传统文化和习俗，保护和合理利用旅游资源。"},{"i":47,"n":"第四十七条","txt":"青藏高原县级以上地方人民政府应当根据区域资源环境承载能力，统筹推进交通、水利、能源等重大基础设施建设和生活污水、垃圾收集处理等环境基础设施建设，加强城市内部以及周边毗邻地带生态保护修复，统筹规划城乡社区综合服务设施建设，加快推进基本公共服务均等化。"},{"i":48,"n":"第四十八条","txt":"国务院有关部门和青藏高原县级以上地方人民政府有关部门按照职责分工，对青藏高原生态保护各类活动进行监督检查，查处违法行为，依法公开青藏高原生态保护工作相关信息，完善公众参与程序。"},{"i":49,"n":"第四十九条","txt":"国务院有关部门和青藏高原县级以上地方人民政府及其有关部门应当加强青藏高原生态保护监督管理能力建设，提高科技化、信息化水平，建立执法协调机制，对重大违法案件和跨行政区域、生态敏感区域的违法案件，依法开展联合执法。"},{"i":50,"n":"第五十条","txt":"国家实行青藏高原生态保护绩效评价考核制度，将环境质量提升、生态保护成效、生态产品供给能力等纳入指标体系。"},{"i":51,"n":"第五十一条","txt":"国家加强青藏高原生态保护司法保障建设，鼓励有关单位为青藏高原生态保护提供法律服务。"},{"i":52,"n":"第五十二条","txt":"青藏高原县级以上地方人民政府应当定期向本级人民代表大会或者其常务委员会报告本级人民政府青藏高原生态保护工作情况。"},{"i":53,"n":"第五十三条","txt":"国务院有关部门和地方各级人民政府及其有关部门违反本法规定，在履行相关职责中有玩忽职守、滥用职权、徇私舞弊行为的，对直接负责的主管人员和其他直接责任人员依法给予警告、记过、记大过或者降级处分；造成严重后果的，给予撤职或者开除处分，其主要负责人应当引咎辞职。"},{"i":54,"n":"第五十四条","txt":"违反本法规定，在青藏高原有下列行为之一的，依照有关法律法规的规定从重处罚："},{"i":55,"n":"第五十五条","txt":"违反本法规定，利用、占用青藏高原河道、湖泊水域和岸线的，由县级以上人民政府水行政主管部门责令停止违法行为，限期拆除并恢复原状，处五万元以上五十万元以下罚款；逾期不拆除或者不恢复原状的，强制拆除或者代为恢复原状，所需费用由违法者承担。"},{"i":56,"n":"第五十六条","txt":"违反本法规定，在长江、黄河、澜沧江、雅鲁藏布江、怒江等江河源头自然保护地内从事不符合生态保护管控要求的采矿活动的，由自然资源、生态环境主管部门按照职责分工，责令改正，没收违法所得和直接用于违法开采的设备、工具；违法所得十万元以上的，并处违法所得十倍以上二十倍以下罚款；违法所得不足十万元的，并处十万元以上一百万元以下罚款。"},{"i":57,"n":"第五十七条","txt":"违反本法规定，建设单位新建小水电项目的，由县级以上地方人民政府责令停止建设，根据违法情节和危害后果，责令恢复原状，处建设项目总投资额百分之一以上百分之五以下罚款。"},{"i":58,"n":"第五十八条","txt":"违反本法规定，在旅游、山地户外运动中随意倾倒、抛撒生活垃圾的，由环境卫生主管部门或者县级以上地方人民政府指定的部门责令改正，对个人处一百元以上五百元以下罚款，情节严重的，处五百元以上一万元以下罚款；对单位处五万元以上五十万元以下罚款。"},{"i":59,"n":"第五十九条","txt":"污染青藏高原环境、破坏青藏高原生态造成他人损害的，侵权人应当承担侵权责任。"},{"i":60,"n":"第六十条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":61,"n":"第六十一条","txt":"本法第二条第二款规定的相关县级行政区域，由国务院授权的部门确定。"},{"i":62,"n":"第六十二条","txt":"青藏高原省、自治区和设区的市、自治州可以结合本地实际，制定青藏高原生态保护具体办法。"},{"i":63,"n":"第六十三条","txt":"本法自2023年9月1日起施行。"}],"huanghebaohufa":[{"i":1,"n":"第一条","txt":"为了加强黄河流域生态环境保护，保障黄河安澜，推进水资源节约集约利用，推动高质量发展，保护传承弘扬黄河文化，实现人与自然和谐共生、中华民族永续发展，制定本法。"},{"i":2,"n":"第二条","txt":"黄河流域生态保护和高质量发展各类活动，适用本法；本法未作规定的，适用其他有关法律的规定。"},{"i":3,"n":"第三条","txt":"黄河流域生态保护和高质量发展，坚持中国共产党的领导，落实重在保护、要在治理的要求，加强污染防治，贯彻生态优先、绿色发展，量水而行、节水为重，因地制宜、分类施策，统筹谋划、协同推进的原则。"},{"i":4,"n":"第四条","txt":"国家建立黄河流域生态保护和高质量发展统筹协调机制（以下简称黄河流域统筹协调机制），全面指导、统筹协调黄河流域生态保护和高质量发展工作，审议黄河流域重大政策、重大规划、重大项目等，协调跨地区跨部门重大事项，督促检查相关重要工作的落实情况。"},{"i":5,"n":"第五条","txt":"国务院有关部门按照职责分工，负责黄河流域生态保护和高质量发展相关工作。"},{"i":6,"n":"第六条","txt":"黄河流域县级以上地方人民政府负责本行政区域黄河流域生态保护和高质量发展工作。"},{"i":7,"n":"第七条","txt":"国务院水行政、生态环境、自然资源、住房和城乡建设、农业农村、发展改革、应急管理、林业和草原、文化和旅游、标准化等主管部门按照职责分工，建立健全黄河流域水资源节约集约利用、水沙调控、防汛抗旱、水土保持、水文、水环境质量和污染物排放、生态保护与修复、自然资源调查监测评价、生物多样性保护、文化遗产保护等标准体系。"},{"i":8,"n":"第八条","txt":"国家在黄河流域实行水资源刚性约束制度，坚持以水定城、以水定地、以水定人、以水定产，优化国土空间开发保护格局，促进人口和城市科学合理布局，构建与水资源承载能力相适应的现代产业体系。"},{"i":9,"n":"第九条","txt":"国家在黄河流域强化农业节水增效、工业节水减排和城镇节水降损措施，鼓励、推广使用先进节水技术，加快形成节水型生产、生活方式，有效实现水资源节约集约利用，推进节水型社会建设。"},{"i":10,"n":"第十条","txt":"国家统筹黄河干支流防洪体系建设，加强流域及流域间防洪体系协同，推进黄河上中下游防汛抗旱、防凌联动，构建科学高效的综合性防洪减灾体系，并适时组织评估，有效提升黄河流域防治洪涝等灾害的能力。"},{"i":11,"n":"第十一条","txt":"国务院自然资源主管部门应当会同国务院有关部门定期组织开展黄河流域土地、矿产、水流、森林、草原、湿地等自然资源状况调查，建立资源基础数据库，开展资源环境承载能力评价，并向社会公布黄河流域自然资源状况。"},{"i":12,"n":"第十二条","txt":"黄河流域统筹协调机制统筹协调国务院有关部门和黄河流域省级人民政府，在已经建立的台站和监测项目基础上，健全黄河流域生态环境、自然资源、水文、泥沙、荒漠化和沙化、水土保持、自然灾害、气象等监测网络体系。"},{"i":13,"n":"第十三条","txt":"国家加强黄河流域自然灾害的预防与应急准备、监测与预警、应急处置与救援、事后恢复与重建体系建设，维护相关工程和设施安全，控制、减轻和消除自然灾害引起的危害。"},{"i":14,"n":"第十四条","txt":"黄河流域统筹协调机制设立黄河流域生态保护和高质量发展专家咨询委员会，对黄河流域重大政策、重大规划、重大项目和重大科技问题等提供专业咨询。"},{"i":15,"n":"第十五条","txt":"黄河流域统筹协调机制统筹协调国务院有关部门和黄河流域省级人民政府，建立健全黄河流域信息共享系统，组织建立智慧黄河信息共享平台，提高科学化水平。国务院有关部门和黄河流域省级人民政府及其有关部门应当按照国家有关规定，共享黄河流域生态环境、自然资源、水土保持、防洪安全以及管理执法等信息。"},{"i":16,"n":"第十六条","txt":"国家鼓励、支持开展黄河流域生态保护与修复、水资源节约集约利用、水沙运动与调控、防沙治沙、泥沙综合利用、河流动力与河床演变、水土保持、水文、气候、污染防治等方面的重大科技问题研究，加强协同创新，推动关键性技术研究，推广应用先进适用技术，提升科技创新支撑能力。"},{"i":17,"n":"第十七条","txt":"国家加强黄河文化保护传承弘扬，系统保护黄河文化遗产，研究黄河文化发展脉络，阐发黄河文化精神内涵和时代价值，铸牢中华民族共同体意识。"},{"i":18,"n":"第十八条","txt":"国务院有关部门和黄河流域县级以上地方人民政府及其有关部门应当加强黄河流域生态保护和高质量发展的宣传教育。"},{"i":19,"n":"第十九条","txt":"国家鼓励、支持单位和个人参与黄河流域生态保护和高质量发展相关活动。"},{"i":20,"n":"第二十条","txt":"国家建立以国家发展规划为统领，以空间规划为基础，以专项规划、区域规划为支撑的黄河流域规划体系，发挥规划对推进黄河流域生态保护和高质量发展的引领、指导和约束作用。"},{"i":21,"n":"第二十一条","txt":"国务院和黄河流域县级以上地方人民政府应当将黄河流域生态保护和高质量发展工作纳入国民经济和社会发展规划。"},{"i":22,"n":"第二十二条","txt":"国务院自然资源主管部门应当会同国务院有关部门组织编制黄河流域国土空间规划，科学有序统筹安排黄河流域农业、生态、城镇等功能空间，划定永久基本农田、生态保护红线、城镇开发边界，优化国土空间结构和布局，统领黄河流域国土空间利用任务，报国务院批准后实施。涉及黄河流域国土空间利用的专项规划应当与黄河流域国土空间规划相衔接。"},{"i":23,"n":"第二十三条","txt":"国务院水行政主管部门应当会同国务院有关部门和黄河流域省级人民政府，按照统一规划、统一管理、统一调度的原则，依法编制黄河流域综合规划、水资源规划、防洪规划等，对节约、保护、开发、利用水资源和防治水害作出部署。"},{"i":24,"n":"第二十四条","txt":"国民经济和社会发展规划、国土空间总体规划的编制以及重大产业政策的制定，应当与黄河流域水资源条件和防洪要求相适应，并进行科学论证。"},{"i":25,"n":"第二十五条","txt":"国家对黄河流域国土空间严格实行用途管制。黄河流域县级以上地方人民政府自然资源主管部门依据国土空间规划，对本行政区域黄河流域国土空间实行分区、分类用途管制。"},{"i":26,"n":"第二十六条","txt":"黄河流域省级人民政府根据本行政区域的生态环境和资源利用状况，按照生态保护红线、环境质量底线、资源利用上线的要求，制定生态环境分区管控方案和生态环境准入清单，报国务院生态环境主管部门备案后实施。生态环境分区管控方案和生态环境准入清单应当与国土空间规划相衔接。"},{"i":27,"n":"第二十七条","txt":"黄河流域水电开发，应当进行科学论证，符合国家发展规划、流域综合规划和生态保护要求。对黄河流域已建小水电工程，不符合生态保护要求的，县级以上地方人民政府应当组织分类整改或者采取措施逐步退出。"},{"i":28,"n":"第二十八条","txt":"黄河流域管理机构统筹防洪减淤、城乡供水、生态保护、灌溉用水、水力发电等目标，建立水资源、水沙、防洪防凌综合调度体系，实施黄河干支流控制性水工程统一调度，保障流域水安全，发挥水资源综合效益。"},{"i":29,"n":"第二十九条","txt":"国家加强黄河流域生态保护与修复，坚持山水林田湖草沙一体化保护与修复，实行自然恢复为主、自然恢复与人工修复相结合的系统治理。"},{"i":30,"n":"第三十条","txt":"国家加强对黄河水源涵养区的保护，加大对黄河干流和支流源头、水源涵养区的雪山冰川、高原冻土、高寒草甸、草原、湿地、荒漠、泉域等的保护力度。"},{"i":31,"n":"第三十一条","txt":"国务院和黄河流域省级人民政府应当依法在重要生态功能区域、生态脆弱区域划定公益林，实施严格管护；需要补充灌溉的，在水资源承载能力范围内合理安排灌溉用水。"},{"i":32,"n":"第三十二条","txt":"国家加强对黄河流域子午岭—六盘山、秦岭北麓、贺兰山、白于山、陇中等水土流失重点预防区、治理区和渭河、洮河、汾河、伊洛河等重要支流源头区的水土流失防治。水土流失防治应当根据实际情况，科学采取生物措施和工程措施。"},{"i":33,"n":"第三十三条","txt":"国务院水行政主管部门应当会同国务院有关部门加强黄河流域砒砂岩区、多沙粗沙区、水蚀风蚀交错区和沙漠入河区等生态脆弱区域保护和治理，开展土壤侵蚀和水土流失状况评估，实施重点防治工程。"},{"i":34,"n":"第三十四条","txt":"国务院水行政主管部门应当会同国务院有关部门制定淤地坝建设、养护标准或者技术规范，健全淤地坝建设、管理、安全运行制度。"},{"i":35,"n":"第三十五条","txt":"禁止在黄河流域水土流失严重、生态脆弱区域开展可能造成水土流失的生产建设活动。确因国家发展战略和国计民生需要建设的，应当进行科学论证，并依法办理审批手续。"},{"i":36,"n":"第三十六条","txt":"国务院水行政主管部门应当会同国务院有关部门和山东省人民政府，编制并实施黄河入海河口整治规划，合理布局黄河入海流路，加强河口治理，保障入海河道畅通和河口防洪防凌安全，实施清水沟、刁口河生态补水，维护河口生态功能。"},{"i":37,"n":"第三十七条","txt":"国务院水行政主管部门确定黄河干流、重要支流控制断面生态流量和重要湖泊生态水位的管控指标，应当征求并研究国务院生态环境、自然资源等主管部门的意见。黄河流域省级人民政府水行政主管部门确定其他河流生态流量和其他湖泊生态水位的管控指标，应当征求并研究同级人民政府生态环境、自然资源等主管部门的意见，报黄河流域管理机构、黄河流域生态环境监督管理机构备案。确定生态流量和生态水位的管控指标，应当进行科学论证，综合考虑水资源条件、气候状况、生态环境保护要求、生活生产用水状况等因素。"},{"i":38,"n":"第三十八条","txt":"国家统筹黄河流域自然保护地体系建设。国务院和黄河流域省级人民政府在黄河流域重要典型生态系统的完整分布区、生态环境敏感区以及珍贵濒危野生动植物天然集中分布区和重要栖息地、重要自然遗迹分布区等区域，依法设立国家公园、自然保护区、自然公园等自然保护地。"},{"i":39,"n":"第三十九条","txt":"国务院林业和草原、农业农村主管部门应当会同国务院有关部门和黄河流域省级人民政府按照职责分工，对黄河流域数量急剧下降或者极度濒危的野生动植物和受到严重破坏的栖息地、天然集中分布区、破碎化的典型生态系统开展保护与修复，修建迁地保护设施，建立野生动植物遗传资源基因库，进行抢救性修复。"},{"i":40,"n":"第四十条","txt":"国务院农业农村主管部门应当会同国务院有关部门和黄河流域省级人民政府，建立黄河流域水生生物完整性指数评价体系，组织开展黄河流域水生生物完整性评价，并将评价结果作为评估黄河流域生态系统总体状况的重要依据。黄河流域水生生物完整性指数应当与黄河流域水环境质量标准相衔接。"},{"i":41,"n":"第四十一条","txt":"国家保护黄河流域水产种质资源和珍贵濒危物种，支持开展水产种质资源保护区、国家重点保护野生动物人工繁育基地建设。"},{"i":42,"n":"第四十二条","txt":"国家加强黄河流域水生生物产卵场、索饵场、越冬场、洄游通道等重要栖息地的生态保护与修复。对鱼类等水生生物洄游产生阻隔的涉水工程应当结合实际采取建设过鱼设施、河湖连通、增殖放流、人工繁育等多种措施，满足水生生物的生态需求。"},{"i":43,"n":"第四十三条","txt":"国务院水行政主管部门应当会同国务院自然资源主管部门组织划定并公布黄河流域地下水超采区。"},{"i":44,"n":"第四十四条","txt":"黄河流域县级以上地方人民政府应当组织开展退化农用地生态修复，实施农田综合整治。"},{"i":45,"n":"第四十五条","txt":"黄河流域水资源利用，应当坚持节水优先、统筹兼顾、集约使用、精打细算，优先满足城乡居民生活用水，保障基本生态用水，统筹生产用水。"},{"i":46,"n":"第四十六条","txt":"国家对黄河水量实行统一配置。制定和调整黄河水量分配方案，应当充分考虑黄河流域水资源条件、生态环境状况、区域用水状况、节水水平、洪水资源化利用等，统筹当地水和外调水、常规水和非常规水，科学确定水资源可利用总量和河道输沙入海水量，分配区域地表水取用水总量。"},{"i":47,"n":"第四十七条","txt":"国家对黄河流域水资源实行统一调度，遵循总量控制、断面流量控制、分级管理、分级负责的原则，根据水情变化进行动态调整。"},{"i":48,"n":"第四十八条","txt":"国务院水行政主管部门应当会同国务院自然资源主管部门制定黄河流域省级行政区域地下水取水总量控制指标。"},{"i":49,"n":"第四十九条","txt":"黄河流域县级以上行政区域的地表水取用水总量不得超过水量分配方案确定的控制指标，并符合生态流量和生态水位的管控指标要求；地下水取水总量不得超过本行政区域地下水取水总量控制指标，并符合地下水水位控制指标要求。"},{"i":50,"n":"第五十条","txt":"在黄河流域取用水资源，应当依法取得取水许可。"},{"i":51,"n":"第五十一条","txt":"国家在黄河流域实行水资源差别化管理。国务院水行政主管部门应当会同国务院自然资源主管部门定期组织开展黄河流域水资源评价和承载能力调查评估。评估结果作为划定水资源超载地区、临界超载地区、不超载地区的依据。"},{"i":52,"n":"第五十二条","txt":"国家在黄河流域实行强制性用水定额管理制度。国务院水行政、标准化主管部门应当会同国务院发展改革部门组织制定黄河流域高耗水工业和服务业强制性用水定额。制定强制性用水定额应当征求国务院有关部门、黄河流域省级人民政府、企业事业单位和社会公众等方面的意见，并依照《中华人民共和国标准化法》的有关规定执行。"},{"i":53,"n":"第五十三条","txt":"黄河流域以及黄河流经省、自治区其他黄河供水区相关县级行政区域的县级以上地方人民政府水行政主管部门和黄河流域管理机构核定取水单位的取水量，应当符合用水定额的要求。"},{"i":54,"n":"第五十四条","txt":"国家在黄河流域实行高耗水产业准入负面清单和淘汰类高耗水产业目录制度。列入高耗水产业准入负面清单和淘汰类高耗水产业目录的建设项目，取水申请不予批准。高耗水产业准入负面清单和淘汰类高耗水产业目录由国务院发展改革部门会同国务院水行政主管部门制定并发布。"},{"i":55,"n":"第五十五条","txt":"黄河流域县级以上地方人民政府应当组织发展高效节水农业，加强农业节水设施和农业用水计量设施建设，选育推广低耗水、高耐旱农作物，降低农业耗水量。禁止取用深层地下水用于农业灌溉。"},{"i":56,"n":"第五十六条","txt":"国家在黄河流域建立促进节约用水的水价体系。城镇居民生活用水和具备条件的农村居民生活用水实行阶梯水价，高耗水工业和服务业水价实行高额累进加价，非居民用水水价实行超定额累进加价，推进农业水价综合改革。"},{"i":57,"n":"第五十七条","txt":"国务院水行政主管部门应当会同国务院有关部门制定黄河流域重要饮用水水源地名录。黄河流域省级人民政府水行政主管部门应当会同本级人民政府有关部门制定本行政区域的其他饮用水水源地名录。"},{"i":58,"n":"第五十八条","txt":"国家综合考虑黄河流域水资源条件、经济社会发展需要和生态环境保护要求，统筹调出区和调入区供水安全和生态安全，科学论证、规划和建设跨流域调水和重大水源工程，加快构建国家水网，优化水资源配置，提高水资源承载能力。"},{"i":59,"n":"第五十九条","txt":"黄河流域县级以上地方人民政府应当推进污水资源化利用，国家对相关设施建设予以支持。"},{"i":60,"n":"第六十条","txt":"国家依据黄河流域综合规划、防洪规划，在黄河流域组织建设水沙调控和防洪减灾工程体系，完善水沙调控和防洪防凌调度机制，加强水文和气象监测预报预警、水沙观测和河势调查，实施重点水库和河段清淤疏浚、滩区放淤，提高河道行洪输沙能力，塑造河道主槽，维持河势稳定，保障防洪安全。"},{"i":61,"n":"第六十一条","txt":"国家完善以骨干水库等重大水工程为主的水沙调控体系，采取联合调水调沙、泥沙综合处理利用等措施，提高拦沙输沙能力。纳入水沙调控体系的工程名录由国务院水行政主管部门制定。"},{"i":62,"n":"第六十二条","txt":"国家实行黄河流域水沙统一调度制度。黄河流域管理机构应当组织实施黄河干支流水库群统一调度，编制水沙调控方案，确定重点水库水沙调控运用指标、运用方式、调控起止时间，下达调度指令。水沙调控应当采取措施尽量减少对水生生物及其栖息地的影响。"},{"i":63,"n":"第六十三条","txt":"国务院水行政主管部门组织编制黄河防御洪水方案，经国家防汛抗旱指挥机构审核后，报国务院批准。"},{"i":64,"n":"第六十四条","txt":"黄河流域管理机构制定年度防凌调度方案，报国务院水行政主管部门备案，按照职责组织实施。"},{"i":65,"n":"第六十五条","txt":"黄河防汛抗旱指挥机构负责指挥黄河流域防汛抗旱工作，其办事机构设在黄河流域管理机构，承担黄河防汛抗旱指挥机构的日常工作。"},{"i":66,"n":"第六十六条","txt":"黄河流域管理机构应当会同黄河流域省级人民政府依据黄河流域防洪规划，制定黄河滩区名录，报国务院水行政主管部门批准。黄河流域省级人民政府应当有序安排滩区居民迁建，严格控制向滩区迁入常住人口，实施滩区综合提升治理工程。"},{"i":67,"n":"第六十七条","txt":"国家加强黄河流域河道、湖泊管理和保护。禁止在河道、湖泊管理范围内建设妨碍行洪的建筑物、构筑物以及从事影响河势稳定、危害河岸堤防安全和其他妨碍河道行洪的活动。禁止违法利用、占用河道、湖泊水域和岸线。河道、湖泊管理范围由黄河流域管理机构和有关县级以上地方人民政府依法科学划定并公布。"},{"i":68,"n":"第六十八条","txt":"黄河流域河道治理，应当因地制宜采取河道清障、清淤疏浚、岸坡整治、堤防加固、水源涵养与水土保持、河湖管护等治理措施，加强悬河和游荡性河道整治，增强河道、湖泊、水库防御洪水能力。"},{"i":69,"n":"第六十九条","txt":"国家实行黄河流域河道采砂规划和许可制度。黄河流域河道采砂应当依法取得采砂许可。"},{"i":70,"n":"第七十条","txt":"国务院有关部门应当会同黄河流域省级人民政府加强对龙羊峡、刘家峡、三门峡、小浪底、故县、陆浑、河口村等干支流骨干水库库区的管理，科学调控水库水位，加强库区水土保持、生态保护和地质灾害防治工作。"},{"i":71,"n":"第七十一条","txt":"黄河流域城市人民政府应当统筹城市防洪和排涝工作，加强城市防洪排涝设施建设和管理，完善城市洪涝灾害监测预警机制，健全城市防灾减灾体系，提升城市洪涝灾害防御和应对能力。"},{"i":72,"n":"第七十二条","txt":"国家加强黄河流域农业面源污染、工业污染、城乡生活污染等的综合治理、系统治理、源头治理，推进重点河湖环境综合整治。"},{"i":73,"n":"第七十三条","txt":"国务院生态环境主管部门制定黄河流域水环境质量标准，对国家水环境质量标准中未作规定的项目，可以作出补充规定；对国家水环境质量标准中已经规定的项目，可以作出更加严格的规定。制定黄河流域水环境质量标准应当征求国务院有关部门和有关省级人民政府的意见。"},{"i":74,"n":"第七十四条","txt":"对没有国家水污染物排放标准的特色产业、特有污染物，以及国家有明确要求的特定水污染源或者水污染物，黄河流域省级人民政府应当补充制定地方水污染物排放标准，报国务院生态环境主管部门备案。"},{"i":75,"n":"第七十五条","txt":"国务院生态环境主管部门根据水环境质量改善目标和水污染防治要求，确定黄河流域各省级行政区域重点水污染物排放总量控制指标。黄河流域水环境质量不达标的水功能区，省级人民政府生态环境主管部门应当实施更加严格的水污染物排放总量削减措施，限期实现水环境质量达标。排放水污染物的企业事业单位应当按照要求，采取水污染物排放总量控制措施。"},{"i":76,"n":"第七十六条","txt":"在黄河流域河道、湖泊新设、改设或者扩大排污口，应当报经有管辖权的生态环境主管部门或者黄河流域生态环境监督管理机构批准。新设、改设或者扩大可能影响防洪、供水、堤防安全、河势稳定的排污口的，审批时应当征求县级以上地方人民政府水行政主管部门或者黄河流域管理机构的意见。"},{"i":77,"n":"第七十七条","txt":"黄河流域县级以上地方人民政府应当对沿河道、湖泊的垃圾填埋场、加油站、储油库、矿山、尾矿库、危险废物处置场、化工园区和化工项目等地下水重点污染源及周边地下水环境风险隐患组织开展调查评估，采取风险防范和整治措施。"},{"i":78,"n":"第七十八条","txt":"黄河流域省级人民政府生态环境主管部门应当会同本级人民政府水行政、自然资源等主管部门，根据本行政区域地下水污染防治需要，划定地下水污染防治重点区，明确环境准入、隐患排查、风险管控等管理要求。"},{"i":79,"n":"第七十九条","txt":"黄河流域县级以上地方人民政府应当加强黄河流域土壤生态环境保护，防止新增土壤污染，因地制宜分类推进土壤污染风险管控与修复。"},{"i":80,"n":"第八十条","txt":"国务院生态环境主管部门应当在黄河流域定期组织开展大气、水体、土壤、生物中有毒有害化学物质调查监测，并会同国务院卫生健康等主管部门开展黄河流域有毒有害化学物质环境风险评估与管控。"},{"i":81,"n":"第八十一条","txt":"黄河流域县级以上地方人民政府及其有关部门应当加强农药、化肥等农业投入品使用总量控制、使用指导和技术服务，推广病虫害绿色防控等先进适用技术，实施灌区农田退水循环利用，加强对农业污染源的监测预警。"},{"i":82,"n":"第八十二条","txt":"促进黄河流域高质量发展应当坚持新发展理念，加快发展方式绿色转型，以生态保护为前提优化调整区域经济和生产力布局。"},{"i":83,"n":"第八十三条","txt":"国务院有关部门和黄河流域县级以上地方人民政府及其有关部门应当协同推进黄河流域生态保护和高质量发展战略与乡村振兴战略、新型城镇化战略和中部崛起、西部大开发等区域协调发展战略的实施，统筹城乡基础设施建设和产业发展，改善城乡人居环境，健全基本公共服务体系，促进城乡融合发展。"},{"i":84,"n":"第八十四条","txt":"国务院有关部门和黄河流域县级以上地方人民政府应当强化生态环境、水资源等约束和城镇开发边界管控，严格控制黄河流域上中游地区新建各类开发区，推进节水型城市、海绵城市建设，提升城市综合承载能力和公共服务能力。"},{"i":85,"n":"第八十五条","txt":"国务院有关部门和黄河流域县级以上地方人民政府应当科学规划乡村布局，统筹生态保护与乡村发展，加强农村基础设施建设，推进农村产业融合发展，鼓励使用绿色低碳能源，加快推进农房和村庄建设现代化，塑造乡村风貌，建设生态宜居美丽乡村。"},{"i":86,"n":"第八十六条","txt":"黄河流域产业结构和布局应当与黄河流域生态系统和资源环境承载能力相适应。严格限制在黄河流域布局高耗水、高污染或者高耗能项目。"},{"i":87,"n":"第八十七条","txt":"国家鼓励黄河流域开展新型基础设施建设，完善交通运输、水利、能源、防灾减灾等基础设施网络。"},{"i":88,"n":"第八十八条","txt":"国家鼓励、支持黄河流域建设高标准农田、现代畜牧业生产基地以及种质资源和制种基地，因地制宜开展盐碱地农业技术研究、开发和应用，支持地方品种申请地理标志产品保护，发展现代农业服务业。"},{"i":89,"n":"第八十九条","txt":"国务院有关部门和黄河流域县级以上地方人民政府应当鼓励、支持黄河流域科技创新，引导社会资金参与科技成果开发和推广应用，提升黄河流域科技创新能力。"},{"i":90,"n":"第九十条","txt":"黄河流域县级以上地方人民政府及其有关部门应当采取有效措施，提高城乡居民对本行政区域生态环境、资源禀赋的认识，支持、引导居民形成绿色低碳的生活方式。"},{"i":91,"n":"第九十一条","txt":"国务院文化和旅游主管部门应当会同国务院有关部门编制并实施黄河文化保护传承弘扬规划，加强统筹协调，推动黄河文化体系建设。"},{"i":92,"n":"第九十二条","txt":"国务院文化和旅游主管部门应当会同国务院有关部门和黄河流域省级人民政府，组织开展黄河文化和治河历史研究，推动黄河文化创造性转化和创新性发展。"},{"i":93,"n":"第九十三条","txt":"国务院文化和旅游主管部门应当会同国务院有关部门组织指导黄河文化资源调查和认定，对文物古迹、非物质文化遗产、古籍文献等重要文化遗产进行记录、建档，建立黄河文化资源基础数据库，推动黄河文化资源整合利用和公共数据开放共享。"},{"i":94,"n":"第九十四条","txt":"国家加强黄河流域历史文化名城名镇名村、历史文化街区、文物、历史建筑、传统村落、少数民族特色村寨和古河道、古堤防、古灌溉工程等水文化遗产以及农耕文化遗产、地名文化遗产等的保护。国务院住房和城乡建设、文化和旅游、文物等主管部门和黄河流域县级以上地方人民政府有关部门按照职责分工和分级保护、分类实施的原则，加强监督管理。"},{"i":95,"n":"第九十五条","txt":"国家加强黄河流域具有革命纪念意义的文物和遗迹保护，建设革命传统教育、爱国主义教育基地，传承弘扬黄河红色文化。"},{"i":96,"n":"第九十六条","txt":"国家建设黄河国家文化公园，统筹利用文化遗产地以及博物馆、纪念馆、展览馆、教育基地、水工程等资源，综合运用信息化手段，系统展示黄河文化。"},{"i":97,"n":"第九十七条","txt":"国家采取政府购买服务等措施，支持单位和个人参与提供反映黄河流域特色、体现黄河文化精神、适宜普及推广的公共文化服务。"},{"i":98,"n":"第九十八条","txt":"黄河流域县级以上地方人民政府应当以保护传承弘扬黄河文化为重点，推动文化产业发展，促进文化产业与农业、水利、制造业、交通运输业、服务业等深度融合。"},{"i":99,"n":"第九十九条","txt":"国家鼓励开展黄河题材文艺作品创作。黄河流域县级以上地方人民政府应当加强对黄河题材文艺作品创作的支持和保护。"},{"i":100,"n":"第一百条","txt":"国务院和黄河流域县级以上地方人民政府应当加大对黄河流域生态保护和高质量发展的财政投入。"},{"i":101,"n":"第一百零一条","txt":"国家实行有利于节水、节能、生态环境保护和资源综合利用的税收政策，鼓励发展绿色信贷、绿色债券、绿色保险等金融产品，为黄河流域生态保护和高质量发展提供支持。"},{"i":102,"n":"第一百零二条","txt":"国家建立健全黄河流域生态保护补偿制度。"},{"i":103,"n":"第一百零三条","txt":"国家实行黄河流域生态保护和高质量发展责任制和考核评价制度。上级人民政府应当对下级人民政府水资源、水土保持强制性约束控制指标落实情况等生态保护和高质量发展目标完成情况进行考核。"},{"i":104,"n":"第一百零四条","txt":"国务院有关部门、黄河流域县级以上地方人民政府有关部门、黄河流域管理机构及其所属管理机构、黄河流域生态环境监督管理机构按照职责分工，对黄河流域各类生产生活、开发建设等活动进行监督检查，依法查处违法行为，公开黄河保护工作相关信息，完善公众参与程序，为单位和个人参与和监督黄河保护工作提供便利。"},{"i":105,"n":"第一百零五条","txt":"国务院有关部门、黄河流域县级以上地方人民政府及其有关部门、黄河流域管理机构及其所属管理机构、黄河流域生态环境监督管理机构应当加强黄河保护监督管理能力建设，提高科技化、信息化水平，建立执法协调机制，对跨行政区域、生态敏感区域以及重大违法案件，依法开展联合执法。"},{"i":106,"n":"第一百零六条","txt":"国务院有关部门和黄河流域省级人民政府对黄河保护不力、问题突出、群众反映集中的地区，可以约谈该地区县级以上地方人民政府及其有关部门主要负责人，要求其采取措施及时整改。约谈和整改情况应当向社会公布。"},{"i":107,"n":"第一百零七条","txt":"国务院应当定期向全国人民代表大会常务委员会报告黄河流域生态保护和高质量发展工作情况。"},{"i":108,"n":"第一百零八条","txt":"国务院有关部门、黄河流域县级以上地方人民政府及其有关部门、黄河流域管理机构及其所属管理机构、黄河流域生态环境监督管理机构违反本法规定，有下列行为之一的，对直接负责的主管人员和其他直接责任人员依法给予警告、记过、记大过或者降级处分；造成严重后果的，给予撤职或者开除处分，其主要负责人应当引咎辞职："},{"i":109,"n":"第一百零九条","txt":"违反本法规定，有下列行为之一的，由地方人民政府生态环境、自然资源等主管部门按照职责分工，责令停止违法行为，限期拆除或者恢复原状，处五十万元以上五百万元以下罚款，对直接负责的主管人员和其他直接责任人员处五万元以上十万元以下罚款；逾期不拆除或者不恢复原状的，强制拆除或者代为恢复原状，所需费用由违法者承担；情节严重的，报经有批准权的人民政府批准，责令关闭："},{"i":110,"n":"第一百一十条","txt":"违反本法规定，在黄河流域禁止开垦坡度以上陡坡地开垦种植农作物的，由县级以上地方人民政府水行政主管部门或者黄河流域管理机构及其所属管理机构责令停止违法行为，采取退耕、恢复植被等补救措施；按照开垦面积，可以对单位处每平方米一百元以下罚款、对个人处每平方米二十元以下罚款。"},{"i":111,"n":"第一百一十一条","txt":"违反本法规定，黄河干流、重要支流水工程未将生态用水调度纳入日常运行调度规程的，由有关主管部门按照职责分工，责令改正，给予警告，并处一万元以上十万元以下罚款；情节严重的，并处十万元以上五十万元以下罚款。"},{"i":112,"n":"第一百一十二条","txt":"违反本法规定，禁渔期内在黄河流域重点水域从事天然渔业资源生产性捕捞的，由县级以上地方人民政府农业农村主管部门没收渔获物、违法所得以及用于违法活动的渔船、渔具和其他工具，并处一万元以上五万元以下罚款；采用电鱼、毒鱼、炸鱼等方式捕捞，或者有其他严重情节的，并处五万元以上五十万元以下罚款。"},{"i":113,"n":"第一百一十三条","txt":"违反本法规定，未经批准擅自取水，或者未依照批准的取水许可规定条件取水的，由县级以上地方人民政府水行政主管部门或者黄河流域管理机构及其所属管理机构责令停止违法行为，限期采取补救措施，处五万元以上五十万元以下罚款；情节严重的，吊销取水许可证。"},{"i":114,"n":"第一百一十四条","txt":"违反本法规定，黄河流域以及黄河流经省、自治区其他黄河供水区相关县级行政区域的用水单位用水超过强制性用水定额，未按照规定期限实施节水技术改造的，由县级以上地方人民政府水行政主管部门或者黄河流域管理机构及其所属管理机构责令限期整改，可以处十万元以下罚款；情节严重的，处十万元以上五十万元以下罚款，吊销取水许可证。"},{"i":115,"n":"第一百一十五条","txt":"违反本法规定，黄河流域以及黄河流经省、自治区其他黄河供水区相关县级行政区域取水量达到取水规模以上的单位未安装在线计量设施的，由县级以上地方人民政府水行政主管部门或者黄河流域管理机构及其所属管理机构责令限期安装，并按照日最大取水能力计算的取水量计征相关费用，处二万元以上十万元以下罚款；情节严重的，处十万元以上五十万元以下罚款，吊销取水许可证。"},{"i":116,"n":"第一百一十六条","txt":"违反本法规定，黄河流域农业灌溉取用深层地下水的，由县级以上地方人民政府水行政主管部门或者黄河流域管理机构及其所属管理机构责令限期整改，可以处十万元以下罚款；情节严重的，处十万元以上五十万元以下罚款，吊销取水许可证。"},{"i":117,"n":"第一百一十七条","txt":"违反本法规定，黄河流域水库管理单位不执行黄河流域管理机构的水沙调度指令的，由黄河流域管理机构及其所属管理机构责令改正，给予警告，并处二万元以上十万元以下罚款；情节严重的，并处十万元以上五十万元以下罚款；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":118,"n":"第一百一十八条","txt":"违反本法规定，有下列行为之一的，由县级以上地方人民政府水行政主管部门或者黄河流域管理机构及其所属管理机构责令停止违法行为，限期拆除违法建筑物、构筑物或者恢复原状，处五万元以上五十万元以下罚款；逾期不拆除或者不恢复原状的，强制拆除或者代为恢复原状，所需费用由违法者承担："},{"i":119,"n":"第一百一十九条","txt":"违反本法规定，在黄河流域破坏自然资源和生态、污染环境、妨碍防洪安全、破坏文化遗产等造成他人损害的，侵权人应当依法承担侵权责任。"},{"i":120,"n":"第一百二十条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":121,"n":"第一百二十一条","txt":"本法下列用语的含义："},{"i":122,"n":"第一百二十二条","txt":"本法自2023年4月1日起施行。"}],"heitudibaohufa":[{"i":1,"n":"第一条","txt":"为了保护黑土地资源，稳步恢复提升黑土地基础地力，促进资源可持续利用，维护生态平衡，保障国家粮食安全，制定本法。"},{"i":2,"n":"第二条","txt":"从事黑土地保护、利用和相关治理、修复等活动，适用本法。本法没有规定的，适用土地管理等有关法律的规定。"},{"i":3,"n":"第三条","txt":"国家实行科学、有效的黑土地保护政策，保障黑土地保护财政投入，综合采取工程、农艺、农机、生物等措施，保护黑土地的优良生产能力，确保黑土地总量不减少、功能不退化、质量有提升、产能可持续。"},{"i":4,"n":"第四条","txt":"黑土地保护应当坚持统筹规划、因地制宜、用养结合、近期目标与远期目标结合、突出重点、综合施策的原则，建立健全政府主导、农业生产经营者实施、社会参与的保护机制。"},{"i":5,"n":"第五条","txt":"黑土地应当用于粮食和油料作物、糖料作物、蔬菜等农产品生产。"},{"i":6,"n":"第六条","txt":"国务院和四省区人民政府加强对黑土地保护工作的领导、组织、协调、监督管理，统筹制定黑土地保护政策。四省区人民政府对本行政区域内的黑土地数量、质量、生态环境负责。"},{"i":7,"n":"第七条","txt":"各级人民政府应当加强黑土地保护宣传教育，提高全社会的黑土地保护意识。"},{"i":8,"n":"第八条","txt":"国务院标准化主管部门和农业农村、自然资源、水行政等主管部门按照职责分工，制定和完善黑土地质量和其他保护标准。"},{"i":9,"n":"第九条","txt":"国家建立健全黑土地调查和监测制度。"},{"i":10,"n":"第十条","txt":"县级以上人民政府应当将黑土地保护工作纳入国民经济和社会发展规划。"},{"i":11,"n":"第十一条","txt":"国家采取措施加强黑土地保护的科技支撑能力建设，将黑土地保护、治理、修复和利用的科技创新作为重点支持领域；鼓励高等学校、科研机构和农业技术推广机构等协同开展科技攻关。县级以上人民政府应当鼓励和支持水土保持、防风固沙、土壤改良、地力培肥、生态保护等科学研究和科研成果推广应用。"},{"i":12,"n":"第十二条","txt":"县级以上人民政府应当采取以下措施加强黑土地农田基础设施建设："},{"i":13,"n":"第十三条","txt":"县级以上人民政府应当推广科学的耕作制度，采取以下措施提高黑土地质量："},{"i":14,"n":"第十四条","txt":"国家鼓励采取综合性措施，预防和治理水土流失，防止黑土地土壤侵蚀、土地沙化和盐渍化，改善和修复农田生态环境。"},{"i":15,"n":"第十五条","txt":"县级以上人民政府应当加强黑土地生态保护和黑土地周边林地、草原、湿地的保护修复，推动荒山荒坡治理，提升自然生态系统涵养水源、保持水土、防风固沙、维护生物多样性等生态功能，维持有利于黑土地保护的自然生态环境。"},{"i":16,"n":"第十六条","txt":"县级人民政府应当依据黑土地调查和监测数据，并结合土壤类型和质量等级、气候特点、环境状况等实际情况，对本行政区域内的黑土地进行科学分区，制定并组织实施黑土地质量提升计划，因地制宜合理采取保护、治理、修复和利用的精细化措施。"},{"i":17,"n":"第十七条","txt":"国有农场应当对其经营管理范围内的黑土地加强保护，充分发挥示范作用，并依法接受监督检查。"},{"i":18,"n":"第十八条","txt":"农业投入品生产者、经营者和使用者应当依法对农药、肥料、农用薄膜等农业投入品的包装物、废弃物进行回收以及资源化利用或者无害化处理，不得随意丢弃，防止黑土地污染。"},{"i":19,"n":"第十九条","txt":"从事畜禽养殖的单位和个人，应当科学开展畜禽粪污无害化处理和资源化利用，以畜禽粪污就地就近还田利用为重点，促进黑土地绿色种养循环农业发展。"},{"i":20,"n":"第二十条","txt":"任何组织和个人不得破坏黑土地资源和生态环境。禁止盗挖、滥挖和非法买卖黑土。国务院自然资源主管部门会同农业农村、水行政、公安、交通运输、市场监督管理等部门应当建立健全保护黑土地资源监督管理制度，提高对盗挖、滥挖、非法买卖黑土和其他破坏黑土地资源、生态环境行为的综合治理能力。"},{"i":21,"n":"第二十一条","txt":"建设项目不得占用黑土地；确需占用的，应当依法严格审批，并补充数量和质量相当的耕地。"},{"i":22,"n":"第二十二条","txt":"国家建立健全黑土地保护财政投入保障制度。县级以上人民政府应当将黑土地保护资金纳入本级预算。"},{"i":23,"n":"第二十三条","txt":"国家实行用养结合、保护效果导向的激励政策，对采取黑土地保护和治理修复措施的农业生产经营者按照国家有关规定给予奖励补助。"},{"i":24,"n":"第二十四条","txt":"国家鼓励粮食主销区通过资金支持、与四省区建立稳定粮食购销关系等经济合作方式参与黑土地保护，建立健全黑土地跨区域投入保护机制。"},{"i":25,"n":"第二十五条","txt":"国家按照政策支持、社会参与、市场化运作的原则，鼓励社会资本投入黑土地保护活动，并保护投资者的合法权益。"},{"i":26,"n":"第二十六条","txt":"国务院对四省区人民政府黑土地保护责任落实情况进行考核，将黑土地保护情况纳入耕地保护责任目标。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府自然资源、农业农村、水行政等有关部门按照职责，依法对黑土地保护和质量建设情况联合开展监督检查。"},{"i":28,"n":"第二十八条","txt":"县级以上人民政府应当向本级人民代表大会或者其常务委员会报告黑土地保护情况，依法接受监督。"},{"i":29,"n":"第二十九条","txt":"违反本法规定，国务院农业农村、自然资源等有关部门、县级以上地方人民政府及其有关部门有下列行为之一的，对直接负责的主管人员和其他直接责任人员给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分："},{"i":30,"n":"第三十条","txt":"非法占用或者损毁黑土地农田基础设施的，由县级以上地方人民政府农业农村、水行政等部门责令停止违法行为，限期恢复原状，处恢复费用一倍以上三倍以下罚款。"},{"i":31,"n":"第三十一条","txt":"违法将黑土地用于非农建设的，依照土地管理等有关法律法规的规定从重处罚。"},{"i":32,"n":"第三十二条","txt":"违反本法第二十条规定，盗挖、滥挖黑土的，依照土地管理等有关法律法规的规定从重处罚。"},{"i":33,"n":"第三十三条","txt":"违反本法第二十一条规定，建设项目占用黑土地未对耕作层的土壤实施剥离的，由县级以上地方人民政府自然资源主管部门处每平方米一百元以上二百元以下罚款；未按照规定的标准对耕作层的土壤实施剥离的，处每平方米五十元以上一百元以下罚款。"},{"i":34,"n":"第三十四条","txt":"拒绝、阻碍对黑土地保护情况依法进行监督检查的，由县级以上地方人民政府有关部门责令改正；拒不改正的，处二千元以上二万元以下罚款。"},{"i":35,"n":"第三十五条","txt":"造成黑土地污染、水土流失的，分别依照污染防治、水土保持等有关法律法规的规定从重处罚。"},{"i":36,"n":"第三十六条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"林地、草原、湿地、河湖等范围内黑土的保护，适用《中华人民共和国森林法》、《中华人民共和国草原法》、《中华人民共和国湿地保护法》、《中华人民共和国水法》等有关法律；有关法律对盗挖、滥挖、非法买卖黑土未作规定的，参照本法第三十二条的规定处罚。"},{"i":38,"n":"第三十八条","txt":"本法自2022年8月1日起施行。"}]};
